# Makefile for Sphinx documentation
#

# You can set these variables from the command line.
PYTHON        ?= python
SPHINXOPTS    ?=
SPHINXBUILD   ?= sphinx-build
PAPER         ?=
BUILDDIR      ?= _build
LANGUAGE      ?=
JOBS          ?= auto

# Set the default language.
ifndef LANGUAGE
override LANGUAGE = en
endif

# Convert something like "en_US" to "en", because Sphinx does not recognize
# underscores. Country codes should be passed using a dash, e.g. "pt-BR".
LANGUAGEOPT = $(firstword $(subst _, ,$(LANGUAGE)))

# Internal variables.
PAPEROPT_a4     = -D latex_paper_size=a4
PAPEROPT_letter = -D latex_paper_size=letter
ALLSPHINXOPTS   = -n -d $(BUILDDIR)/doctrees -D language=$(LANGUAGEOPT) --jobs $(JOBS) $(PAPEROPT_$(PAPER)) $(SPHINXOPTS) .
# the i18n builder cannot share the environment and doctrees with the others
I18NSPHINXOPTS  = $(PAPEROPT_$(PAPER)) $(SPHINXOPTS) .

.PHONY: help clean html htmlview dirhtml singlehtml pickle json htmlhelp qthelp devhelp epub latex latexpdf text man changes linkcheck doctest gettext

help:
	@echo "Please use \`make <target>' where <target> is one of"
	@echo "  html       to make standalone HTML files"
	@echo "  htmlview   to open the index page built by the html target in your browser"
	@echo "  dirhtml    to make HTML files named index.html in directories"
	@echo "  singlehtml to make a single large HTML file"
	@echo "  pickle     to make pickle files"
	@echo "  json       to make JSON files"
	@echo "  htmlhelp   to make HTML files and a HTML help project"
	@echo "  qthelp     to make HTML files and a qthelp project"
	@echo "  devhelp    to make HTML files and a Devhelp project"
	@echo "  epub       to make an epub"
	@echo "  latex      to make LaTeX files, you can set PAPER=a4 or PAPER=letter"
	@echo "  latexpdf   to make LaTeX files and run them through pdflatex"
	@echo "  text       to make text files"
	@echo "  man        to make manual pages"
	@echo "  texinfo    to make a Texinfo source file"
	@echo "  gettext    to make PO message catalogs"
	@echo "  changes    to make an overview of all changed/added/deprecated items"
	@echo "  linkcheck  to check all external links for integrity"
	@echo "  doctest    to run all doctests embedded in the documentation (if enabled)"
	@echo "  spelling   to check for typos in documentation"
	@echo "  black      to apply the black formatting to code blocks in documentation"


clean:
	-rm -rf $(BUILDDIR)/*

html:
	$(SPHINXBUILD) -b djangohtml $(ALLSPHINXOPTS) $(BUILDDIR)/html
	@echo
	@echo "Build finished. The HTML pages are in $(BUILDDIR)/html."

htmlview: html
	$(PYTHON) -m webbrowser "$(BUILDDIR)/html/index.html"

dirhtml:
	$(SPHINXBUILD) -b dirhtml $(ALLSPHINXOPTS) $(BUILDDIR)/dirhtml
	@echo
	@echo "Build finished. The HTML pages are in $(BUILDDIR)/dirhtml."

singlehtml:
	$(SPHINXBUILD) -b singlehtml $(ALLSPHINXOPTS) $(BUILDDIR)/singlehtml
	@echo
	@echo "Build finished. The HTML page is in $(BUILDDIR)/singlehtml."

pickle:
	$(SPHINXBUILD) -b pickle $(ALLSPHINXOPTS) $(BUILDDIR)/pickle
	@echo
	@echo "Build finished; now you can process the pickle files."

json:
	$(SPHINXBUILD) -b json $(ALLSPHINXOPTS) $(BUILDDIR)/json
	@echo
	@echo "Build finished; now you can process the JSON files."

htmlhelp:
	$(SPHINXBUILD) -b htmlhelp $(ALLSPHINXOPTS) $(BUILDDIR)/htmlhelp
	@echo
	@echo "Build finished; now you can run HTML Help Workshop with the" \
	      ".hhp project file in $(BUILDDIR)/htmlhelp."

qthelp:
	$(SPHINXBUILD) -b qthelp $(ALLSPHINXOPTS) $(BUILDDIR)/qthelp
	@echo
	@echo "Build finished; now you can run "qcollectiongenerator" with the" \
	      ".qhcp project file in $(BUILDDIR)/qthelp, like this:"
	@echo "# qcollectiongenerator $(BUILDDIR)/qthelp/django.qhcp"
	@echo "To view the help file:"
	@echo "# assistant -collectionFile $(BUILDDIR)/qthelp/django.qhc"

devhelp:
	$(SPHINXBUILD) -b devhelp $(ALLSPHINXOPTS) $(BUILDDIR)/devhelp
	@echo
	@echo "Build finished."
	@echo "To view the help file:"
	@echo "# mkdir -p $$HOME/.local/share/devhelp/django"
	@echo "# ln -s $(BUILDDIR)/devhelp $$HOME/.local/share/devhelp/django"
	@echo "# devhelp"

epub:
	$(SPHINXBUILD) -b epub $(ALLSPHINXOPTS) $(BUILDDIR)/epub
	@echo
	@echo "Build finished. The epub file is in $(BUILDDIR)/epub."

latex:
	$(SPHINXBUILD) -b latex $(ALLSPHINXOPTS) $(BUILDDIR)/latex
	@echo
	@echo "Build finished; the LaTeX files are in $(BUILDDIR)/latex."
	@echo "Run \`make' in that directory to run these through (pdf)latex" \
	      "(use \`make latexpdf' here to do that automatically)."

latexpdf:
	$(SPHINXBUILD) -b latex $(ALLSPHINXOPTS) $(BUILDDIR)/latex
	@echo "Running LaTeX files through pdflatex..."
	make -C $(BUILDDIR)/latex all-pdf
	@echo "pdflatex finished; the PDF files are in $(BUILDDIR)/latex."

text:
	$(SPHINXBUILD) -b text $(ALLSPHINXOPTS) $(BUILDDIR)/text
	@echo
	@echo "Build finished. The text files are in $(BUILDDIR)/text."

man:
	$(SPHINXBUILD) -b man $(ALLSPHINXOPTS) $(BUILDDIR)/man
	@echo
	@echo "Build finished. The manual pages are in $(BUILDDIR)/man."

texinfo:
	$(SPHINXBUILD) -b texinfo $(ALLSPHINXOPTS) $(BUILDDIR)/texinfo
	@echo
	@echo "Build finished; the Texinfo files are in $(BUILDDIR)/texinfo."

gettext:
	$(SPHINXBUILD) -b gettext $(I18NSPHINXOPTS) $(BUILDDIR)/locale
	@echo
	@echo "Build finished. The message catalogs are in $(BUILDDIR)/locale."

changes:
	$(SPHINXBUILD) -b changes $(ALLSPHINXOPTS) $(BUILDDIR)/changes
	@echo
	@echo "The overview file is in $(BUILDDIR)/changes."

linkcheck:
	$(SPHINXBUILD) -b linkcheck $(ALLSPHINXOPTS) $(BUILDDIR)/linkcheck
	@echo
	@echo "Link check complete; look for any errors in the above output " \
	      "or in $(BUILDDIR)/linkcheck/output.txt."

doctest:
	$(SPHINXBUILD) -b doctest $(ALLSPHINXOPTS) $(BUILDDIR)/doctest
	@echo "Testing of doctests in the sources finished, look at the " \
	      "results in $(BUILDDIR)/doctest/output.txt."

spelling:
	$(SPHINXBUILD) -b spelling $(ALLSPHINXOPTS) $(BUILDDIR)/spelling
	@echo
	@echo "Check finished. Wrong words can be found in " \
		"$(BUILDDIR)/spelling/output.txt."

black:
	@mkdir -p $(BUILDDIR)/black
	find . -name "*.txt" -not -path "./_build/*" -not -path "./_theme/*" \
		| xargs blacken-docs --rst-literal-block; echo $$? > "$(BUILDDIR)/black/output.txt"
	@echo
	@echo "Code blocks reformatted"

def version_github_linkcode_resolve(domain, info):
    return github_links.github_linkcode_resolve(
        domain, info, version=version, next_version=django_next_version
    )


linkcode_resolve = version_github_linkcode_resolve

def run(*args, verbosity=0, **kwargs):
    if verbosity > 1:
        print(f"\n** subprocess.run ** command: {args=} {kwargs=}")
    return subprocess.run(*args, **kwargs)

def get_api_response(endpoint, api_token=None, params=None, verbosity=0):
    if api_token is None:
        api_token = get_api_token()
    headers = {
        "Authorization": f"Bearer {api_token}",
        "Accept": "application/vnd.api+json",
        "Content-Type": "application/json",
    }
    endpoint = endpoint.strip("/")
    url = f"https://rest.api.transifex.com/{endpoint}"
    if verbosity > 2:
        print(f"\n>>> GET {url=} {params=}")
    response = requests.get(url, headers=headers, params=params)
    if verbosity > 2:
        print(f">>>> GET {response=}\n")
    response.raise_for_status()
    return response.json()["data"]

def list_resources_with_updates(
    date_since, resources=None, languages=None, verbosity=0
):
    api_token = get_api_token()
    project = "o:django:p:django"
    date_since_iso = date_since.isoformat().strip("Z") + "Z"
    if verbosity:
        print(f"\n== Starting list_resources_with_updates at {date_since_iso=}")

    if not languages:
        languages = [  # List languages using Transifex projects API.
            d["attributes"]["code"]
            for d in get_api_response(
                f"projects/{project}/languages", api_token, verbosity=verbosity
            )
        ]
    if verbosity > 1:
        print(f"\n=== Languages to process: {languages=}")

    if not resources:
        resources = [  # List resources using Transifex resources API.
            d["attributes"]["slug"]
            for d in get_api_response(
                "resources",
                api_token,
                params={"filter[project]": project},
                verbosity=verbosity,
            )
        ]
    else:
        resources = [_tx_resource_slug_for_name(r) for r in resources]
    if verbosity > 1:
        print(f"\n=== Resources to process: {resources=}")

    resource_lang_changed = defaultdict(list)
    for lang, resource in product(languages, resources):
        if verbosity:
            print(f"\n=== Getting data for: {lang=} {resource=} {date_since_iso=}")
        data = get_api_response(
            "resource_translations",
            api_token,
            params={
                "filter[resource]": f"{project}:r:{resource}",
                "filter[language]": f"l:{lang}",
                "filter[date_translated][gt]": date_since_iso,
            },
            verbosity=verbosity,
        )
        local_resource = resource.replace("contrib-", "", 1)
        local_lang = lang  # XXX: LANG_OVERRIDES.get(lang, lang)
        if data:
            resource_lang_changed[local_resource].append(local_lang)
            if verbosity > 2:
                fname = f"{local_resource}-{local_lang}.json"
                with open(fname, "w") as f:
                    f.write(json.dumps(data, sort_keys=True, indent=2))
                print(f"==== Stored full data JSON in: {fname}")
        if verbosity > 1:
            print(f"==== Result for {local_resource=} {local_lang=}: {len(data)=}")

    return resource_lang_changed

def _tx_resource_slug_for_name(name):
    """Return the Transifex resource slug for the given name."""
    if name != "core":
        name = f"contrib-{name}"
    return name

def _tx_resource_for_name(name):
    """Return the Transifex resource name."""
    return "django." + _tx_resource_slug_for_name(name)

def fetch(resources=None, languages=None, date_since=None, verbosity=0):
    """
    Fetch translations from Transifex, wrap long lines, generate mo files.
    """
    if date_since is None:
        resource_lang_mapping = {}
    else:
        # Filter resources and languages that were updates after `date_since`
        resource_lang_mapping = list_resources_with_updates(
            date_since=date_since,
            resources=resources,
            languages=languages,
            verbosity=verbosity,
        )
        resources = resource_lang_mapping.keys()

    locale_dirs = _get_locale_dirs(resources)
    errors = []

    for name, dir_ in locale_dirs:
        cmd = [
            "tx",
            "pull",
            "-r",
            _tx_resource_for_name(name),
            "-f",
            "--minimum-perc=5",
        ]
        per_resource_langs = resource_lang_mapping.get(name, languages)
        # Transifex pull
        if per_resource_langs is None:
            run([*cmd, "--all"], verbosity=verbosity)
            target_langs = sorted(
                d for d in os.listdir(dir_) if not d.startswith("_") and d != "en"
            )
        else:
            run([*cmd, "-l", ",".join(per_resource_langs)], verbosity=verbosity)
            target_langs = per_resource_langs

        target_langs = [LANG_OVERRIDES.get(d, d) for d in target_langs]

        # msgcat to wrap lines and msgfmt for compilation of .mo file
        for lang in target_langs:
            po_path = "%(path)s/%(lang)s/LC_MESSAGES/django%(ext)s.po" % {
                "path": dir_,
                "lang": lang,
                "ext": "js" if name.endswith("-js") else "",
            }
            if not os.path.exists(po_path):
                print(
                    "No %(lang)s translation for resource %(name)s"
                    % {"lang": lang, "name": name}
                )
                continue
            run(
                ["msgcat", "--no-location", "-o", po_path, po_path], verbosity=verbosity
            )
            msgfmt = run(
                ["msgfmt", "-c", "-o", "%s.mo" % po_path[:-3], po_path],
                verbosity=verbosity,
            )
            if msgfmt.returncode != 0:
                errors.append((name, lang))
    if errors:
        print("\nWARNING: Errors have occurred in following cases:")
        for resource, lang in errors:
            print("\tResource %s for language %s" % (resource, lang))
        exit(1)

    if verbosity:
        print("\nCOMPLETED.")

def render(
    request, template_name, context=None, content_type=None, status=None, using=None
):
    """
    Return an HttpResponse whose content is filled with the result of calling
    django.template.loader.render_to_string() with the passed arguments.
    """
    content = loader.render_to_string(template_name, context, request, using=using)
    return HttpResponse(content, content_type, status)

def get_object_or_404(klass, *args, **kwargs):
    """
    Use get() to return an object, or raise an Http404 exception if the object
    does not exist.

    klass may be a Model, Manager, or QuerySet object. All other passed
    arguments and keyword arguments are used in the get() query.

    Like with QuerySet.get(), MultipleObjectsReturned is raised if more than
    one object is found.
    """
    queryset = _get_queryset(klass)
    if not hasattr(queryset, "get"):
        klass__name = (
            klass.__name__ if isinstance(klass, type) else klass.__class__.__name__
        )
        raise ValueError(
            "First argument to get_object_or_404() must be a Model, Manager, "
            "or QuerySet, not '%s'." % klass__name
        )
    try:
        return queryset.get(*args, **kwargs)
    except queryset.model.DoesNotExist:
        raise Http404(
            "No %s matches the given query." % queryset.model._meta.object_name
        )


async def aget_object_or_404(klass, *args, **kwargs):
    """See get_object_or_404()."""
    queryset = _get_queryset(klass)
    if not hasattr(queryset, "aget"):
        klass__name = (
            klass.__name__ if isinstance(klass, type) else klass.__class__.__name__
        )
        raise ValueError(
            "First argument to aget_object_or_404() must be a Model, Manager, or "
            f"QuerySet, not '{klass__name}'."
        )
    try:
        return await queryset.aget(*args, **kwargs)
    except queryset.model.DoesNotExist:
        raise Http404(f"No {queryset.model._meta.object_name} matches the given query.")

def resolve_url(to, *args, **kwargs):
    """
    Return a URL appropriate for the arguments passed.

    The arguments could be:

        * A model: the model's `get_absolute_url()` function will be called.

        * A view name, possibly with arguments: `urls.reverse()` will be used
          to reverse-resolve the name.

        * A URL, which will be returned as-is.
    """
    # If it's a model, use get_absolute_url()
    if hasattr(to, "get_absolute_url"):
        return to.get_absolute_url()

    if isinstance(to, Promise):
        # Expand the lazy instance, as it can cause issues when it is passed
        # further to some Python functions like urlparse.
        to = str(to)

    # Handle relative URLs
    if isinstance(to, str) and to.startswith(("./", "../")):
        return to

    # Next try a reverse URL resolution.
    try:
        return reverse(to, args=args, kwargs=kwargs)
    except NoReverseMatch:
        # If this is a callable, re-raise.
        if callable(to):
            raise
        # If this doesn't "feel" like a URL, re-raise.
        if "/" not in to and "." not in to:
            raise

    # Finally, fall back and assume it's a URL
    return to

def process_response(self, request, response):
    # Don't set it if it's already in the response
    if response.get("X-Frame-Options") is not None:
        return response

    # Don't set it if they used @xframe_options_exempt
    if getattr(response, "xframe_options_exempt", False):
        return response

    response.headers["X-Frame-Options"] = self.get_xframe_options_value(
        request,
        response,
    )
    return response

def _get_failure_view():
    """Return the view to be used for CSRF rejections."""
    return get_callable(settings.CSRF_FAILURE_VIEW)

def _add_new_csrf_cookie(request):
    """Generate a new random CSRF_COOKIE value, and add it to request.META."""
    csrf_secret = _get_new_csrf_string()
    request.META.update(
        {
            "CSRF_COOKIE": csrf_secret,
            "CSRF_COOKIE_NEEDS_UPDATE": True,
        }
    )
    return csrf_secret

class CsrfViewMiddleware(MiddlewareMixin):
    """
    Require a present and correct csrfmiddlewaretoken for POST requests that
    have a CSRF cookie, and set an outgoing CSRF cookie.

    This middleware should be used in conjunction with the {% csrf_token %}
    template tag.
    """

    @cached_property

def csrf_trusted_origins_hosts(self):
    return [
        urlsplit(origin).netloc.lstrip("*")
        for origin in settings.CSRF_TRUSTED_ORIGINS
    ]

@cached_property

def allowed_origins_exact(self):
    return {origin for origin in settings.CSRF_TRUSTED_ORIGINS if "*" not in origin}

@cached_property

def _get_secret(self, request):
    """
    Return the CSRF secret originally associated with the request, or None
    if it didn't have one.

    If the CSRF_USE_SESSIONS setting is false, raises InvalidTokenFormat if
    the request's secret has invalid characters or an invalid length.
    """
    if settings.CSRF_USE_SESSIONS:
        try:
            csrf_secret = request.session.get(CSRF_SESSION_KEY)
        except AttributeError:
            raise ImproperlyConfigured(
                "CSRF_USE_SESSIONS is enabled, but request.session is not "
                "set. SessionMiddleware must appear before CsrfViewMiddleware "
                "in MIDDLEWARE."
            )
    else:
        try:
            csrf_secret = request.COOKIES[settings.CSRF_COOKIE_NAME]
        except KeyError:
            csrf_secret = None
        else:
            # This can raise InvalidTokenFormat.
            _check_token_format(csrf_secret)
    if csrf_secret is None:
        return None
    # Django versions before 4.0 masked the secret before storing.
    if len(csrf_secret) == CSRF_TOKEN_LENGTH:
        csrf_secret = _unmask_cipher_token(csrf_secret)
    return csrf_secret

def _origin_verified(self, request):
    request_origin = request.META["HTTP_ORIGIN"]
    try:
        good_host = request.get_host()
    except DisallowedHost:
        pass
    else:
        good_origin = "%s://%s" % (
            "https" if request.is_secure() else "http",
            good_host,
        )
        if request_origin == good_origin:
            return True
    if request_origin in self.allowed_origins_exact:
        return True
    try:
        parsed_origin = urlsplit(request_origin)
    except ValueError:
        return False
    request_scheme = parsed_origin.scheme
    request_netloc = parsed_origin.netloc
    return any(
        is_same_domain(request_netloc, host)
        for host in self.allowed_origin_subdomains.get(request_scheme, ())
    )

def _check_referer(self, request):
    referer = request.META.get("HTTP_REFERER")
    if referer is None:
        raise RejectRequest(REASON_NO_REFERER)

    try:
        referer = urlsplit(referer)
    except ValueError:
        raise RejectRequest(REASON_MALFORMED_REFERER)

    # Make sure we have a valid URL for Referer.
    if "" in (referer.scheme, referer.netloc):
        raise RejectRequest(REASON_MALFORMED_REFERER)

    # Ensure that our Referer is also secure.
    if referer.scheme != "https":
        raise RejectRequest(REASON_INSECURE_REFERER)

    if any(
        is_same_domain(referer.netloc, host)
        for host in self.csrf_trusted_origins_hosts
    ):
        return
    # Allow matching the configured cookie domain.
    good_referer = (
        settings.SESSION_COOKIE_DOMAIN
        if settings.CSRF_USE_SESSIONS
        else settings.CSRF_COOKIE_DOMAIN
    )
    if good_referer is None:
        # If no cookie domain is configured, allow matching the current
        # host:port exactly if it's permitted by ALLOWED_HOSTS.
        try:
            # request.get_host() includes the port.
            good_referer = request.get_host()
        except DisallowedHost:
            raise RejectRequest(REASON_BAD_REFERER % referer.geturl())
    else:
        server_port = request.get_port()
        if server_port not in ("443", "80"):
            good_referer = "%s:%s" % (good_referer, server_port)

    if not is_same_domain(referer.netloc, good_referer):
        raise RejectRequest(REASON_BAD_REFERER % referer.geturl())

def _bad_token_message(self, reason, token_source):
    if token_source != "POST":
        # Assume it is a settings.CSRF_HEADER_NAME value.
        header_name = HttpHeaders.parse_header_name(token_source)
        token_source = f"the {header_name!r} HTTP header"
    return f"CSRF token from {token_source} {reason}."

def _check_token(self, request):
    # Access csrf_secret via self._get_secret() as rotate_token() may have
    # been called by an authentication middleware during the
    # process_request() phase.
    try:
        csrf_secret = self._get_secret(request)
    except InvalidTokenFormat as exc:
        raise RejectRequest(f"CSRF cookie {exc.reason}.")

    if csrf_secret is None:
        # No CSRF cookie. For POST requests, we insist on a CSRF cookie,
        # and in this way we can avoid all CSRF attacks, including login
        # CSRF.
        raise RejectRequest(REASON_NO_CSRF_COOKIE)

    # Check non-cookie token for match.
    request_csrf_token = ""
    if request.method == "POST":
        try:
            request_csrf_token = request.POST.get("csrfmiddlewaretoken", "")
        except UnreadablePostError:
            # Handle a broken connection before we've completed reading the
            # POST data. process_view shouldn't raise any exceptions, so
            # we'll ignore and serve the user a 403 (assuming they're still
            # listening, which they probably aren't because of the error).
            pass

    if request_csrf_token == "":
        # Fall back to X-CSRFToken, to make things easier for AJAX, and
        # possible for PUT/DELETE.
        try:
            # This can have length CSRF_SECRET_LENGTH or CSRF_TOKEN_LENGTH,
            # depending on whether the client obtained the token from
            # the DOM or the cookie (and if the cookie, whether the cookie
            # was masked or unmasked).
            request_csrf_token = request.META[settings.CSRF_HEADER_NAME]
        except KeyError:
            raise RejectRequest(REASON_CSRF_TOKEN_MISSING)
        token_source = settings.CSRF_HEADER_NAME
    else:
        token_source = "POST"

    try:
        _check_token_format(request_csrf_token)
    except InvalidTokenFormat as exc:
        reason = self._bad_token_message(exc.reason, token_source)
        raise RejectRequest(reason)

    if not _does_token_match(request_csrf_token, csrf_secret):
        reason = self._bad_token_message("incorrect", token_source)
        raise RejectRequest(reason)

def process_request(self, request):
    try:
        csrf_secret = self._get_secret(request)
    except InvalidTokenFormat:
        _add_new_csrf_cookie(request)
    else:
        if csrf_secret is not None:
            # Use the same secret next time. If the secret was originally
            # masked, this also causes it to be replaced with the unmasked
            # form, but only in cases where the secret is already getting
            # saved anyways.
            request.META["CSRF_COOKIE"] = csrf_secret

def process_view(self, request, callback, callback_args, callback_kwargs):
    if getattr(request, "csrf_processing_done", False):
        return None

    # Wait until request.META["CSRF_COOKIE"] has been manipulated before
    # bailing out, so that get_token still works
    if getattr(callback, "csrf_exempt", False):
        return None

    # Assume that anything not defined as 'safe' by RFC 9110 needs protection
    if request.method in ("GET", "HEAD", "OPTIONS", "TRACE"):
        return self._accept(request)

    if getattr(request, "_dont_enforce_csrf_checks", False):
        # Mechanism to turn off CSRF checks for test suite. It comes after
        # the creation of CSRF cookies, so that everything else continues
        # to work exactly the same (e.g. cookies are sent, etc.), but
        # before any branches that call the _reject method.
        return self._accept(request)

    # Reject the request if the Origin header doesn't match an allowed
    # value.
    if "HTTP_ORIGIN" in request.META:
        if not self._origin_verified(request):
            return self._reject(
                request, REASON_BAD_ORIGIN % request.META["HTTP_ORIGIN"]
            )
    elif request.is_secure():
        # If the Origin header wasn't provided, reject HTTPS requests if
        # the Referer header doesn't match an allowed value.
        #
        # Suppose user visits http://example.com/
        # An active network attacker (man-in-the-middle, MITM) sends a
        # POST form that targets https://example.com/detonate-bomb/ and
        # submits it via JavaScript.
        #
        # The attacker will need to provide a CSRF cookie and token, but
        # that's no problem for a MITM and the session-independent secret
        # we're using. So the MITM can circumvent the CSRF protection. This
        # is true for any HTTP connection, but anyone using HTTPS expects
        # better! For this reason, for https://example.com/ we need
        # additional protection that treats http://example.com/ as
        # completely untrusted. Under HTTPS, Barth et al. found that the
        # Referer header is missing for same-domain requests in only about
        # 0.2% of cases or less, so we can use strict Referer checking.
        try:
            self._check_referer(request)
        except RejectRequest as exc:
            return self._reject(request, exc.reason)

    try:
        self._check_token(request)
    except RejectRequest as exc:
        return self._reject(request, exc.reason)

    return self._accept(request)

def process_request(self, request):
    path = request.path.lstrip("/")
    if (
        self.redirect
        and not request.is_secure()
        and not any(pattern.search(path) for pattern in self.redirect_exempt)
    ):
        host = self.redirect_host or request.get_host()
        return HttpResponsePermanentRedirect(
            "https://%s%s" % (host, request.get_full_path())
        )

def process_response(self, request, response):
    if (
        self.sts_seconds
        and request.is_secure()
        and "Strict-Transport-Security" not in response
    ):
        sts_header = "max-age=%s" % self.sts_seconds
        if self.sts_include_subdomains:
            sts_header += "; includeSubDomains"
        if self.sts_preload:
            sts_header += "; preload"
        response.headers["Strict-Transport-Security"] = sts_header

    if self.content_type_nosniff:
        response.headers.setdefault("X-Content-Type-Options", "nosniff")

    if self.referrer_policy:
        # Support a comma-separated string or iterable of values to allow
        # fallback.
        response.headers.setdefault(
            "Referrer-Policy",
            ",".join(
                [v.strip() for v in self.referrer_policy.split(",")]
                if isinstance(self.referrer_policy, str)
                else self.referrer_policy
            ),
        )

    if self.cross_origin_opener_policy:
        response.setdefault(
            "Cross-Origin-Opener-Policy",
            self.cross_origin_opener_policy,
        )
    return response

def process_response(self, request, response):
    # In DEBUG mode, exclude CSP headers for specific status codes that
    # trigger the debug view.
    exempted_status_codes = {
        HTTPStatus.NOT_FOUND,
        HTTPStatus.INTERNAL_SERVER_ERROR,
    }
    if settings.DEBUG and response.status_code in exempted_status_codes:
        return response

    nonce = get_nonce(request)
    for header, config in [
        (CSP.HEADER_ENFORCE, settings.SECURE_CSP),
        (CSP.HEADER_REPORT_ONLY, settings.SECURE_CSP_REPORT_ONLY),
    ]:
        # If headers are already set on the response, don't overwrite them.
        # This allows for views to set their own CSP headers as needed.
        if config and header not in response:
            response.headers[str(header)] = build_policy(config, nonce)

    return response

def process_request(self, request):
    """
    Check for denied User-Agents and rewrite the URL based on
    settings.APPEND_SLASH and settings.PREPEND_WWW
    """

    # Check for denied User-Agents
    user_agent = request.META.get("HTTP_USER_AGENT")
    if user_agent is not None:
        for user_agent_regex in settings.DISALLOWED_USER_AGENTS:
            if user_agent_regex.search(user_agent):
                raise PermissionDenied("Forbidden user agent")

    # Check for a redirect based on settings.PREPEND_WWW
    host = request.get_host()

    if settings.PREPEND_WWW and host and not host.startswith("www."):
        # Check if we also need to append a slash so we can do it all
        # with a single redirect. (This check may be somewhat expensive,
        # so we only do it if we already know we're sending a redirect,
        # or in process_response if we get a 404.)
        if self.should_redirect_with_slash(request):
            path = self.get_full_path_with_slash(request)
        else:
            path = request.get_full_path()

        return self.response_redirect_class(f"{request.scheme}://www.{host}{path}")

def should_redirect_with_slash(self, request):
    """
    Return True if settings.APPEND_SLASH is True and appending a slash to
    the request path turns an invalid path into a valid one.
    """
    if settings.APPEND_SLASH and not request.path_info.endswith("/"):
        urlconf = getattr(request, "urlconf", None)
        if not is_valid_path(request.path_info, urlconf):
            match = is_valid_path("%s/" % request.path_info, urlconf)
            if match:
                view = match.func
                return getattr(view, "should_append_slash", True)
    return False

def process_response(self, request, response):
    # It's too late to prevent an unsafe request with a 412 response, and
    # for a HEAD request, the response body is always empty so computing
    # an accurate ETag isn't possible.
    if request.method != "GET":
        return response

    if self.needs_etag(response) and not response.has_header("ETag"):
        set_response_etag(response)

    etag = response.get("ETag")
    last_modified = response.get("Last-Modified")
    last_modified = last_modified and parse_http_date_safe(last_modified)

    if etag or last_modified:
        return get_conditional_response(
            request,
            etag=etag,
            last_modified=last_modified,
            response=response,
        )

    return response

def needs_etag(self, response):
    """Return True if an ETag header should be added to response."""
    cache_control_headers = cc_delim_re.split(response.get("Cache-Control", ""))
    return all(header.lower() != "no-store" for header in cache_control_headers)

def construct_instance(form, instance, fields=None, exclude=None):
    """
    Construct and return a model instance from the bound ``form``'s
    ``cleaned_data``, but do not save the returned instance to the database.
    """
    from django.db import models

    opts = instance._meta

    cleaned_data = form.cleaned_data
    file_field_list = []
    for f in opts.fields:
        if (
            not f.editable
            or isinstance(f, models.AutoField)
            or f.name not in cleaned_data
        ):
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        # Leave defaults for fields that aren't in POST data, except for
        # checkbox inputs because they don't appear in POST data if not checked.
        if (
            f.has_default()
            and form[f.name].field.widget.value_omitted_from_data(
                form.data, form.files, form.add_prefix(f.name)
            )
            and cleaned_data.get(f.name) in form[f.name].field.empty_values
        ):
            continue
        # Defer saving file-type fields until after the other fields, so a
        # callable upload_to can use the values from other fields.
        if isinstance(f, models.FileField):
            file_field_list.append(f)
        else:
            f.save_form_data(instance, cleaned_data[f.name])

    for f in file_field_list:
        f.save_form_data(instance, cleaned_data[f.name])

    return instance


