def is_django_module(module):
    """Return True if the given module is nested under Django."""
    return module.__name__.startswith("django.")

def is_django_path(path):
    """Return True if the given file path is nested under Django."""
    return Path(django.__file__).parent in Path(path).parents

def wrapper(*args, **kwargs):
    global _exception
    try:
        fn(*args, **kwargs)
    except Exception:
        _exception = sys.exc_info()

        et, ev, tb = _exception

        if getattr(ev, "filename", None) is None:
            # get the filename from the last item in the stack
            filename = traceback.extract_tb(tb)[-1][0]
        else:
            filename = ev.filename

        if filename not in _error_files:
            _error_files.append(filename)

        raise

return wrapper

def raise_last_exception():
    if _exception is not None:
        raise _exception[1]

def ensure_echo_on():
    """
    Ensure that echo mode is enabled. Some tools such as PDB disable
    it which causes usability issues after reload.
    """
    if not termios or not sys.stdin.isatty():
        return
    attr_list = termios.tcgetattr(sys.stdin)
    if not attr_list[3] & termios.ECHO:
        attr_list[3] |= termios.ECHO
        if hasattr(signal, "SIGTTOU"):
            old_handler = signal.signal(signal.SIGTTOU, signal.SIG_IGN)
        else:
            old_handler = None
        termios.tcsetattr(sys.stdin, termios.TCSANOW, attr_list)
        if old_handler is not None:
            signal.signal(signal.SIGTTOU, old_handler)

def iter_all_python_module_files():
    # This is a hot path during reloading. Create a stable sorted list of
    # modules based on the module name and pass it to iter_modules_and_files().
    # This ensures cached results are returned in the usual case that modules
    # aren't loaded on the fly.
    keys = sorted(sys.modules)
    modules = tuple(
        m
        for m in map(sys.modules.__getitem__, keys)
        if not isinstance(m, weakref.ProxyTypes)
    )
    return iter_modules_and_files(modules, frozenset(_error_files))


@lru_cache(maxsize=1)

def iter_modules_and_files(modules, extra_files):
    """Iterate through all modules needed to be watched."""
    sys_file_paths = []
    for module in modules:
        # During debugging (with PyDev) the 'typing.io' and 'typing.re' objects
        # are added to sys.modules, however they are types not modules and so
        # cause issues here.
        if not isinstance(module, ModuleType):
            continue
        if module.__name__ in ("__main__", "__mp_main__"):
            # __main__ (usually manage.py) doesn't always have a __spec__ set.
            # Handle this by falling back to using __file__, resolved below.
            # See https://docs.python.org/reference/import.html#main-spec
            # __file__ may not exists, e.g. when running ipdb debugger.
            if hasattr(module, "__file__"):
                sys_file_paths.append(module.__file__)
            continue
        if getattr(module, "__spec__", None) is None:
            continue
        spec = module.__spec__
        # Modules could be loaded from places without a concrete location. If
        # this is the case, skip them.
        if spec.has_location:
            origin = (
                spec.loader.archive
                if isinstance(spec.loader, zipimporter)
                else spec.origin
            )
            sys_file_paths.append(origin)

    results = set()
    for filename in itertools.chain(sys_file_paths, extra_files):
        if not filename:
            continue
        path = Path(filename)
        try:
            if not path.exists():
                # The module could have been removed, don't fail loudly if this
                # is the case.
                continue
        except ValueError as e:
            # Network filesystems may return null bytes in file paths.
            logger.debug('"%s" raised when resolving path: "%s"', e, path)
            continue
        resolved_path = path.resolve().absolute()
        results.add(resolved_path)
    return frozenset(results)


@lru_cache(maxsize=1)

def _walk(node, path):
    for prefix, child in node.items():
        yield from _walk(child, [*path, prefix])
    if not node:
        yield Path(*path)

return tuple(_walk(tree, ()))

def sys_path_directories():
    """
    Yield absolute directories from sys.path, ignoring entries that don't
    exist.
    """
    for path in sys.path:
        path = Path(path)
        if not path.exists():
            continue
        resolved_path = path.resolve().absolute()
        # If the path is a file (like a zip file), watch the parent directory.
        if resolved_path.is_file():
            yield resolved_path.parent
        else:
            yield resolved_path

def trigger_reload(filename):
    logger.info("%s changed, reloading.", filename)
    sys.exit(3)

def restart_with_reloader():
    new_environ = {**os.environ, DJANGO_AUTORELOAD_ENV: "true"}
    args = get_child_arguments()
    while True:
        p = subprocess.run(args, env=new_environ, close_fds=False)
        if p.returncode != 3:
            return p.returncode

def watch_dir(self, path, glob):
    path = Path(path)
    try:
        path = path.absolute()
    except FileNotFoundError:
        logger.debug(
            "Unable to watch directory %s as it cannot be resolved.",
            path,
            exc_info=True,
        )
        return
    logger.debug("Watching dir %s with glob %s.", path, glob)
    self.directory_globs[path].add(glob)

def watched_files(self, include_globs=True):
    """
    Yield all files that need to be watched, including module files and
    files within globs.
    """
    yield from iter_all_python_module_files()
    yield from self.extra_files
    if include_globs:
        for directory, patterns in self.directory_globs.items():
            for pattern in patterns:
                yield from directory.glob(pattern)

def run_loop(self):
    ticker = self.tick()
    while not self.should_stop:
        try:
            next(ticker)
        except StopIteration:
            break
    self.stop()

def notify_file_changed(self, path):
    results = file_changed.send(sender=self, file_path=path)
    logger.debug("%s notified as changed. Signal results: %s.", path, results)
    if not any(res[1] for res in results):
        trigger_reload(path)

# These are primarily used for testing.
@property

def tick(self):
    mtimes = {}
    while True:
        for filepath, mtime in self.snapshot_files():
            old_time = mtimes.get(filepath)
            mtimes[filepath] = mtime
            if old_time is None:
                logger.debug("File %s first seen with mtime %s", filepath, mtime)
                continue
            elif mtime > old_time:
                logger.debug(
                    "File %s previous mtime: %s, current mtime: %s",
                    filepath,
                    old_time,
                    mtime,
                )
                self.notify_file_changed(filepath)

        time.sleep(self.SLEEP_TIME)
        yield

def snapshot_files(self):
    # watched_files may produce duplicate paths if globs overlap.
    seen_files = set()
    for file in self.watched_files():
        if file in seen_files:
            continue
        try:
            mtime = file.stat().st_mtime
        except OSError:
            # This is thrown when the file does not exist.
            continue
        seen_files.add(file)
        yield file, mtime

@classmethod

def __init__(self):
    self.roots = defaultdict(set)
    self.processed_request = threading.Event()
    self.client_timeout = int(os.environ.get("DJANGO_WATCHMAN_TIMEOUT", 5))
    super().__init__()

@cached_property

def _subscribe_dir(self, directory, filenames):
    if not directory.exists():
        if not directory.parent.exists():
            logger.warning(
                "Unable to watch directory %s as neither it or its parent exist.",
                directory,
            )
            return
        prefix = "files-parent-%s" % directory.name
        filenames = ["%s/%s" % (directory.name, filename) for filename in filenames]
        directory = directory.parent
        expression = ["name", filenames, "wholename"]
    else:
        prefix = "files"
        expression = ["name", filenames]
    self._subscribe(directory, "%s:%s" % (prefix, directory), expression)

def watched_roots(self, watched_files):
    extra_directories = self.directory_globs.keys()
    watched_file_dirs = [f.parent for f in watched_files]
    sys_paths = list(sys_path_directories())
    return frozenset((*extra_directories, *watched_file_dirs, *sys_paths))

def update_watches(self):
    try:
        self._update_watches()
    except Exception as ex:
        # If the service is still available, raise the original exception.
        if self.check_server_status(ex):
            raise

def request_processed(self, **kwargs):
    logger.debug("Request processed. Setting update_watches event.")
    self.processed_request.set()

def tick(self):
    request_finished.connect(self.request_processed)
    self.update_watches()
    while True:
        if self.processed_request.is_set():
            self.update_watches()
            self.processed_request.clear()
        try:
            self.client.receive()
        except pywatchman.SocketTimeout:
            pass
        except pywatchman.WatchmanError as ex:
            logger.debug("Watchman error: %s, checking server status.", ex)
            self.check_server_status(ex)
        else:
            for sub in list(self.client.subs.keys()):
                self._check_subscription(sub)
        yield
        # Protect against busy loops.
        time.sleep(0.1)

def stop(self):
    self.client.close()
    super().stop()

def check_server_status(self, inner_ex=None):
    """Return True if the server is available."""
    try:
        self.client.query("version")
    except Exception:
        raise WatchmanUnavailable(str(inner_ex)) from inner_ex
    return True

@classmethod

def check_availability(cls):
    if not pywatchman:
        raise WatchmanUnavailable("pywatchman not installed.")
    client = pywatchman.client(timeout=0.1)
    try:
        result = client.capabilityCheck()
    except Exception:
        # The service is down?
        raise WatchmanUnavailable("Cannot connect to the watchman service.")
    version = get_version_tuple(result["version"])
    # Watchman 4.9 includes multiple improvements to watching project
    # directories as well as case insensitive filesystems.
    logger.debug("Watchman version %s", version)
    if version < (4, 9):
        raise WatchmanUnavailable("Watchman 4.9 or later is required.")

def get_reloader():
    """Return the most suitable reloader for this environment."""
    try:
        WatchmanReloader.check_availability()
    except WatchmanUnavailable:
        return StatReloader()
    return WatchmanReloader()

def start_django(reloader, main_func, *args, **kwargs):
    ensure_echo_on()

    main_func = check_errors(main_func)
    django_main_thread = threading.Thread(
        target=main_func, args=args, kwargs=kwargs, name="django-main-thread"
    )
    django_main_thread.daemon = True
    django_main_thread.start()

    while not reloader.should_stop:
        reloader.run(django_main_thread)

def run_with_reloader(main_func, *args, **kwargs):
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))
    try:
        if os.environ.get(DJANGO_AUTORELOAD_ENV) == "true":
            reloader = get_reloader()
            logger.info(
                "Watching for file changes with %s", reloader.__class__.__name__
            )
            start_django(reloader, main_func, *args, **kwargs)
        else:
            exit_code = restart_with_reloader()
            sys.exit(exit_code)
    except KeyboardInterrupt:
        pass

def discard(self, item):
    try:
        self.remove(item)
    except KeyError:
        pass

def __repr__(self):
    data = repr(list(self.dict)) if self.dict else ""
    return f"{self.__class__.__qualname__}({data})"

def __getitem__(self, key):
    """
    Return the last data value for this key, or [] if it's an empty list;
    raise KeyError if not found.
    """
    try:
        list_ = super().__getitem__(key)
    except KeyError:
        raise MultiValueDictKeyError(key)
    try:
        return list_[-1]
    except IndexError:
        return []

def __deepcopy__(self, memo):
    result = self.__class__()
    memo[id(self)] = result
    for key, value in dict.items(self):
        dict.__setitem__(
            result, copy.deepcopy(key, memo), copy.deepcopy(value, memo)
        )
    return result

def __setstate__(self, obj_dict):
    data = obj_dict.pop("_data", {})
    for k, v in data.items():
        self.setlist(k, v)
    self.__dict__.update(obj_dict)

def get(self, key, default=None):
    """
    Return the last data value for the passed key. If key doesn't exist
    or value is an empty list, return `default`.
    """
    try:
        val = self[key]
    except KeyError:
        return default
    if val == []:
        return default
    return val

def _getlist(self, key, default=None, force_list=False):
    """
    Return a list of values for the key.

    Used internally to manipulate values list. If force_list is True,
    return a new copy of values.
    """
    try:
        values = super().__getitem__(key)
    except KeyError:
        if default is None:
            return []
        return default
    else:
        if force_list:
            values = list(values) if values is not None else None
        return values

def getlist(self, key, default=None):
    """
    Return the list of values for the key. If key doesn't exist, return a
    default value.
    """
    return self._getlist(key, default, force_list=True)

def setdefault(self, key, default=None):
    if key not in self:
        self[key] = default
        # Do not return default here because __setitem__() may store
        # another value -- QueryDict.__setitem__() does. Look it up.
    return self[key]

def setlistdefault(self, key, default_list=None):
    if key not in self:
        if default_list is None:
            default_list = []
        self.setlist(key, default_list)
        # Do not return default_list here because setlist() may store
        # another value -- QueryDict.setlist() does. Look it up.
    return self._getlist(key)

def appendlist(self, key, value):
    """Append an item to the internal list associated with key."""
    self.setlistdefault(key).append(value)

def lists(self):
    """Yield (key, list) pairs."""
    return iter(super().items())

def values(self):
    """Yield the last value on every key list."""
    for key in self:
        yield self[key]

def copy(self):
    """Return a shallow copy of this object."""
    return copy.copy(self)

def update(self, *args, **kwargs):
    """Extend rather than replace existing key lists."""
    if len(args) > 1:
        raise TypeError("update expected at most 1 argument, got %d" % len(args))
    if args:
        arg = args[0]
        if isinstance(arg, MultiValueDict):
            for key, value_list in arg.lists():
                self.setlistdefault(key).extend(value_list)
        else:
            if isinstance(arg, Mapping):
                arg = arg.items()
            for key, value in arg:
                self.setlistdefault(key).append(value)
    for key, value in kwargs.items():
        self.setlistdefault(key).append(value)

def dict(self):
    """Return current object as a dict with singular values."""
    return {key: self[key] for key in self}

def __eq__(self, other):
    return isinstance(other, Mapping) and {
        k.lower(): v for k, v in self.items()
    } == {k.lower(): v for k, v in other.items()}

