def method_get_order(self, ordered_obj):
    order_wrt = ordered_obj._meta.order_with_respect_to
    filter_args = order_wrt.get_forward_related_filter(self)
    pk_name = ordered_obj._meta.pk.name
    return ordered_obj.objects.filter(**filter_args).values_list(pk_name, flat=True)

def model_unpickle(model_id):
    """Used to unpickle Model subclasses with deferred fields."""
    if isinstance(model_id, tuple):
        model = apps.get_model(*model_id)
    else:
        # Backwards compat - the model was cached directly in earlier versions.
        model = model_id
    return model.__new__(model)


model_unpickle.__safe_for_unpickle__ = True

def as_postgresql(self, compiler, connection, **extra_context):
    # Cast FloatField to DecimalField as PostgreSQL doesn't support the
    # following function signatures:
    # - LOG(double, double)
    # - MOD(double, double)
    output_field = DecimalField(decimal_places=sys.float_info.dig, max_digits=1000)
    clone = self.copy()
    clone.set_source_expressions(
        [
            (
                Cast(expression, output_field)
                if isinstance(expression.output_field, FloatField)
                else expression
            )
            for expression in self.get_source_expressions()
        ]
    )
    return clone.as_sql(compiler, connection, **extra_context)

def as_mysql(self, compiler, connection, **extra_context):
    sql, params = super().as_sql(compiler, connection, **extra_context)
    if self.output_field.get_internal_type() == "DurationField":
        sql = "CAST(%s AS SIGNED)" % sql
    return sql, params

def as_oracle(self, compiler, connection, **extra_context):
    if (
        self.output_field.get_internal_type() == "DurationField"
        and not connection.features.supports_aggregation_over_interval_types
    ):
        expression = self.get_source_expressions()[0]
        options = self._get_repr_options()
        from django.db.backends.oracle.functions import (
            IntervalToSeconds,
            SecondsToInterval,
        )

        return compiler.compile(
            SecondsToInterval(
                self.__class__(IntervalToSeconds(expression), **options)
            )
        )
    return super().as_sql(compiler, connection, **extra_context)

def _resolve_output_field(self):
    source_fields = self.get_source_fields()
    if any(isinstance(s, DecimalField) for s in source_fields):
        return DecimalField()
    if any(isinstance(s, IntegerField) for s in source_fields):
        return FloatField()
    return super()._resolve_output_field() if source_fields else FloatField()

def __init__(self, expression, offset=1, default=None, **extra):
    if expression is None:
        raise ValueError(
            "%s requires a non-null source expression." % self.__class__.__name__
        )
    if offset is None or offset <= 0:
        raise ValueError(
            "%s requires a positive integer for the offset."
            % self.__class__.__name__
        )
    args = (expression, offset)
    if default is not None:
        args += (default,)
    super().__init__(*args, **extra)

def _resolve_output_field(self):
    sources = self.get_source_expressions()
    return sources[0].output_field

class NthValue(Func):
    function = "NTH_VALUE"
    window_compatible = True

def __init__(self, expression, nth=1, **extra):
    if expression is None:
        raise ValueError(
            "%s requires a non-null source expression." % self.__class__.__name__
        )
    if nth is None or nth <= 0:
        raise ValueError(
            "%s requires a positive integer as for nth." % self.__class__.__name__
        )
    super().__init__(expression, nth, **extra)

def _resolve_output_field(self):
    sources = self.get_source_expressions()
    return sources[0].output_field

def __init__(self, num_buckets=1, **extra):
    if num_buckets <= 0:
        raise ValueError("num_buckets must be greater than 0.")
    super().__init__(num_buckets, **extra)

def as_sql(self, compiler, connection, **extra_context):
    extra_context["db_type"] = self.output_field.cast_db_type(connection)
    return super().as_sql(compiler, connection, **extra_context)

def as_sqlite(self, compiler, connection, **extra_context):
    db_type = self.output_field.db_type(connection)
    if db_type in {"datetime", "time"}:
        # Use strftime as datetime/time don't keep fractional seconds.
        template = "strftime(%%s, %(expressions)s)"
        sql, params = super().as_sql(
            compiler, connection, template=template, **extra_context
        )
        format_string = "%H:%M:%f" if db_type == "time" else "%Y-%m-%d %H:%M:%f"
        params.insert(0, format_string)
        return sql, params
    elif db_type == "date":
        template = "date(%(expressions)s)"
        return super().as_sql(
            compiler, connection, template=template, **extra_context
        )
    return self.as_sql(compiler, connection, **extra_context)

def as_mysql(self, compiler, connection, **extra_context):
    template = None
    output_type = self.output_field.get_internal_type()
    # MySQL doesn't support explicit cast to float.
    if output_type == "FloatField":
        template = "(%(expressions)s + 0.0)"
    # MariaDB doesn't support explicit cast to JSON.
    elif output_type == "JSONField" and connection.mysql_is_mariadb:
        template = "JSON_EXTRACT(%(expressions)s, '$')"
    return self.as_sql(compiler, connection, template=template, **extra_context)

def as_postgresql(self, compiler, connection, **extra_context):
    # CAST would be valid too, but the :: shortcut syntax is more readable.
    # 'expressions' is wrapped in parentheses in case it's a complex
    # expression.
    return self.as_sql(
        compiler,
        connection,
        template="(%(expressions)s)::%(db_type)s",
        **extra_context,
    )

def as_oracle(self, compiler, connection, **extra_context):
    if self.output_field.get_internal_type() == "JSONField":
        # Oracle doesn't support explicit cast to JSON.
        template = "JSON_QUERY(%(expressions)s, '$')"
        return super().as_sql(
            compiler, connection, template=template, **extra_context
        )
    return self.as_sql(compiler, connection, **extra_context)

class Coalesce(Func):
    """Return, from left to right, the first non-null expression."""

    function = "COALESCE"

def __init__(self, *expressions, **extra):
    if len(expressions) < 2:
        raise ValueError("Coalesce must take at least two expressions")
    super().__init__(*expressions, **extra)

@property

def empty_result_set_value(self):
    for expression in self.get_source_expressions():
        result = expression.empty_result_set_value
        if result is NotImplemented or result is not None:
            return result
    return None

def as_oracle(self, compiler, connection, **extra_context):
    # Oracle prohibits mixing TextField (NCLOB) and CharField (NVARCHAR2),
    # so convert all fields to NCLOB when that type is expected.
    if self.output_field.get_internal_type() == "TextField":
        clone = self.copy()
        clone.set_source_expressions(
            [
                Func(expression, function="TO_NCLOB")
                for expression in self.get_source_expressions()
            ]
        )
        return super(Coalesce, clone).as_sql(compiler, connection, **extra_context)
    return self.as_sql(compiler, connection, **extra_context)

def __init__(self, expression, collation):
    if not (collation and self.collation_re.match(collation)):
