def _check_max_digits(self):
    try:
        max_digits = int(self.max_digits)
        if max_digits <= 0:
            raise ValueError()
    except TypeError:
        return [
            checks.Error(
                "DecimalFields must define a 'max_digits' attribute.",
                obj=self,
                id="fields.E132",
            )
        ]
    except ValueError:
