def __init__(self, ordinal, refs, source):
    self.ordinal = ordinal
    super().__init__(refs, source)

class SQLCompiler:
    # Multiline ordering SQL clause may appear from RawSQL.
    ordering_parts = _lazy_re_compile(
        r"^(.*)\s(?:ASC|DESC).*",
        re.MULTILINE | re.DOTALL,
    )

def __repr__(self):
    return (
        f"<{self.__class__.__qualname__} "
        f"model={self.query.model.__qualname__} "
        f"connection={self.connection!r} using={self.using!r}>"
    )

def setup_query(self, with_col_aliases=False):
    if all(self.query.alias_refcount[a] == 0 for a in self.query.alias_map):
        self.query.get_initial_alias()
    self.select, self.klass_info, self.annotation_col_map = self.get_select(
        with_col_aliases=with_col_aliases,
    )
    self.col_count = len(self.select)

def get_select(self, with_col_aliases=False):
    """
    Return three values:
    - a list of 3-tuples of (expression, (sql, params), alias)
    - a klass_info structure,
    - a dictionary of annotations

    The (sql, params) is what the expression will produce, and alias is the
    "AS alias" for the column (possibly None).

    The klass_info structure contains the following information:
    - The base model of the query.
    - Which columns for that model are present in the query (by
      position of the select clause).
    - related_klass_infos: [f, klass_info] to descent into

    The annotations is a dictionary of {'attname': column position} values.
    """
    select = []
    klass_info = None
    annotations = {}
    assert not (self.query.select and self.query.default_cols)
    select_mask = self.query.get_select_mask()
    if self.query.default_cols:
        cols = self.get_default_columns(select_mask)
    else:
        # self.query.select is a special case. These columns never go to
        # any model.
        cols = self.query.select
    selected = []
    select_fields = None
    if self.query.selected is None:
        selected = [
            *(
                (alias, RawSQL(*args))
                for alias, args in self.query.extra_select.items()
            ),
            *((None, col) for col in cols),
            *self.query.annotation_select.items(),
        ]
        select_fields = list(
            range(
                len(self.query.extra_select),
                len(self.query.extra_select) + len(cols),
            )
        )
    else:
        select_fields = []
        for index, (alias, expression) in enumerate(self.query.selected.items()):
            # Reference to an annotation.
            if isinstance(expression, str):
                expression = self.query.annotations[expression]
            # Reference to a column.
            elif isinstance(expression, int):
                select_fields.append(index)
                expression = cols[expression]
            # ColPairs cannot be aliased.
            if isinstance(expression, ColPairs):
                alias = None
            selected.append((alias, expression))
    if select_fields:
        klass_info = {"model": self.query.model, "select_fields": select_fields}

    for select_idx, (alias, expression) in enumerate(selected):
        if alias:
            annotations[alias] = select_idx
        select.append((expression, alias))

    if self.query.select_related:
        related_klass_infos = self.get_related_selections(select, select_mask)
        klass_info["related_klass_infos"] = related_klass_infos

    def get_select_from_parent(klass_info):
        for ki in klass_info["related_klass_infos"]:
            if ki["from_parent"]:
                ki["select_fields"] = (
                    klass_info["select_fields"] + ki["select_fields"]
                )
            get_select_from_parent(ki)

    get_select_from_parent(klass_info)

ret = []
col_idx = 1
for col, alias in select:
    try:
        sql, params = self.compile(col)
    except EmptyResultSet:
        empty_result_set_value = getattr(
            col, "empty_result_set_value", NotImplemented
        )
        if empty_result_set_value is NotImplemented:
            # Select a predicate that's always False.
            sql, params = "0", ()
        else:
            sql, params = self.compile(Value(empty_result_set_value))
    except FullResultSet:
        sql, params = self.compile(Value(True))
    else:
        sql, params = col.select_format(self, sql, params)
    if alias is None and with_col_aliases:
        alias = f"col{col_idx}"
        col_idx += 1
    ret.append((col, (sql, params), alias))
return ret, klass_info, annotations

def _order_by_pairs(self):
    if self.query.extra_order_by:
        ordering = self.query.extra_order_by
    elif not self.query.default_ordering:
        ordering = self.query.order_by
    elif self.query.order_by:
        ordering = self.query.order_by
    elif (meta := self.query.get_meta()) and meta.ordering:
        ordering = meta.ordering
        self._meta_ordering = ordering
    else:
        ordering = []
    if self.query.standard_ordering:
        default_order, _ = ORDER_DIR["ASC"]
    else:
        default_order, _ = ORDER_DIR["DESC"]

    selected_exprs = {}
    # Avoid computing `selected_exprs` if there is no `ordering` as it's
    # relatively expensive.
    if ordering and (select := self.select):
        for ordinal, (expr, _, alias) in enumerate(select, start=1):
            pos_expr = PositionRef(ordinal, alias, expr)
            if alias:
                selected_exprs[alias] = pos_expr
            selected_exprs[expr] = pos_expr

    for field in ordering:
        if hasattr(field, "resolve_expression"):
            if isinstance(field, Value):
                # output_field must be resolved for constants.
                field = Cast(field, field.output_field)
            if not isinstance(field, OrderBy):
                field = field.asc()
            if not self.query.standard_ordering:
                field = field.copy()
                field.reverse_ordering()
            select_ref = selected_exprs.get(field.expression)
            if select_ref or (
                isinstance(field.expression, F)
                and (select_ref := selected_exprs.get(field.expression.name))
            ):
                # Emulation of NULLS (FIRST|LAST) cannot be combined with
                # the usage of ordering by position.
                if (
                    field.nulls_first is None and field.nulls_last is None
                ) or self.connection.features.supports_order_by_nulls_modifier:
                    field = field.copy()
                    field.expression = select_ref
                # Alias collisions are not possible when dealing with
                # combined queries so fallback to it if emulation of NULLS
                # handling is required.
                elif self.query.combinator:
                    field = field.copy()
                    field.expression = Ref(select_ref.refs, select_ref.source)
            yield field, select_ref is not None
            continue
        if field == "?":  # random
            yield OrderBy(Random()), False
            continue

        col, order = get_order_dir(field, default_order)
        descending = order == "DESC"

        if select_ref := selected_exprs.get(col):
            # Reference to expression in SELECT clause
            yield (
                OrderBy(
                    select_ref,
                    descending=descending,
                ),
                True,
            )
            continue

        if expr := self.query.annotations.get(col):
            ref = col
            transforms = []
        else:
            ref, *transforms = col.split(LOOKUP_SEP)
            expr = self.query.annotations.get(ref)
        if expr:
            if self.query.combinator and self.select:
                if transforms:
                    raise NotImplementedError(
                        "Ordering combined queries by transforms is not "
                        "implemented."
                    )
                # Don't use the resolved annotation because other
                # combined queries might define it differently.
                expr = F(ref)
            if transforms:
                for name in transforms:
                    expr = self.query.try_transform(expr, name)
            if isinstance(expr, Value):
                # output_field must be resolved for constants.
                expr = Cast(expr, expr.output_field)
            yield OrderBy(expr, descending=descending), False
            continue

        if "." in field:
            # This came in through an extra(order_by=...) addition. Pass it
            # on verbatim.
            table, col = col.split(".", 1)
            yield (
                OrderBy(
                    RawSQL(
                        "%s.%s" % (self.quote_name_unless_alias(table), col), []
                    ),
                    descending=descending,
                ),
                False,
            )
            continue

        if self.query.extra and col in self.query.extra:
            if col in self.query.extra_select:
                yield (
                    OrderBy(
                        Ref(col, RawSQL(*self.query.extra[col])),
                        descending=descending,
                    ),
                    True,
                )
            else:
                yield (
                    OrderBy(RawSQL(*self.query.extra[col]), descending=descending),
                    False,
                )
        else:
            if self.query.combinator and self.select:
                # Don't use the first model's field because other
                # combinated queries might define it differently.
                yield OrderBy(F(col), descending=descending), False
            else:
                # 'col' is of the form 'field' or 'field1__field2' or
                # '-field1__field2__field', etc.
                yield from self.find_ordering_name(
                    field,
                    self.query.get_meta(),
                    default_order=default_order,
                )

def get_extra_select(self, order_by, select):
    extra_select = []
    if self.query.distinct and not self.query.distinct_fields:
        select_sql = [t[1] for t in select]
        for expr, (sql, params, is_ref) in order_by:
            without_ordering = self.ordering_parts.search(sql)[1]
            if not is_ref and (without_ordering, params) not in select_sql:
                extra_select.append((expr, (without_ordering, params), None))
    return extra_select

def compile(self, node):
    vendor_impl = getattr(node, "as_" + self.connection.vendor, None)
    if vendor_impl:
        sql, params = vendor_impl(self, self.connection)
    else:
        sql, params = node.as_sql(self, self.connection)
    return sql, params

def get_combinator_sql(self, combinator, all):
    features = self.connection.features
    compilers = [
        query.get_compiler(self.using, self.connection, self.elide_empty)
        for query in self.query.combined_queries
    ]
    if not features.supports_slicing_ordering_in_compound:
        for compiler in compilers:
            if compiler.query.is_sliced:
                raise DatabaseError(
                    "LIMIT/OFFSET not allowed in subqueries of compound statements."
                )
            if compiler.get_order_by():
                raise DatabaseError(
                    "ORDER BY not allowed in subqueries of compound statements."
                )
    parts = []
    empty_compiler = None
    for compiler in compilers:
        try:
            parts.append(self._get_combinator_part_sql(compiler))
        except EmptyResultSet:
            # Omit the empty queryset with UNION and with DIFFERENCE if the
            # first queryset is nonempty.
            if combinator == "union" or (combinator == "difference" and parts):
                empty_compiler = compiler
                continue
            raise
    if not parts:
        raise EmptyResultSet
    elif len(parts) == 1 and combinator == "union" and self.query.is_sliced:
        # A sliced union cannot be composed of a single component because
        # in the event the later is also sliced it might result in invalid
        # SQL due to the usage of multiple LIMIT clauses. Prevent that from
        # happening by always including an empty resultset query to force
        # the creation of an union.
        empty_compiler.elide_empty = False
        parts.append(self._get_combinator_part_sql(empty_compiler))
    combinator_sql = self.connection.ops.set_operators[combinator]
    if all and combinator == "union":
        combinator_sql += " ALL"
    braces = "{}"
    if not self.query.subquery and features.supports_slicing_ordering_in_compound:
        braces = "({})"
    sql_parts, args_parts = zip(
        *((braces.format(sql), args) for sql, args in parts)
    )
    result = [" {} ".format(combinator_sql).join(sql_parts)]
    params = []
    for part in args_parts:
        params.extend(part)
    return result, params

def get_qualify_sql(self):
    where_parts = []
    if self.where:
        where_parts.append(self.where)
    if self.having:
        where_parts.append(self.having)
    inner_query = self.query.clone()
    inner_query.subquery = True
    inner_query.where = inner_query.where.__class__(where_parts)
    # Augment the inner query with any window function references that
    # might have been masked via values() and alias(). If any masked
    # aliases are added they'll be masked again to avoid fetching
    # the data in the `if qual_aliases` branch below.
    select = {
        expr: alias for expr, _, alias in self.get_select(with_col_aliases=True)[0]
    }
    select_aliases = set(select.values())
    qual_aliases = set()
    replacements = {}

def as_sql(self, with_limits=True, with_col_aliases=False):
    """
    Create the SQL for this query. Return the SQL string and list of
    parameters.

    If 'with_limits' is False, any limit/offset information is not included
    in the query.
    """
    refcounts_before = self.query.alias_refcount.copy()
    try:
        combinator = self.query.combinator
        extra_select, order_by, group_by = self.pre_sql_setup(
            with_col_aliases=with_col_aliases or bool(combinator),
        )
        for_update_part = None
        # Is a LIMIT/OFFSET clause needed?
        with_limit_offset = with_limits and self.query.is_sliced
        combinator = self.query.combinator
        features = self.connection.features
        if combinator:
            if not getattr(features, "supports_select_{}".format(combinator)):
                raise NotSupportedError(
                    "{} is not supported on this database backend.".format(
                        combinator
                    )
                )
            result, params = self.get_combinator_sql(
                combinator, self.query.combinator_all
            )
        elif self.qualify:
            result, params = self.get_qualify_sql()
            order_by = None
        else:
            distinct_fields, distinct_params = self.get_distinct()
            # This must come after 'select', 'ordering', and 'distinct'
            # (see docstring of get_from_clause() for details).
            from_, f_params = self.get_from_clause()
            try:
                where, w_params = (
                    self.compile(self.where) if self.where is not None else ("", [])
                )
            except EmptyResultSet:
                if self.elide_empty:
                    raise
                # Use a predicate that's always False.
                where, w_params = "0 = 1", []
            except FullResultSet:
                where, w_params = "", []
            try:
                having, h_params = (
                    self.compile(self.having)
                    if self.having is not None
                    else ("", [])
                )
            except FullResultSet:
                having, h_params = "", []
            result = ["SELECT"]
            params = []

            if self.query.distinct:
                distinct_result, distinct_params = self.connection.ops.distinct_sql(
                    distinct_fields,
                    distinct_params,
                )
                result += distinct_result
                params += distinct_params

            out_cols = []
            for _, (s_sql, s_params), alias in self.select + extra_select:
                if alias:
                    s_sql = "%s AS %s" % (
                        s_sql,
                        self.connection.ops.quote_name(alias),
                    )
                params.extend(s_params)
                out_cols.append(s_sql)

            result += [", ".join(out_cols)]
            if from_:
                result += ["FROM", *from_]
            elif self.connection.features.bare_select_suffix:
                result += [self.connection.features.bare_select_suffix]
            params.extend(f_params)

            if self.query.select_for_update and features.has_select_for_update:
                if (
                    self.connection.get_autocommit()
                    # Don't raise an exception when database doesn't
                    # support transactions, as it's a noop.
                    and features.supports_transactions
                ):
                    raise TransactionManagementError(
                        "select_for_update cannot be used outside of a transaction."
                    )

                if (
                    with_limit_offset
                    and not features.supports_select_for_update_with_limit
                ):
                    raise NotSupportedError(
                        "LIMIT/OFFSET is not supported with "
                        "select_for_update on this database backend."
                    )
                nowait = self.query.select_for_update_nowait
                skip_locked = self.query.select_for_update_skip_locked
                of = self.query.select_for_update_of
                no_key = self.query.select_for_no_key_update
                # If it's a NOWAIT/SKIP LOCKED/OF/NO KEY query but the
                # backend doesn't support it, raise NotSupportedError to
                # prevent a possible deadlock.
                if nowait and not features.has_select_for_update_nowait:
                    raise NotSupportedError(
                        "NOWAIT is not supported on this database backend."
                    )
                elif skip_locked and not features.has_select_for_update_skip_locked:
                    raise NotSupportedError(
                        "SKIP LOCKED is not supported on this database backend."
                    )
                elif of and not features.has_select_for_update_of:
                    raise NotSupportedError(
                        "FOR UPDATE OF is not supported on this database backend."
                    )
                elif no_key and not features.has_select_for_no_key_update:
                    raise NotSupportedError(
                        "FOR NO KEY UPDATE is not supported on this "
                        "database backend."
                    )
                for_update_part = self.connection.ops.for_update_sql(
                    nowait=nowait,
                    skip_locked=skip_locked,
                    of=self.get_select_for_update_of_arguments(),
                    no_key=no_key,
                )

            if for_update_part and features.for_update_after_from:
                result.append(for_update_part)

            if where:
                result.append("WHERE %s" % where)
                params.extend(w_params)

            grouping = []
            for g_sql, g_params in group_by:
                grouping.append(g_sql)
                params.extend(g_params)
            if grouping:
                if distinct_fields:
                    raise NotImplementedError(
                        "annotate() + distinct(fields) is not implemented."
                    )
                order_by = order_by or self.connection.ops.force_no_ordering()
                result.append("GROUP BY %s" % ", ".join(grouping))
                if self._meta_ordering:
                    order_by = None
            if having:
                if not grouping:
                    result.extend(self.connection.ops.force_group_by())
                result.append("HAVING %s" % having)
                params.extend(h_params)

        if self.query.explain_info:
            result.insert(
                0,
                self.connection.ops.explain_query_prefix(
                    self.query.explain_info.format,
                    **self.query.explain_info.options,
                ),
            )

        if order_by:
            ordering = []
            for _, (o_sql, o_params, _) in order_by:
                ordering.append(o_sql)
                params.extend(o_params)
            order_by_sql = "ORDER BY %s" % ", ".join(ordering)
            if combinator and features.requires_compound_order_by_subquery:
                result = ["SELECT * FROM (", *result, ")", order_by_sql]
            else:
                result.append(order_by_sql)

        if with_limit_offset:
            result.append(
                self.connection.ops.limit_offset_sql(
                    self.query.low_mark, self.query.high_mark
                )
            )

        if for_update_part and not features.for_update_after_from:
            result.append(for_update_part)

        if self.query.subquery and extra_select:
            # If the query is used as a subquery, the extra selects would
            # result in more columns than the left-hand side expression is
            # expecting. This can happen when a subquery uses a combination
            # of order_by() and distinct(), forcing the ordering expressions
            # to be selected as well. Wrap the query in another subquery
            # to exclude extraneous selects.
            sub_selects = []
            sub_params = []
            for index, (select, _, alias) in enumerate(self.select, start=1):
                if alias:
                    sub_selects.append(
                        "%s.%s"
                        % (
                            self.connection.ops.quote_name("subquery"),
                            self.connection.ops.quote_name(alias),
                        )
                    )
                else:
                    select_clone = select.relabeled_clone(
                        {select.alias: "subquery"}
                    )
                    subselect, subparams = select_clone.as_sql(
                        self, self.connection
                    )
                    sub_selects.append(subselect)
                    sub_params.extend(subparams)
            return "SELECT %s FROM (%s) subquery" % (
                ", ".join(sub_selects),
                " ".join(result),
            ), tuple(sub_params + params)

        return " ".join(result), tuple(params)
    finally:
        # Finally do cleanup - get rid of the joins we created above.
        self.query.reset_refcounts(refcounts_before)

def _get_field_choices():
    direct_choices = (f.name for f in opts.fields if f.is_relation)
    reverse_choices = (
        f.field.related_query_name()
        for f in opts.related_objects
        if f.field.unique
    )
    return chain(
        direct_choices, reverse_choices, self.query._filtered_relations
    )

related_klass_infos = []
if not restricted and cur_depth > self.query.max_depth:
    # We've recursed far enough; bail out.
    return related_klass_infos

if not opts:
    opts = self.query.get_meta()
    root_alias = self.query.get_initial_alias()

# Setup for the case when only particular related fields should be
# included in the related selection.
fields_found = set()
if requested is None:
    restricted = isinstance(self.query.select_related, dict)
    if restricted:
        requested = self.query.select_related

def local_setter(final_field, obj, from_obj):
    # Set a reverse fk object when relation is non-empty.
    if from_obj:
        final_field.remote_field.set_cached_value(from_obj, obj)

def _get_parent_klass_info(klass_info):
    concrete_model = klass_info["model"]._meta.concrete_model
    for parent_model, parent_link in concrete_model._meta.parents.items():
        all_parents = parent_model._meta.all_parents
        yield {
            "model": parent_model,
            "field": parent_link,
            "reverse": False,
            "select_fields": [
                select_index
                for select_index in klass_info["select_fields"]
                # Selected columns from a model or its parents.
                if (
                    self.select[select_index][0].target.model == parent_model
                    or self.select[select_index][0].target.model in all_parents
                )
            ],
        }

def _get_field_choices():
    """Yield all allowed field paths in breadth-first search order."""
    queue = collections.deque([(None, self.klass_info)])
    while queue:
        parent_path, klass_info = queue.popleft()
        if parent_path is None:
            path = []
            yield "self"
        else:
            field = klass_info["field"]
            if klass_info["reverse"]:
                field = field.remote_field
            path = [*parent_path, field.name]
            yield LOOKUP_SEP.join(path)
        queue.extend(
            (path, klass_info)
            for klass_info in _get_parent_klass_info(klass_info)
        )
        queue.extend(
            (path, klass_info)
            for klass_info in klass_info.get("related_klass_infos", [])
        )

if not self.klass_info:
    return []
result = []
invalid_names = []
for name in self.query.select_for_update_of:
    klass_info = self.klass_info
    if name == "self":
        col = _get_first_selected_col_from_model(klass_info)
    else:
        for part in name.split(LOOKUP_SEP):
            klass_infos = (
                *klass_info.get("related_klass_infos", []),
                *_get_parent_klass_info(klass_info),
            )
            for related_klass_info in klass_infos:
                field = related_klass_info["field"]
                if related_klass_info["reverse"]:
                    field = field.remote_field
                if field.name == part:
                    klass_info = related_klass_info
                    break
            else:
                klass_info = None
                break
        if klass_info is None:
            invalid_names.append(name)
            continue
        col = _get_first_selected_col_from_model(klass_info)
    if col is not None:
        if self.connection.features.select_for_update_of_column:
            result.append(self.compile(col)[0])
        else:
            result.append(self.quote_name_unless_alias(col.alias))
if invalid_names:
    raise FieldError(
        "Invalid field name(s) given in select_for_update(of=(...)): %s. "
        "Only relational fields followed in the query are allowed. "
        "Choices are: %s."
        % (
            ", ".join(invalid_names),
            ", ".join(_get_field_choices()),
        )
    )
return result

def get_converters(self, expressions):
    i = 0
    converters = {}

    for expression in expressions:
        if isinstance(expression, ColPairs):
            cols = expression.get_source_expressions()
            cols_converters = self.get_converters(cols)
            for j, (convs, col) in cols_converters.items():
                converters[i + j] = (convs, col)
            i += len(expression)
        elif expression:
            backend_converters = self.connection.ops.get_db_converters(expression)
            field_converters = expression.get_db_converters(self.connection)
            if backend_converters or field_converters:
                converters[i] = (backend_converters + field_converters, expression)
            i += 1
        else:
            i += 1

    return converters

def apply_converters(self, rows, converters):
    connection = self.connection
    converters = list(converters.items())
    for row in map(list, rows):
        for pos, (convs, expression) in converters:
            value = row[pos]
            for converter in convs:
                value = converter(value, expression, connection)
            row[pos] = value
        yield row

def has_composite_fields(self, expressions):
    # Check for composite fields before calling the relatively costly
    # composite_fields_to_tuples.
    return any(isinstance(expression, ColPairs) for expression in expressions)

def composite_fields_to_tuples(self, rows, expressions):
    col_pair_slices = [
        slice(i, i + len(expression))
        for i, expression in enumerate(expressions)
        if isinstance(expression, ColPairs)
    ]

    for row in map(list, rows):
        for pos in col_pair_slices:
            row[pos] = (tuple(row[pos]),)

        yield row

def results_iter(
    self,
    results=None,
    tuple_expected=False,
    chunked_fetch=False,
    chunk_size=GET_ITERATOR_CHUNK_SIZE,
):
    """Return an iterator over the results from executing this query."""
    if results is None:
        results = self.execute_sql(
            MULTI, chunked_fetch=chunked_fetch, chunk_size=chunk_size
        )
    fields = [s[0] for s in self.select[0 : self.col_count]]
    converters = self.get_converters(fields)
    rows = chain.from_iterable(results)
    if converters:
        rows = self.apply_converters(rows, converters)
    if self.has_composite_fields(fields):
        rows = self.composite_fields_to_tuples(rows, fields)
    if tuple_expected:
        rows = map(tuple, rows)
    return rows

def has_results(self):
    """
    Backends (e.g. NoSQL) can override this in order to use optimized
    versions of "query has any results."
    """
    return bool(self.execute_sql(SINGLE))

def execute_sql(
    self, result_type=MULTI, chunked_fetch=False, chunk_size=GET_ITERATOR_CHUNK_SIZE
):
    """
    Run the query against the database and return the result(s). The
    return value depends on the value of result_type.

    When result_type is:
    - MULTI: Retrieves all rows using fetchmany(). Wraps in an iterator for
       chunked reads when supported.
    - SINGLE: Retrieves a single row using fetchone().
    - ROW_COUNT: Retrieves the number of rows in the result.
    - CURSOR: Runs the query, and returns the cursor object. It is the
       caller's responsibility to close the cursor.
    """
    result_type = result_type or NO_RESULTS
    try:
        sql, params = self.as_sql()
        if not sql:
            raise EmptyResultSet
    except EmptyResultSet:
        if result_type == MULTI:
            return iter([])
        else:
            return
    if chunked_fetch:
        cursor = self.connection.chunked_cursor()
    else:
        cursor = self.connection.cursor()
    try:
        cursor.execute(sql, params)
    except Exception:
        # Might fail for server-side cursors (e.g. connection closed)
        cursor.close()
        raise

    if result_type == ROW_COUNT:
        try:
            return cursor.rowcount
        finally:
            cursor.close()
    if result_type == CURSOR:
        # Give the caller the cursor to process and close.
        return cursor
    if result_type == SINGLE:
        try:
            val = cursor.fetchone()
            if val:
                return val[0 : self.col_count]
            return val
        finally:
            # done with the cursor
            cursor.close()
    if result_type == NO_RESULTS:
        cursor.close()
        return

    result = cursor_iter(
        cursor,
        self.connection.features.empty_fetchmany_value,
        self.col_count if self.has_extra_select else None,
        chunk_size,
    )
    if not chunked_fetch or not self.connection.features.can_use_chunked_reads:
        # If we are using non-chunked reads, we return the same data
        # structure as normally, but ensure it is all read into memory
        # before going any further. Use chunked_fetch if requested,
        # unless the database doesn't support it.
        return list(result)
    return result

def explain_query(self):
    result = list(self.execute_sql())
    # Some backends return 1 item tuples with strings, and others return
    # tuples with integers and strings. Flatten them out into strings.
    format_ = self.query.explain_info.format
    output_formatter = json.dumps if format_ and format_.lower() == "json" else str
    for row in result:
        for value in row:
            if not isinstance(value, str):
                yield " ".join([output_formatter(c) for c in value])
            else:
                yield value

class SQLInsertCompiler(SQLCompiler):
    returning_fields = None
    returning_params = ()

def prepare_value(self, field, value):
    """
    Prepare a value to be used in a query by resolving it if it is an
    expression and otherwise calling the field's get_db_prep_save().
    """
    if hasattr(value, "resolve_expression"):
        value = value.resolve_expression(
            self.query, allow_joins=False, for_save=True
        )
        # Don't allow values containing Col expressions. They refer to
        # existing columns on a row, but in the case of insert the row
        # doesn't exist yet.
        if value.contains_column_references:
            raise ValueError(
                'Failed to insert expression "%s" on %s. F() expressions '
                "can only be used to update, not to insert." % (value, field)
            )
        if value.contains_aggregate:
            raise FieldError(
                "Aggregate functions are not allowed in this query "
                "(%s=%r)." % (field.name, value)
            )
        if value.contains_over_clause:
            raise FieldError(
                "Window expressions are not allowed in this query (%s=%r)."
                % (field.name, value)
            )
    return field.get_db_prep_save(value, connection=self.connection)

def pre_save_val(self, field, obj):
    """
    Get the given field's value off the given obj. pre_save() is used for
    things like auto_now on DateTimeField. Skip it if this is a raw query.
    """
    if self.query.raw:
        return getattr(obj, field.attname)
    return field.pre_save(obj, add=True)

def execute_sql(self, returning_fields=None):
    assert not (
        returning_fields
        and len(self.query.objs) != 1
        and not self.connection.features.can_return_rows_from_bulk_insert
    )
    opts = self.query.get_meta()
    self.returning_fields = returning_fields
    cols = []
    with self.connection.cursor() as cursor:
        for sql, params in self.as_sql():
            cursor.execute(sql, params)
        if not self.returning_fields:
            return []
        if (
            self.connection.features.can_return_rows_from_bulk_insert
            and len(self.query.objs) > 1
        ):
            rows = self.connection.ops.fetch_returned_insert_rows(cursor)
            cols = [field.get_col(opts.db_table) for field in self.returning_fields]
        elif self.connection.features.can_return_columns_from_insert:
            assert len(self.query.objs) == 1
            rows = [
                self.connection.ops.fetch_returned_insert_columns(
                    cursor,
                    self.returning_params,
                )
            ]
            cols = [field.get_col(opts.db_table) for field in self.returning_fields]
        elif returning_fields and isinstance(
            returning_field := returning_fields[0], AutoField
        ):
            cols = [returning_field.get_col(opts.db_table)]
            rows = [
                (
                    self.connection.ops.last_insert_id(
                        cursor,
                        opts.db_table,
                        returning_field.column,
                    ),
                )
            ]
        else:
            # Backend doesn't support returning fields and no auto-field
            # that can be retrieved from `last_insert_id` was specified.
            return []
    converters = self.get_converters(cols)
    if converters:
        rows = self.apply_converters(rows, converters)
    return list(rows)

def single_alias(self):
    # Ensure base table is in aliases.
    self.query.get_initial_alias()
    return sum(self.query.alias_refcount[t] > 0 for t in self.query.alias_map) == 1

@classmethod

def _expr_refs_base_model(cls, expr, base_model):
    if isinstance(expr, Query):
        return expr.model == base_model
    if not hasattr(expr, "get_source_expressions"):
        return False
    return any(
        cls._expr_refs_base_model(source_expr, base_model)
        for source_expr in expr.get_source_expressions()
    )

@cached_property

def contains_self_reference_subquery(self):
    return any(
        self._expr_refs_base_model(expr, self.query.model)
        for expr in chain(
            self.query.annotations.values(), self.query.where.children
        )
    )

def _as_sql(self, query):
    delete = "DELETE FROM %s" % self.quote_name_unless_alias(query.base_table)
    try:
        where, params = self.compile(query.where)
    except FullResultSet:
        return delete, ()
    return f"{delete} WHERE {where}", tuple(params)

def as_sql(self):
    """
    Create the SQL for this query. Return the SQL string and list of
    parameters.
    """
    self.pre_sql_setup()
    if not self.query.values:
        return "", ()
    qn = self.quote_name_unless_alias
    values, update_params = [], []
    for field, model, val in self.query.values:
        if hasattr(val, "resolve_expression"):
            val = val.resolve_expression(
                self.query, allow_joins=False, for_save=True
            )
            if val.contains_aggregate:
                raise FieldError(
                    "Aggregate functions are not allowed in this query "
                    "(%s=%r)." % (field.name, val)
                )
            if val.contains_over_clause:
                raise FieldError(
                    "Window expressions are not allowed in this query "
                    "(%s=%r)." % (field.name, val)
                )
            if isinstance(val, ColPairs):
                raise FieldError(
                    "Composite primary keys expressions are not allowed "
                    "in this query (%s=F('pk'))." % field.name
                )
        elif hasattr(val, "prepare_database_save"):
            if field.remote_field:
                val = val.prepare_database_save(field)
            else:
                raise TypeError(
                    "Tried to update field %s with a model instance, %r. "
                    "Use a value compatible with %s."
                    % (field, val, field.__class__.__name__)
                )
        val = field.get_db_prep_save(val, connection=self.connection)

        # Getting the placeholder for the field.
        if hasattr(field, "get_placeholder"):
            placeholder = field.get_placeholder(val, self, self.connection)
        else:
            placeholder = "%s"
        name = field.column
        if hasattr(val, "as_sql"):
            sql, params = self.compile(val)
            values.append("%s = %s" % (qn(name), placeholder % sql))
            update_params.extend(params)
        elif val is not None:
            values.append("%s = %s" % (qn(name), placeholder))
            update_params.append(val)
        else:
            values.append("%s = NULL" % qn(name))
    table = self.query.base_table
    result = [
        "UPDATE %s SET" % qn(table),
        ", ".join(values),
    ]
    try:
        where, params = self.compile(self.query.where)
    except FullResultSet:
        params = []
    else:
        result.append("WHERE %s" % where)
    return " ".join(result), tuple(update_params + params)

def cursor_iter(cursor, sentinel, col_count, itersize):
    """
    Yield blocks of rows from a cursor and ensure the cursor is closed when
    done.
    """
    try:
        for rows in iter((lambda: cursor.fetchmany(itersize)), sentinel):
            yield rows if col_count is None else [r[:col_count] for r in rows]
    finally:
        cursor.close()

def get_field_names_from_opts(opts):
    if opts is None:
        return set()
    return set(
        chain.from_iterable(
            (f.name, f.attname) if f.concrete else (f.name,) for f in opts.get_fields()
        )
    )

def get_paths_from_expression(expr):
    if isinstance(expr, F):
        yield expr.name
    elif hasattr(expr, "flatten"):
        for child in expr.flatten():
            if isinstance(child, F):
                yield child.name
            elif isinstance(child, Q):
                yield from get_children_from_q(child)

def get_children_from_q(q):
    for child in q.children:
        if isinstance(child, Node):
            yield from get_children_from_q(child)
        elif isinstance(child, tuple):
            lhs, rhs = child
            yield lhs
            if hasattr(rhs, "resolve_expression"):
                yield from get_paths_from_expression(rhs)
        elif hasattr(child, "resolve_expression"):
            yield from get_paths_from_expression(child)

def get_child_with_renamed_prefix(prefix, replacement, child):
    from django.db.models.query import QuerySet

    if isinstance(child, Node):
        return rename_prefix_from_q(prefix, replacement, child)
    if isinstance(child, tuple):
        lhs, rhs = child
        if lhs.startswith(prefix + LOOKUP_SEP):
            lhs = lhs.replace(prefix, replacement, 1)
        if not isinstance(rhs, F) and hasattr(rhs, "resolve_expression"):
            rhs = get_child_with_renamed_prefix(prefix, replacement, rhs)
        return lhs, rhs

    if isinstance(child, F):
        child = child.copy()
        if child.name.startswith(prefix + LOOKUP_SEP):
            child.name = child.name.replace(prefix, replacement, 1)
    elif isinstance(child, QuerySet):
        # QuerySet may contain OuterRef() references which cannot work properly
        # without repointing to the filtered annotation and will spawn a
        # different JOIN. Always raise ValueError instead of providing partial
        # support in other cases.
        raise ValueError(
            "Passing a QuerySet within a FilteredRelation is not supported."
        )
    elif hasattr(child, "resolve_expression"):
        child = child.copy()
        child.set_source_expressions(
            [
                get_child_with_renamed_prefix(prefix, replacement, grand_child)
                for grand_child in child.get_source_expressions()
            ]
        )
    return child

def rename_prefix_from_q(prefix, replacement, q):
    return Q.create(
        [get_child_with_renamed_prefix(prefix, replacement, c) for c in q.children],
        q.connector,
        q.negated,
    )


JoinInfo = namedtuple(
    "JoinInfo",
    ("final_field", "targets", "opts", "joins", "path", "transform_function"),
)

def __init__(self, sql, using, params=()):
    self.params = params
    self.sql = sql
    self.using = using
    self.cursor = None

    # Mirror some properties of a normal query so that
    # the compiler can be used to process results.
    self.low_mark, self.high_mark = 0, None  # Used for offset/limit
    self.extra_select = {}
    self.annotation_select = {}

def get_columns(self):
    if self.cursor is None:
        self._execute_query()
    converter = connections[self.using].introspection.identifier_converter
    return [converter(column_meta[0]) for column_meta in self.cursor.description]

def __iter__(self):
    # Always execute a new query for a new iterator.
    # This could be optimized with a cache at the expense of RAM.
    self._execute_query()
    if not connections[self.using].features.can_use_chunked_reads:
        # If the database can't use chunked reads we need to make sure we
        # evaluate the entire query up front.
        result = list(self.cursor)
    else:
        result = self.cursor
    return iter(result)

def __repr__(self):
    return "<%s: %s>" % (self.__class__.__name__, self)

@property

def params_type(self):
    if self.params is None:
        return None
    return dict if isinstance(self.params, Mapping) else tuple

def __str__(self):
    if self.params_type is None:
        return self.sql
    return self.sql % self.params_type(self.params)

    def _execute_query(self):
        connection = connections[self.using]

        # Adapt parameters to the database, as much as possible considering
        # that the target type isn't known. See #17755.
        params_type = self.params_type
        adapter = connection.ops.adapt_unknown_value
        if params_type is tuple:
            params = tuple(adapter(val) for val in self.params)
        elif params_type is dict:
            params = {key: adapter(val) for key, val in self.params.items()}
        elif params_type is None:
            params = None
        else:
            raise RuntimeError("Unexpected params type: %s" % params_type)

        self.cursor = connection.cursor()
        self.cursor.execute(self.sql, params)


ExplainInfo = namedtuple("ExplainInfo", ("format", "options"))

def output_field(self):
    if len(self.select) == 1:
        select = self.select[0]
        return getattr(select, "target", None) or select.field
    elif len(self.annotation_select) == 1:
        return next(iter(self.annotation_select.values())).output_field

@cached_property

def base_table(self):
    for alias in self.alias_map:
        return alias

def sql_with_params(self):
    """
    Return the query as an SQL string and the parameters that will be
    substituted into the query.
    """
    return self.get_compiler(DEFAULT_DB_ALIAS).as_sql()

def get_compiler(self, using=None, connection=None, elide_empty=True):
    if using is None and connection is None:
        raise ValueError("Need either using or connection")
    if using:
        connection = connections[using]
    return connection.ops.compiler(self.compiler)(
        self, connection, using, elide_empty
    )

def _get_col(self, target, field, alias):
    if not self.alias_cols:
        alias = None
    return target.get_col(alias, field)

def exists(self, limit=True):
    q = self.clone()
    if not (q.distinct and q.is_sliced):
        if q.group_by is True:
            q.add_fields(
                (f.attname for f in self.model._meta.concrete_fields), False
            )
            # Disable GROUP BY aliases to avoid orphaning references to the
            # SELECT clause which is about to be cleared.
            q.set_group_by(allow_aliases=False)
        q.clear_select_clause()
    if q.combined_queries and q.combinator == "union":
        q.combined_queries = tuple(
            combined_query.exists(limit=False)
            for combined_query in q.combined_queries
        )
    q.clear_ordering(force=True)
    if limit is True:
        q.set_limits(high=1)
    q.add_annotation(Value(1), "a")
    return q

def has_results(self, using):
    q = self.exists()
    compiler = q.get_compiler(using=using)
    return compiler.has_results()

def explain(self, using, format=None, **options):
    q = self.clone()
    for option_name in options:
        if (
            not EXPLAIN_OPTIONS_PATTERN.fullmatch(option_name)
            or "--" in option_name
        ):
            raise ValueError(f"Invalid option name: {option_name!r}.")
    q.explain_info = ExplainInfo(format, options)
    compiler = q.get_compiler(using=using)
    return "\n".join(compiler.explain_query())

def _get_defer_select_mask(self, opts, mask, select_mask=None):
    if select_mask is None:
        select_mask = {}
    select_mask[opts.pk] = {}
    # All concrete fields and related objects that are not part of the
    # defer mask must be included. If a relational field is encountered it
    # gets added to the mask for it be considered if `select_related` and
    # the cycle continues by recursively calling this function.
    for field in opts.concrete_fields + opts.related_objects:
        field_mask = mask.pop(field.name, None)
        field_att_mask = None
        if field_attname := getattr(field, "attname", None):
            field_att_mask = mask.pop(field_attname, None)
        if field_mask is None and field_att_mask is None:
            select_mask.setdefault(field, {})
        elif field_mask:
            if not field.is_relation:
                raise FieldError(next(iter(field_mask)))
            # Virtual fields such as many-to-many and generic foreign keys
            # cannot be effectively deferred. Historically, they were
            # allowed to be passed to QuerySet.defer(). Ignore such field
            # references until a layer of validation at mask alteration
            # time is eventually implemented.
            if field.many_to_many:
                continue
            field_select_mask = select_mask.setdefault(field, {})
            related_model = field.related_model._meta.concrete_model
            self._get_defer_select_mask(
                related_model._meta, field_mask, field_select_mask
            )
    # Remaining defer entries must be references to filtered relations
    # otherwise they are surfaced as missing field errors.
    for field_name, field_mask in mask.items():
        if filtered_relation := self._filtered_relations.get(field_name):
            relation = opts.get_field(filtered_relation.relation_name)
            field_select_mask = select_mask.setdefault((field_name, relation), {})
            related_model = relation.related_model._meta.concrete_model
            self._get_defer_select_mask(
                related_model._meta, field_mask, field_select_mask
            )
        else:
            opts.get_field(field_name)
    return select_mask

def _get_only_select_mask(self, opts, mask, select_mask=None):
    if select_mask is None:
        select_mask = {}
    select_mask[opts.pk] = {}
    # Only include fields mentioned in the mask.
    for field_name, field_mask in mask.items():
        field = opts.get_field(field_name)
        field_select_mask = select_mask.setdefault(field, {})
        if field_mask:
            if not field.is_relation:
                raise FieldError(next(iter(field_mask)))
            related_model = field.remote_field.model._meta.concrete_model
            self._get_only_select_mask(
                related_model._meta, field_mask, field_select_mask
            )
    return select_mask

def get_select_mask(self):
    """
    Convert the self.deferred_loading data structure to an alternate data
    structure, describing the field that *will* be loaded. This is used to
    compute the columns to select from the database and also by the
    QuerySet class to work out which fields are being initialized on each
    model. Models that have all their fields included aren't mentioned in
    the result, only those that have field restrictions in place.
    """
    field_names, defer = self.deferred_loading
    if not field_names:
        return {}
    mask = {}
    for field_name in field_names:
        part_mask = mask
        for part in field_name.split(LOOKUP_SEP):
            part_mask = part_mask.setdefault(part, {})
    opts = self.get_meta()
    if defer:
        return self._get_defer_select_mask(opts, mask)
    return self._get_only_select_mask(opts, mask)

def ref_alias(self, alias):
    """Increases the reference count for this alias."""
    self.alias_refcount[alias] += 1

def unref_alias(self, alias, amount=1):
    """Decreases the reference count for this alias."""
    self.alias_refcount[alias] -= amount

def change_aliases(self, change_map):
    """
    Change the aliases in change_map (which maps old-alias -> new-alias),
    relabelling any references to them in select columns and the where
    clause.
    """
    if not change_map:
        return self
    # If keys and values of change_map were to intersect, an alias might be
    # updated twice (e.g. T4 -> T5, T5 -> T6, so also T4 -> T6) depending
    # on their order in change_map.
    assert set(change_map).isdisjoint(change_map.values())

    # 1. Update references in "select" (normal columns plus aliases),
    # "group by" and "where".
    self.where.relabel_aliases(change_map)
    if isinstance(self.group_by, tuple):
        self.group_by = tuple(
            [col.relabeled_clone(change_map) for col in self.group_by]
        )
    self.select = tuple([col.relabeled_clone(change_map) for col in self.select])
    self.annotations = self.annotations and {
        key: col.relabeled_clone(change_map)
        for key, col in self.annotations.items()
    }

    # 2. Rename the alias in the internal table/alias datastructures.
    for old_alias, new_alias in change_map.items():
        if old_alias not in self.alias_map:
            continue
        alias_data = self.alias_map[old_alias].relabeled_clone(change_map)
        self.alias_map[new_alias] = alias_data
        self.alias_refcount[new_alias] = self.alias_refcount[old_alias]
        del self.alias_refcount[old_alias]
        del self.alias_map[old_alias]

        table_aliases = self.table_map[alias_data.table_name]
        for pos, alias in enumerate(table_aliases):
            if alias == old_alias:
                table_aliases[pos] = new_alias
                break

    # 3. Rename the direct external aliases and the ones of combined
    # queries (union, intersection, difference).
    self.external_aliases = {
        # Table is aliased or it's being changed and thus is aliased.
        change_map.get(alias, alias): (aliased or alias in change_map)
        for alias, aliased in self.external_aliases.items()
    }
    for combined_query in self.combined_queries:
        external_change_map = {
            alias: aliased
            for alias, aliased in change_map.items()
            if alias in combined_query.external_aliases
        }
        combined_query.change_aliases(external_change_map)

def prefix_gen():
    """
    Generate a sequence of characters in alphabetical order:
        -> 'A', 'B', 'C', ...

    When the alphabet is finished, the sequence will continue with the
    Cartesian product:
        -> 'AA', 'AB', 'AC', ...
    """
    alphabet = ascii_uppercase
    prefix = chr(ord(self.alias_prefix) + 1)
    yield prefix
    for n in count(1):
        seq = alphabet[alphabet.index(prefix) :] if prefix else alphabet
        for s in product(seq, repeat=n):
            yield "".join(s)
        prefix = None

if self.alias_prefix != other_query.alias_prefix:
    # No clashes between self and outer query should be possible.
    return

# Explicitly avoid infinite loop. The constant divider is based on how
# much depth recursive subquery references add to the stack. This value
# might need to be adjusted when adding or removing function calls from
# the code path in charge of performing these operations.
local_recursion_limit = sys.getrecursionlimit() // 16
for pos, prefix in enumerate(prefix_gen()):
    if prefix not in self.subq_aliases:
        self.alias_prefix = prefix
        break
    if pos > local_recursion_limit:
        raise RecursionError(
            "Maximum recursion depth exceeded: too many subqueries."
        )
self.subq_aliases = self.subq_aliases.union([self.alias_prefix])
other_query.subq_aliases = other_query.subq_aliases.union(self.subq_aliases)
if exclude is None:
    exclude = {}
self.change_aliases(
    {
        alias: "%s%d" % (self.alias_prefix, pos)
        for pos, alias in enumerate(self.alias_map)
        if alias not in exclude
    }
)

def get_initial_alias(self):
    """
    Return the first alias for this query, after increasing its reference
    count.
    """
    if self.alias_map:
        alias = self.base_table
        self.ref_alias(alias)
    elif self.model:
        alias = self.join(self.base_table_class(self.get_meta().db_table, None))
    else:
        alias = None
    return alias

def join(self, join, reuse=None):
    """
    Return an alias for the 'join', either reusing an existing alias for
    that join or creating a new one. 'join' is either a base_table_class or
    join_class.

    The 'reuse' parameter can be either None which means all joins are
    reusable, or it can be a set containing the aliases that can be reused.

    A join is always created as LOUTER if the lhs alias is LOUTER to make
    sure chains like t1 LOUTER t2 INNER t3 aren't generated. All new
    joins are created as LOUTER if the join is nullable.
    """
    reuse_aliases = [
        a
        for a, j in self.alias_map.items()
        if (reuse is None or a in reuse) and j == join
    ]
    if reuse_aliases:
        if join.table_alias in reuse_aliases:
            reuse_alias = join.table_alias
        else:
            # Reuse the most recent alias of the joined table
            # (a many-to-many relation may be joined multiple times).
            reuse_alias = reuse_aliases[-1]
        self.ref_alias(reuse_alias)
        return reuse_alias

    # No reuse is possible, so we need a new alias.
    alias, _ = self.table_alias(
        join.table_name, create=True, filtered_relation=join.filtered_relation
    )
    if join.join_type:
        if self.alias_map[join.parent_alias].join_type == LOUTER or join.nullable:
            join_type = LOUTER
        else:
            join_type = INNER
        join.join_type = join_type
    join.table_alias = alias
    self.alias_map[alias] = join
    if filtered_relation := join.filtered_relation:
        resolve_reuse = reuse
        if resolve_reuse is not None:
            resolve_reuse = set(reuse) | {alias}
        joins_len = len(self.alias_map)
        join.filtered_relation = filtered_relation.resolve_expression(
            self, reuse=resolve_reuse
        )
        # Some joins were during expression resolving, they must be present
        # before the one we just added.
        if joins_len < len(self.alias_map):
            self.alias_map[alias] = self.alias_map.pop(alias)
    return alias

def check_alias(self, alias):
    # RemovedInDjango70Warning: When the deprecation ends, remove.
    if "%" in alias:
        if "aggregate" in {frame.function for frame in inspect.stack()}:
            stacklevel = 5
        else:
            # annotate() and alias().
            stacklevel = 6
        warnings.warn(
            "Using percent signs in a column alias is deprecated.",
            stacklevel=stacklevel,
            category=RemovedInDjango70Warning,
        )
    if FORBIDDEN_ALIAS_PATTERN.search(alias):
        raise ValueError(
            "Column aliases cannot contain whitespace characters, quotation marks, "
            # RemovedInDjango70Warning: When the deprecation ends, replace with:
            # "semicolons, percent signs, or SQL comments."
            "semicolons, or SQL comments."
        )

def add_annotation(self, annotation, alias, select=True):
    """Add a single annotation expression to the Query."""
    self.check_alias(alias)
    annotation = annotation.resolve_expression(self, allow_joins=True, reuse=None)
    if select:
        self.append_annotation_mask([alias])
    else:
        self.set_annotation_mask(set(self.annotation_select).difference({alias}))
    self.annotations[alias] = annotation
    if select and self.selected:
        self.selected[alias] = alias

@property

def _subquery_fields_len(self):
    if self.has_select_fields:
        return sum(
            len(self.model._meta.pk_fields) if field == "pk" else 1
            for field in self.selected
        )
    return len(self.model._meta.pk_fields)

def resolve_expression(self, query, *args, **kwargs):
    clone = self.clone()
    # Subqueries need to use a different set of aliases than the outer query.
    clone.bump_prefix(query)
    clone.subquery = True
    clone.where.resolve_expression(query, *args, **kwargs)
    # Resolve combined queries.
    if clone.combinator:
        clone.combined_queries = tuple(
            [
                combined_query.resolve_expression(query, *args, **kwargs)
                for combined_query in clone.combined_queries
            ]
        )
    for key, value in clone.annotations.items():
        resolved = value.resolve_expression(query, *args, **kwargs)
        if hasattr(resolved, "external_aliases"):
            resolved.external_aliases.update(clone.external_aliases)
        clone.annotations[key] = resolved
    # Outer query's aliases are considered external.
    for alias, table in query.alias_map.items():
        clone.external_aliases[alias] = (
            isinstance(table, Join)
            and table.join_field.related_model._meta.db_table != alias
        ) or (
            isinstance(table, BaseTable) and table.table_name != table.table_alias
        )
    return clone

def get_external_cols(self):
    exprs = chain(self.annotations.values(), self.where.children)
    return [
        col
        for col in self._gen_cols(exprs, include_external=True)
        if col.alias in self.external_aliases
    ]

def as_sql(self, compiler, connection):
    # Some backends (e.g. Oracle) raise an error when a subquery contains
    # unnecessary ORDER BY clause.
    if (
        self.subquery
        and not connection.features.ignores_unnecessary_order_by_in_subqueries
    ):
        self.clear_ordering(force=False)
        for query in self.combined_queries:
            query.clear_ordering(force=False)
    sql, params = self.get_compiler(connection=connection).as_sql()
    if self.subquery:
        sql = "(%s)" % sql
    return sql, params

def resolve_lookup_value(self, value, can_reuse, allow_joins, summarize=False):
    if hasattr(value, "resolve_expression"):
        value = value.resolve_expression(
            self,
            reuse=can_reuse,
            allow_joins=allow_joins,
            summarize=summarize,
        )
    elif isinstance(value, (list, tuple)):
        # The items of the iterable may be expressions and therefore need
        # to be resolved independently.
        values = (
            self.resolve_lookup_value(sub_value, can_reuse, allow_joins, summarize)
            for sub_value in value
        )
        type_ = type(value)
        if hasattr(type_, "_make"):  # namedtuple
            return type_(*values)
        return type_(values)
    return value

def solve_lookup_type(self, lookup, summarize=False):
    """
    Solve the lookup type from the lookup (e.g.: 'foobar__id__icontains').
    """
    lookup_splitted = lookup.split(LOOKUP_SEP)
    if self.annotations:
        annotation, expression_lookups = refs_expression(
            lookup_splitted, self.annotations
        )
        if annotation:
            expression = self.annotations[annotation]
            if summarize:
                expression = Ref(annotation, expression)
            return expression_lookups, (), expression
    _, field, _, lookup_parts = self.names_to_path(lookup_splitted, self.get_meta())
    field_parts = lookup_splitted[0 : len(lookup_splitted) - len(lookup_parts)]
    if len(lookup_parts) > 1 and not field_parts:
        raise FieldError(
            'Invalid lookup "%s" for model %s".'
            % (lookup, self.get_meta().model.__name__)
        )
    return lookup_parts, field_parts, False

def check_query_object_type(self, value, opts, field):
    """
    Check whether the object passed while querying is of the correct type.
    If not, raise a ValueError specifying the wrong object.
    """
    if hasattr(value, "_meta"):
        if not check_rel_lookup_compatibility(value._meta.model, opts, field):
            raise ValueError(
                'Cannot query "%s": Must be "%s" instance.'
                % (value, opts.object_name)
            )

def check_related_objects(self, field, value, opts):
    """Check the type of object passed to query relations."""
    if field.is_relation:
        # Check that the field and the queryset use the same model in a
        # query like .filter(author=Author.objects.all()). For example, the
        # opts would be Author's (from the author field) and value.model
        # would be Author.objects.all() queryset's .model (Author also).
        # The field is the related field on the lhs side.
        if (
            isinstance(value, Query)
            and not value.has_select_fields
            and not check_rel_lookup_compatibility(value.model, opts, field)
        ):
            raise ValueError(
                'Cannot use QuerySet for "%s": Use a QuerySet for "%s".'
                % (value.model._meta.object_name, opts.object_name)
            )
        elif hasattr(value, "_meta"):
            self.check_query_object_type(value, opts, field)
        elif hasattr(value, "__iter__"):
            for v in value:
                self.check_query_object_type(v, opts, field)

def check_filterable(self, expression):
    """Raise an error if expression cannot be used in a WHERE clause."""
    if hasattr(expression, "resolve_expression") and not getattr(
        expression, "filterable", True
    ):
        raise NotSupportedError(
            expression.__class__.__name__ + " is disallowed in the filter "
            "clause."
        )
    if hasattr(expression, "get_source_expressions"):
        for expr in expression.get_source_expressions():
            self.check_filterable(expr)

def try_transform(self, lhs, name, lookups=None):
    """
    Helper method for build_lookup(). Try to fetch and initialize
    a transform for name parameter from lhs.
    """
    transform_class = lhs.get_transform(name)
    if transform_class:
        return transform_class(lhs)
    else:
        output_field = lhs.output_field.__class__
        suggested_lookups = difflib.get_close_matches(
            name, lhs.output_field.get_lookups()
        )
        if suggested_lookups:
            suggestion = ", perhaps you meant %s?" % " or ".join(suggested_lookups)
        else:
            suggestion = "."
        if lookups is not None:
            name_index = lookups.index(name)
            unsupported_lookup = LOOKUP_SEP.join(lookups[name_index:])
        else:
            unsupported_lookup = name
        raise FieldError(
            "Unsupported lookup '%s' for %s or join on the field not "
            "permitted%s" % (unsupported_lookup, output_field.__name__, suggestion)
        )

def add_filtered_relation(self, filtered_relation, alias):
    filtered_relation.alias = alias
    relation_lookup_parts, relation_field_parts, _ = self.solve_lookup_type(
        filtered_relation.relation_name
    )
    if relation_lookup_parts:
        raise ValueError(
            "FilteredRelation's relation_name cannot contain lookups "
            "(got %r)." % filtered_relation.relation_name
        )
    for lookup in get_children_from_q(filtered_relation.condition):
        lookup_parts, lookup_field_parts, _ = self.solve_lookup_type(lookup)
        shift = 2 if not lookup_parts else 1
        lookup_field_path = lookup_field_parts[:-shift]
        for idx, lookup_field_part in enumerate(lookup_field_path):
            if len(relation_field_parts) > idx:
                if relation_field_parts[idx] != lookup_field_part:
                    raise ValueError(
                        "FilteredRelation's condition doesn't support "
                        "relations outside the %r (got %r)."
                        % (filtered_relation.relation_name, lookup)
                    )
        if len(lookup_field_parts) > len(relation_field_parts) + 1:
            raise ValueError(
                "FilteredRelation's condition doesn't support nested "
                "relations deeper than the relation_name (got %r for "
                "%r)." % (lookup, filtered_relation.relation_name)
            )
    filtered_relation = filtered_relation.clone()
    filtered_relation.condition = rename_prefix_from_q(
        filtered_relation.relation_name,
        alias,
        filtered_relation.condition,
    )
    self._filtered_relations[filtered_relation.alias] = filtered_relation

def final_transformer(field, alias):
    if not self.alias_cols:
        alias = None
    return field.get_col(alias)

# Try resolving all the names as fields first. If there's an error,
# treat trailing names as lookups until a field can be resolved.
last_field_exception = None
for pivot in range(len(names), 0, -1):
    try:
        path, final_field, targets, rest = self.names_to_path(
            names[:pivot],
            opts,
            allow_many,
            fail_on_missing=True,
        )
    except FieldError as exc:
        if pivot == 1:
            # The first item cannot be a lookup, so it's safe
            # to raise the field error here.
            raise
        else:
            last_field_exception = exc
    else:
        # The transforms are the remaining items that couldn't be
        # resolved into fields.
        transforms = names[pivot:]
        break
for name in transforms:

    def transform(field, alias, *, name, previous):
        try:
            wrapped = previous(field, alias)
            return self.try_transform(wrapped, name)
        except FieldError:
            # FieldError is raised if the transform doesn't exist.
            if isinstance(final_field, Field) and last_field_exception:
                raise last_field_exception
            else:
                raise

    final_transformer = functools.partial(
        transform, name=name, previous=final_transformer
    )
    final_transformer.has_transforms = True
# Then, add the path to the query's joins. Note that we can't trim
# joins at this stage - we will need the information about join type
# of the trimmed joins.
for join in path:
    if join.filtered_relation:
        filtered_relation = join.filtered_relation.clone()
        table_alias = filtered_relation.alias
    else:
        filtered_relation = None
        table_alias = None
    opts = join.to_opts
    if join.direct:
        nullable = self.is_nullable(join.join_field)
    else:
        nullable = True
    connection = self.join_class(
        opts.db_table,
        alias,
        table_alias,
        INNER,
        join.join_field,
        nullable,
        filtered_relation=filtered_relation,
    )
    reuse = can_reuse if join.m2m else None
    alias = self.join(connection, reuse=reuse)
    joins.append(alias)
    if join.filtered_relation and can_reuse is not None:
        can_reuse.add(alias)
return JoinInfo(final_field, targets, opts, joins, path, final_transformer)

def trim_joins(self, targets, joins, path):
    """
    The 'target' parameter is the final field being joined to, 'joins'
    is the full list of join aliases. The 'path' contain the PathInfos
    used to create the joins.

    Return the final target field and table alias and the new active
    joins.

    Always trim any direct join if the target column is already in the
    previous table. Can't trim reverse joins as it's unknown if there's
    anything on the other side of the join.
    """
    joins = joins[:]
    for pos, info in enumerate(reversed(path)):
        if len(joins) == 1 or not info.direct:
            break
        if info.filtered_relation:
            break
        join_targets = {t.column for t in info.join_field.foreign_related_fields}
        cur_targets = {t.column for t in targets}
        if not cur_targets.issubset(join_targets):
            break
        targets_dict = {
            r[1].column: r[0]
            for r in info.join_field.related_fields
            if r[1].column in cur_targets
        }
        targets = tuple(targets_dict[t.column] for t in targets)
        self.unref_alias(joins.pop())
    return targets, joins[-1], joins

@classmethod

def _gen_cols(cls, exprs, include_external=False, resolve_refs=True):
    for expr in exprs:
        if isinstance(expr, Col):
            yield expr
        elif include_external and callable(
            getattr(expr, "get_external_cols", None)
        ):
            yield from expr.get_external_cols()
        elif hasattr(expr, "get_source_expressions"):
            if not resolve_refs and isinstance(expr, Ref):
                continue
            yield from cls._gen_cols(
                expr.get_source_expressions(),
                include_external=include_external,
                resolve_refs=resolve_refs,
            )

@classmethod

def resolve_ref(self, name, allow_joins=True, reuse=None, summarize=False):
    annotation = self.annotations.get(name)
    if annotation is not None:
        if not allow_joins:
            for alias in self._gen_col_aliases([annotation]):
                if isinstance(self.alias_map[alias], Join):
                    raise FieldError(
                        "Joined field references are not permitted in this query"
                    )
        if summarize:
            # Summarize currently means we are doing an aggregate() query
            # which is executed as a wrapped subquery if any of the
            # aggregate() elements reference an existing annotation. In
            # that case we need to return a Ref to the subquery's annotation.
            if name not in self.annotation_select:
                raise FieldError(
                    "Cannot aggregate over the '%s' alias. Use annotate() "
                    "to promote it." % name
                )
            return Ref(name, self.annotation_select[name])
        else:
            return annotation
    else:
        field_list = name.split(LOOKUP_SEP)
        annotation = self.annotations.get(field_list[0])
        if annotation is not None:
            for transform in field_list[1:]:
                annotation = self.try_transform(annotation, transform)
            return annotation
        join_info = self.setup_joins(
            field_list, self.get_meta(), self.get_initial_alias(), can_reuse=reuse
        )
        targets, final_alias, join_list = self.trim_joins(
            join_info.targets, join_info.joins, join_info.path
        )
        if not allow_joins and len(join_list) > 1:
            raise FieldError(
                "Joined field references are not permitted in this query"
            )
        if len(targets) > 1:
            raise FieldError(
                "Referencing multicolumn fields with F() objects isn't supported"
            )
        # Verify that the last lookup in name is a field or a transform:
        # transform_function() raises FieldError if not.
        transform = join_info.transform_function(targets[0], final_alias)
        if reuse is not None:
            reuse.update(join_list)
        return transform

def set_empty(self):
    self.where.add(NothingNode(), AND)
    for query in self.combined_queries:
        query.set_empty()

def set_limits(self, low=None, high=None):
    """
    Adjust the limits on the rows retrieved. Use low/high to set these,
    as it makes it more Pythonic to read and write. When the SQL query is
    created, convert them to the appropriate offset and limit values.

    Apply any limits passed in here to the existing constraints. Add low
    to the current low value and clamp both to any existing high value.
    """
    if high is not None:
        if self.high_mark is not None:
            self.high_mark = min(self.high_mark, self.low_mark + high)
        else:
            self.high_mark = self.low_mark + high
    if low is not None:
        if self.high_mark is not None:
            self.low_mark = min(self.high_mark, self.low_mark + low)
        else:
            self.low_mark = self.low_mark + low

    if self.low_mark == self.high_mark:
        self.set_empty()

def clear_limits(self):
    """Clear any existing limits."""
    self.low_mark, self.high_mark = 0, None

@property

def set_select(self, cols):
    self.default_cols = False
    self.select = tuple(cols)

def add_fields(self, field_names, allow_m2m=True):
    """
    Add the given (model) fields to the select set. Add the field names in
    the order specified.
    """
    alias = self.get_initial_alias()
    opts = self.get_meta()

    try:
        cols = []
        for name in field_names:
            # Join promotion note - we must not remove any rows here, so
            # if there is no existing joins, use outer join.
            join_info = self.setup_joins(
                name.split(LOOKUP_SEP), opts, alias, allow_many=allow_m2m
            )
            targets, final_alias, joins = self.trim_joins(
                join_info.targets,
                join_info.joins,
                join_info.path,
            )
            for target in targets:
                cols.append(join_info.transform_function(target, final_alias))
        if cols:
            self.set_select(cols)
    except MultiJoin:
        raise FieldError("Invalid field name: '%s'" % name)
    except FieldError:
        if LOOKUP_SEP in name:
            # For lookups spanning over relationships, show the error
            # from the model on which the lookup failed.
            raise
        else:
            names = sorted(
                [
                    *get_field_names_from_opts(opts),
                    *self.extra,
                    *self.annotation_select,
                    *self._filtered_relations,
                ]
            )
            raise FieldError(
                "Cannot resolve keyword %r into field. "
                "Choices are: %s" % (name, ", ".join(names))
            )

def add_ordering(self, *ordering):
    """
    Add items from the 'ordering' sequence to the query's "order by"
    clause. These items are either field names (not column names) --
    possibly with a direction prefix ('-' or '?') -- or OrderBy
    expressions.

    If 'ordering' is empty, clear all ordering from the query.
    """
    errors = []
    for item in ordering:
        if isinstance(item, str):
            if item == "?":
                continue
            item = item.removeprefix("-")
            if item in self.annotations:
                continue
            if self.extra and item in self.extra:
                continue
            # names_to_path() validates the lookup. A descriptive
            # FieldError will be raise if it's not.
            self.names_to_path(item.split(LOOKUP_SEP), self.model._meta)
        elif not hasattr(item, "resolve_expression"):
            errors.append(item)
        if getattr(item, "contains_aggregate", False):
            raise FieldError(
                "Using an aggregate in order_by() without also including "
                "it in annotate() is not allowed: %s" % item
            )
    if errors:
        raise FieldError("Invalid order_by arguments: %s" % errors)
    if ordering:
        self.order_by += ordering
    else:
        self.default_ordering = False

def set_group_by(self, allow_aliases=True):
    """
    Expand the GROUP BY clause required by the query.

    This will usually be the set of all non-aggregate fields in the
    return data. If the database backend supports grouping by the
    primary key, and the query would be equivalent, the optimization
    will be made automatically.
    """
    if allow_aliases and self.values_select:
        # If grouping by aliases is allowed assign selected value aliases
        # by moving them to annotations.
        group_by_annotations = {}
        values_select = {}
        for alias, expr in zip(self.values_select, self.select):
            if isinstance(expr, Col):
                values_select[alias] = expr
            else:
                group_by_annotations[alias] = expr
        self.annotations = {**group_by_annotations, **self.annotations}
        self.append_annotation_mask(group_by_annotations)
        self.select = tuple(values_select.values())
        self.values_select = tuple(values_select)
        if self.selected is not None:
            for index, value_select in enumerate(values_select):
                self.selected[value_select] = index
    group_by = list(self.select)
    for alias, annotation in self.annotation_select.items():
        if not (group_by_cols := annotation.get_group_by_cols()):
            continue
        if allow_aliases and not annotation.contains_aggregate:
            group_by.append(Ref(alias, annotation))
        else:
            group_by.extend(group_by_cols)
    self.group_by = tuple(group_by)

def add_select_related(self, fields):
    """
    Set up the select_related data structure so that we only select
    certain related models (as opposed to all models, when
    self.select_related=True).
    """
    if isinstance(self.select_related, bool):
        field_dict = {}
    else:
        field_dict = self.select_related
    for field in fields:
        d = field_dict
        for part in field.split(LOOKUP_SEP):
            d = d.setdefault(part, {})
    self.select_related = field_dict

def add_extra(self, select, select_params, where, params, tables, order_by):
    """
    Add data to the various extra_* attributes for user-created additions
    to the query.
    """
    if select:
        # We need to pair any placeholder markers in the 'select'
        # dictionary with their parameters in 'select_params' so that
        # subsequent updates to the select dictionary also adjust the
        # parameters appropriately.
        select_pairs = {}
        if select_params:
            param_iter = iter(select_params)
        else:
            param_iter = iter([])
        for name, entry in select.items():
            self.check_alias(name)
            entry = str(entry)
            entry_params = []
            pos = entry.find("%s")
            while pos != -1:
                if pos == 0 or entry[pos - 1] != "%":
                    entry_params.append(next(param_iter))
                pos = entry.find("%s", pos + 2)
            select_pairs[name] = (entry, entry_params)
        self.extra.update(select_pairs)
    if where or params:
        self.where.add(ExtraWhere(where, params), AND)
    if tables:
        self.extra_tables += tuple(tables)
    if order_by:
        self.extra_order_by = order_by

def clear_deferred_loading(self):
    """Remove any fields from the deferred loading set."""
    self.deferred_loading = (frozenset(), True)

def set_annotation_mask(self, names):
    """Set the mask of annotations that will be returned by the SELECT."""
    if names is None:
        self.annotation_select_mask = None
    else:
        self.annotation_select_mask = set(names)
        if self.selected:
            # Prune the masked annotations.
            self.selected = {
                key: value
                for key, value in self.selected.items()
                if not isinstance(value, str)
                or value in self.annotation_select_mask
            }
            # Append the unmasked annotations.
            for name in names:
                self.selected[name] = name
    self._annotation_select_cache = None

def append_annotation_mask(self, names):
    if self.annotation_select_mask is not None:
        self.set_annotation_mask(self.annotation_select_mask.union(names))

def set_extra_mask(self, names):
    """
    Set the mask of extra select items that will be returned by SELECT.
    Don't remove them from the Query since they might be used later.
    """
    if names is None:
        self.extra_select_mask = None
    else:
        self.extra_select_mask = set(names)
    self._extra_select_cache = None

@property

def set_values(self, fields):
    self.select_related = False
    self.clear_deferred_loading()
    self.clear_select_fields()

    selected = {}
    if fields:
        for field in fields:
            self.check_alias(field)
        field_names = []
        extra_names = []
        annotation_names = []
        if not self.extra and not self.annotations:
            # Shortcut - if there are no extra or annotations, then
            # the values() clause must be just field names.
            field_names = list(fields)
            selected = dict(zip(fields, range(len(fields))))
        else:
            self.default_cols = False
            for f in fields:
                if extra := self.extra_select.get(f):
                    extra_names.append(f)
                    selected[f] = RawSQL(*extra)
                elif f in self.annotation_select:
                    annotation_names.append(f)
                    selected[f] = f
                elif f in self.annotations:
                    raise FieldError(
                        f"Cannot select the '{f}' alias. Use annotate() to "
                        "promote it."
                    )
                else:
                    # Call `names_to_path` to ensure a FieldError including
                    # annotations about to be masked as valid choices if
                    # `f` is not resolvable.
                    if self.annotation_select:
                        self.names_to_path(f.split(LOOKUP_SEP), self.model._meta)
                    selected[f] = len(field_names)
                    field_names.append(f)
        self.set_extra_mask(extra_names)
        self.set_annotation_mask(annotation_names)
    else:
        field_names = [f.attname for f in self.model._meta.concrete_fields]
        selected = dict.fromkeys(field_names, None)
    # Selected annotations must be known before setting the GROUP BY
    # clause.
    if self.group_by is True:
        self.add_fields(
            (f.attname for f in self.model._meta.concrete_fields), False
        )
        # Disable GROUP BY aliases to avoid orphaning references to the
        # SELECT clause which is about to be cleared.
        self.set_group_by(allow_aliases=False)
        self.clear_select_fields()
    elif self.group_by:
        # Resolve GROUP BY annotation references if they are not part of
        # the selected fields anymore.
        group_by = []
        for expr in self.group_by:
            if isinstance(expr, Ref) and expr.refs not in selected:
                expr = self.annotations[expr.refs]
            group_by.append(expr)
        self.group_by = tuple(group_by)

    self.values_select = tuple(field_names)
    self.add_fields(field_names, True)
    self.selected = selected if fields else None

@property

def annotation_select(self):
    """
    Return the dictionary of aggregate columns that are not masked and
    should be used in the SELECT clause. Cache this result for performance.
    """
    if self._annotation_select_cache is not None:
        return self._annotation_select_cache
    elif not self.annotations:
        return {}
    elif self.annotation_select_mask is not None:
        self._annotation_select_cache = {
            k: v
            for k, v in self.annotations.items()
            if k in self.annotation_select_mask
        }
        return self._annotation_select_cache
    else:
        return self.annotations

@property

def extra_select(self):
    if self._extra_select_cache is not None:
        return self._extra_select_cache
    if not self.extra:
        return {}
    elif self.extra_select_mask is not None:
        self._extra_select_cache = {
            k: v for k, v in self.extra.items() if k in self.extra_select_mask
        }
        return self._extra_select_cache
    else:
        return self.extra

def __init__(self, connector, num_children, negated):
    self.connector = connector
    self.negated = negated
    if self.negated:
        if connector == AND:
            self.effective_connector = OR
        else:
            self.effective_connector = AND
    else:
        self.effective_connector = self.connector
    self.num_children = num_children
    # Maps of table alias to how many times it is seen as required for
    # inner and/or outer joins.
    self.votes = Counter()

def __repr__(self):
    return (
        f"{self.__class__.__qualname__}(connector={self.connector!r}, "
        f"num_children={self.num_children!r}, negated={self.negated!r})"
    )

class DeleteQuery(Query):
    """A DELETE SQL query."""

    compiler = "SQLDeleteCompiler"

def do_query(self, table, where, using):
    self.alias_map = {table: self.alias_map[table]}
    self.where = where
    return self.get_compiler(using).execute_sql(ROW_COUNT)

class UpdateQuery(Query):
    """An UPDATE SQL query."""

    compiler = "SQLUpdateCompiler"

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self._setup_query()

def update_batch(self, pk_list, values, using):
    self.add_update_values(values)
    for offset in range(0, len(pk_list), GET_ITERATOR_CHUNK_SIZE):
        self.clear_where()
        self.add_filter(
            "pk__in", pk_list[offset : offset + GET_ITERATOR_CHUNK_SIZE]
        )
        self.get_compiler(using).execute_sql(NO_RESULTS)

def add_update_values(self, values):
    """
    Convert a dictionary of field name to value mappings into an update
    query. This is the entry point for the public update() method on
    querysets.
    """
    values_seq = []
    for name, val in values.items():
        field = self.get_meta().get_field(name)
        direct = (
            not (field.auto_created and not field.concrete) or not field.concrete
        )
        model = field.model._meta.concrete_model
        if field.name == "pk" and model._meta.is_composite_pk:
            raise FieldError(
                "Composite primary key fields must be updated individually."
            )
        if not direct or (field.is_relation and field.many_to_many):
            raise FieldError(
                "Cannot update model field %r (only non-relations and "
                "foreign keys permitted)." % field
            )
        if model is not self.get_meta().concrete_model:
            self.add_related_update(model, field, val)
            continue
        values_seq.append((field, model, val))
    return self.add_update_fields(values_seq)

def __init__(self, model, inner_query):
    self.inner_query = inner_query
    super().__init__(model)

def as_sql(self, compiler, connection):
    """
    Return the SQL version of the where clause and the value to be
    substituted in. Return '', [] if this node matches everything,
    None, [] if this node is empty, and raise EmptyResultSet if this
    node can't match anything.
    """
    result = []
    result_params = []
    if self.connector == AND:
        full_needed, empty_needed = len(self.children), 1
    else:
        full_needed, empty_needed = 1, len(self.children)

    if self.connector == XOR and not connection.features.supports_logical_xor:
        # Convert if the database doesn't support XOR:
        #   a XOR b XOR c XOR ...
        # to:
        #   (a OR b OR c OR ...) AND MOD(a + b + c + ..., 2) == 1
        # The result of an n-ary XOR is true when an odd number of operands
        # are true.
        lhs = self.__class__(self.children, OR)
        rhs_sum = reduce(
            operator.add,
            (Case(When(c, then=1), default=0) for c in self.children),
        )
        if len(self.children) > 2:
            rhs_sum = Mod(rhs_sum, 2)
        rhs = Exact(1, rhs_sum)
        return self.__class__([lhs, rhs], AND, self.negated).as_sql(
            compiler, connection
        )

    for child in self.children:
        try:
            sql, params = compiler.compile(child)
        except EmptyResultSet:
            empty_needed -= 1
        except FullResultSet:
            full_needed -= 1
        else:
            if sql:
                result.append(sql)
                result_params.extend(params)
            else:
                full_needed -= 1
        # Check if this node matches nothing or everything.
        # First check the amount of full nodes and empty nodes
        # to make this node empty/full.
        # Now, check if this node is full/empty using the
        # counts.
        if empty_needed == 0:
            if self.negated:
                raise FullResultSet
            else:
                raise EmptyResultSet
        if full_needed == 0:
            if self.negated:
                raise EmptyResultSet
            else:
                raise FullResultSet
    conn = " %s " % self.connector
    sql_string = conn.join(result)
    if not sql_string:
        raise FullResultSet
    if self.negated:
        # Some backends (Oracle at least) need parentheses around the inner
        # SQL in the negated case, even if the inner SQL contains just a
        # single expression.
        sql_string = "NOT (%s)" % sql_string
    elif len(result) > 1 or self.resolved:
        sql_string = "(%s)" % sql_string
    return sql_string, result_params

def get_group_by_cols(self):
    cols = []
    for child in self.children:
        cols.extend(child.get_group_by_cols())
    return cols

def set_source_expressions(self, children):
    assert len(children) == len(self.children)
    self.children = children

def relabel_aliases(self, change_map):
    """
    Relabel the alias values of any children. 'change_map' is a dictionary
    mapping old (current) alias values to the new values.
    """
    if not change_map:
        return self
    for pos, child in enumerate(self.children):
        if hasattr(child, "relabel_aliases"):
            # For example another WhereNode
            child.relabel_aliases(change_map)
        elif hasattr(child, "relabeled_clone"):
            self.children[pos] = child.relabeled_clone(change_map)

def clone(self):
    clone = self.create(connector=self.connector, negated=self.negated)
    for child in self.children:
        if hasattr(child, "clone"):
            child = child.clone()
        clone.children.append(child)
    return clone

def replace_expressions(self, replacements):
    if not replacements:
        return self
    if replacement := replacements.get(self):
        return replacement
    clone = self.create(connector=self.connector, negated=self.negated)
    for child in self.children:
        clone.children.append(child.replace_expressions(replacements))
    return clone

def get_refs(self):
    refs = set()
    for child in self.children:
        refs |= child.get_refs()
    return refs

@classmethod

def _contains_aggregate(cls, obj):
    if isinstance(obj, tree.Node):
        return any(cls._contains_aggregate(c) for c in obj.children)
    return obj.contains_aggregate

@cached_property

def contains_aggregate(self):
    return self._contains_aggregate(self)

@classmethod

def _contains_over_clause(cls, obj):
    if isinstance(obj, tree.Node):
        return any(cls._contains_over_clause(c) for c in obj.children)
    return obj.contains_over_clause

@cached_property

def contains_over_clause(self):
    return self._contains_over_clause(self)

@property

def is_summary(self):
    return any(child.is_summary for child in self.children)

@staticmethod

def _resolve_leaf(expr, query, *args, **kwargs):
    if hasattr(expr, "resolve_expression"):
        expr = expr.resolve_expression(query, *args, **kwargs)
    return expr

@classmethod

def _resolve_node(cls, node, query, *args, **kwargs):
    if hasattr(node, "children"):
        for child in node.children:
            cls._resolve_node(child, query, *args, **kwargs)
    if hasattr(node, "lhs"):
        node.lhs = cls._resolve_leaf(node.lhs, query, *args, **kwargs)
    if hasattr(node, "rhs"):
        node.rhs = cls._resolve_leaf(node.rhs, query, *args, **kwargs)

def resolve_expression(self, *args, **kwargs):
    clone = self.clone()
    clone._resolve_node(clone, *args, **kwargs)
    clone.resolved = True
    return clone

@cached_property

def output_field(self):
    from django.db.models import BooleanField

    return BooleanField()

@property

def leaves(self):
    for child in self.children:
        if isinstance(child, WhereNode):
            yield from child.leaves()
        else:
            yield child

def __init__(self, sqls, params):
    self.sqls = sqls
    self.params = params

def as_sql(self, compiler=None, connection=None):
    sqls = ["(%s)" % sql for sql in self.sqls]
    return " AND ".join(sqls), list(self.params or ())

def relabeled_clone(self, change_map):
    new_parent_alias = change_map.get(self.parent_alias, self.parent_alias)
    new_table_alias = change_map.get(self.table_alias, self.table_alias)
    if self.filtered_relation is not None:
        filtered_relation = self.filtered_relation.relabeled_clone(change_map)
    else:
        filtered_relation = None
    return self.__class__(
        self.table_name,
        new_parent_alias,
        new_table_alias,
        self.join_type,
        self.join_field,
        self.nullable,
        filtered_relation=filtered_relation,
    )

@property

def identity(self):
    return (
        self.__class__,
        self.table_name,
        self.parent_alias,
        self.join_field,
        self.filtered_relation,
    )

def __eq__(self, other):
    if not isinstance(other, Join):
        return NotImplemented
    return self.identity == other.identity

def __init__(self, table_name, alias):
    self.table_name = table_name
    self.table_alias = alias

def as_sql(self, compiler, connection):
    alias_str = (
        "" if self.table_alias == self.table_name else (" %s" % self.table_alias)
    )
    base_sql = compiler.quote_name_unless_alias(self.table_name)
    return base_sql + alias_str, []

def relabeled_clone(self, change_map):
    return self.__class__(
        self.table_name, change_map.get(self.table_alias, self.table_alias)
    )

@property

def __eq__(self, other):
    if not isinstance(other, BaseTable):
        return NotImplemented
    return self.identity == other.identity

def _get_database_create_suffix(self, encoding=None, template=None):
    suffix = ""
    if encoding:
        suffix += " ENCODING '{}'".format(encoding)
    if template:
        suffix += " TEMPLATE {}".format(self._quote_name(template))
    return suffix and "WITH" + suffix

def sql_table_creation_suffix(self):
    test_settings = self.connection.settings_dict["TEST"]
    if test_settings.get("COLLATION") is not None:
        raise ImproperlyConfigured(
            "PostgreSQL does not support collation setting at database "
            "creation time."
        )
    return self._get_database_create_suffix(
        encoding=test_settings["CHARSET"],
        template=test_settings.get("TEMPLATE"),
    )

def _database_exists(self, cursor, database_name):
    cursor.execute(
        "SELECT 1 FROM pg_catalog.pg_database WHERE datname = %s",
        [strip_quotes(database_name)],
    )
    return cursor.fetchone() is not None

def _execute_create_test_db(self, cursor, parameters, keepdb=False):
    try:
        if keepdb and self._database_exists(cursor, parameters["dbname"]):
            # If the database should be kept and it already exists, don't
            # try to create a new one.
            return
        super()._execute_create_test_db(cursor, parameters, keepdb)
    except Exception as e:
        if not isinstance(e.__cause__, errors.DuplicateDatabase):
            # All errors except "database already exists" cancel tests.
            self.log("Got an error creating the test database: %s" % e)
            sys.exit(2)
        elif not keepdb:
            # If the database should be kept, ignore "database already
            # exists".
            raise

def _clone_test_db(self, suffix, verbosity, keepdb=False):
    # CREATE DATABASE ... WITH TEMPLATE ... requires closing connections
    # to the template database.
    self.connection.close()
    self.connection.close_pool()

    source_database_name = self.connection.settings_dict["NAME"]
    target_database_name = self.get_test_db_clone_settings(suffix)["NAME"]
    test_db_params = {
        "dbname": self._quote_name(target_database_name),
        "suffix": self._get_database_create_suffix(template=source_database_name),
    }
    with self._nodb_cursor() as cursor:
        try:
            self._execute_create_test_db(cursor, test_db_params, keepdb)
        except Exception:
            try:
                if verbosity >= 1:
                    self.log(
                        "Destroying old test database for alias %s..."
                        % (
                            self._get_database_display_str(
                                verbosity, target_database_name
                            ),
                        )
                    )
                cursor.execute("DROP DATABASE %(dbname)s" % test_db_params)
                self._execute_create_test_db(cursor, test_db_params, keepdb)
            except Exception as e:
                self.log("Got an error cloning the test database: %s" % e)
                sys.exit(2)

def _destroy_test_db(self, test_database_name, verbosity):
    self.connection.close_pool()
    return super()._destroy_test_db(test_database_name, verbosity)

