def last_executed_query(self, cursor, sql, params):
    # Python substitutes parameters in Modules/_sqlite/cursor.c with:
    # bind_parameters(state, self->statement, parameters);
    # Unfortunately there is no way to reach self->statement from Python,
    # so we quote and substitute parameters manually.
    if params:
        if isinstance(params, (list, tuple)):
            params = self._quote_params_for_last_executed_query(params)
        else:
            values = tuple(params.values())
            values = self._quote_params_for_last_executed_query(values)
            params = dict(zip(params, values))
        return sql % params
    # For consistency with SQLiteCursorWrapper.execute(), just return sql
    # when there are no parameters. See #13648 and #17158.
    else:
        return sql

def quote_name(self, name):
    if name.startswith('"') and name.endswith('"'):
        return name  # Quoting once is enough.
    return '"%s"' % name

def _references_graph(self):
    # 512 is large enough to fit the ~330 tables (as of this writing) in
    # Django's test suite.
    return lru_cache(maxsize=512)(self.__references_graph)

def sql_flush(self, style, tables, *, reset_sequences=False, allow_cascade=False):
    if tables and allow_cascade:
        # Simulate TRUNCATE CASCADE by recursively collecting the tables
        # referencing the tables to be flushed.
        tables = set(
            chain.from_iterable(self._references_graph(table) for table in tables)
        )
    sql = [
        "%s %s %s;"
        % (
            style.SQL_KEYWORD("DELETE"),
            style.SQL_KEYWORD("FROM"),
            style.SQL_FIELD(self.quote_name(table)),
        )
        for table in tables
    ]
    if reset_sequences:
        sequences = [{"table": table} for table in tables]
        sql.extend(self.sequence_reset_by_name_sql(style, sequences))
    return sql

def adapt_datetimefield_value(self, value):
    if value is None:
        return None

    # SQLite doesn't support tz-aware datetimes
    if timezone.is_aware(value):
        if settings.USE_TZ:
            value = timezone.make_naive(value, self.connection.timezone)
        else:
            raise ValueError(
                "SQLite backend does not support timezone-aware datetimes when "
                "USE_TZ is False."
            )

    return str(value)

def adapt_timefield_value(self, value):
    if value is None:
        return None

    # SQLite doesn't support tz-aware datetimes
    if timezone.is_aware(value):
        raise ValueError("SQLite backend does not support timezone-aware times.")

    return str(value)

def get_db_converters(self, expression):
    converters = super().get_db_converters(expression)
    internal_type = expression.output_field.get_internal_type()
    if internal_type == "DateTimeField":
        converters.append(self.convert_datetimefield_value)
    elif internal_type == "DateField":
        converters.append(self.convert_datefield_value)
    elif internal_type == "TimeField":
        converters.append(self.convert_timefield_value)
    elif internal_type == "DecimalField":
        converters.append(self.get_decimalfield_converter(expression))
    elif internal_type == "UUIDField":
        converters.append(self.convert_uuidfield_value)
    elif internal_type == "BooleanField":
        converters.append(self.convert_booleanfield_value)
    return converters

def convert_datetimefield_value(self, value, expression, connection):
    if value is not None:
        if not isinstance(value, datetime.datetime):
            value = parse_datetime(value)
        if settings.USE_TZ and not timezone.is_aware(value):
            value = timezone.make_aware(value, self.connection.timezone)
    return value

def convert_datefield_value(self, value, expression, connection):
    if value is not None:
        if not isinstance(value, datetime.date):
            value = parse_date(value)
    return value

def convert_timefield_value(self, value, expression, connection):
    if value is not None:
        if not isinstance(value, datetime.time):
            value = parse_time(value)
    return value

def get_decimalfield_converter(self, expression):
    # SQLite stores only 15 significant digits. Digits coming from
    # float inaccuracy must be removed.
    create_decimal = decimal.Context(prec=15).create_decimal_from_float
    if isinstance(expression, Col):
        quantize_value = decimal.Decimal(1).scaleb(
            -expression.output_field.decimal_places
        )

    def converter(value, expression, connection):
        if value is not None:
            return create_decimal(value).quantize(
                quantize_value, context=expression.output_field.context
            )

else:

    def converter(value, expression, connection):
        if value is not None:
            return create_decimal(value)

return converter

def convert_uuidfield_value(self, value, expression, connection):
    if value is not None:
        value = uuid.UUID(value)
    return value

def combine_expression(self, connector, sub_expressions):
    # SQLite doesn't have a ^ operator, so use the user-defined POWER
    # function that's registered in connect().
    if connector == "^":
        return "POWER(%s)" % ",".join(sub_expressions)
    elif connector == "#":
        return "BITXOR(%s)" % ",".join(sub_expressions)
    return super().combine_expression(connector, sub_expressions)

def combine_duration_expression(self, connector, sub_expressions):
    if connector not in ["+", "-", "*", "/"]:
        raise DatabaseError("Invalid connector for timedelta: %s." % connector)
    fn_params = ["'%s'" % connector, *sub_expressions]
    if len(fn_params) > 3:
        raise ValueError("Too many params for timedelta operations.")
    return "django_format_dtdelta(%s)" % ", ".join(fn_params)

def integer_field_range(self, internal_type):
    # SQLite doesn't enforce any integer constraints, but sqlite3 supports
    # integers up to 64 bits.
    if internal_type in [
        "PositiveBigIntegerField",
        "PositiveIntegerField",
        "PositiveSmallIntegerField",
    ]:
        return (0, 9223372036854775807)
    return (-9223372036854775808, 9223372036854775807)

def insert_statement(self, on_conflict=None):
    if on_conflict == OnConflict.IGNORE:
        return "INSERT OR IGNORE INTO"
    return super().insert_statement(on_conflict=on_conflict)

def return_insert_columns(self, fields):
    # SQLite < 3.35 doesn't support an INSERT...RETURNING statement.
    if not fields:
        return "", ()
    columns = [
        "%s.%s"
        % (
            self.quote_name(field.model._meta.db_table),
            self.quote_name(field.column),
        )
        for field in fields
    ]
    return "RETURNING %s" % ", ".join(columns), ()

def on_conflict_suffix_sql(self, fields, on_conflict, update_fields, unique_fields):
    if (
        on_conflict == OnConflict.UPDATE
        and self.connection.features.supports_update_conflicts_with_target
    ):
        return "ON CONFLICT(%s) DO UPDATE SET %s" % (
            ", ".join(map(self.quote_name, unique_fields)),
            ", ".join(
                [
                    f"{field} = EXCLUDED.{field}"
                    for field in map(self.quote_name, update_fields)
                ]
            ),
        )
    return super().on_conflict_suffix_sql(
        fields,
        on_conflict,
        update_fields,
        unique_fields,
    )

def __getitem__(self, key):
    key = key.lower().split("(", 1)[0].strip()
    return self.base_data_types_reverse[key]

def get_field_type(self, data_type, description):
    field_type = super().get_field_type(data_type, description)
    if description.pk and field_type in {
        "BigIntegerField",
        "IntegerField",
        "SmallIntegerField",
    }:
        # No support for BigAutoField or SmallAutoField as SQLite treats
        # all integer primary keys as signed 64-bit integers.
        return "AutoField"
    if description.has_json_constraint:
        return "JSONField"
    return field_type

def get_sequences(self, cursor, table_name, table_fields=()):
    pk_col = self.get_primary_key_column(cursor, table_name)
    return [{"table": table_name, "column": pk_col}]

def get_relations(self, cursor, table_name):
    """
    Return a dictionary of {column_name: (ref_column_name, ref_table_name)}
    representing all foreign keys in the given table.
    """
    cursor.execute(
        "PRAGMA foreign_key_list(%s)" % self.connection.ops.quote_name(table_name)
    )
    return {
        column_name: (ref_column_name, ref_table_name)
        for (
            _,
            _,
            ref_table_name,
            column_name,
            ref_column_name,
            *_,
        ) in cursor.fetchall()
    }

def get_primary_key_columns(self, cursor, table_name):
    cursor.execute(
        "PRAGMA table_info(%s)" % self.connection.ops.quote_name(table_name)
    )
    return [name for _, name, *_, pk in cursor.fetchall() if pk]

def _parse_column_or_constraint_definition(self, tokens, columns):
    token = None
    is_constraint_definition = None
    field_name = None
    constraint_name = None
    unique = False
    unique_columns = []
    check = False
    check_columns = []
    braces_deep = 0
    for token in tokens:
        if token.match(sqlparse.tokens.Punctuation, "("):
            braces_deep += 1
        elif token.match(sqlparse.tokens.Punctuation, ")"):
            braces_deep -= 1
            if braces_deep < 0:
                # End of columns and constraints for table definition.
                break
        elif braces_deep == 0 and token.match(sqlparse.tokens.Punctuation, ","):
            # End of current column or constraint definition.
            break
        # Detect column or constraint definition by first token.
        if is_constraint_definition is None:
            is_constraint_definition = token.match(
                sqlparse.tokens.Keyword, "CONSTRAINT"
            )
            if is_constraint_definition:
                continue
        if is_constraint_definition:
            # Detect constraint name by second token.
            if constraint_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    constraint_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    constraint_name = token.value[1:-1]
            # Start constraint columns parsing after UNIQUE keyword.
            if token.match(sqlparse.tokens.Keyword, "UNIQUE"):
                unique = True
                unique_braces_deep = braces_deep
            elif unique:
                if unique_braces_deep == braces_deep:
                    if unique_columns:
                        # Stop constraint parsing.
                        unique = False
                    continue
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    unique_columns.append(token.value)
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    unique_columns.append(token.value[1:-1])
        else:
            # Detect field name by first token.
            if field_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    field_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    field_name = token.value[1:-1]
            if token.match(sqlparse.tokens.Keyword, "UNIQUE"):
                unique_columns = [field_name]
        # Start constraint columns parsing after CHECK keyword.
        if token.match(sqlparse.tokens.Keyword, "CHECK"):
            check = True
            check_braces_deep = braces_deep
        elif check:
            if check_braces_deep == braces_deep:
                if check_columns:
                    # Stop constraint parsing.
                    check = False
                continue
            if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                if token.value in columns:
                    check_columns.append(token.value)
            elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                if token.value[1:-1] in columns:
                    check_columns.append(token.value[1:-1])
    unique_constraint = (
        {
            "unique": True,
            "columns": unique_columns,
            "primary_key": False,
            "foreign_key": None,
            "check": False,
            "index": False,
        }
        if unique_columns
        else None
    )
    check_constraint = (
        {
            "check": True,
            "columns": check_columns,
            "primary_key": False,
            "unique": False,
            "foreign_key": None,
            "index": False,
        }
        if check_columns
        else None
    )
    return constraint_name, unique_constraint, check_constraint, token

def _parse_table_constraints(self, sql, columns):
    # Check constraint parsing is based of SQLite syntax diagram.
    # https://www.sqlite.org/syntaxdiagrams.html#table-constraint
    statement = sqlparse.parse(sql)[0]
    constraints = {}
    unnamed_constrains_index = 0
    tokens = (token for token in statement.flatten() if not token.is_whitespace)
    # Go to columns and constraint definition
    for token in tokens:
        if token.match(sqlparse.tokens.Punctuation, "("):
            break
    # Parse columns and constraint definition
    while True:
        (
            constraint_name,
            unique,
            check,
            end_token,
        ) = self._parse_column_or_constraint_definition(tokens, columns)
        if unique:
            if constraint_name:
                constraints[constraint_name] = unique
            else:
                unnamed_constrains_index += 1
                constraints[
                    "__unnamed_constraint_%s__" % unnamed_constrains_index
                ] = unique
        if check:
            if constraint_name:
                constraints[constraint_name] = check
            else:
                unnamed_constrains_index += 1
                constraints[
                    "__unnamed_constraint_%s__" % unnamed_constrains_index
                ] = check
        if end_token.match(sqlparse.tokens.Punctuation, ")"):
            break
    return constraints

def _get_index_columns_orders(self, sql):
    tokens = sqlparse.parse(sql)[0]
    for token in tokens:
        if isinstance(token, sqlparse.sql.Parenthesis):
            columns = str(token).strip("()").split(", ")
            return ["DESC" if info.endswith("DESC") else "ASC" for info in columns]
    return None

def _get_column_collations(self, cursor, table_name):
    row = cursor.execute(
        """
        SELECT sql
        FROM sqlite_master
        WHERE type = 'table' AND name = %s
    """,
        [table_name],
    ).fetchone()
    if not row:
        return {}

    sql = row[0]
    columns = str(sqlparse.parse(sql)[0][-1]).strip("()").split(", ")
    collations = {}
    for column in columns:
        tokens = column[1:].split()
        column_name = tokens[0].strip('"')
        for index, token in enumerate(tokens):
            if token == "COLLATE":
                collation = tokens[index + 1]
                break
        else:
            collation = None
        collations[column_name] = collation
    return collations

def decoder(conv_func):
    """
    Convert bytestrings from Python's sqlite3 interface to a regular string.
    """
    return lambda s: conv_func(s.decode())

def get_database_version(self):
    return self.Database.sqlite_version_info

@async_unsafe

def create_cursor(self, name=None):
    return self.connection.cursor(factory=SQLiteCursorWrapper)

@async_unsafe

def enable_constraint_checking(self):
    with self.cursor() as cursor:
        cursor.execute("PRAGMA foreign_keys = ON")

def _start_transaction_under_autocommit(self):
    """
    Start a transaction explicitly in autocommit mode.

    Staying in autocommit mode works around a bug of sqlite3 that breaks
    savepoints when autocommit is disabled.
    """
    if self.transaction_mode is None:
        self.cursor().execute("BEGIN")
    else:
        self.cursor().execute(f"BEGIN {self.transaction_mode}")

    def is_in_memory_db(self):
        return self.creation.is_in_memory_db(self.settings_dict["NAME"])


FORMAT_QMARK_REGEX = _lazy_re_compile(r"(?<!%)%s")

def execute(self, query, params=None):
    if params is None:
        return super().execute(query)
    # Extract names if params is a mapping, i.e. "pyformat" style is used.
    param_names = list(params) if isinstance(params, Mapping) else None
    query = self.convert_query(query, param_names=param_names)
    return super().execute(query, params)

def executemany(self, query, param_list):
    # Extract names if params is a mapping, i.e. "pyformat" style is used.
    # Peek carefully as a generator can be passed instead of a list/tuple.
    peekable, param_list = tee(iter(param_list))
    if (params := next(peekable, None)) and isinstance(params, Mapping):
        param_names = list(params)
    else:
        param_names = None
    query = self.convert_query(query, param_names=param_names)
    return super().executemany(query, param_list)

def convert_query(self, query, *, param_names=None):
    if param_names is None:
        # Convert from "format" style to "qmark" style.
        return FORMAT_QMARK_REGEX.sub("?", query).replace("%%", "%")
    else:
        # Convert from "pyformat" style to "named" style.
        return query % {name: f":{name}" for name in param_names}

def __enter__(self):
    # Some SQLite schema alterations need foreign key constraints to be
    # disabled. Enforce it here for the duration of the schema edition.
    if not self.connection.disable_constraint_checking():
        raise NotSupportedError(
            "SQLite schema editor cannot be used while foreign key "
            "constraint checks are enabled. Make sure to disable them "
            "before entering a transaction.atomic() context because "
            "SQLite does not support disabling them in the middle of "
            "a multi-statement transaction."
        )
    return super().__enter__()

def quote_value(self, value):
    # The backend "mostly works" without this function and there are use
    # cases for compiling Python without the sqlite3 libraries (e.g.
    # security hardening).
    try:
        import sqlite3

        value = sqlite3.adapt(value)
    except ImportError:
        pass
    except sqlite3.ProgrammingError:
        pass
    # Manual emulation of SQLite parameter quoting
    if isinstance(value, bool):
        return str(int(value))
    elif isinstance(value, (Decimal, float, int)):
        return str(value)
    elif isinstance(value, str):
        return "'%s'" % value.replace("'", "''")
    elif value is None:
        return "NULL"
    elif isinstance(value, (bytes, bytearray, memoryview)):
        # Bytes are only allowed for BLOB fields, encoded as string
        # literals containing hexadecimal data and preceded by a single "X"
        # character.
        return "X'%s'" % value.hex()
    else:
        raise ValueError(
            "Cannot quote parameter value %r of type %s" % (value, type(value))
        )

def delete_model(self, model, handle_autom2m=True):
    if handle_autom2m:
        super().delete_model(model)
    else:
        # Delete the table (and only that)
        self.execute(
            self.sql_delete_table
            % {
                "table": self.quote_name(model._meta.db_table),
            }
        )
        # Remove all deferred statements referencing the deleted table.
        for sql in list(self.deferred_sql):
            if isinstance(sql, Statement) and sql.references_table(
                model._meta.db_table
            ):
                self.deferred_sql.remove(sql)

def _alter_field(
    self,
    model,
    old_field,
    new_field,
    old_type,
    new_type,
    old_db_params,
    new_db_params,
    strict=False,
):
    """Perform a "physical" (non-ManyToMany) field update."""
    # Use "ALTER TABLE ... RENAME COLUMN" if only the column name
    # changed and there aren't any constraints.
    if (
        old_field.column != new_field.column
        and self.column_sql(model, old_field) == self.column_sql(model, new_field)
        and not (
            old_field.remote_field
            and old_field.db_constraint
            or new_field.remote_field
            and new_field.db_constraint
        )
    ):
        return self.execute(
            self._rename_field_sql(
                model._meta.db_table, old_field, new_field, new_type
            )
        )
    # Alter by remaking table
    self._remake_table(model, alter_fields=[(old_field, new_field)])
    # Rebuild tables with FKs pointing to this field.
    old_collation = old_db_params.get("collation")
    new_collation = new_db_params.get("collation")
    if new_field.unique and (
        old_type != new_type or old_collation != new_collation
    ):
        related_models = set()
        opts = new_field.model._meta
        for remote_field in opts.related_objects:
            # Ignore self-relationship since the table was already rebuilt.
            if remote_field.related_model == model:
                continue
            if not remote_field.many_to_many:
                if remote_field.field_name == new_field.name:
                    related_models.add(remote_field.related_model)
            elif new_field.primary_key and remote_field.through._meta.auto_created:
                related_models.add(remote_field.through)
        if new_field.primary_key:
            for many_to_many in opts.many_to_many:
                # Ignore self-relationship since the table was already rebuilt.
                if many_to_many.related_model == model:
                    continue
                if many_to_many.remote_field.through._meta.auto_created:
                    related_models.add(many_to_many.remote_field.through)
        for related_model in related_models:
            self._remake_table(related_model)

def add_constraint(self, model, constraint):
    if isinstance(constraint, UniqueConstraint) and (
        constraint.condition
        or constraint.contains_expressions
        or constraint.include
        or constraint.deferrable
    ):
        super().add_constraint(model, constraint)
    else:
        self._remake_table(model)

def remove_constraint(self, model, constraint):
    if isinstance(constraint, UniqueConstraint) and (
        constraint.condition
        or constraint.contains_expressions
        or constraint.include
        or constraint.deferrable
    ):
        super().remove_constraint(model, constraint)
    else:
        self._remake_table(model)

def as_sql(self):
    # Prefer the non-standard DELETE FROM syntax over the SQL generated by
    # the SQLDeleteCompiler's default implementation when multiple tables
    # are involved since MySQL/MariaDB will generate a more efficient query
    # plan than when using a subquery.
    where, having, qualify = self.query.where.split_having_qualify(
        must_group_by=self.query.group_by is not None
    )
    if self.single_alias or having or qualify:
        # DELETE FROM cannot be used when filtering against aggregates or
        # window functions as it doesn't allow for GROUP BY/HAVING clauses
        # and the subquery wrapping (necessary to emulate QUALIFY).
        return super().as_sql()
    result = [
        "DELETE %s FROM"
        % self.quote_name_unless_alias(self.query.get_initial_alias())
    ]
    from_sql, params = self.get_from_clause()
    result.extend(from_sql)
    try:
        where_sql, where_params = self.compile(where)
    except FullResultSet:
        pass
    else:
        result.append("WHERE %s" % where_sql)
        params.extend(where_params)
    return " ".join(result), tuple(params)

def sql_table_creation_suffix(self):
    suffix = []
    test_settings = self.connection.settings_dict["TEST"]
    if test_settings["CHARSET"]:
        suffix.append("CHARACTER SET %s" % test_settings["CHARSET"])
    if test_settings["COLLATION"]:
        suffix.append("COLLATE %s" % test_settings["COLLATION"])
    return " ".join(suffix)

def _execute_create_test_db(self, cursor, parameters, keepdb=False):
    try:
        super()._execute_create_test_db(cursor, parameters, keepdb)
    except Exception as e:
        if len(e.args) < 1 or e.args[0] != 1007:
            # All errors except "database exists" (1007) cancel tests.
            self.log("Got an error creating the test database: %s" % e)
            sys.exit(2)
        else:
            raise

def _clone_test_db(self, suffix, verbosity, keepdb=False):
    source_database_name = self.connection.settings_dict["NAME"]
    target_database_name = self.get_test_db_clone_settings(suffix)["NAME"]
    test_db_params = {
        "dbname": self.connection.ops.quote_name(target_database_name),
        "suffix": self.sql_table_creation_suffix(),
    }
    with self._nodb_cursor() as cursor:
        try:
            self._execute_create_test_db(cursor, test_db_params, keepdb)
        except Exception:
            if keepdb:
                # If the database should be kept, skip everything else.
                return
            try:
                if verbosity >= 1:
                    self.log(
                        "Destroying old test database for alias %s..."
                        % (
                            self._get_database_display_str(
                                verbosity, target_database_name
                            ),
                        )
                    )
                cursor.execute("DROP DATABASE %(dbname)s" % test_db_params)
                self._execute_create_test_db(cursor, test_db_params, keepdb)
            except Exception as e:
                self.log("Got an error recreating the test database: %s" % e)
                sys.exit(2)
    self._clone_db(source_database_name, target_database_name)

class DatabaseClient(BaseDatabaseClient):
    executable_name = "mysql"

    @classmethod

def settings_to_cmd_args_env(cls, settings_dict, parameters):
    args = [cls.executable_name]
    env = None
    database = settings_dict["OPTIONS"].get(
        "database",
        settings_dict["OPTIONS"].get("db", settings_dict["NAME"]),
    )
    user = settings_dict["OPTIONS"].get("user", settings_dict["USER"])
    password = settings_dict["OPTIONS"].get(
        "password",
        settings_dict["OPTIONS"].get("passwd", settings_dict["PASSWORD"]),
    )
    host = settings_dict["OPTIONS"].get("host", settings_dict["HOST"])
    port = settings_dict["OPTIONS"].get("port", settings_dict["PORT"])
    server_ca = settings_dict["OPTIONS"].get("ssl", {}).get("ca")
    client_cert = settings_dict["OPTIONS"].get("ssl", {}).get("cert")
    client_key = settings_dict["OPTIONS"].get("ssl", {}).get("key")
    defaults_file = settings_dict["OPTIONS"].get("read_default_file")
    charset = settings_dict["OPTIONS"].get("charset")
    # Seems to be no good way to set sql_mode with CLI.

    if defaults_file:
        args += ["--defaults-file=%s" % defaults_file]
    if user:
        args += ["--user=%s" % user]
    if password:
        # The MYSQL_PWD environment variable usage is discouraged per
        # MySQL's documentation due to the possibility of exposure through
        # `ps` on old Unix flavors but --password suffers from the same
        # flaw on even more systems. Usage of an environment variable also
        # prevents password exposure if the subprocess.run(check=True) call
        # raises a CalledProcessError since the string representation of
        # the latter includes all of the provided `args`.
        env = {"MYSQL_PWD": password}
    if host:
        if "/" in host:
            args += ["--socket=%s" % host]
        else:
            args += ["--host=%s" % host]
    if port:
        args += ["--port=%s" % port]
    if server_ca:
        args += ["--ssl-ca=%s" % server_ca]
    if client_cert:
        args += ["--ssl-cert=%s" % client_cert]
    if client_key:
        args += ["--ssl-key=%s" % client_key]
    if charset:
        args += ["--default-character-set=%s" % charset]
    if database:
        args += [database]
    args.extend(parameters)
    return args, env

