    # NO_AUTO_VALUE_ON_ZERO SQL mode.
    if value == 0 and not self.connection.features.allows_auto_pk_0:
        raise ValueError(
            "The database backend does not accept 0 as a value for AutoField."
        )
    return value

def adapt_datetimefield_value(self, value):
    if value is None:
        return None

    # Expression values are adapted by the database.
    if hasattr(value, "resolve_expression"):
        return value

    # MySQL doesn't support tz-aware datetimes
    if timezone.is_aware(value):
        if settings.USE_TZ:
            value = timezone.make_naive(value, self.connection.timezone)
        else:
            raise ValueError(
                "MySQL backend does not support timezone-aware datetimes when "
                "USE_TZ is False."
            )
    return str(value)

def adapt_timefield_value(self, value):
    if value is None:
        return None

    # Expression values are adapted by the database.
    if hasattr(value, "resolve_expression"):
        return value

    # MySQL doesn't support tz-aware times
    if timezone.is_aware(value):
        raise ValueError("MySQL backend does not support timezone-aware times.")

    return value.isoformat(timespec="microseconds")

def combine_expression(self, connector, sub_expressions):
    if connector == "^":
        return "POW(%s)" % ",".join(sub_expressions)
    # Convert the result to a signed integer since MySQL's binary operators
    # return an unsigned integer.
    elif connector in ("&", "|", "<<", "#"):
        connector = "^" if connector == "#" else connector
        return "CONVERT(%s, SIGNED)" % connector.join(sub_expressions)
    elif connector == ">>":
        lhs, rhs = sub_expressions
        return "FLOOR(%(lhs)s / POW(2, %(rhs)s))" % {"lhs": lhs, "rhs": rhs}
    return super().combine_expression(connector, sub_expressions)

def get_db_converters(self, expression):
    converters = super().get_db_converters(expression)
    internal_type = expression.output_field.get_internal_type()
    if internal_type == "BooleanField":
        converters.append(self.convert_booleanfield_value)
    elif internal_type == "DateTimeField":
        if settings.USE_TZ:
            converters.append(self.convert_datetimefield_value)
    elif internal_type == "UUIDField":
        converters.append(self.convert_uuidfield_value)
    return converters

def convert_booleanfield_value(self, value, expression, connection):
    if value in (0, 1):
        value = bool(value)
    return value

def convert_datetimefield_value(self, value, expression, connection):
    if value is not None:
        value = timezone.make_aware(value, self.connection.timezone)
    return value

def convert_uuidfield_value(self, value, expression, connection):
    if value is not None:
        value = uuid.UUID(value)
    return value

def binary_placeholder_sql(self, value):
    return (
        "_binary %s" if value is not None and not hasattr(value, "as_sql") else "%s"
    )

def subtract_temporals(self, internal_type, lhs, rhs):
    lhs_sql, lhs_params = lhs
    rhs_sql, rhs_params = rhs
    if internal_type == "TimeField":
        if self.connection.mysql_is_mariadb:
            # MariaDB includes the microsecond component in TIME_TO_SEC as
            # a decimal. MySQL returns an integer without microseconds.
            return (
                "CAST((TIME_TO_SEC(%(lhs)s) - TIME_TO_SEC(%(rhs)s)) "
                "* 1000000 AS SIGNED)"
            ) % {
                "lhs": lhs_sql,
                "rhs": rhs_sql,
            }, (
                *lhs_params,
                *rhs_params,
            )
        return (
            "((TIME_TO_SEC(%(lhs)s) * 1000000 + MICROSECOND(%(lhs)s)) -"
            " (TIME_TO_SEC(%(rhs)s) * 1000000 + MICROSECOND(%(rhs)s)))"
        ) % {"lhs": lhs_sql, "rhs": rhs_sql}, tuple(lhs_params) * 2 + tuple(
            rhs_params
        ) * 2
    params = (*rhs_params, *lhs_params)
    return "TIMESTAMPDIFF(MICROSECOND, %s, %s)" % (rhs_sql, lhs_sql), params

def explain_query_prefix(self, format=None, **options):
    # Alias MySQL's TRADITIONAL to TEXT for consistency with other backends.
    if format and format.upper() == "TEXT":
        format = "TRADITIONAL"
    elif (
        not format and "TREE" in self.connection.features.supported_explain_formats
    ):
        # Use TREE by default (if supported) as it's more informative.
        format = "TREE"
    analyze = options.pop("analyze", False)
    prefix = super().explain_query_prefix(format, **options)
    if analyze and self.connection.features.supports_explain_analyze:
        # MariaDB uses ANALYZE instead of EXPLAIN ANALYZE.
        prefix = (
            "ANALYZE" if self.connection.mysql_is_mariadb else prefix + " ANALYZE"
        )
    if format and not (analyze and not self.connection.mysql_is_mariadb):
        # Only MariaDB supports the analyze option with formats.
        prefix += " FORMAT=%s" % format
    return prefix

def regex_lookup(self, lookup_type):
    # REGEXP_LIKE doesn't exist in MariaDB.
    if self.connection.mysql_is_mariadb:
        if lookup_type == "regex":
            return "%s REGEXP BINARY %s"
        return "%s REGEXP %s"

    match_option = "c" if lookup_type == "regex" else "i"
    return "REGEXP_LIKE(%%s, %%s, '%s')" % match_option

def insert_statement(self, on_conflict=None):
    if on_conflict == OnConflict.IGNORE:
        return "INSERT IGNORE INTO"
    return super().insert_statement(on_conflict=on_conflict)

def conditional_expression_supported_in_where_clause(self, expression):
    # MySQL ignores indexes with boolean fields unless they're compared
    # directly to a boolean value.
    if isinstance(expression, (Exists, Lookup)):
        return True
    if isinstance(expression, ExpressionWrapper) and expression.conditional:
        return self.conditional_expression_supported_in_where_clause(
            expression.expression
        )
    if getattr(expression, "conditional", False):
        return False
    return super().conditional_expression_supported_in_where_clause(expression)

def on_conflict_suffix_sql(self, fields, on_conflict, update_fields, unique_fields):
    if on_conflict == OnConflict.UPDATE:
        conflict_suffix_sql = "ON DUPLICATE KEY UPDATE %(fields)s"
        # The use of VALUES() is deprecated in MySQL 8.0.20+. Instead, use
        # aliases for the new row and its columns available in MySQL
        # 8.0.19+.
        if not self.connection.mysql_is_mariadb:
            if self.connection.mysql_version >= (8, 0, 19):
                conflict_suffix_sql = f"AS new {conflict_suffix_sql}"
                field_sql = "%(field)s = new.%(field)s"
            else:
                field_sql = "%(field)s = VALUES(%(field)s)"
        # Use VALUE() on MariaDB.
        else:
            field_sql = "%(field)s = VALUE(%(field)s)"

        fields = ", ".join(
            [
                field_sql % {"field": field}
                for field in map(self.quote_name, update_fields)
            ]
        )
        return conflict_suffix_sql % {"fields": fields}
    return super().on_conflict_suffix_sql(
        fields,
        on_conflict,
        update_fields,
        unique_fields,
    )

def get_field_type(self, data_type, description):
    field_type = super().get_field_type(data_type, description)
    if "auto_increment" in description.extra:
        if field_type == "IntegerField":
            return "AutoField"
        elif field_type == "BigIntegerField":
            return "BigAutoField"
        elif field_type == "SmallIntegerField":
            return "SmallAutoField"
    if description.is_unsigned:
        if field_type == "BigIntegerField":
            return "PositiveBigIntegerField"
        elif field_type == "IntegerField":
            return "PositiveIntegerField"
        elif field_type == "SmallIntegerField":
            return "PositiveSmallIntegerField"
    if description.data_type.upper() == "UUID":
        return "UUIDField"
    # JSON data type is an alias for LONGTEXT in MariaDB, use check
    # constraints clauses to introspect JSONField.
    if description.has_json_constraint:
        return "JSONField"
    return field_type

def get_sequences(self, cursor, table_name, table_fields=()):
    for field_info in self.get_table_description(cursor, table_name):
        if "auto_increment" in field_info.extra:
            # MySQL allows only one auto-increment column per table.
            return [{"table": table_name, "column": field_info.name}]
    return []

def _parse_constraint_columns(self, check_clause, columns):
    check_columns = OrderedSet()
    statement = sqlparse.parse(check_clause)[0]
    tokens = (token for token in statement.flatten() if not token.is_whitespace)
    for token in tokens:
        if (
            token.ttype == sqlparse.tokens.Name
            and self.connection.ops.quote_name(token.value) == token.value
            and token.value[1:-1] in columns
        ):
            check_columns.add(token.value[1:-1])
    return check_columns

def execute(self, query, args=None):
    try:
        # args is None means no string interpolation
        return self.cursor.execute(query, args)
    except Database.OperationalError as e:
        # Map some error codes to IntegrityError, since they seem to be
        # misclassified and Django would prefer the more logical place.
        if e.args[0] in self.codes_for_integrityerror:
            raise IntegrityError(*tuple(e.args))
        raise

def executemany(self, query, args):
    try:
        return self.cursor.executemany(query, args)
    except Database.OperationalError as e:
        # Map some error codes to IntegrityError, since they seem to be
        # misclassified and Django would prefer the more logical place.
        if e.args[0] in self.codes_for_integrityerror:
            raise IntegrityError(*tuple(e.args))
        raise

def get_connection_params(self):
    kwargs = {
        "conv": django_conversions,
        "charset": "utf8mb4",
    }
    settings_dict = self.settings_dict
    if settings_dict["USER"]:
        kwargs["user"] = settings_dict["USER"]
    if settings_dict["NAME"]:
        kwargs["database"] = settings_dict["NAME"]
    if settings_dict["PASSWORD"]:
        kwargs["password"] = settings_dict["PASSWORD"]
    if settings_dict["HOST"].startswith("/"):
        kwargs["unix_socket"] = settings_dict["HOST"]
    elif settings_dict["HOST"]:
        kwargs["host"] = settings_dict["HOST"]
    if settings_dict["PORT"]:
        kwargs["port"] = int(settings_dict["PORT"])
    # We need the number of potentially affected rows after an
    # "UPDATE", not the number of changed rows.
    kwargs["client_flag"] = CLIENT.FOUND_ROWS
    # Validate the transaction isolation level, if specified.
    options = settings_dict["OPTIONS"].copy()
    isolation_level = options.pop("isolation_level", "read committed")
    if isolation_level:
        isolation_level = isolation_level.lower()
        if isolation_level not in self.isolation_levels:
            raise ImproperlyConfigured(
                "Invalid transaction isolation level '%s' specified.\n"
                "Use one of %s, or None."
                % (
                    isolation_level,
                    ", ".join("'%s'" % s for s in sorted(self.isolation_levels)),
                )
            )
    self.isolation_level = isolation_level
    kwargs.update(options)
    return kwargs

@async_unsafe

def get_new_connection(self, conn_params):
    connection = Database.connect(**conn_params)
    return connection

def init_connection_state(self):
    super().init_connection_state()
    assignments = []
    if self.features.is_sql_auto_is_null_enabled:
        # SQL_AUTO_IS_NULL controls whether an AUTO_INCREMENT column on
        # a recently inserted row will return when the field is tested
        # for NULL. Disabling this brings this aspect of MySQL in line
        # with SQL standards.
        assignments.append("SET SQL_AUTO_IS_NULL = 0")

    if self.isolation_level:
        assignments.append(
            "SET SESSION TRANSACTION ISOLATION LEVEL %s"
            % self.isolation_level.upper()
        )

    if assignments:
        with self.cursor() as cursor:
            cursor.execute("; ".join(assignments))

@async_unsafe

def create_cursor(self, name=None):
    cursor = self.connection.cursor()
    return CursorWrapper(cursor)

def _rollback(self):
    try:
        BaseDatabaseWrapper._rollback(self)
    except Database.NotSupportedError:
        pass

def _set_autocommit(self, autocommit):
    with self.wrap_database_errors:
        self.connection.autocommit(autocommit)

def is_usable(self):
    try:
        self.connection.ping()
    except Database.Error:
        return False
    else:
        return True

@cached_property

def display_name(self):
    return "MariaDB" if self.mysql_is_mariadb else "MySQL"

@cached_property

def data_type_check_constraints(self):
    if self.features.supports_column_check_constraints:
        check_constraints = {
            "PositiveBigIntegerField": "`%(column)s` >= 0",
            "PositiveIntegerField": "`%(column)s` >= 0",
            "PositiveSmallIntegerField": "`%(column)s` >= 0",
        }
        return check_constraints
    return {}

@cached_property

def mysql_server_info(self):
    return self.mysql_server_data["version"]

@cached_property

def mysql_version(self):
    match = server_version_re.match(self.mysql_server_info)
    if not match:
        raise Exception(
            "Unable to determine MySQL version from version string %r"
            % self.mysql_server_info
        )
    return tuple(int(x) for x in match.groups())

@cached_property

def mysql_is_mariadb(self):
    return "mariadb" in self.mysql_server_info.lower()

@cached_property

def sql_mode(self):
    sql_mode = self.mysql_server_data["sql_mode"]
    return set(sql_mode.split(",") if sql_mode else ())

def quote_value(self, value):
    self.connection.ensure_connection()
    # MySQLdb escapes to string, PyMySQL to bytes.
    quoted = self.connection.connection.escape(
        value, self.connection.connection.encoders
    )
    if isinstance(value, str) and isinstance(quoted, bytes):
        quoted = quoted.decode()
    return quoted

def _is_limited_data_type(self, field):
    db_type = field.db_type(self.connection)
    return (
        db_type is not None
        and db_type.lower() in self.connection._limited_data_types
    )

def _is_text_or_blob(self, field):
    db_type = field.db_type(self.connection)
    return db_type and db_type.lower().endswith(("blob", "text"))

def skip_default(self, field):
    default_is_empty = self.effective_default(field) in ("", b"")
    if default_is_empty and self._is_text_or_blob(field):
        return True
    if not self._supports_limited_data_type_defaults:
        return self._is_limited_data_type(field)
    return False

def skip_default_on_alter(self, field):
    default_is_empty = self.effective_default(field) in ("", b"")
    if default_is_empty and self._is_text_or_blob(field):
        return True
    if self._is_limited_data_type(field) and not self.connection.mysql_is_mariadb:
        # MySQL doesn't support defaults for BLOB and TEXT in the
        # ALTER COLUMN statement.
        return True
    return False

@property

def _supports_limited_data_type_defaults(self):
    # MariaDB and MySQL >= 8.0.13 support defaults for BLOB and TEXT.
    if self.connection.mysql_is_mariadb:
        return True
    return self.connection.mysql_version >= (8, 0, 13)

def _column_default_sql(self, field):
    if (
        not self.connection.mysql_is_mariadb
        and self._supports_limited_data_type_defaults
        and self._is_limited_data_type(field)
    ):
        # MySQL supports defaults for BLOB and TEXT columns only if the
        # default value is written as an expression i.e. in parentheses.
        return "(%s)"
    return super()._column_default_sql(field)

def add_field(self, model, field):
    super().add_field(model, field)

    # Simulate the effect of a one-off default.
    # field.default may be unhashable, so a set isn't used for "in" check.
    if self.skip_default(field) and field.default not in (None, NOT_PROVIDED):
        effective_default = self.effective_default(field)
        self.execute(
            "UPDATE %(table)s SET %(column)s = %%s"
            % {
                "table": self.quote_name(model._meta.db_table),
                "column": self.quote_name(field.column),
            },
            [effective_default],
        )

def remove_constraint(self, model, constraint):
    if (
        isinstance(constraint, UniqueConstraint)
        and constraint.create_sql(model, self) is not None
    ):
        self._create_missing_fk_index(
            model,
            fields=constraint.fields,
            expressions=constraint.expressions,
        )
    super().remove_constraint(model, constraint)

def _field_should_be_indexed(self, model, field):
    if not super()._field_should_be_indexed(model, field):
        return False

    storage = self.connection.introspection.get_storage_engine(
        self.connection.cursor(), model._meta.db_table
    )
    # No need to create an index for ForeignKey fields except if
    # db_constraint=False because the index from that constraint won't be
    # created.
    if (
        storage == "InnoDB"
        and field.get_internal_type() == "ForeignKey"
        and field.db_constraint
    ):
        return False
    return not self._is_limited_data_type(field)

def _delete_composed_index(self, model, fields, *args):
    self._create_missing_fk_index(model, fields=fields)
    return super()._delete_composed_index(model, fields, *args)

def _alter_column_type_sql(
    self, model, old_field, new_field, new_type, old_collation, new_collation
):
    new_type = self._set_field_new_type(old_field, new_type)
    return super()._alter_column_type_sql(
        model, old_field, new_field, new_type, old_collation, new_collation
    )

def _field_db_check(self, field, field_db_params):
    if self.connection.mysql_is_mariadb:
        return super()._field_db_check(field, field_db_params)
    # On MySQL, check constraints with the column name as it requires
    # explicit recreation when the column is renamed.
    return field_db_params["check"]

def _rename_field_sql(self, table, old_field, new_field, new_type):
    new_type = self._set_field_new_type(old_field, new_type)
    return super()._rename_field_sql(table, old_field, new_field, new_type)

def _alter_column_comment_sql(self, model, new_field, new_type, new_db_comment):
    # Comment is alter when altering the column type.
    return "", []

def _comment_sql(self, comment):
    comment_sql = super()._comment_sql(comment)
    return f" COMMENT {comment_sql}"

def _alter_column_null_sql(self, model, old_field, new_field):
    if not new_field.has_db_default():
        return super()._alter_column_null_sql(model, old_field, new_field)

    new_db_params = new_field.db_parameters(connection=self.connection)
    type_sql = self._set_field_new_type(new_field, new_db_params["type"])
    return (
        "MODIFY %(column)s %(type)s"
        % {
            "column": self.quote_name(new_field.column),
            "type": type_sql,
        },
        [],
    )

def _check_sql_mode(self, **kwargs):
    if not (
        self.connection.sql_mode & {"STRICT_TRANS_TABLES", "STRICT_ALL_TABLES"}
    ):
        return [
            checks.Warning(
                "%s Strict Mode is not set for database connection '%s'"
                % (self.connection.display_name, self.connection.alias),
                hint=(
                    "%s's Strict Mode fixes many data integrity problems in "
                    "%s, such as data truncation upon insertion, by "
                    "escalating warnings into errors. It is strongly "
                    "recommended you activate it. See: "
                    "https://docs.djangoproject.com/en/%s/ref/databases/"
                    "#mysql-sql-mode"
                    % (
                        self.connection.display_name,
                        self.connection.display_name,
                        get_docs_version(),
                    ),
                ),
                id="mysql.W002",
            )
        ]
    return []

def get_objects():
    from django.db.migrations.loader import MigrationLoader

    loader = MigrationLoader(self.connection)
    for app_config in apps.get_app_configs():
        if (
            app_config.models_module is not None
            and app_config.label in loader.migrated_apps
            and app_config.name not in settings.TEST_NON_SERIALIZED_APPS
        ):
            for model in app_config.get_models():
                if model._meta.can_migrate(
                    self.connection
                ) and router.allow_migrate_model(self.connection.alias, model):
                    queryset = model._base_manager.using(
                        self.connection.alias,
                    ).order_by(model._meta.pk.name)
                    chunk_size = (
                        2000 if queryset._prefetch_related_lookups else None
                    )
                    yield from queryset.iterator(chunk_size=chunk_size)

# Serialize to a string
out = StringIO()
serializers.serialize("json", get_objects(), indent=None, stream=out)
return out.getvalue()

def _get_database_display_str(self, verbosity, database_name):
    """
    Return display string for a database for use in various actions.
    """
    return "'%s'%s" % (
        self.connection.alias,
        (" ('%s')" % database_name) if verbosity >= 2 else "",
    )

def _create_test_db(self, verbosity, autoclobber, keepdb=False):
    """
    Internal implementation - create the test db tables.
    """
    test_database_name = self._get_test_db_name()
    test_db_params = {
        "dbname": self.connection.ops.quote_name(test_database_name),
        "suffix": self.sql_table_creation_suffix(),
    }
    # Create the test database and connect to it.
    with self._nodb_cursor() as cursor:
        try:
            self._execute_create_test_db(cursor, test_db_params, keepdb)
        except Exception as e:
            # if we want to keep the db, then no need to do any of the below,
            # just return and skip it all.
            if keepdb:
                return test_database_name

            self.log("Got an error creating the test database: %s" % e)
            if not autoclobber:
                confirm = input(
                    "Type 'yes' if you would like to try deleting the test "
                    "database '%s', or 'no' to cancel: " % test_database_name
                )
            if autoclobber or confirm == "yes":
                try:
                    if verbosity >= 1:
                        self.log(
                            "Destroying old test database for alias %s..."
                            % (
                                self._get_database_display_str(
                                    verbosity, test_database_name
                                ),
                            )
                        )
                    cursor.execute("DROP DATABASE %(dbname)s" % test_db_params)
                    self._execute_create_test_db(cursor, test_db_params, keepdb)
                except Exception as e:
                    self.log("Got an error recreating the test database: %s" % e)
                    sys.exit(2)
            else:
                self.log("Tests cancelled.")
                sys.exit(1)

    return test_database_name

def destroy_test_db(
    self, old_database_name=None, verbosity=1, keepdb=False, suffix=None
):
    """
    Destroy a test database, prompting the user for confirmation if the
    database already exists.
    """
    self.connection.close()
    if suffix is None:
        test_database_name = self.connection.settings_dict["NAME"]
    else:
        test_database_name = self.get_test_db_clone_settings(suffix)["NAME"]

    if verbosity >= 1:
        action = "Destroying"
        if keepdb:
            action = "Preserving"
        self.log(
            "%s test database for alias %s..."
            % (
                action,
                self._get_database_display_str(verbosity, test_database_name),
            )
        )

    # if we want to preserve the database
    # skip the actual destroying piece.
    if not keepdb:
        self._destroy_test_db(test_database_name, verbosity)

    # Restore the original database name
    if old_database_name is not None:
        settings.DATABASES[self.connection.alias]["NAME"] = old_database_name
        self.connection.settings_dict["NAME"] = old_database_name

def __init__(self, connection):
    # connection is an instance of BaseDatabaseWrapper.
    self.connection = connection

def __del__(self):
    del self.connection

@classmethod

def settings_to_cmd_args_env(cls, settings_dict, parameters):
    raise NotImplementedError(
        "subclasses of BaseDatabaseClient must provide a "
        "settings_to_cmd_args_env() method or override a runshell()."
    )

def runshell(self, parameters):
    args, env = self.settings_to_cmd_args_env(
        self.connection.settings_dict, parameters
    )
    env = {**os.environ, **env} if env else None
    subprocess.run(args, env=env, check=True)

def __del__(self):
    del self.connection

@cached_property

def supports_explaining_query_execution(self):
    """Does this backend support explaining query execution?"""
    return self.connection.ops.explain_prefix is not None

@cached_property

def allows_group_by_selected_pks_on_model(self, model):
    if not self.allows_group_by_selected_pks:
        return False
    return model._meta.managed

def __init__(self, connection):
    self.connection = connection
    self._cache = None

def format_for_duration_arithmetic(self, sql):
    raise NotImplementedError(
        "subclasses of BaseDatabaseOperations may require a "
        "format_for_duration_arithmetic() method."
    )

def time_extract_sql(self, lookup_type, sql, params):
    """
    Given a lookup_type of 'hour', 'minute', or 'second', return the SQL
    that extracts a value from the given time field field_name.
    """
    return self.date_extract_sql(lookup_type, sql, params)

def distinct_sql(self, fields, params):
    """
    Return an SQL DISTINCT clause which removes duplicate rows from the
    result set. If any fields are given, only check the given fields for
    duplicates.
    """
    if fields:
        raise NotSupportedError(
            "DISTINCT ON fields is not supported by this database backend"
        )
    else:
        return ["DISTINCT"], []

def fetch_returned_insert_columns(self, cursor, returning_params):
    """
    Given a cursor object that has just performed an INSERT...RETURNING
    statement into a table, return the newly created data.
    """
    return cursor.fetchone()

def for_update_sql(self, nowait=False, skip_locked=False, of=(), no_key=False):
    """
    Return the FOR UPDATE SQL clause to lock rows for an update operation.
    """
    return "FOR%s UPDATE%s%s%s" % (
        " NO KEY" if no_key else "",
        " OF %s" % ", ".join(of) if of else "",
        " NOWAIT" if nowait else "",
        " SKIP LOCKED" if skip_locked else "",
    )

def _get_limit_offset_params(self, low_mark, high_mark):
    offset = low_mark or 0
    if high_mark is not None:
        return (high_mark - offset), offset
    elif offset:
        return self.connection.ops.no_limit_value(), offset
    return None, offset

def limit_offset_sql(self, low_mark, high_mark):
    """Return LIMIT/OFFSET SQL clause."""
    limit, offset = self._get_limit_offset_params(low_mark, high_mark)
    return " ".join(
        sql
        for sql in (
            ("LIMIT %d" % limit) if limit else None,
            ("OFFSET %d" % offset) if offset else None,
        )
        if sql
    )

def to_string(s):
    return force_str(s, strings_only=True, errors="replace")

if isinstance(params, (list, tuple)):
    u_params = tuple(to_string(val) for val in params)
elif params is None:
    u_params = ()
else:
    u_params = {to_string(k): to_string(v) for k, v in params.items()}

return "QUERY = %r - PARAMS = %r" % (sql, u_params)

def compiler(self, compiler_name):
    """
    Return the SQLCompiler class corresponding to the given name,
    in the namespace corresponding to the `compiler_module` attribute
    on this backend.
    """
    if self._cache is None:
        self._cache = import_module(self.compiler_module)
    return getattr(self._cache, compiler_name)

def savepoint_commit_sql(self, sid):
    """
    Return the SQL for committing the given savepoint.
    """
    return "RELEASE SAVEPOINT %s" % self.quote_name(sid)

def savepoint_rollback_sql(self, sid):
    """
    Return the SQL for rolling back the given savepoint.
    """
    return "ROLLBACK TO SAVEPOINT %s" % self.quote_name(sid)

def execute_sql_flush(self, sql_list):
    """Execute a list of SQL statements to flush the database."""
    with transaction.atomic(
        using=self.connection.alias,
        savepoint=self.connection.features.can_rollback_ddl,
    ):
        with self.connection.cursor() as cursor:
            for sql in sql_list:
                cursor.execute(sql)

def start_transaction_sql(self):
    """Return the SQL statement required to start a transaction."""
    return "BEGIN;"

def end_transaction_sql(self, success=True):
    """Return the SQL statement required to end a transaction."""
    if not success:
        return "ROLLBACK;"
    return "COMMIT;"

def prep_for_like_query(self, x):
    """Prepare a value for use in a LIKE query."""
    return str(x).replace("\\", "\\\\").replace("%", r"\%").replace("_", r"\_")

# Same as prep_for_like_query(), but called for "iexact" matches, which
# need not necessarily be implemented using "LIKE" in the backend.
prep_for_iexact_query = prep_for_like_query

def adapt_unknown_value(self, value):
    """
    Transform a value to something compatible with the backend driver.

    This method only depends on the type of the value. It's designed for
    cases where the target type isn't known, such as .raw() SQL queries.
    As a consequence it may not work perfectly in all circumstances.
    """
    if isinstance(value, datetime.datetime):  # must be before date
        return self.adapt_datetimefield_value(value)
    elif isinstance(value, datetime.date):
        return self.adapt_datefield_value(value)
    elif isinstance(value, datetime.time):
        return self.adapt_timefield_value(value)
    elif isinstance(value, decimal.Decimal):
        return self.adapt_decimalfield_value(value)
    else:
        return value

def adapt_datefield_value(self, value):
    """
    Transform a date value to an object compatible with what is expected
    by the backend driver for date columns.
    """
    if value is None:
        return None
    return str(value)

def adapt_datetimefield_value(self, value):
    """
    Transform a datetime value to an object compatible with what is expected
    by the backend driver for datetime columns.
    """
    if value is None:
        return None
    return str(value)

def adapt_timefield_value(self, value):
    """
    Transform a time value to an object compatible with what is expected
    by the backend driver for time columns.
    """
    if value is None:
        return None
    if timezone.is_aware(value):
        raise ValueError("Django does not support timezone-aware times.")
    return str(value)

def convert_durationfield_value(self, value, expression, connection):
    if value is not None:
        return datetime.timedelta(0, 0, value)

def subtract_temporals(self, internal_type, lhs, rhs):
    if self.connection.features.supports_temporal_subtraction:
        lhs_sql, lhs_params = lhs
        rhs_sql, rhs_params = rhs
        return "(%s - %s)" % (lhs_sql, rhs_sql), (*lhs_params, *rhs_params)
    raise NotSupportedError(
        "This backend does not support %s subtraction." % internal_type
    )

def window_frame_value(self, value):
    if isinstance(value, int):
        if value == 0:
            return self.CURRENT_ROW
        elif value < 0:
            return "%d %s" % (abs(value), self.PRECEDING)
        else:
            return "%d %s" % (value, self.FOLLOWING)

def window_frame_rows_start_end(self, start=None, end=None):
    """
    Return SQL for start and end points in an OVER clause window frame.
    """
    if isinstance(start, int) and isinstance(end, int) and start > end:
        raise ValueError("start cannot be greater than end.")
    if start is not None and not isinstance(start, int):
        raise ValueError(
            f"start argument must be an integer, zero, or None, but got '{start}'."
        )
    if end is not None and not isinstance(end, int):
        raise ValueError(
            f"end argument must be an integer, zero, or None, but got '{end}'."
        )
    start_ = self.window_frame_value(start) or self.UNBOUNDED_PRECEDING
    end_ = self.window_frame_value(end) or self.UNBOUNDED_FOLLOWING
    return start_, end_

def window_frame_range_start_end(self, start=None, end=None):
    if (start is not None and not isinstance(start, int)) or (
        isinstance(start, int) and start > 0
    ):
        raise ValueError(
            "start argument must be a negative integer, zero, or None, "
            "but got '%s'." % start
        )
    if (end is not None and not isinstance(end, int)) or (
        isinstance(end, int) and end < 0
    ):
        raise ValueError(
            "end argument must be a positive integer, zero, or None, but got '%s'."
            % end
        )
    start_ = self.window_frame_value(start) or self.UNBOUNDED_PRECEDING
    end_ = self.window_frame_value(end) or self.UNBOUNDED_FOLLOWING
    features = self.connection.features
    if features.only_supports_unbounded_with_preceding_and_following and (
        (start and start < 0) or (end and end > 0)
    ):
        raise NotSupportedError(
            "%s only supports UNBOUNDED together with PRECEDING and "
            "FOLLOWING." % self.connection.display_name
        )
    return start_, end_

def explain_query_prefix(self, format=None, **options):
    if not self.connection.features.supports_explaining_query_execution:
        raise NotSupportedError(
            "This backend does not support explaining query execution."
        )
    if format:
        supported_formats = self.connection.features.supported_explain_formats
        normalized_format = format.upper()
        if normalized_format not in supported_formats:
            msg = "%s is not a recognized format." % normalized_format
            if supported_formats:
                msg += " Allowed formats: %s" % ", ".join(sorted(supported_formats))
            else:
                msg += (
                    f" {self.connection.display_name} does not support any formats."
                )
            raise ValueError(msg)
    if options:
        raise ValueError("Unknown options: %s" % ", ".join(sorted(options.keys())))
    return self.explain_prefix

def format_debug_sql(self, sql):
    # Hook for backends (e.g. NoSQL) to customize formatting.
    return sqlparse.format(sql, reindent=True, keyword_case="upper")

def compile_json_path(self, key_transforms, include_root=True):
    """
    Hook for backends to customize all aspects of JSON path construction.
    """
    path = ["$"] if include_root else []
    for key_transform in key_transforms:
        try:
            num = int(key_transform)
        except ValueError:  # Non-integer.
            path.append(".")
            path.append(json.dumps(key_transform))
        else:
            if (
                num < 0
                and not self.connection.features.supports_json_negative_indexing
            ):
                raise NotSupportedError(
                    "Using negative JSON array indices is not supported on this "
                    "database backend."
                )
            path.append(self.format_json_path_numeric_index(num))
    return "".join(path)

class BaseDatabaseIntrospection:
    """Encapsulate backend-specific introspection utilities."""

    data_types_reverse = {}

def get_names(cursor):
    return sorted(
        ti.name
        for ti in self.get_table_list(cursor)
        if include_views or ti.type == "t"
    )

if cursor is None:
    with self.connection.cursor() as cursor:
        return get_names(cursor)
return get_names(cursor)

def get_migratable_models(self):
    from django.apps import apps
    from django.db import router

    return (
        model
        for app_config in apps.get_app_configs()
        for model in router.get_migratable_models(app_config, self.connection.alias)
        if model._meta.can_migrate(self.connection)
    )

def installed_models(self, tables):
    """
    Return a set of all models represented by the provided list of table
    names.
    """
    tables = set(map(self.identifier_converter, tables))
    return {
        m
        for m in self.get_migratable_models()
        if self.identifier_converter(m._meta.db_table) in tables
    }

def sequence_list(self):
    """
    Return a list of information about all DB sequences for all models in
    all apps.
    """
    sequence_list = []
    with self.connection.cursor() as cursor:
        for model in self.get_migratable_models():
            if not model._meta.managed:
                continue
            if model._meta.swapped:
                continue
            sequence_list.extend(
                self.get_sequences(
                    cursor, model._meta.db_table, model._meta.local_fields
                )
            )
            for f in model._meta.local_many_to_many:
                # If this is an m2m using an intermediate table,
                # we don't need to reset the sequence.
                if f.remote_field.through._meta.auto_created:
                    sequence = self.get_sequences(cursor, f.m2m_db_table())
                    sequence_list.extend(
                        sequence or [{"table": f.m2m_db_table(), "column": None}]
                    )
    return sequence_list

def get_relations(self, cursor, table_name):
    """
    Return a dictionary of {field_name: (field_name_other_table, other_table)}
    representing all foreign keys in the given table.
    """
    raise NotImplementedError(
        "subclasses of BaseDatabaseIntrospection may require a "
        "get_relations() method."
    )

def get_primary_key_columns(self, cursor, table_name):
    """Return a list of primary key columns for the given table."""
    for constraint in self.get_constraints(cursor, table_name).values():
        if constraint["primary_key"]:
            return constraint["columns"]
    return None

def __repr__(self):
    return (
        f"<{self.__class__.__qualname__} "
        f"vendor={self.vendor!r} alias={self.alias!r}>"
    )

def timezone(self):
    """
    Return a tzinfo of the database connection time zone.

    This is only used when time zone support is enabled. When a datetime is
    read from the database, it is always returned in this time zone.

    When the database backend supports time zones, it doesn't matter which
    time zone Django uses, as long as aware datetimes are used everywhere.
    Other users connecting to the database can choose their own time zone.

    When the database backend doesn't support time zones, the time zone
    Django uses may be constrained by the requirements of other users of
    the database.
    """
    if not settings.USE_TZ:
        return None
    elif self.settings_dict["TIME_ZONE"] is None:
        return datetime.UTC
    else:
        return zoneinfo.ZoneInfo(self.settings_dict["TIME_ZONE"])

@cached_property

def timezone_name(self):
    """
    Name of the time zone of the database connection.
    """
    if not settings.USE_TZ:
        return settings.TIME_ZONE
    elif self.settings_dict["TIME_ZONE"] is None:
        return "UTC"
    else:
        return self.settings_dict["TIME_ZONE"]

@property

def queries_logged(self):
    return self.force_debug_cursor or settings.DEBUG

@property

def queries(self):
    if len(self.queries_log) == self.queries_log.maxlen:
        warnings.warn(
            "Limit for query logging exceeded, only the last {} queries "
            "will be returned.".format(self.queries_log.maxlen),
            stacklevel=2,
        )
    return list(self.queries_log)

def get_database_version(self):
    """Return a tuple of the database's version."""
    raise NotImplementedError(
        "subclasses of BaseDatabaseWrapper may require a get_database_version() "
        "method."
    )

def get_connection_params(self):
    """Return a dict of parameters suitable for get_new_connection."""
    raise NotImplementedError(
        "subclasses of BaseDatabaseWrapper may require a get_connection_params() "
        "method"
    )

def get_new_connection(self, conn_params):
    """Open a connection to the database."""
    raise NotImplementedError(
        "subclasses of BaseDatabaseWrapper may require a get_new_connection() "
        "method"
    )

def init_connection_state(self):
    """Initialize the database connection settings."""
    if self.alias not in RAN_DB_VERSION_CHECK:
        self.check_database_version_supported()
        RAN_DB_VERSION_CHECK.add(self.alias)

def create_cursor(self, name=None):
    """Create a cursor. Assume that a connection is established."""
    raise NotImplementedError(
        "subclasses of BaseDatabaseWrapper may require a create_cursor() method"
    )

# ##### Backend-specific methods for creating connections #####

@async_unsafe

def check_settings(self):
    if self.settings_dict["TIME_ZONE"] is not None and not settings.USE_TZ:
        raise ImproperlyConfigured(
            "Connection '%s' cannot set TIME_ZONE because USE_TZ is False."
            % self.alias
        )

@async_unsafe

def ensure_connection(self):
    """Guarantee that a connection to the database is established."""
    if self.connection is None:
        if self.in_atomic_block and self.closed_in_transaction:
            raise ProgrammingError(
                "Cannot open a new connection in an atomic block."
            )
        with self.wrap_database_errors:
            self.connect()

# ##### Backend-specific wrappers for PEP-249 connection methods #####

def _prepare_cursor(self, cursor):
    """
    Validate the connection is usable and perform database cursor wrapping.
    """
    self.validate_thread_sharing()
    if self.queries_logged:
        wrapped_cursor = self.make_debug_cursor(cursor)
    else:
        wrapped_cursor = self.make_cursor(cursor)
    return wrapped_cursor

def _cursor(self, name=None):
    self.close_if_health_check_failed()
    self.ensure_connection()
    with self.wrap_database_errors:
        return self._prepare_cursor(self.create_cursor(name))

def _commit(self):
    if self.connection is not None:
        with debug_transaction(self, "COMMIT"), self.wrap_database_errors:
            return self.connection.commit()

def _rollback(self):
    if self.connection is not None:
        with debug_transaction(self, "ROLLBACK"), self.wrap_database_errors:
            return self.connection.rollback()

def _close(self):
    if self.connection is not None:
        with self.wrap_database_errors:
            return self.connection.close()

# ##### Generic wrappers for PEP-249 connection methods #####

@async_unsafe

def cursor(self):
    """Create a cursor, opening a connection if necessary."""
    return self._cursor()

@async_unsafe

def _savepoint(self, sid):
    with self.cursor() as cursor:
        cursor.execute(self.ops.savepoint_create_sql(sid))

def _savepoint_rollback(self, sid):
    with self.cursor() as cursor:
        cursor.execute(self.ops.savepoint_rollback_sql(sid))

def _savepoint_commit(self, sid):
    with self.cursor() as cursor:
        cursor.execute(self.ops.savepoint_commit_sql(sid))

def _savepoint_allowed(self):
    # Savepoints cannot be created outside a transaction
    return self.features.uses_savepoints and not self.get_autocommit()

# ##### Generic savepoint management methods #####

@async_unsafe

def savepoint_commit(self, sid):
    """
    Release a savepoint. Do nothing if savepoints are not supported.
    """
    if not self._savepoint_allowed():
        return

    self.validate_thread_sharing()
    self._savepoint_commit(sid)

@async_unsafe

def get_rollback(self):
    """Get the "needs rollback" flag -- for *advanced use* only."""
    if not self.in_atomic_block:
        raise TransactionManagementError(
            "The rollback flag doesn't work outside of an 'atomic' block."
        )
    return self.needs_rollback

def set_rollback(self, rollback):
    """
    Set or unset the "needs rollback" flag -- for *advanced use* only.
    """
    if not self.in_atomic_block:
        raise TransactionManagementError(
            "The rollback flag doesn't work outside of an 'atomic' block."
        )
    self.needs_rollback = rollback

def validate_no_atomic_block(self):
    """Raise an error if an atomic block is active."""
    if self.in_atomic_block:
        raise TransactionManagementError(
            "This is forbidden when an 'atomic' block is active."
        )

def validate_no_broken_transaction(self):
    if self.needs_rollback:
        raise TransactionManagementError(
            "An error occurred in the current transaction. You can't "
            "execute queries until the end of the 'atomic' block."
        ) from self.rollback_exc

# ##### Foreign key constraints checks handling #####

@contextmanager

def constraint_checks_disabled(self):
    """
    Disable foreign key constraint checking.
    """
    disabled = self.disable_constraint_checking()
    try:
        yield
    finally:
        if disabled:
            self.enable_constraint_checking()

def close_if_health_check_failed(self):
    """Close existing connection if it fails a health check."""
    if (
        self.connection is None
        or not self.health_check_enabled
        or self.health_check_done
    ):
        return

    if not self.is_usable():
        self.close()
    self.health_check_done = True

def close_if_unusable_or_obsolete(self):
    """
    Close the current connection if unrecoverable errors have occurred
    or if it outlived its maximum age.
    """
    if self.connection is not None:
        self.health_check_done = False
        # If the application didn't restore the original autocommit setting,
        # don't take chances, drop the connection.
        if self.get_autocommit() != self.settings_dict["AUTOCOMMIT"]:
            self.close()
            return

        # If an exception other than DataError or IntegrityError occurred
        # since the last commit / rollback, check if the connection works.
        if self.errors_occurred:
            if self.is_usable():
                self.errors_occurred = False
                self.health_check_done = True
            else:
                self.close()
                return

        if self.close_at is not None and time.monotonic() >= self.close_at:
            self.close()
            return

# ##### Thread safety handling #####

@property

def allow_thread_sharing(self):
    with self._thread_sharing_lock:
        return self._thread_sharing_count > 0

def inc_thread_sharing(self):
    with self._thread_sharing_lock:
        self._thread_sharing_count += 1

def dec_thread_sharing(self):
    with self._thread_sharing_lock:
        if self._thread_sharing_count <= 0:
            raise RuntimeError(
                "Cannot decrement the thread sharing count below zero."
            )
        self._thread_sharing_count -= 1

def wrap_database_errors(self):
    """
    Context manager and decorator that re-throws backend-specific database
    exceptions using Django's common wrappers.
    """
    return DatabaseErrorWrapper(self)

def chunked_cursor(self):
    """
    Return a cursor that tries to avoid caching in the database (if
    supported by the database), otherwise return a regular cursor.
    """
    return self.cursor()

def make_debug_cursor(self, cursor):
    """Create a cursor that logs all queries in self.queries_log."""
    return utils.CursorDebugWrapper(cursor, self)

def make_cursor(self, cursor):
    """Create a cursor without debug logging."""
    return utils.CursorWrapper(cursor, self)

@contextmanager

def schema_editor(self, *args, **kwargs):
    """
    Return a new instance of this backend's SchemaEditor.
    """
    if self.SchemaEditorClass is None:
        raise NotImplementedError(
            "The SchemaEditorClass attribute of this database wrapper is still None"
        )
    return self.SchemaEditorClass(self, *args, **kwargs)

def on_commit(self, func, robust=False):
    if not callable(func):
        raise TypeError("on_commit()'s callback must be a callable.")
    if self.in_atomic_block:
        # Transaction in progress; save for execution on commit.
        self.run_on_commit.append((set(self.savepoint_ids), func, robust))
    elif not self.get_autocommit():
        raise TransactionManagementError(
            "on_commit() cannot be used in manual transaction management"
        )
    else:
        # No transaction in progress and in autocommit mode; execute
        # immediately.
        if robust:
            try:
                func()
            except Exception as e:
                logger.error(
                    f"Error calling {func.__qualname__} in on_commit() (%s).",
                    e,
                    exc_info=True,
                )
        else:
            func()

def run_and_clear_commit_hooks(self):
    self.validate_no_atomic_block()
    current_run_on_commit = self.run_on_commit
    self.run_on_commit = []
    while current_run_on_commit:
        _, func, robust = current_run_on_commit.pop(0)
        if robust:
            try:
                func()
            except Exception as e:
                logger.error(
                    f"Error calling {func.__qualname__} in on_commit() during "
                    f"transaction (%s).",
                    e,
                    exc_info=True,
                )
        else:
            func()

@contextmanager

def copy(self, alias=None):
    """
    Return a copy of this connection.

    For tests that require two connections to the same database.
    """
    settings_dict = copy.deepcopy(self.settings_dict)
    if alias is None:
        alias = self.alias
    return type(self)(settings_dict, alias)

def _all_related_fields(model):
    # Related fields must be returned in a deterministic order.
    return sorted(
        model._meta._get_fields(
            forward=False,
            reverse=True,
            include_hidden=True,
            include_parents=False,
        ),
        key=operator.attrgetter("name"),
    )

def _related_non_m2m_objects(old_field, new_field):
    # Filter out m2m objects from reverse relations.
    # Return (old_relation, new_relation) tuples.
    related_fields = zip(
        (
            obj
            for obj in _all_related_fields(old_field.model)
            if _is_relevant_relation(obj, old_field)
        ),
        (
            obj
            for obj in _all_related_fields(new_field.model)
            if _is_relevant_relation(obj, new_field)
        ),
    )
    for old_rel, new_rel in related_fields:
        yield old_rel, new_rel
        yield from _related_non_m2m_objects(
            old_rel.remote_field,
            new_rel.remote_field,
        )

def __enter__(self):
    self.deferred_sql = []
    if self.atomic_migration:
        self.atomic = atomic(self.connection.alias)
        self.atomic.__enter__()
    return self

def __exit__(self, exc_type, exc_value, traceback):
    if exc_type is None:
        for sql in self.deferred_sql:
            self.execute(sql, None)
    if self.atomic_migration:
        self.atomic.__exit__(exc_type, exc_value, traceback)

# Core utility functions

def execute(self, sql, params=()):
    """Execute the given SQL statement, with optional parameters."""
    # Don't perform the transactional DDL check if SQL is being collected
    # as it's not going to be executed anyway.
    if (
        not self.collect_sql
        and self.connection.in_atomic_block
        and not self.connection.features.can_rollback_ddl
    ):
        raise TransactionManagementError(
            "Executing DDL statements while in a transaction on databases "
            "that can't perform a rollback is prohibited."
        )
    # Account for non-string statement objects.
    sql = str(sql)
    # Log the command we're running, then run it
    logger.debug(
        "%s; (params %r)", sql, params, extra={"params": params, "sql": sql}
    )
    if self.collect_sql:
        ending = "" if sql.rstrip().endswith(";") else ";"
        if params is not None:
            self.collected_sql.append(
                (sql % tuple(map(self.quote_value, params))) + ending
            )
        else:
            self.collected_sql.append(sql + ending)
    else:
        with self.connection.cursor() as cursor:
            cursor.execute(sql, params)

def table_sql(self, model):
    """Take a model and return its table definition."""
    # Add any unique_togethers (always deferred, as some fields might be
    # created afterward, like geometry fields with some backends).
    for field_names in model._meta.unique_together:
        fields = [model._meta.get_field(field) for field in field_names]
        self.deferred_sql.append(self._create_unique_sql(model, fields))
    # Create column SQL, add FK deferreds if needed.
    column_sqls = []
    params = []
    for field in model._meta.local_fields:
        # SQL.
        definition, extra_params = self.column_sql(model, field)
        if definition is None:
            continue
        # Check constraints can go on the column SQL here.
        db_params = field.db_parameters(connection=self.connection)
        if db_params["check"]:
            definition += " " + self.sql_check_constraint % db_params
        # Autoincrement SQL (for backends with inline variant).
        col_type_suffix = field.db_type_suffix(connection=self.connection)
        if col_type_suffix:
            definition += " %s" % col_type_suffix
        params.extend(extra_params)
        # FK.
        if field.remote_field and field.db_constraint:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(
                field.remote_field.field_name
            ).column
            if self.sql_create_inline_fk:
                definition += " " + self.sql_create_inline_fk % {
                    "to_table": self.quote_name(to_table),
                    "to_column": self.quote_name(to_column),
                }
            elif self.connection.features.supports_foreign_keys:
                self.deferred_sql.append(
                    self._create_fk_sql(
                        model, field, "_fk_%(to_table)s_%(to_column)s"
                    )
                )
        # Add the SQL to our big list.
        column_sqls.append(
            "%s %s"
            % (
                self.quote_name(field.column),
                definition,
            )
        )
        # Autoincrement SQL (for backends with post table definition
        # variant).
        if field.get_internal_type() in (
            "AutoField",
            "BigAutoField",
            "SmallAutoField",
        ):
            autoinc_sql = self.connection.ops.autoinc_sql(
                model._meta.db_table, field.column
            )
            if autoinc_sql:
                self.deferred_sql.extend(autoinc_sql)
    # The BaseConstraint DDL creation methods such as constraint_sql(),
    # create_sql(), and delete_sql(), were not designed in a way that
    # separate SQL from parameters which make their generated SQL unfit to
    # be used in a context where parametrization is delegated to the
    # backend.
    constraint_sqls = []
    if params:
        # If parameters are present (e.g. a DEFAULT clause on backends that
        # allow parametrization) defer constraint creation so they are not
        # mixed with SQL meant to be parametrized.
        for constraint in model._meta.constraints:
            self.deferred_sql.append(constraint.create_sql(model, self))
    else:
        constraint_sqls.extend(
            constraint.constraint_sql(model, self)
            for constraint in model._meta.constraints
        )

    pk = model._meta.pk
    if isinstance(pk, CompositePrimaryKey):
        constraint_sqls.append(self._pk_constraint_sql(pk.columns))

    sql = self.sql_create_table % {
        "table": self.quote_name(model._meta.db_table),
        "definition": ", ".join(
            str(statement)
            for statement in (*column_sqls, *constraint_sqls)
            if statement
        ),
    }
    if model._meta.db_tablespace:
        tablespace_sql = self.connection.ops.tablespace_sql(
            model._meta.db_tablespace
        )
        if tablespace_sql:
            sql += " " + tablespace_sql
    return sql, params

# Field <-> database mapping functions

def _column_generated_sql(self, field):
    """Return the SQL to use in a GENERATED ALWAYS clause."""
    expression_sql, params = field.generated_sql(self.connection)
    persistency_sql = "STORED" if field.db_persist else "VIRTUAL"
    if self.connection.features.requires_literal_defaults:
        expression_sql = expression_sql % tuple(self.quote_value(p) for p in params)
        params = ()
    return f"GENERATED ALWAYS AS ({expression_sql}) {persistency_sql}", params

@staticmethod

def _effective_default(field):
    # This method allows testing its logic without a connection.
    if field.has_default():
        default = field.get_default()
    elif field.generated:
        default = None
    elif not field.null and field.blank and field.empty_strings_allowed:
        if field.get_internal_type() == "BinaryField":
            default = b""
        else:
            default = ""
    elif getattr(field, "auto_now", False) or getattr(field, "auto_now_add", False):
        internal_type = field.get_internal_type()
        if internal_type == "DateTimeField":
            default = timezone.now()
        else:
            default = datetime.now()
            if internal_type == "DateField":
                default = default.date()
            elif internal_type == "TimeField":
                default = default.time()
    else:
        default = None
    return default

def effective_default(self, field):
    """Return a field's effective database default value."""
    return field.get_db_prep_save(self._effective_default(field), self.connection)

def create_model(self, model):
    """
    Create a table and any accompanying indexes or unique constraints for
    the given `model`.
    """
    sql, params = self.table_sql(model)
    # Prevent using [] as params, in the case a literal '%' is used in the
    # definition on backends that don't support parametrized DDL.
    self.execute(sql, params or None)

    if self.connection.features.supports_comments:
        # Add table comment.
        if model._meta.db_table_comment:
            self.alter_db_table_comment(model, None, model._meta.db_table_comment)
        # Add column comments.
        if not self.connection.features.supports_comments_inline:
            for field in model._meta.local_fields:
                if field.db_comment:
                    field_db_params = field.db_parameters(
                        connection=self.connection
                    )
                    field_type = field_db_params["type"]
                    self.execute(
                        *self._alter_column_comment_sql(
                            model, field, field_type, field.db_comment
                        )
                    )
    # Add any field index (deferred as SQLite _remake_table needs it).
    self.deferred_sql.extend(self._model_indexes_sql(model))

    # Make M2M tables
    for field in model._meta.local_many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.create_model(field.remote_field.through)

def delete_model(self, model):
    """Delete a model from the database."""
    # Handle auto-created intermediary models
    for field in model._meta.local_many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.delete_model(field.remote_field.through)

    # Delete the table
    self.execute(
        self.sql_delete_table
        % {
            "table": self.quote_name(model._meta.db_table),
        }
    )
    # Remove all deferred statements referencing the deleted table.
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_table(
            model._meta.db_table
        ):
            self.deferred_sql.remove(sql)

def add_index(self, model, index):
    """Add an index on a model."""
    if (
        index.contains_expressions
        and not self.connection.features.supports_expression_indexes
    ):
        return None
    # Index.create_sql returns interpolated SQL which makes params=None a
    # necessity to avoid escaping attempts on execution.
    self.execute(index.create_sql(model, self), params=None)

def remove_index(self, model, index):
    """Remove an index from a model."""
    if (
        index.contains_expressions
        and not self.connection.features.supports_expression_indexes
    ):
        return None
    self.execute(index.remove_sql(model, self))

def rename_index(self, model, old_index, new_index):
    if self.connection.features.can_rename_index:
        self.execute(
            self._rename_index_sql(model, old_index.name, new_index.name),
            params=None,
        )
    else:
        self.remove_index(model, old_index)
        self.add_index(model, new_index)

def remove_constraint(self, model, constraint):
    """Remove a constraint from a model."""
    sql = constraint.remove_sql(model, self)
    if sql:
        self.execute(sql)

def alter_unique_together(self, model, old_unique_together, new_unique_together):
    """
    Deal with a model changing its unique_together. The input
    unique_togethers must be doubly-nested, not the single-nested
    ["foo", "bar"] format.
    """
    olds = {tuple(fields) for fields in old_unique_together}
    news = {tuple(fields) for fields in new_unique_together}
    # Deleted uniques
    for fields in olds.difference(news):
        self._delete_composed_index(
            model,
            fields,
            {"unique": True, "primary_key": False},
            self.sql_delete_unique,
        )
    # Created uniques
    for field_names in news.difference(olds):
        fields = [model._meta.get_field(field) for field in field_names]
        self.execute(self._create_unique_sql(model, fields))

def alter_index_together(self, model, old_index_together, new_index_together):
    """
    Deal with a model changing its index_together. The input
    index_togethers must be doubly-nested, not the single-nested
    ["foo", "bar"] format.
    """
    olds = {tuple(fields) for fields in old_index_together}
    news = {tuple(fields) for fields in new_index_together}
    # Deleted indexes
    for fields in olds.difference(news):
        self._delete_composed_index(
            model,
            fields,
            {"index": True, "unique": False},
            self.sql_delete_index,
        )
    # Created indexes
    for field_names in news.difference(olds):
        fields = [model._meta.get_field(field) for field in field_names]
        self.execute(self._create_index_sql(model, fields=fields, suffix="_idx"))

def _delete_composed_index(self, model, fields, constraint_kwargs, sql):
    meta_constraint_names = {
        constraint.name for constraint in model._meta.constraints
    }
    meta_index_names = {constraint.name for constraint in model._meta.indexes}
    columns = [model._meta.get_field(field).column for field in fields]
    constraint_names = self._constraint_names(
        model,
        columns,
        exclude=meta_constraint_names | meta_index_names,
        **constraint_kwargs,
    )
    if (
        constraint_kwargs.get("unique") is True
        and constraint_names
        and self.connection.features.allows_multiple_constraints_on_same_fields
    ):
        # Constraint matching the unique_together name.
        default_name = str(
            self._unique_constraint_name(model._meta.db_table, columns, quote=False)
        )
        if default_name in constraint_names:
            constraint_names = [default_name]
    if len(constraint_names) != 1:
        raise ValueError(
            "Found wrong number (%s) of constraints for %s(%s)"
            % (
                len(constraint_names),
                model._meta.db_table,
                ", ".join(columns),
            )
        )
    self.execute(self._delete_constraint_sql(sql, model, constraint_names[0]))

def alter_db_table(self, model, old_db_table, new_db_table):
    """Rename the table a model points to."""
    if old_db_table == new_db_table or (
        self.connection.features.ignores_table_name_case
        and old_db_table.lower() == new_db_table.lower()
    ):
        return
    self.execute(
        self.sql_rename_table
        % {
            "old_table": self.quote_name(old_db_table),
            "new_table": self.quote_name(new_db_table),
        }
    )
    # Rename all references to the old table name.
    for sql in self.deferred_sql:
        if isinstance(sql, Statement):
            sql.rename_table_references(old_db_table, new_db_table)

def alter_db_table_comment(self, model, old_db_table_comment, new_db_table_comment):
    if self.sql_alter_table_comment and self.connection.features.supports_comments:
        self.execute(
            self.sql_alter_table_comment
            % {
                "table": self.quote_name(model._meta.db_table),
                "comment": self.quote_value(new_db_table_comment or ""),
            }
        )

def alter_db_tablespace(self, model, old_db_tablespace, new_db_tablespace):
    """Move a model's table between tablespaces."""
    self.execute(
        self.sql_retablespace_table
        % {
            "table": self.quote_name(model._meta.db_table),
            "old_tablespace": self.quote_name(old_db_tablespace),
            "new_tablespace": self.quote_name(new_db_tablespace),
        }
    )

def add_field(self, model, field):
    """
    Create a field on a model. Usually involves adding a column, but may
    involve adding a table instead (for M2M fields).
    """
    # Special-case implicit M2M tables
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.create_model(field.remote_field.through)
    # Get the column's definition
    definition, params = self.column_sql(model, field, include_default=True)
    # It might not actually have a column behind it
    if definition is None:
        return
    if col_type_suffix := field.db_type_suffix(connection=self.connection):
        definition += f" {col_type_suffix}"
    # Check constraints can go on the column SQL here
    db_params = field.db_parameters(connection=self.connection)
    if db_params["check"]:
        definition += " " + self.sql_check_constraint % db_params
    if (
        field.remote_field
        and self.connection.features.supports_foreign_keys
        and field.db_constraint
    ):
        constraint_suffix = "_fk_%(to_table)s_%(to_column)s"
        # Add FK constraint inline, if supported.
        if self.sql_create_column_inline_fk:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(
                field.remote_field.field_name
            ).column
            namespace, _ = split_identifier(model._meta.db_table)
            definition += " " + self.sql_create_column_inline_fk % {
                "name": self._fk_constraint_name(model, field, constraint_suffix),
                "namespace": (
                    "%s." % self.quote_name(namespace) if namespace else ""
                ),
                "column": self.quote_name(field.column),
                "to_table": self.quote_name(to_table),
                "to_column": self.quote_name(to_column),
                "deferrable": self.connection.ops.deferrable_sql(),
            }
        # Otherwise, add FK constraints later.
        else:
            self.deferred_sql.append(
                self._create_fk_sql(model, field, constraint_suffix)
            )
    # Build the SQL and run it
    sql = self.sql_create_column % {
        "table": self.quote_name(model._meta.db_table),
        "column": self.quote_name(field.column),
        "definition": definition,
    }
    # Prevent using [] as params, in the case a literal '%' is used in the
    # definition on backends that don't support parametrized DDL.
    self.execute(sql, params or None)
    # Drop the default if we need to
    if (
        not field.has_db_default()
        and not self.skip_default_on_alter(field)
        and self.effective_default(field) is not None
    ):
        changes_sql, params = self._alter_column_default_sql(
            model, None, field, drop=True
        )
        sql = self.sql_alter_column % {
            "table": self.quote_name(model._meta.db_table),
            "changes": changes_sql,
        }
        self.execute(sql, params)
    # Add field comment, if required.
    if (
        field.db_comment
        and self.connection.features.supports_comments
        and not self.connection.features.supports_comments_inline
    ):
        field_type = db_params["type"]
        self.execute(
            *self._alter_column_comment_sql(
                model, field, field_type, field.db_comment
            )
        )
    # Add an index, if required
    self.deferred_sql.extend(self._field_indexes_sql(model, field))
    # Reset connection if required
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()

def remove_field(self, model, field):
    """
    Remove a field from a model. Usually involves deleting a column,
    but for M2Ms may involve deleting a table.
    """
    # Special-case implicit M2M tables
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.delete_model(field.remote_field.through)
    # It might not actually have a column behind it
    if field.db_parameters(connection=self.connection)["type"] is None:
        return
    # Drop any FK constraints, MySQL requires explicit deletion
    if field.remote_field:
        fk_names = self._constraint_names(model, [field.column], foreign_key=True)
        for fk_name in fk_names:
            self.execute(self._delete_fk_sql(model, fk_name))
    # Delete the column
    sql = self.sql_delete_column % {
        "table": self.quote_name(model._meta.db_table),
        "column": self.quote_name(field.column),
    }
    self.execute(sql)
    # Reset connection if required
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()
    # Remove all deferred statements referencing the deleted column.
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_column(
            model._meta.db_table, field.column
        ):
            self.deferred_sql.remove(sql)

def _field_db_check(self, field, field_db_params):
    # Always check constraints with the same mocked column name to avoid
    # recreating constrains when the column is renamed.
    check_constraints = self.connection.data_type_check_constraints
    data = field.db_type_parameters(self.connection)
    data["column"] = "__column_name__"
    try:
        return check_constraints[field.get_internal_type()] % data
    except KeyError:
        return None

def _alter_column_null_sql(self, model, old_field, new_field):
    """
    Hook to specialize column null alteration.

    Return a (sql, params) fragment to set a column to null or non-null
    as required by new_field, or None if no changes are required.
    """
    if (
        self.connection.features.interprets_empty_strings_as_nulls
        and new_field.empty_strings_allowed
    ):
        # The field is nullable in the database anyway, leave it alone.
        return
    else:
        new_db_params = new_field.db_parameters(connection=self.connection)
        sql = (
            self.sql_alter_column_null
            if new_field.null
            else self.sql_alter_column_not_null
        )
        return (
            sql
            % {
                "column": self.quote_name(new_field.column),
                "type": new_db_params["type"],
            },
            [],
        )

def _alter_column_default_sql(self, model, old_field, new_field, drop=False):
    """
    Hook to specialize column default alteration.

    Return a (sql, params) fragment to add or drop (depending on the drop
    argument) a default to new_field's column.
    """
    new_default = self.effective_default(new_field)
    default = self._column_default_sql(new_field)
    params = [new_default]

    if drop:
        params = []
    elif self.connection.features.requires_literal_defaults:
        # Some databases (Oracle) can't take defaults as a parameter
        # If this is the case, the SchemaEditor for that database should
        # implement prepare_default().
        default = self.prepare_default(new_default)
        params = []

    new_db_params = new_field.db_parameters(connection=self.connection)
    if drop:
        if new_field.null:
            sql = self.sql_alter_column_no_default_null
        else:
            sql = self.sql_alter_column_no_default
    else:
        sql = self.sql_alter_column_default
    return (
        sql
        % {
            "column": self.quote_name(new_field.column),
            "type": new_db_params["type"],
            "default": default,
        },
        params,
    )

def _alter_column_database_default_sql(
    self, model, old_field, new_field, drop=False
):
    """
    Hook to specialize column database default alteration.

    Return a (sql, params) fragment to add or drop (depending on the drop
    argument) a default to new_field's column.
    """
    if drop:
        sql = self.sql_alter_column_no_default
        default_sql = ""
        params = []
    else:
        sql = self.sql_alter_column_default
        default_sql, params = self.db_default_sql(new_field)

    new_db_params = new_field.db_parameters(connection=self.connection)
    return (
        sql
        % {
            "column": self.quote_name(new_field.column),
            "type": new_db_params["type"],
            "default": default_sql,
        },
        params,
    )

def _alter_column_type_sql(
    self, model, old_field, new_field, new_type, old_collation, new_collation
):
    """
    Hook to specialize column type alteration for different backends,
    for cases when a creation type is different to an alteration type
    (e.g. SERIAL in PostgreSQL, PostGIS fields).

    Return a 2-tuple of: an SQL fragment of (sql, params) to insert into
    an ALTER TABLE statement and a list of extra (sql, params) tuples to
    run once the field is altered.
    """
    other_actions = []
    if collate_sql := self._collate_sql(
        new_collation, old_collation, model._meta.db_table
    ):
        collate_sql = f" {collate_sql}"
    else:
        collate_sql = ""
    # Comment change?
    comment_sql = ""
    if self.connection.features.supports_comments and not new_field.many_to_many:
        if old_field.db_comment != new_field.db_comment:
            # PostgreSQL and Oracle can't execute 'ALTER COLUMN ...' and
            # 'COMMENT ON ...' at the same time.
            sql, params = self._alter_column_comment_sql(
                model, new_field, new_type, new_field.db_comment
            )
            if sql:
                other_actions.append((sql, params))
        if new_field.db_comment:
            comment_sql = self._comment_sql(new_field.db_comment)
    return (
        (
            self.sql_alter_column_type
            % {
                "column": self.quote_name(new_field.column),
                "type": new_type,
                "collation": collate_sql,
                "comment": comment_sql,
            },
            [],
        ),
        other_actions,
    )

def _alter_column_comment_sql(self, model, new_field, new_type, new_db_comment):
    return (
        self.sql_alter_column_comment
        % {
            "table": self.quote_name(model._meta.db_table),
            "column": self.quote_name(new_field.column),
            "comment": self._comment_sql(new_db_comment),
        },
        [],
    )

def _get_index_tablespace_sql(self, model, fields, db_tablespace=None):
    if db_tablespace is None:
        if len(fields) == 1 and fields[0].db_tablespace:
            db_tablespace = fields[0].db_tablespace
        elif settings.DEFAULT_INDEX_TABLESPACE:
            db_tablespace = settings.DEFAULT_INDEX_TABLESPACE
        elif model._meta.db_tablespace:
            db_tablespace = model._meta.db_tablespace
    if db_tablespace is not None:
        return " " + self.connection.ops.tablespace_sql(db_tablespace)
    return ""

def _index_condition_sql(self, condition):
    if condition:
        return " WHERE " + condition
    return ""

def _index_include_sql(self, model, columns):
    if not columns or not self.connection.features.supports_covering_indexes:
        return ""
    return Statement(
        " INCLUDE (%(columns)s)",
        columns=Columns(model._meta.db_table, columns, self.quote_name),
    )

def create_index_name(*args, **kwargs):
    nonlocal name
    if name is None:
        name = self._create_index_name(*args, **kwargs)
    return self.quote_name(name)

return Statement(
    sql_create_index,
    table=Table(table, self.quote_name),
    name=IndexName(table, columns, suffix, create_index_name),
    using=using,
    columns=(
        self._index_columns(table, columns, col_suffixes, opclasses)
        if columns
        else Expressions(table, expressions, compiler, self.quote_value)
    ),
    extra=tablespace_sql,
    condition=self._index_condition_sql(condition),
    include=self._index_include_sql(model, include),
)

def _delete_index_sql(self, model, name, sql=None):
    statement = Statement(
        sql or self.sql_delete_index,
        table=Table(model._meta.db_table, self.quote_name),
        name=self.quote_name(name),
    )

    # Remove all deferred statements referencing the deleted index.
    table_name = statement.parts["table"].table
    index_name = statement.parts["name"]
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_index(
            table_name, index_name
        ):
            self.deferred_sql.remove(sql)

    return statement

def _rename_index_sql(self, model, old_name, new_name):
    return Statement(
        self.sql_rename_index,
        table=Table(model._meta.db_table, self.quote_name),
        old_name=self.quote_name(old_name),
        new_name=self.quote_name(new_name),
    )

def _model_indexes_sql(self, model):
    """
    Return a list of all index SQL statements (field indexes, Meta.indexes)
    for the specified model.
    """
    if not model._meta.managed or model._meta.proxy or model._meta.swapped:
        return []
    output = []
    for field in model._meta.local_fields:
        output.extend(self._field_indexes_sql(model, field))

    for index in model._meta.indexes:
        if (
            not index.contains_expressions
            or self.connection.features.supports_expression_indexes
        ):
            output.append(index.create_sql(model, self))
    return output

def _unique_should_be_added(self, old_field, new_field):
    return (
        not new_field.primary_key
        and new_field.unique
        and (not old_field.unique or old_field.primary_key)
    )

def _rename_field_sql(self, table, old_field, new_field, new_type):
    return self.sql_rename_column % {
        "table": self.quote_name(table),
        "old_column": self.quote_name(old_field.column),
        "new_column": self.quote_name(new_field.column),
        "type": new_type,
    }

def create_fk_name(*args, **kwargs):
    return self.quote_name(self._create_index_name(*args, **kwargs))

return ForeignKeyName(
    model._meta.db_table,
    [field.column],
    split_identifier(field.target_field.model._meta.db_table)[1],
    [field.target_field.column],
    suffix,
    create_fk_name,
)

def _deferrable_constraint_sql(self, deferrable):
    if deferrable is None:
        return ""
    if deferrable == Deferrable.DEFERRED:
        return " DEFERRABLE INITIALLY DEFERRED"
    if deferrable == Deferrable.IMMEDIATE:
        return " DEFERRABLE INITIALLY IMMEDIATE"

def _unique_index_nulls_distinct_sql(self, nulls_distinct):
    if nulls_distinct is False:
        return " NULLS NOT DISTINCT"
    elif nulls_distinct is True:
        return " NULLS DISTINCT"
    return ""

def _unique_supported(
    self,
    condition=None,
    deferrable=None,
    include=None,
    expressions=None,
    nulls_distinct=None,
):
    return (
        (not condition or self.connection.features.supports_partial_indexes)
        and (
            not deferrable
            or self.connection.features.supports_deferrable_unique_constraints
        )
        and (not include or self.connection.features.supports_covering_indexes)
        and (
            not expressions or self.connection.features.supports_expression_indexes
        )
        and (
            nulls_distinct is None
            or self.connection.features.supports_nulls_distinct_unique_constraints
        )
    )

    def create_unique_name(*args, **kwargs):
        return self.quote_name(self._create_index_name(*args, **kwargs))

else:
    create_unique_name = self._create_index_name

return IndexName(table, columns, "_uniq", create_unique_name)

def _check_sql(self, name, check):
    return self.sql_constraint % {
        "name": self.quote_name(name),
        "constraint": self.sql_check_constraint % {"check": check},
    }

def _create_check_sql(self, model, name, check):
    if not self.connection.features.supports_table_check_constraints:
        return None
    return Statement(
        self.sql_create_check,
        table=Table(model._meta.db_table, self.quote_name),
        name=self.quote_name(name),
        check=check,
    )

def _delete_check_sql(self, model, name):
    if not self.connection.features.supports_table_check_constraints:
        return None
    return self._delete_constraint_sql(self.sql_delete_check, model, name)

def _delete_constraint_sql(self, template, model, name):
    return Statement(
        template,
        table=Table(model._meta.db_table, self.quote_name),
        name=self.quote_name(name),
    )

def _constraint_names(
    self,
    model,
    column_names=None,
    unique=None,
    primary_key=None,
    index=None,
    foreign_key=None,
    check=None,
    type_=None,
    exclude=None,
):
    """Return all constraint names matching the columns and conditions."""
    if column_names is not None:
        column_names = [
            (
                self.connection.introspection.identifier_converter(
                    truncate_name(name, self.connection.ops.max_name_length())
                )
                if self.connection.features.truncates_names
                else self.connection.introspection.identifier_converter(name)
            )
            for name in column_names
        ]
    with self.connection.cursor() as cursor:
        constraints = self.connection.introspection.get_constraints(
            cursor, model._meta.db_table
        )
    result = []
    for name, infodict in constraints.items():
        if column_names is None or column_names == infodict["columns"]:
            if unique is not None and infodict["unique"] != unique:
                continue
            if primary_key is not None and infodict["primary_key"] != primary_key:
                continue
            if index is not None and infodict["index"] != index:
                continue
            if check is not None and infodict["check"] != check:
                continue
            if foreign_key is not None and not infodict["foreign_key"]:
                continue
            if type_ is not None and infodict["type"] != type_:
                continue
            if not exclude or name not in exclude:
                result.append(name)
    return result

def _pk_constraint_sql(self, columns):
    return self.sql_pk_constraint % {
        "columns": ", ".join(self.quote_name(column) for column in columns)
    }

def _delete_primary_key(self, model, strict=False):
    constraint_names = self._constraint_names(model, primary_key=True)
    if strict and len(constraint_names) != 1:
        raise ValueError(
            "Found wrong number (%s) of PK constraints for %s"
            % (
                len(constraint_names),
                model._meta.db_table,
            )
        )
    for constraint_name in constraint_names:
        self.execute(self._delete_primary_key_sql(model, constraint_name))

def _create_primary_key_sql(self, model, field):
    return Statement(
        self.sql_create_pk,
        table=Table(model._meta.db_table, self.quote_name),
        name=self.quote_name(
            self._create_index_name(
                model._meta.db_table, [field.column], suffix="_pk"
            )
        ),
        columns=Columns(model._meta.db_table, [field.column], self.quote_name),
    )

def remove_procedure(self, procedure_name, param_types=()):
    sql = self.sql_delete_procedure % {
        "procedure": self.quote_name(procedure_name),
        "param_types": ",".join(param_types),
    }
    self.execute(sql)

def check_field(self, field, **kwargs):
    errors = []
    # Backends may implement a check_field_type() method.
    if (
        hasattr(self, "check_field_type")
        and
        # Ignore any related fields.
        not getattr(field, "remote_field", None)
    ):
        # Ignore fields with unsupported features.
        db_supports_all_required_features = all(
            getattr(self.connection.features, feature, False)
            for feature in field.model._meta.required_db_features
        )
        if db_supports_all_required_features:
            field_type = field.db_type(self.connection)
            # Ignore non-concrete fields.
            if field_type is not None:
                errors.extend(self.check_field_type(field, field_type))
    return errors

