class FieldIsAForeignKeyColumnName(Exception):
    """A field is a foreign key attname, i.e. <FK>_id."""

    pass

def lookup_spawns_duplicates(opts, lookup_path):
    """
    Return True if the given lookup path spawns duplicates.
    """
    lookup_fields = lookup_path.split(LOOKUP_SEP)
    # Go through the fields (following all relations) and look for an m2m.
    for field_name in lookup_fields:
        if field_name == "pk":
            field_name = opts.pk.name
        try:
            field = opts.get_field(field_name)
        except FieldDoesNotExist:
            # Ignore query lookups.
            continue
        else:
            if hasattr(field, "path_infos"):
                # This field is a relation; update opts to follow the relation.
                path_info = field.path_infos
                opts = path_info[-1].to_opts
                if any(path.m2m for path in path_info):
                    # This field is a m2m relation so duplicates must be
                    # handled.
                    return True
    return False

def get_last_value_from_parameters(parameters, key):
    value = parameters.get(key)
    return value[-1] if isinstance(value, list) else value

def prepare_lookup_value(key, value, separator=","):
    """
    Return a lookup value prepared to be used in queryset filtering.
    """
    if isinstance(value, list):
        return [prepare_lookup_value(key, v, separator=separator) for v in value]
    # if key ends with __in, split parameter into separate values
    if key.endswith("__in"):
        value = value.split(separator)
    # if key ends with __isnull, special case '' and the string literals 'false' and '0'
    elif key.endswith("__isnull"):
        value = value.lower() not in ("", "false", "0")
    return value

def build_q_object_from_lookup_parameters(parameters):
    q_object = models.Q()
    for param, param_item_list in parameters.items():
        q_object &= reduce(or_, (models.Q((param, item)) for item in param_item_list))
    return q_object

def unquote(s):
    """Undo the effects of quote()."""
    return UNQUOTE_RE.sub(lambda m: UNQUOTE_MAP[m[0]], s)

def flatten(fields):
    """
    Return a list which is a single level of flattening of the original list.
    """
    flat = []
    for field in fields:
        if isinstance(field, (list, tuple)):
            flat.extend(field)
        else:
            flat.append(field)
    return flat

def flatten_fieldsets(fieldsets):
    """Return a list of field names from an admin fieldsets structure."""
    field_names = []
    for name, opts in fieldsets:
        field_names.extend(flatten(opts["fields"]))
    return field_names

def get_deleted_objects(objs, request, admin_site):
    """
    Find all objects related to ``objs`` that should also be deleted. ``objs``
    must be a homogeneous iterable of objects (e.g. a QuerySet).

    Return a nested list of strings suitable for display in the
    template with the ``unordered_list`` filter.
    """
    try:
        obj = objs[0]
    except IndexError:
        return [], {}, set(), []
    else:
        using = router.db_for_write(obj._meta.model)
    collector = NestedObjects(using=using, origin=objs)
    collector.collect(objs)
    perms_needed = set()

def format_callback(obj):
    model = obj.__class__
    opts = obj._meta

    no_edit_link = "%s: %s" % (capfirst(opts.verbose_name), obj)

    if admin_site.is_registered(model):
        if not admin_site.get_model_admin(model).has_delete_permission(
            request, obj
        ):
            perms_needed.add(opts.verbose_name)
        try:
            admin_url = reverse(
                "%s:%s_%s_change"
                % (admin_site.name, opts.app_label, opts.model_name),
                None,
                (quote(obj.pk),),
            )
        except NoReverseMatch:
            # Change url doesn't exist -- don't display link to edit
            return no_edit_link

        # Display a link to the admin page.
        return format_html(
            '{}: <a href="{}">{}</a>', capfirst(opts.verbose_name), admin_url, obj
        )
    else:
        # Don't display link to edit, because it either has no
        # admin or is edited inline.
        return no_edit_link

to_delete = collector.nested(format_callback)

protected = [format_callback(obj) for obj in collector.protected]
model_count = {
    model._meta.verbose_name_plural: len(objs)
    for model, objs in collector.model_objs.items()
}

return to_delete, model_count, perms_needed, protected

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self.edges = {}  # {from_instance: [to_instances]}
    self.protected = set()
    self.model_objs = defaultdict(set)

def collect(self, objs, source=None, source_attr=None, **kwargs):
    for obj in objs:
        if source_attr and not source_attr.endswith("+"):
            related_name = source_attr % {
                "class": source._meta.model_name,
                "app_label": source._meta.app_label,
            }
            self.add_edge(getattr(obj, related_name), obj)
        else:
            self.add_edge(None, obj)
        self.model_objs[obj._meta.model].add(obj)
    try:
        return super().collect(objs, source_attr=source_attr, **kwargs)
    except models.ProtectedError as e:
        self.protected.update(e.protected_objects)
    except models.RestrictedError as e:
        self.protected.update(e.restricted_objects)

def related_objects(self, related_model, related_fields, objs):
    qs = super().related_objects(related_model, related_fields, objs)
    return qs.select_related(
        *[related_field.name for related_field in related_fields]
    )

def _nested(self, obj, seen, format_callback):
    if obj in seen:
        return []
    seen.add(obj)
    children = []
    for child in self.edges.get(obj, ()):
        children.extend(self._nested(child, seen, format_callback))
    if format_callback:
        ret = [format_callback(obj)]
    else:
        ret = [obj]
    if children:
        ret.append(children)
    return ret

def model_format_dict(obj):
    """
    Return a `dict` with keys 'verbose_name' and 'verbose_name_plural',
    typically for use with string formatting.

    `obj` may be a `Model` instance, `Model` subclass, or `QuerySet` instance.
    """
    if isinstance(obj, (models.Model, models.base.ModelBase)):
        opts = obj._meta
    elif isinstance(obj, models.query.QuerySet):
        opts = obj.model._meta
    else:
        opts = obj
    return {
        "verbose_name": opts.verbose_name,
        "verbose_name_plural": opts.verbose_name_plural,
    }

def lookup_field(name, obj, model_admin=None):
    opts = obj._meta
    try:
        f = _get_non_gfk_field(opts, name)
    except (FieldDoesNotExist, FieldIsAForeignKeyColumnName):
        # For non-regular field values, the value is either a method,
        # property, related field, or returned via a callable.
        if callable(name):
            attr = name
            value = attr(obj)
        elif hasattr(model_admin, name) and name != "__str__":
            attr = getattr(model_admin, name)
            value = attr(obj)
        else:
            sentinel = object()
            attr = getattr(obj, name, sentinel)
            if callable(attr):
                value = attr()
            else:
                if attr is sentinel:
                    attr = obj
                    for part in name.split(LOOKUP_SEP):
                        attr = getattr(attr, part, sentinel)
                        if attr is sentinel:
                            return None, None, None
                value = attr
            if hasattr(model_admin, "model") and hasattr(model_admin.model, name):
                attr = getattr(model_admin.model, name)
        f = None
    else:
        attr = None
        value = getattr(obj, name)
    return f, attr, value

def label_for_field(name, model, model_admin=None, return_attr=False, form=None):
    """
    Return a sensible label for a field name. The name can be a callable,
    property (but not created with @property decorator), or the name of an
    object's attribute, as well as a model field, including across related
    objects. If return_attr is True, also return the resolved attribute
    (which could be a callable). This will be None if (and only if) the name
    refers to a field.
    """
    attr = None
    try:
        field = _get_non_gfk_field(model._meta, name)
        try:
            label = field.verbose_name
        except AttributeError:
            # field is likely a ForeignObjectRel
            label = field.related_model._meta.verbose_name
    except FieldDoesNotExist:
        if name == "__str__":
            label = str(model._meta.verbose_name)
            attr = str
        else:
            if callable(name):
                attr = name
            elif hasattr(model_admin, name):
                attr = getattr(model_admin, name)
            elif hasattr(model, name):
                attr = getattr(model, name)
            elif form and name in form.fields:
                attr = form.fields[name]
            else:
                try:
                    attr = get_fields_from_path(model, name)[-1]
                except (FieldDoesNotExist, NotRelationField):
                    message = f"Unable to lookup '{name}' on {model._meta.object_name}"
                    if model_admin:
                        message += f" or {model_admin.__class__.__name__}"
                    if form:
                        message += f" or {form.__class__.__name__}"
                    raise AttributeError(message)

            if hasattr(attr, "short_description"):
                label = attr.short_description
            elif (
                isinstance(attr, property)
                and hasattr(attr, "fget")
                and hasattr(attr.fget, "short_description")
            ):
                label = attr.fget.short_description
            elif callable(attr):
                if attr.__name__ == "<lambda>":
                    label = "--"
                else:
                    label = pretty_name(attr.__name__)
            else:
                label = pretty_name(name)
    except FieldIsAForeignKeyColumnName:
        label = pretty_name(name)
        attr = name

    if return_attr:
        return (label, attr)
    else:
        return label

def help_text_for_field(name, model):
    help_text = ""
    try:
        field = _get_non_gfk_field(model._meta, name)
    except (FieldDoesNotExist, FieldIsAForeignKeyColumnName):
        pass
    else:
        if hasattr(field, "help_text"):
            help_text = field.help_text
    return help_text

def display_for_field(value, field, empty_value_display, avoid_link=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if field.name == "password" and field.model == get_user_model():
        return render_password_as_hash(value)
    elif getattr(field, "flatchoices", None):
        try:
            return dict(field.flatchoices).get(value, empty_value_display)
        except TypeError:
            # Allow list-like choices.
            flatchoices = make_hashable(field.flatchoices)
            value = make_hashable(value)
            return dict(flatchoices).get(value, empty_value_display)

    # BooleanField needs special-case null-handling, so it comes before the
    # general null test.
    elif isinstance(field, models.BooleanField):
        return _boolean_icon(value)
    elif value in field.empty_values:
        return empty_value_display
    elif isinstance(field, models.DateTimeField):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(field, (models.DateField, models.TimeField)):
        return formats.localize(value)
    elif isinstance(field, models.DecimalField):
        return formats.number_format(value, field.decimal_places)
    elif isinstance(field, (models.IntegerField, models.FloatField)):
        return formats.number_format(value)
    elif isinstance(field, models.FileField) and value and not avoid_link:
        return format_html('<a href="{}">{}</a>', value.url, value)
    elif isinstance(field, models.URLField) and value and not avoid_link:
        return format_html('<a href="{}">{}</a>', value, value)
    elif isinstance(field, models.JSONField) and value:
        try:
            return json.dumps(value, ensure_ascii=False, cls=field.encoder)
        except TypeError:
            return display_for_value(value, empty_value_display)
    else:
        return display_for_value(value, empty_value_display)

def display_for_value(value, empty_value_display, boolean=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if boolean:
        return _boolean_icon(value)
    elif value in EMPTY_VALUES:
        return empty_value_display
    elif isinstance(value, bool):
        return str(value)
    elif isinstance(value, datetime.datetime):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(value, (datetime.date, datetime.time)):
        return formats.localize(value)
    elif isinstance(value, (int, decimal.Decimal, float)):
        return formats.number_format(value)
    elif isinstance(value, (list, tuple)):
        return ", ".join(str(v) for v in value)
    else:
        return str(value)

def get_model_from_relation(field):
    if hasattr(field, "path_infos"):
        return field.path_infos[-1].to_opts.model
    else:
        raise NotRelationField

def construct_change_message(form, formsets, add):
    """
    Construct a JSON structure describing changes from a changed object.
    Translations are deactivated so that strings are stored untranslated.
    Translation happens later on LogEntry access.
    """
    # Evaluating `form.changed_data` prior to disabling translations is required
    # to avoid fields affected by localization from being included incorrectly,
    # e.g. where date formats differ such as MM/DD/YYYY vs DD/MM/YYYY.
    changed_data = form.changed_data
    with translation_override(None):
        # Deactivate translations while fetching verbose_name for form
        # field labels and using `field_name`, if verbose_name is not provided.
        # Translations will happen later on LogEntry access.
        changed_field_labels = _get_changed_field_labels_from_form(form, changed_data)

    change_message = []
    if add:
        change_message.append({"added": {}})
    elif form.changed_data:
        change_message.append({"changed": {"fields": changed_field_labels}})
    if formsets:
        with translation_override(None):
            for formset in formsets:
                for added_object in formset.new_objects:
                    change_message.append(
                        {
                            "added": {
                                "name": str(added_object._meta.verbose_name),
                                "object": str(added_object),
                            }
                        }
                    )
                for changed_object, changed_fields in formset.changed_objects:
                    change_message.append(
                        {
                            "changed": {
                                "name": str(changed_object._meta.verbose_name),
                                "object": str(changed_object),
                                "fields": _get_changed_field_labels_from_form(
                                    formset.forms[0], changed_fields
                                ),
                            }
                        }
                    )
                for deleted_object in formset.deleted_objects:
                    change_message.append(
                        {
                            "deleted": {
                                "name": str(deleted_object._meta.verbose_name),
                                "object": str(deleted_object),
                            }
                        }
                    )
    return change_message

def _get_changed_field_labels_from_form(form, changed_data):
    changed_field_labels = []
    for field_name in changed_data:
        try:
            verbose_field_name = form.fields[field_name].label or field_name
        except KeyError:
            verbose_field_name = field_name
        changed_field_labels.append(str(verbose_field_name))
    return changed_field_labels

def __init__(self, name="admin"):
    self._registry = {}  # model_class class -> admin_class instance
    self.name = name
    self._actions = {"delete_selected": actions.delete_selected}
    self._global_actions = self._actions.copy()
    all_sites.add(self)

def check(self, app_configs):
    """
    Run the system checks on all ModelAdmins, except if they aren't
    customized at all.
    """
    if app_configs is None:
        app_configs = apps.get_app_configs()
    app_configs = set(app_configs)  # Speed up lookups below

    errors = []
    modeladmins = (
        o for o in self._registry.values() if o.__class__ is not ModelAdmin
    )
    for modeladmin in modeladmins:
        if modeladmin.model._meta.app_config in app_configs:
            errors.extend(modeladmin.check())
    return errors

def unregister(self, model_or_iterable):
    """
    Unregister the given model(s).

    If a model isn't already registered, raise NotRegistered.
    """
    if isinstance(model_or_iterable, ModelBase):
        model_or_iterable = [model_or_iterable]
    for model in model_or_iterable:
        if not self.is_registered(model):
            raise NotRegistered("The model %s is not registered" % model.__name__)
        del self._registry[model]

def get_model_admin(self, model):
    try:
        return self._registry[model]
    except KeyError:
        raise NotRegistered(f"The model {model.__name__} is not registered.")

def actions(self):
    """
    Get all the enabled actions as an iterable of (name, func).
    """
    return self._actions.items()

def inner(request, *args, **kwargs):
    if not self.has_permission(request):
        if request.path == reverse("admin:logout", current_app=self.name):
            index_path = reverse("admin:index", current_app=self.name)
            return HttpResponseRedirect(index_path)
        # Inner import to prevent django.contrib.admin (app) from
        # importing django.contrib.auth.models.User (unrelated model).
        from django.contrib.auth.views import redirect_to_login

        return redirect_to_login(
            request.get_full_path(),
            reverse("admin:login", current_app=self.name),
        )
    return view(request, *args, **kwargs)

if not cacheable:
    inner = never_cache(inner)
# We add csrf_protect here so this function can be used as a utility
# function for any view, without having to repeat 'csrf_protect'.
if not getattr(view, "csrf_exempt", False):
    inner = csrf_protect(inner)
return update_wrapper(inner, view)

def password_change(self, request, extra_context=None):
    """
    Handle the "change password" task -- both form display and validation.
    """
    from django.contrib.admin.forms import AdminPasswordChangeForm
    from django.contrib.auth.views import PasswordChangeView

    url = reverse("admin:password_change_done", current_app=self.name)
    defaults = {
        "form_class": self.password_change_form or AdminPasswordChangeForm,
        "success_url": url,
        "extra_context": {**self.each_context(request), **(extra_context or {})},
    }
    if self.password_change_template is not None:
        defaults["template_name"] = self.password_change_template
    request.current_app = self.name
    return PasswordChangeView.as_view(**defaults)(request)

def password_change_done(self, request, extra_context=None):
    """
    Display the "success" page after a password change.
    """
    from django.contrib.auth.views import PasswordChangeDoneView

    defaults = {
        "extra_context": {**self.each_context(request), **(extra_context or {})},
    }
    if self.password_change_done_template is not None:
        defaults["template_name"] = self.password_change_done_template
    request.current_app = self.name
    return PasswordChangeDoneView.as_view(**defaults)(request)

def logout(self, request, extra_context=None):
    """
    Log out the user for the given HttpRequest.

    This should *not* assume the user is already logged in.
    """
    from django.contrib.auth.views import LogoutView

    defaults = {
        "extra_context": {
            **self.each_context(request),
            # Since the user isn't logged out at this point, the value of
            # has_permission must be overridden.
            "has_permission": False,
            **(extra_context or {}),
        },
    }
    if self.logout_template is not None:
        defaults["template_name"] = self.logout_template
    request.current_app = self.name
    return LogoutView.as_view(**defaults)(request)

@method_decorator(never_cache)
@login_not_required

def login(self, request, extra_context=None):
    """
    Display the login form for the given HttpRequest.
    """
    if request.method == "GET" and self.has_permission(request):
        # Already logged-in, redirect to admin index
        index_path = reverse("admin:index", current_app=self.name)
        return HttpResponseRedirect(index_path)

    # Since this module gets imported in the application's root package,
    # it cannot import models from other applications at the module level,
    # and django.contrib.admin.forms eventually imports User.
    from django.contrib.admin.forms import AdminAuthenticationForm
    from django.contrib.auth.views import LoginView

    context = {
        **self.each_context(request),
        "title": _("Log in"),
        "subtitle": None,
        "app_path": request.get_full_path(),
        "username": request.user.get_username(),
    }
    if (
        REDIRECT_FIELD_NAME not in request.GET
        and REDIRECT_FIELD_NAME not in request.POST
    ):
        context[REDIRECT_FIELD_NAME] = reverse("admin:index", current_app=self.name)
    context.update(extra_context or {})

    defaults = {
        "extra_context": context,
        "authentication_form": self.login_form or AdminAuthenticationForm,
        "template_name": self.login_template or "admin/login.html",
    }
    request.current_app = self.name
    return LoginView.as_view(**defaults)(request)

def autocomplete_view(self, request):
    return AutocompleteJsonView.as_view(admin_site=self)(request)

@no_append_slash

def catch_all_view(self, request, url):
    if settings.APPEND_SLASH and not url.endswith("/"):
        urlconf = getattr(request, "urlconf", None)
        try:
            match = resolve("%s/" % request.path_info, urlconf)
        except Resolver404:
            pass
        else:
            if getattr(match.func, "should_append_slash", True):
                return HttpResponsePermanentRedirect(
                    request.get_full_path(force_append_slash=True)
                )
    raise Http404

def _build_app_dict(self, request, label=None):
    """
    Build the app dictionary. The optional `label` parameter filters models
    of a specific app.
    """
    app_dict = {}

    if label:
        models = {
            m: m_a
            for m, m_a in self._registry.items()
            if m._meta.app_label == label
        }
    else:
        models = self._registry

    for model, model_admin in models.items():
        app_label = model._meta.app_label

        has_module_perms = model_admin.has_module_permission(request)
        if not has_module_perms:
            continue

        perms = model_admin.get_model_perms(request)

        # Check whether user has any perm for this module.
        # If so, add the module to the model_list.
        if True not in perms.values():
            continue

        info = (app_label, model._meta.model_name)
        model_dict = {
            "model": model,
            "name": capfirst(model._meta.verbose_name_plural),
            "object_name": model._meta.object_name,
            "perms": perms,
            "admin_url": None,
            "add_url": None,
        }
        if perms.get("change") or perms.get("view"):
            model_dict["view_only"] = not perms.get("change")
            try:
                model_dict["admin_url"] = reverse(
                    "admin:%s_%s_changelist" % info, current_app=self.name
                )
            except NoReverseMatch:
                pass
        if perms.get("add"):
            try:
                model_dict["add_url"] = reverse(
                    "admin:%s_%s_add" % info, current_app=self.name
                )
            except NoReverseMatch:
                pass

        if app_label in app_dict:
            app_dict[app_label]["models"].append(model_dict)
        else:
            app_dict[app_label] = {
                "name": apps.get_app_config(app_label).verbose_name,
                "app_label": app_label,
                "app_url": reverse(
                    "admin:app_list",
                    kwargs={"app_label": app_label},
                    current_app=self.name,
                ),
                "has_module_perms": has_module_perms,
                "models": [model_dict],
            }

    return app_dict

def app_index(self, request, app_label, extra_context=None):
    app_list = self.get_app_list(request, app_label)

    if not app_list:
        raise Http404("The requested admin page does not exist.")

    context = {
        **self.each_context(request),
        "title": _("%(app)s administration") % {"app": app_list[0]["name"]},
        "subtitle": None,
        "app_list": app_list,
        "app_label": app_label,
        **(extra_context or {}),
    }

    request.current_app = self.name

    return TemplateResponse(
        request,
        self.app_index_template
        or ["admin/%s/app_index.html" % app_label, "admin/app_index.html"],
        context,
    )

def get_log_entries(self, request):
    from django.contrib.admin.models import LogEntry

    return LogEntry.objects.select_related("content_type", "user")

def _setup(self):
    AdminSiteClass = import_string(apps.get_app_config("admin").default_site)
    self._wrapped = AdminSiteClass()

class DisallowedModelAdminLookup(SuspiciousOperation):
    """Invalid filter was passed to admin view via URL querystring"""

    pass

class DisallowedModelAdminToField(SuspiciousOperation):
    """Invalid to_field was passed to admin view via URL query string"""

    pass

class AlreadyRegistered(Exception):
    """The model is already registered."""

    pass

class NotRegistered(Exception):
    """The model is not registered."""

    pass

def __init__(
    self,
    form,
    fieldsets,
    prepopulated_fields,
    readonly_fields=None,
    model_admin=None,
):
    self.form, self.fieldsets = form, fieldsets
    self.prepopulated_fields = [
        {"field": form[field_name], "dependencies": [form[f] for f in dependencies]}
        for field_name, dependencies in prepopulated_fields.items()
    ]
    self.model_admin = model_admin
    if readonly_fields is None:
        readonly_fields = ()
    self.readonly_fields = readonly_fields

def __repr__(self):
    return (
        f"<{self.__class__.__qualname__}: "
        f"form={self.form.__class__.__qualname__} "
        f"fieldsets={self.fieldsets!r}>"
    )

def __iter__(self):
    for name, options in self.fieldsets:
        yield Fieldset(
            self.form,
            name,
            readonly_fields=self.readonly_fields,
            model_admin=self.model_admin,
            **options,
        )

@property

def errors(self):
    return self.form.errors

@property

def non_field_errors(self):
    return self.form.non_field_errors

@property

def fields(self):
    return self.form.fields

@property

def is_bound(self):
    return self.form.is_bound

@property

def media(self):
    media = self.form.media
    for fs in self:
        media += fs.media
    return media

def media(self):
    return forms.Media()

@cached_property

def is_collapsible(self):
    if any(field in self.fields for field in self.form.errors):
        return False
    return "collapse" in self.classes

def __iter__(self):
    for field in self.fields:
        yield Fieldline(
            self.form, field, self.readonly_fields, model_admin=self.model_admin
        )

def __init__(self, form, field, readonly_fields=None, model_admin=None):
    self.form = form  # A django.forms.Form instance
    if not hasattr(field, "__iter__") or isinstance(field, str):
        self.fields = [field]
    else:
        self.fields = field
    self.has_visible_field = not all(
        field in self.form.fields and self.form.fields[field].widget.is_hidden
        for field in self.fields
    )
    self.model_admin = model_admin
    if readonly_fields is None:
        readonly_fields = ()
    self.readonly_fields = readonly_fields

def __iter__(self):
    for i, field in enumerate(self.fields):
        if field in self.readonly_fields:
            yield AdminReadonlyField(
                self.form, field, is_first=(i == 0), model_admin=self.model_admin
            )
        else:
            yield AdminField(self.form, field, is_first=(i == 0))

def errors(self):
    return mark_safe(
        "\n".join(
            self.form[f].errors.as_ul()
            for f in self.fields
            if f not in self.readonly_fields
        ).strip("\n")
    )

def label_tag(self):
    classes = []
    contents = conditional_escape(self.field.label)
    if self.is_checkbox:
        classes.append("vCheckboxLabel")

    if self.field.field.required:
        classes.append("required")
    if not self.is_first:
        classes.append("inline")
    attrs = {"class": " ".join(classes)} if classes else {}
    # checkboxes should not have a label suffix as the checkbox appears
    # to the left of the label.
    return self.field.label_tag(
        contents=mark_safe(contents),
        attrs=attrs,
        label_suffix="" if self.is_checkbox else None,
    )

def __init__(self, form, field, is_first, model_admin=None):
    # Make self.field look a little bit like a field. This means that
    # {{ field.name }} must be a useful class name to identify the field.
    # For convenience, store other field-related data here too.
    if callable(field):
        class_name = field.__name__ if field.__name__ != "<lambda>" else ""
    else:
        class_name = field

    if form._meta.labels and class_name in form._meta.labels:
        label = form._meta.labels[class_name]
    else:
        label = label_for_field(field, form._meta.model, model_admin, form=form)

    if form._meta.help_texts and class_name in form._meta.help_texts:
        help_text = form._meta.help_texts[class_name]
    else:
        help_text = help_text_for_field(class_name, form._meta.model)

    if field in form.fields:
        is_hidden = form.fields[field].widget.is_hidden
    else:
        is_hidden = False

    self.field = {
        "name": class_name,
        "label": label,
        "help_text": help_text,
        "field": field,
        "is_hidden": is_hidden,
    }
    self.form = form
    self.model_admin = model_admin
    self.is_first = is_first
    self.is_checkbox = False
    self.is_readonly = True
    self.empty_value_display = model_admin.get_empty_value_display()

def label_tag(self):
    attrs = {}
    if not self.is_first:
        attrs["class"] = "inline"
    label = self.field["label"]
    return format_html(
        "<label{}>{}{}</label>",
        flatatt(attrs),
        capfirst(label),
        self.form.label_suffix,
    )

def get_admin_url(self, remote_field, remote_obj):
    url_name = "admin:%s_%s_change" % (
        remote_field.model._meta.app_label,
        remote_field.model._meta.model_name,
    )
    try:
        url = reverse(
            url_name,
            args=[quote(remote_obj.pk)],
            current_app=self.model_admin.admin_site.name,
        )
        return format_html('<a href="{}">{}</a>', url, remote_obj)
    except NoReverseMatch:
        return str(remote_obj)

def contents(self):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    field, obj, model_admin = (
        self.field["field"],
        self.form.instance,
        self.model_admin,
    )
    try:
        f, attr, value = lookup_field(field, obj, model_admin)
    except (AttributeError, ValueError, ObjectDoesNotExist):
        result_repr = self.empty_value_display
    else:
        if f is None:
            if getattr(attr, "boolean", False):
                result_repr = _boolean_icon(value)
            else:
                if hasattr(value, "__html__"):
                    result_repr = value
                else:
                    result_repr = linebreaksbr(value)
        else:
            if isinstance(f.remote_field, ManyToManyRel) and value is not None:
                result_repr = ", ".join(map(str, value.all()))
            elif (
                isinstance(f.remote_field, (ForeignObjectRel, OneToOneField))
                and value is not None
            ):
                result_repr = self.get_admin_url(f.remote_field, value)
            else:
                result_repr = display_for_field(value, f, self.empty_value_display)
            result_repr = linebreaksbr(result_repr)
    return conditional_escape(result_repr)

def fields(self):
    fk = getattr(self.formset, "fk", None)
    empty_form = self.formset.empty_form
    meta_labels = empty_form._meta.labels or {}
    meta_help_texts = empty_form._meta.help_texts or {}
    for i, field_name in enumerate(flatten_fieldsets(self.fieldsets)):
        if fk and fk.name == field_name:
            continue
        if not self.has_change_permission or field_name in self.readonly_fields:
            form_field = empty_form.fields.get(field_name)
            widget_is_hidden = False
            if form_field is not None:
                widget_is_hidden = form_field.widget.is_hidden
            yield {
                "name": field_name,
                "label": meta_labels.get(field_name)
                or label_for_field(
                    field_name,
                    self.opts.model,
                    self.opts,
                    form=empty_form,
                ),
                "widget": {"is_hidden": widget_is_hidden},
                "required": False,
                "help_text": meta_help_texts.get(field_name)
                or help_text_for_field(field_name, self.opts.model),
            }
        else:
            form_field = empty_form.fields[field_name]
            label = form_field.label
            if label is None:
                label = label_for_field(
                    field_name, self.opts.model, self.opts, form=empty_form
                )
            yield {
                "name": field_name,
                "label": label,
                "widget": form_field.widget,
                "required": form_field.required,
                "help_text": form_field.help_text,
            }

def inline_formset_data(self):
    verbose_name = self.opts.verbose_name
    return json.dumps(
        {
            "name": "#%s" % self.formset.prefix,
            "options": {
                "prefix": self.formset.prefix,
