        try:
            obj.model._meta.get_field(obj.ct_field)
        except FieldDoesNotExist:
            return [
                checks.Error(
                    "'ct_field' references '%s', which is not a field on '%s'."
                    % (
                        obj.ct_field,
                        obj.model._meta.label,
                    ),
                    obj=obj.__class__,
                    id="admin.E302",
                )
            ]

        try:
            obj.model._meta.get_field(obj.ct_fk_field)
        except FieldDoesNotExist:
            return [
                checks.Error(
                    "'ct_fk_field' references '%s', which is not a field on '%s'."
                    % (
                        obj.ct_fk_field,
                        obj.model._meta.label,
                    ),
                    obj=obj.__class__,
                    id="admin.E303",
                )
            ]

        # There's one or more GenericForeignKeys; make sure that one of them
        # uses the right ct_field and ct_fk_field.
        for gfk in gfks:
            if gfk.ct_field == obj.ct_field and gfk.fk_field == obj.ct_fk_field:
                return []

        return [
            checks.Error(
                "'%s' has no GenericForeignKey using content type field '%s' and "
                "object ID field '%s'."
                % (
                    obj.model._meta.label,
                    obj.ct_field,
                    obj.ct_fk_field,
                ),
                obj=obj.__class__,
                id="admin.E304",
            )
        ]

def __init__(self, lookup, querysets, to_attr=None):
    for queryset in querysets:
        if queryset is not None and (
            isinstance(queryset, RawQuerySet)
            or (
                hasattr(queryset, "_iterable_class")
                and not issubclass(queryset._iterable_class, ModelIterable)
            )
        ):
            raise ValueError(
                "Prefetch querysets cannot use raw(), values(), and values_list()."
            )
    self.querysets = querysets
    super().__init__(lookup, to_attr=to_attr)

def get_current_querysets(self, level):
    if self.get_current_prefetch_to(level) == self.prefetch_to:
        return self.querysets
    return None

def shortcut(request, content_type_id, object_id):
    """
    Redirect to an object's page based on a content-type ID and an object ID.
    """
    # Look up the object, making sure it's got a get_absolute_url() function.
    try:
        content_type = ContentType.objects.get(pk=content_type_id)
        if not content_type.model_class():
            raise Http404(
                _("Content type %(ct_id)s object has no associated model")
                % {"ct_id": content_type_id}
            )
        obj = content_type.get_object_for_this_type(pk=object_id)
    except (ObjectDoesNotExist, ValueError, ValidationError):
        raise Http404(
            _("Content type %(ct_id)s object %(obj_id)s doesn’t exist")
            % {"ct_id": content_type_id, "obj_id": object_id}
        )

    try:
        get_absolute_url = obj.get_absolute_url
    except AttributeError:
        raise Http404(
            _("%(ct_name)s objects don’t have a get_absolute_url() method")
            % {"ct_name": content_type.name}
        )
    absurl = get_absolute_url()

    # Try to figure out the object's domain, so we can do a cross-site redirect
    # if necessary.

    # If the object actually defines a domain, we're done.
    if absurl.startswith(("http://", "https://", "//")):
        return HttpResponseRedirect(absurl)

    # Otherwise, we need to introspect the object's relationships for a
    # relation to the Site object
    try:
        object_domain = get_current_site(request).domain
    except ObjectDoesNotExist:
        object_domain = None

    if apps.is_installed("django.contrib.sites"):
        Site = apps.get_model("sites.Site")
        opts = obj._meta

        for field in opts.many_to_many:
            # Look for a many-to-many relationship to Site.
            if field.remote_field.model is Site:
                site_qs = getattr(obj, field.name).all()
                if object_domain and site_qs.filter(domain=object_domain).exists():
                    # The current site's domain matches a site attached to the
                    # object.
                    break
                # Caveat: In the case of multiple related Sites, this just
                # selects the *first* one, which is arbitrary.
                site = site_qs.first()
                if site:
                    object_domain = site.domain
                    break
        else:
            # No many-to-many relationship to Site found. Look for a
            # many-to-one relationship to Site.
            for field in obj._meta.fields:
                if field.remote_field and field.remote_field.model is Site:
                    try:
                        site = getattr(obj, field.name)
                    except Site.DoesNotExist:
                        continue
                    if site is not None:
                        object_domain = site.domain
                        break

    # If all that malarkey found an object domain, use it. Otherwise, fall back
    # to whatever get_absolute_url() returned.
    if object_domain is not None:
        protocol = request.scheme
        return HttpResponseRedirect("%s://%s%s" % (protocol, object_domain, absurl))
    else:
        return HttpResponseRedirect(absurl)

def pretty_name(obj):
    return obj.__name__ if obj.__class__ == type else obj.__class__.__name__


@total_ordering

class MeasureBase:
    STANDARD_UNIT = None
    ALIAS = {}
    UNITS = {}
    LALIAS = {}

def __init__(self, default_unit=None, **kwargs):
    value, self._default_unit = self.default_units(kwargs)
    setattr(self, self.STANDARD_UNIT, value)
    if default_unit and isinstance(default_unit, str):
        self._default_unit = default_unit

def _set_standard(self, value):
    setattr(self, self.STANDARD_UNIT, value)

standard = property(_get_standard, _set_standard)

def __getattr__(self, name):
    if name in self.UNITS:
        return self.standard / self.UNITS[name]
    else:
        raise AttributeError("Unknown unit type: %s" % name)

def __repr__(self):
    return "%s(%s=%s)" % (
        pretty_name(self),
        self._default_unit,
        getattr(self, self._default_unit),
    )

def __str__(self):
    return "%s %s" % (getattr(self, self._default_unit), self._default_unit)

# **** Comparison methods ****

def __eq__(self, other):
    if isinstance(other, self.__class__):
        return self.standard == other.standard
    else:
        return NotImplemented

def __lt__(self, other):
    if isinstance(other, self.__class__):
        return self.standard < other.standard
    else:
        return NotImplemented

# **** Operators methods ****

def __add__(self, other):
    if isinstance(other, self.__class__):
        return self.__class__(
            default_unit=self._default_unit,
            **{self.STANDARD_UNIT: (self.standard + other.standard)},
        )
    else:
        raise TypeError(
            "%(class)s must be added with %(class)s" % {"class": pretty_name(self)}
        )

def __iadd__(self, other):
    if isinstance(other, self.__class__):
        self.standard += other.standard
        return self
    else:
        raise TypeError(
            "%(class)s must be added with %(class)s" % {"class": pretty_name(self)}
        )

def __sub__(self, other):
    if isinstance(other, self.__class__):
        return self.__class__(
            default_unit=self._default_unit,
            **{self.STANDARD_UNIT: (self.standard - other.standard)},
        )
    else:
        raise TypeError(
            "%(class)s must be subtracted from %(class)s"
            % {"class": pretty_name(self)}
        )

def __isub__(self, other):
    if isinstance(other, self.__class__):
        self.standard -= other.standard
        return self
    else:
        raise TypeError(
            "%(class)s must be subtracted from %(class)s"
            % {"class": pretty_name(self)}
        )

def __mul__(self, other):
    if isinstance(other, NUMERIC_TYPES):
        return self.__class__(
            default_unit=self._default_unit,
            **{self.STANDARD_UNIT: (self.standard * other)},
        )
    else:
        raise TypeError(
            "%(class)s must be multiplied with number"
            % {"class": pretty_name(self)}
        )

def __imul__(self, other):
    if isinstance(other, NUMERIC_TYPES):
        self.standard *= float(other)
        return self
    else:
        raise TypeError(
            "%(class)s must be multiplied with number"
            % {"class": pretty_name(self)}
        )

def __truediv__(self, other):
    if isinstance(other, self.__class__):
        return self.standard / other.standard
    if isinstance(other, NUMERIC_TYPES):
        return self.__class__(
            default_unit=self._default_unit,
            **{self.STANDARD_UNIT: (self.standard / other)},
        )
    else:
        raise TypeError(
            "%(class)s must be divided with number or %(class)s"
            % {"class": pretty_name(self)}
        )

def __itruediv__(self, other):
    if isinstance(other, NUMERIC_TYPES):
        self.standard /= float(other)
        return self
    else:
        raise TypeError(
            "%(class)s must be divided with number" % {"class": pretty_name(self)}
        )

def default_units(self, kwargs):
    """
    Return the unit value and the default units specified
    from the given keyword arguments dictionary.
    """
    val = 0.0
    default_unit = self.STANDARD_UNIT
    for unit, value in kwargs.items():
        if not isinstance(value, float):
            value = float(value)
        if unit in self.UNITS:
            val += self.UNITS[unit] * value
            default_unit = unit
        elif unit in self.ALIAS:
            u = self.ALIAS[unit]
            val += self.UNITS[u] * value
            default_unit = u
        else:
            lower = unit.lower()
            if lower in self.UNITS:
                val += self.UNITS[lower] * value
                default_unit = lower
            elif lower in self.LALIAS:
                u = self.LALIAS[lower]
                val += self.UNITS[u] * value
                default_unit = u
            else:
                raise AttributeError("Unknown unit type: %s" % unit)
    return val, default_unit

@classmethod

def unit_attname(cls, unit_str):
    """
    Retrieve the unit attribute name for the given unit string.
    For example, if the given unit string is 'metre', return 'm'.
    Raise an AttributeError if an attribute cannot be found.
    """
    lower = unit_str.lower()
    if unit_str in cls.UNITS:
        return unit_str
    elif lower in cls.UNITS:
        return lower
    elif lower in cls.LALIAS:
        return cls.LALIAS[lower]
    else:
        raise AttributeError(f"Unknown unit type: {unit_str}")

def __mul__(self, other):
    if isinstance(other, self.__class__):
        return Area(
            default_unit=AREA_PREFIX + self._default_unit,
            **{AREA_PREFIX + self.STANDARD_UNIT: (self.standard * other.standard)},
        )
    elif isinstance(other, NUMERIC_TYPES):
        return self.__class__(
            default_unit=self._default_unit,
            **{self.STANDARD_UNIT: (self.standard * other)},
        )
    else:
        raise TypeError(
            "%(distance)s must be multiplied with number or %(distance)s"
            % {
                "distance": pretty_name(self.__class__),
            }
        )

class Area(MeasureBase):
    STANDARD_UNIT = AREA_PREFIX + Distance.STANDARD_UNIT
    # Getting the square units values and the alias dictionary.
    UNITS = {"%s%s" % (AREA_PREFIX, k): v**2 for k, v in Distance.UNITS.items()} | {
        "ha": 10000,
    }
    ALIAS = {k: "%s%s" % (AREA_PREFIX, v) for k, v in Distance.ALIAS.items()} | {
        "hectare": "ha",
    }

    LALIAS = {k.lower(): v for k, v in ALIAS.items()}

    def __truediv__(self, other):
        if isinstance(other, NUMERIC_TYPES):
            return self.__class__(
                default_unit=self._default_unit,
                **{self.STANDARD_UNIT: (self.standard / other)},
            )
        else:
            raise TypeError(
                "%(class)s must be divided by a number" % {"class": pretty_name(self)}
            )


