def get_return_data_type(func_name):
    """Return a somewhat-helpful data type given a function name"""
    if func_name.startswith("get_"):
        if func_name.endswith("_list"):
            return "List"
        elif func_name.endswith("_count"):
            return "Integer"
    return ""

def extract_views_from_urlpatterns(urlpatterns, base="", namespace=None):
    """
    Return a list of views from a list of urlpatterns.

    Each object in the returned list is a 4-tuple:
    (view_func, regex, namespace, name)
    """
    views = []
    for p in urlpatterns:
        if hasattr(p, "url_patterns"):
            try:
                patterns = p.url_patterns
            except ImportError:
                continue
            views.extend(
                extract_views_from_urlpatterns(
                    patterns,
                    base + str(p.pattern),
                    (namespace or []) + (p.namespace and [p.namespace] or []),
                )
            )
        elif hasattr(p, "callback"):
            try:
                views.append((p.callback, base + str(p.pattern), namespace, p.name))
            except ViewDoesNotExist:
                continue
        else:
            raise TypeError(_("%s does not appear to be a urlpattern object") % p)
    return views

def __init__(self, *args, **kwargs):
    if not hasattr(self, "_get_single_internal"):
        self._get_single_internal = self._get_single_external

    if not hasattr(self, "_set_single"):
        self._set_single = self._set_single_rebuild
        self._assign_extended_slice = self._assign_extended_slice_rebuild

    super().__init__(*args, **kwargs)

def __getitem__(self, index):
    "Get the item(s) at the specified index/slice."
    if isinstance(index, slice):
        return [
            self._get_single_external(i) for i in range(*index.indices(len(self)))
        ]
    else:
        index = self._checkindex(index)
        return self._get_single_external(index)

def __delitem__(self, index):
    "Delete the item(s) at the specified index/slice."
    if not isinstance(index, (int, slice)):
        raise TypeError("%s is not a legal index" % index)

    # calculate new length and dimensions
    origLen = len(self)
    if isinstance(index, int):
        index = self._checkindex(index)
        indexRange = [index]
    else:
        indexRange = range(*index.indices(origLen))

    newLen = origLen - len(indexRange)
    newItems = (
        self._get_single_internal(i) for i in range(origLen) if i not in indexRange
    )

    self._rebuild(newLen, newItems)

def __setitem__(self, index, val):
    "Set the item(s) at the specified index/slice."
    if isinstance(index, slice):
        self._set_slice(index, val)
    else:
        index = self._checkindex(index)
        self._check_allowed((val,))
        self._set_single(index, val)

# ### Special methods for arithmetic operations ###

def __add__(self, other):
    "add another list-like object"
    return self.__class__([*self, *other])

def __radd__(self, other):
    "add to another list-like object"
    return other.__class__([*other, *self])

def __mul__(self, n):
    "multiply"
    return self.__class__(list(self) * n)

def __rmul__(self, n):
    "multiply"
    return self.__class__(list(self) * n)

def __imul__(self, n):
    "multiply"
    if n <= 0:
        del self[:]
    else:
        cache = list(self)
        for i in range(n - 1):
            self.extend(cache)
    return self

def __eq__(self, other):
    olen = len(other)
    for i in range(olen):
        try:
            c = self[i] == other[i]
        except IndexError:
            # self must be shorter
            return False
        if not c:
            return False
    return len(self) == olen

def __lt__(self, other):
    olen = len(other)
    for i in range(olen):
        try:
            c = self[i] < other[i]
        except IndexError:
            # self must be shorter
            return True
        if c:
            return c
        elif other[i] < self[i]:
            return False
    return len(self) < olen

# ### Public list interface Methods ###
# ## Non-mutating ##

def count(self, val):
    "Standard list count method"
    count = 0
    for i in self:
        if val == i:
            count += 1
    return count

def index(self, val):
    "Standard list index method"
    for i in range(0, len(self)):
        if self[i] == val:
            return i
    raise ValueError("%s not found in object" % val)

# ## Mutating ##

def append(self, val):
    "Standard list append method"
    self[len(self) :] = [val]

def extend(self, vals):
    "Standard list extend method"
    self[len(self) :] = vals

def insert(self, index, val):
    "Standard list insert method"
    if not isinstance(index, int):
        raise TypeError("%s is not a legal index" % index)
    self[index:index] = [val]

def remove(self, val):
    "Standard list remove method"
    del self[self.index(val)]

def reverse(self):
    "Standard list reverse method"
    self[:] = self[-1::-1]

def _rebuild(self, newLen, newItems):
    if newLen and newLen < self._minlength:
        raise ValueError("Must have at least %d items" % self._minlength)
    if self._maxlength is not None and newLen > self._maxlength:
        raise ValueError("Cannot have more than %d items" % self._maxlength)

    self._set_list(newLen, newItems)

def _checkindex(self, index):
    length = len(self)
    if 0 <= index < length:
        return index
    if -length <= index < 0:
        return index + length
    raise IndexError("invalid index: %s" % index)

def _check_allowed(self, items):
    if hasattr(self, "_allowed"):
        if False in [isinstance(val, self._allowed) for val in items]:
            raise TypeError("Invalid type encountered in the arguments.")

def _set_slice(self, index, values):
    "Assign values to a slice of the object"
    try:
        valueList = list(values)
    except TypeError:
        raise TypeError("can only assign an iterable to a slice")

    self._check_allowed(valueList)

    origLen = len(self)
    start, stop, step = index.indices(origLen)

    # CAREFUL: index.step and step are not the same!
    # step will never be None
    if index.step is None:
        self._assign_simple_slice(start, stop, valueList)
    else:
        self._assign_extended_slice(start, stop, step, valueList)

def newItems():
    for i in range(newLen):
        if i in newVals:
            yield newVals[i]
        else:
            yield self._get_single_internal(i)

self._rebuild(newLen, newItems())

def _assign_extended_slice(self, start, stop, step, valueList):
    "Assign an extended slice by re-assigning individual items"
    indexList = range(start, stop, step)
    # extended slice, only allow assigning slice of same size
    if len(valueList) != len(indexList):
        raise ValueError(
            "attempt to assign sequence of size %d "
            "to extended slice of size %d" % (len(valueList), len(indexList))
        )

    for i, val in zip(indexList, valueList):
        self._set_single(i, val)

def newItems():
    for i in range(origLen + 1):
        if i == start:
            yield from valueList

        if i < origLen:
            if i < start or i >= stop:
                yield self._get_single_internal(i)

self._rebuild(newLen, newItems())

class GEOSException(Exception):
    "The base GEOS exception, indicates a GEOS-related error."

    pass

def __iter__(self):
    "Iterate over each ring in the polygon."
    for i in range(len(self)):
        yield self[i]

def __len__(self):
    "Return the number of rings in this Polygon."
    return self.num_interior_rings + 1

@classmethod

def from_bbox(cls, bbox):
    "Construct a Polygon from a bounding box (4-tuple)."
    x0, y0, x1, y1 = bbox
    for z in bbox:
        if not isinstance(z, (float, int)):
            return GEOSGeometry(
                "POLYGON((%s %s, %s %s, %s %s, %s %s, %s %s))"
                % (x0, y0, x0, y1, x1, y1, x1, y0, x0, y0)
            )
    return Polygon(((x0, y0), (x0, y1), (x1, y1), (x1, y0), (x0, y0)))

# ### These routines are needed for list-like operation w/ListMixin ###

def _create_polygon(self, length, items):
    # Instantiate LinearRing objects if necessary, but don't clone them yet
    # _construct_ring will throw a TypeError if a parameter isn't a valid ring
    # If we cloned the pointers here, we wouldn't be able to clean up
    # in case of error.
    if not length:
        return capi.create_empty_polygon()

    rings = []
    for r in items:
        if isinstance(r, GEOM_PTR):
            rings.append(r)
        else:
            rings.append(self._construct_ring(r))

    shell = self._clone(rings.pop(0))

    n_holes = length - 1
    if n_holes:
        holes_param = (GEOM_PTR * n_holes)(*[self._clone(r) for r in rings])
    else:
        holes_param = None

    return capi.create_polygon(shell, holes_param, n_holes)

def _clone(self, g):
    if isinstance(g, GEOM_PTR):
        return capi.geom_clone(g)
    else:
        return capi.geom_clone(g.ptr)

def _construct_ring(
    self,
    param,
    msg=(
        "Parameter must be a sequence of LinearRings or objects that can "
        "initialize to LinearRings"
    ),
):
    "Try to construct a ring from the given parameter."
    if isinstance(param, LinearRing):
        return param
    try:
        return LinearRing(param)
    except TypeError:
        raise TypeError(msg)

def _get_single_internal(self, index):
    """
    Return the ring at the specified index. The first index, 0, will
    always return the exterior ring.  Indices > 0 will return the
    interior ring at the given index (e.g., poly[1] and poly[2] would
    return the first and second interior ring, respectively).

    CAREFUL: Internal/External are not the same as Interior/Exterior!
    Return a pointer from the existing geometries for use internally by the
    object's methods. _get_single_external() returns a clone of the same
    geometry for use by external code.
    """
    if index == 0:
        return capi.get_extring(self.ptr)
    else:
        # Getting the interior ring, have to subtract 1 from the index.
        return capi.get_intring(self.ptr, index - 1)

def _get_single_external(self, index):
    return GEOSGeometry(
        capi.geom_clone(self._get_single_internal(index)), srid=self.srid
    )

_set_single = GEOSGeometry._set_single_rebuild
_assign_extended_slice = GEOSGeometry._assign_extended_slice_rebuild

