class GEOSContext(threading.local):
    handle = None


thread_context = GEOSContext()

def __call__(self, *args):
    # Create a context handle if one doesn't exist for this thread.
    self.thread_context.handle = self.thread_context.handle or GEOSContextHandle()
    # Call the threaded GEOS routine with the pointer of the context handle
    # as the first argument.
    return self.cfunc(self.thread_context.handle.ptr, *args)

def __str__(self):
    return self.cfunc.__name__

# argtypes property

def _set_errcheck(self, errcheck):
    self.cfunc.errcheck = errcheck

errcheck = property(_get_errcheck, _set_errcheck)

def last_arg_byref(args):
    "Return the last C argument's value by reference."
    return args[-1]._obj.value

def check_dbl(result, func, cargs):
    "Check the status code and returns the double value passed in by reference."
    # Checking the status code
    if result != 1:
        return None
    # Double passed in by reference, return its value.
    return last_arg_byref(cargs)

def check_geom(result, func, cargs):
    "Error checking on routines that return Geometries."
    if not result:
        raise GEOSException(
            'Error encountered checking Geometry returned from GEOS C function "%s".'
            % func.__name__
        )
    return result

def check_minus_one(result, func, cargs):
    "Error checking on routines that should not return -1."
    if result == -1:
        raise GEOSException(
            'Error encountered in GEOS C function "%s".' % func.__name__
        )
    else:
        return result

def check_predicate(result, func, cargs):
    "Error checking for unary/binary predicate functions."
    if result == 1:
        return True
    elif result == 0:
        return False
    else:
        raise GEOSException(
            'Error encountered on GEOS C predicate function "%s".' % func.__name__
        )

def _rename(self, apps, schema_editor, old_model, new_model):
    ContentType = apps.get_model("contenttypes", "ContentType")
    db = schema_editor.connection.alias
    if not router.allow_migrate_model(db, ContentType):
        return

    try:
        content_type = ContentType.objects.db_manager(db).get_by_natural_key(
            self.app_label, old_model
        )
    except ContentType.DoesNotExist:
        pass
    else:
        content_type.model = new_model
        try:
            with transaction.atomic(using=db):
                content_type.save(using=db, update_fields={"model"})
        except IntegrityError:
            # Gracefully fallback if a stale content type causes a
            # conflict as remove_stale_contenttypes will take care of
            # asking the user what should be done next.
            content_type.model = old_model
        else:
            # Clear the cache as the `get_by_natural_key()` call will cache
            # the renamed ContentType instance by its old model name.
            ContentType.objects.clear_cache()

def inject_rename_contenttypes_operations(
    plan=None, apps=global_apps, using=DEFAULT_DB_ALIAS, **kwargs
):
    """
    Insert a `RenameContentType` operation after every planned `RenameModel`
    operation.
    """
    if plan is None:
        return

    # Determine whether or not the ContentType model is available.
    try:
        ContentType = apps.get_model("contenttypes", "ContentType")
    except LookupError:
        available = False
    else:
        if not router.allow_migrate_model(using, ContentType):
            return
        available = True

    for migration, backward in plan:
        if (migration.app_label, migration.name) == ("contenttypes", "0001_initial"):
            # There's no point in going forward if the initial contenttypes
            # migration is unapplied as the ContentType model will be
            # unavailable from this point.
            if backward:
                break
            else:
                available = True
                continue
        # The ContentType model is not available yet.
        if not available:
            continue
        inserts = []
        for index, operation in enumerate(migration.operations):
            if isinstance(operation, migrations.RenameModel):
                operation = RenameContentType(
                    migration.app_label,
                    operation.old_name_lower,
                    operation.new_name_lower,
                )
                inserts.append((index + 1, operation))
        for inserted, (index, operation) in enumerate(inserts):
            migration.operations.insert(inserted + index, operation)

def get_contenttypes_and_models(app_config, using, ContentType):
    if not router.allow_migrate_model(using, ContentType):
        return None, None

    ContentType.objects.clear_cache()

    content_types = {
        ct.model: ct
        for ct in ContentType.objects.using(using).filter(app_label=app_config.label)
    }
    app_models = {model._meta.model_name: model for model in app_config.get_models()}
    return content_types, app_models

def create_contenttypes(
    app_config,
    verbosity=2,
    interactive=True,
    using=DEFAULT_DB_ALIAS,
    apps=global_apps,
    **kwargs,
):
    """
    Create content types for models in the given app.
    """
    if not app_config.models_module:
        return

    app_label = app_config.label
    try:
        app_config = apps.get_app_config(app_label)
        ContentType = apps.get_model("contenttypes", "ContentType")
    except LookupError:
        return

    content_types, app_models = get_contenttypes_and_models(
        app_config, using, ContentType
    )

    if not app_models:
        return

    cts = [
        ContentType(
            app_label=app_label,
            model=model_name,
        )
        for (model_name, model) in app_models.items()
        if model_name not in content_types
    ]
    ContentType.objects.using(using).bulk_create(cts)
    if verbosity >= 2:
        for ct in cts:
            print("Adding content type '%s | %s'" % (ct.app_label, ct.model))

def handle(self, **options):
    db = options["database"]
    include_stale_apps = options["include_stale_apps"]
    interactive = options["interactive"]
    verbosity = options["verbosity"]

    if not router.allow_migrate_model(db, ContentType):
        return
    ContentType.objects.clear_cache()

    apps_content_types = itertools.groupby(
        ContentType.objects.using(db).order_by("app_label", "model"),
        lambda obj: obj.app_label,
    )
    for app_label, content_types in apps_content_types:
        if not include_stale_apps and app_label not in apps.app_configs:
            continue
        to_remove = [ct for ct in content_types if ct.model_class() is None]
        # Confirm that the content type is stale before deletion.
        using = router.db_for_write(ContentType)
        if to_remove:
            if interactive:
                ct_info = []
                for ct in to_remove:
                    ct_info.append(
                        "    - Content type for %s.%s" % (ct.app_label, ct.model)
                    )
                    collector = NoFastDeleteCollector(using=using, origin=ct)
                    collector.collect([ct])

                    for obj_type, objs in collector.data.items():
                        if objs != {ct}:
                            ct_info.append(
                                "    - %s %s object(s)"
                                % (
                                    len(objs),
                                    obj_type._meta.label,
                                )
                            )
                content_type_display = "\n".join(ct_info)
                self.stdout.write(
                    "Some content types in your database are stale and can be "
                    "deleted.\n"
                    "Any objects that depend on these content types will also be "
                    "deleted.\n"
                    "The content types and dependent objects that would be deleted "
                    "are:\n\n"
                    f"{content_type_display}\n\n"
                    "This list doesn't include any cascade deletions to data "
                    "outside of Django\n"
                    "models (uncommon).\n\n"
                    "Are you sure you want to delete these content types?\n"
                    "If you're unsure, answer 'no'."
                )
                ok_to_delete = input("Type 'yes' to continue, or 'no' to cancel: ")
            else:
                ok_to_delete = "yes"

            if ok_to_delete == "yes":
                for ct in to_remove:
                    if verbosity >= 2:
                        self.stdout.write(
                            "Deleting stale content type '%s | %s'"
                            % (ct.app_label, ct.model)
                        )
                    ct.delete()
            else:
                if verbosity >= 2:
                    self.stdout.write("Stale content types remain.")

def load(self):
    """
    Load the data from the key itself instead of fetching from some
    external data store. Opposite of _get_session_key(), raise BadSignature
    if signature fails.
    """
    try:
        return signing.loads(
            self.session_key,
            serializer=self.serializer,
            # This doesn't handle non-default expiry dates, see #19201
            max_age=self.get_session_cookie_age(),
            salt="django.contrib.sessions.backends.signed_cookies",
        )
    except Exception:
        # BadSignature, ValueError, or unpickling exceptions. If any of
        # these happen, reset the session.
        self.create()
    return {}

async def aload(self):
    return self.load()

def _get_session_key(self):
    """
    Instead of generating a random string, generate a secure url-safe
    base64-encoded string of data as our session key.
    """
    return signing.dumps(
        self._session,
        compress=True,
        salt="django.contrib.sessions.backends.signed_cookies",
        serializer=self.serializer,
    )

@classmethod

def clear_expired(cls):
    pass

@classmethod
async def aclear_expired(cls):
    pass

def __init__(self, session_key=None):
    super().__init__(session_key)

@classmethod

def get_model_class(cls):
    # Avoids a circular import and allows importing SessionStore when
    # django.contrib.sessions is not in INSTALLED_APPS.
    from django.contrib.sessions.models import Session

    return Session

@cached_property

def _get_session_from_db(self):
    try:
        return self.model.objects.get(
            session_key=self.session_key, expire_date__gt=timezone.now()
        )
    except (self.model.DoesNotExist, SuspiciousOperation) as e:
        if isinstance(e, SuspiciousOperation):
            logger = logging.getLogger("django.security.%s" % e.__class__.__name__)
            logger.warning(str(e))
        self._session_key = None

async def _aget_session_from_db(self):
    try:
        return await self.model.objects.aget(
            session_key=self.session_key, expire_date__gt=timezone.now()
        )
    except (self.model.DoesNotExist, SuspiciousOperation) as e:
        if isinstance(e, SuspiciousOperation):
            logger = logging.getLogger("django.security.%s" % e.__class__.__name__)
            logger.warning(str(e))
        self._session_key = None

def load(self):
    s = self._get_session_from_db()
    return self.decode(s.session_data) if s else {}

async def aload(self):
    s = await self._aget_session_from_db()
    return self.decode(s.session_data) if s else {}

def exists(self, session_key):
    return self.model.objects.filter(session_key=session_key).exists()

async def aexists(self, session_key):
    return await self.model.objects.filter(session_key=session_key).aexists()

def save(self, must_create=False):
    """
    Save the current session data to the database. If 'must_create' is
    True, raise a database error if the saving operation doesn't create a
    new entry (as opposed to possibly updating an existing entry).
    """
    if self.session_key is None:
        return self.create()
    data = self._get_session(no_load=must_create)
    obj = self.create_model_instance(data)
    using = router.db_for_write(self.model, instance=obj)
    try:
        with transaction.atomic(using=using):
            obj.save(
                force_insert=must_create, force_update=not must_create, using=using
            )
    except IntegrityError:
        if must_create:
            raise CreateError
        raise
    except DatabaseError:
        if not must_create:
            raise UpdateError
        raise

async def asave(self, must_create=False):
    """See save()."""
    if self.session_key is None:
        return await self.acreate()
    data = await self._aget_session(no_load=must_create)
    obj = await self.acreate_model_instance(data)
    using = router.db_for_write(self.model, instance=obj)
    try:
        # This code MOST run in a transaction, so it requires
        # @sync_to_async wrapping until transaction.atomic() supports
        # async.
        @sync_to_async

    def sync_transaction():
        with transaction.atomic(using=using):
            obj.save(
                force_insert=must_create,
                force_update=not must_create,
                using=using,
            )

    await sync_transaction()
except IntegrityError:
    if must_create:
        raise CreateError
    raise
except DatabaseError:
    if not must_create:
        raise UpdateError
    raise

def delete(self, session_key=None):
    if session_key is None:
        if self.session_key is None:
            return
        session_key = self.session_key
    try:
        self.model.objects.get(session_key=session_key).delete()
    except self.model.DoesNotExist:
        pass

async def adelete(self, session_key=None):
    if session_key is None:
        if self.session_key is None:
            return
        session_key = self.session_key
    try:
        obj = await self.model.objects.aget(session_key=session_key)
        await obj.adelete()
    except self.model.DoesNotExist:
        pass

@classmethod

def clear_expired(cls):
    cls.get_model_class().objects.filter(expire_date__lt=timezone.now()).delete()

@classmethod
async def aclear_expired(cls):
    await cls.get_model_class().objects.filter(
        expire_date__lt=timezone.now()
    ).adelete()

def __init__(self, session_key=None):
    self.storage_path = self._get_storage_path()
    self.file_prefix = settings.SESSION_COOKIE_NAME
    super().__init__(session_key)

@classmethod

def _get_storage_path(cls):
    try:
        return cls._storage_path
    except AttributeError:
        storage_path = (
            getattr(settings, "SESSION_FILE_PATH", None) or tempfile.gettempdir()
        )
        # Make sure the storage path is valid.
        if not os.path.isdir(storage_path):
            raise ImproperlyConfigured(
                "The session storage path %r doesn't exist. Please set your"
                " SESSION_FILE_PATH setting to an existing directory in which"
                " Django can store session data." % storage_path
            )

        cls._storage_path = storage_path
        return storage_path

def _key_to_file(self, session_key=None):
    """
    Get the file associated with this session key.
    """
    if session_key is None:
        session_key = self._get_or_create_session_key()

    # Make sure we're not vulnerable to directory traversal. Session keys
    # should always be md5s, so they should never contain directory
    # components.
    if not set(session_key).issubset(VALID_KEY_CHARS):
        raise InvalidSessionKey("Invalid characters in session key")

    return os.path.join(self.storage_path, self.file_prefix + session_key)

def _expiry_date(self, session_data):
    """
    Return the expiry time of the file storing the session's content.
    """
    return session_data.get("_session_expiry") or (
        self._last_modification()
        + datetime.timedelta(seconds=self.get_session_cookie_age())
    )

def load(self):
    session_data = {}
    try:
        with open(self._key_to_file(), encoding="ascii") as session_file:
            file_data = session_file.read()
        # Don't fail if there is no data in the session file.
        # We may have opened the empty placeholder file.
        if file_data:
            try:
                session_data = self.decode(file_data)
            except (EOFError, SuspiciousOperation) as e:
                if isinstance(e, SuspiciousOperation):
                    logger = logging.getLogger(
                        "django.security.%s" % e.__class__.__name__
                    )
                    logger.warning(str(e))
                self.create()

            # Remove expired sessions.
            expiry_age = self.get_expiry_age(expiry=self._expiry_date(session_data))
            if expiry_age <= 0:
                session_data = {}
                self.delete()
                self.create()
    except (OSError, SuspiciousOperation):
        self._session_key = None
    return session_data

async def aload(self):
    return self.load()

def create(self):
    while True:
        self._session_key = self._get_new_session_key()
        try:
            self.save(must_create=True)
        except CreateError:
            continue
        self.modified = True
        return

async def acreate(self):
    return self.create()

def exists(self, session_key):
    return os.path.exists(self._key_to_file(session_key))

async def aexists(self, session_key):
    return self.exists(session_key)

def delete(self, session_key=None):
    if session_key is None:
        if self.session_key is None:
            return
        session_key = self.session_key
    try:
        os.unlink(self._key_to_file(session_key))
    except OSError:
        pass

async def adelete(self, session_key=None):
    return self.delete(session_key=session_key)

@classmethod

def __delitem__(self, key):
    del self._session[key]
    self.modified = True

@property

def get(self, key, default=None):
    return self._session.get(key, default)

async def aget(self, key, default=None):
    return (await self._aget_session()).get(key, default)

def pop(self, key, default=__not_given):
    self.modified = self.modified or key in self._session
    args = () if default is self.__not_given else (default,)
    return self._session.pop(key, *args)

async def apop(self, key, default=__not_given):
    self.modified = self.modified or key in (await self._aget_session())
    args = () if default is self.__not_given else (default,)
    return (await self._aget_session()).pop(key, *args)

def setdefault(self, key, value):
    if key in self._session:
        return self._session[key]
    else:
        self[key] = value
        return value

async def asetdefault(self, key, value):
    session = await self._aget_session()
    if key in session:
        return session[key]
    else:
        await self.aset(key, value)
        return value

def encode(self, session_dict):
    "Return the given session dictionary serialized and encoded as a string."
    return signing.dumps(
        session_dict,
        salt=self.key_salt,
        serializer=self.serializer,
        compress=True,
    )

def decode(self, session_data):
    try:
        return signing.loads(
            session_data, salt=self.key_salt, serializer=self.serializer
        )
    except signing.BadSignature:
        logger = logging.getLogger("django.security.SuspiciousSession")
        logger.warning("Session data corrupted")
    except Exception:
        # ValueError, unpickling exceptions. If any of these happen, just
        # return an empty dictionary (an empty session).
        pass
    return {}

def has_key(self, key):
    return key in self._session

async def ahas_key(self, key):
    return key in (await self._aget_session())

def keys(self):
    return self._session.keys()

async def akeys(self):
    return (await self._aget_session()).keys()

def values(self):
    return self._session.values()

async def avalues(self):
    return (await self._aget_session()).values()

def items(self):
    return self._session.items()

async def aitems(self):
    return (await self._aget_session()).items()

def is_empty(self):
    "Return True when there is no session_key and the session is empty."
    try:
        return not self._session_key and not self._session_cache
    except AttributeError:
        return True

def _get_new_session_key(self):
    "Return session key that isn't being used."
    while True:
        session_key = get_random_string(32, VALID_KEY_CHARS)
        if not self.exists(session_key):
            return session_key

async def _aget_new_session_key(self):
    while True:
        session_key = get_random_string(32, VALID_KEY_CHARS)
        if not await self.aexists(session_key):
            return session_key

def _get_or_create_session_key(self):
    if self._session_key is None:
        self._session_key = self._get_new_session_key()
    return self._session_key

async def _aget_or_create_session_key(self):
    if self._session_key is None:
        self._session_key = await self._aget_new_session_key()
    return self._session_key

def _set_session_key(self, value):
    """
    Validate session key on assignment. Invalid values will set to None.
    """
    if self._validate_session_key(value):
        self.__session_key = value
    else:
        self.__session_key = None

session_key = property(_get_session_key)
_session_key = property(_get_session_key, _set_session_key)

def _get_session(self, no_load=False):
    """
    Lazily load session from storage (unless "no_load" is True, when only
    an empty dict is stored) and store it in the current instance.
    """
    self.accessed = True
    try:
        return self._session_cache
    except AttributeError:
        if self.session_key is None or no_load:
            self._session_cache = {}
        else:
            self._session_cache = self.load()
    return self._session_cache

async def _aget_session(self, no_load=False):
    self.accessed = True
    try:
        return self._session_cache
    except AttributeError:
        if self.session_key is None or no_load:
            self._session_cache = {}
        else:
            self._session_cache = await self.aload()
    return self._session_cache

_session = property(_get_session)

def get_expiry_age(self, **kwargs):
    """Get the number of seconds until the session expires.

    Optionally, this function accepts `modification` and `expiry` keyword
    arguments specifying the modification and expiry of the session.
    """
    try:
        modification = kwargs["modification"]
    except KeyError:
        modification = timezone.now()
    # Make the difference between "expiry=None passed in kwargs" and
    # "expiry not passed in kwargs", in order to guarantee not to trigger
    # self.load() when expiry is provided.
    try:
        expiry = kwargs["expiry"]
    except KeyError:
        expiry = self.get("_session_expiry")

    if not expiry:  # Checks both None and 0 cases
        return self.get_session_cookie_age()
    if not isinstance(expiry, (datetime, str)):
        return expiry
    if isinstance(expiry, str):
        expiry = datetime.fromisoformat(expiry)
    delta = expiry - modification
    return delta.days * 86400 + delta.seconds

async def aget_expiry_age(self, **kwargs):
    try:
        modification = kwargs["modification"]
    except KeyError:
        modification = timezone.now()
    try:
        expiry = kwargs["expiry"]
    except KeyError:
        expiry = await self.aget("_session_expiry")

    if not expiry:  # Checks both None and 0 cases
        return self.get_session_cookie_age()
    if not isinstance(expiry, (datetime, str)):
        return expiry
    if isinstance(expiry, str):
        expiry = datetime.fromisoformat(expiry)
    delta = expiry - modification
    return delta.days * 86400 + delta.seconds

def get_expiry_date(self, **kwargs):
    """Get session the expiry date (as a datetime object).

    Optionally, this function accepts `modification` and `expiry` keyword
    arguments specifying the modification and expiry of the session.
    """
    try:
        modification = kwargs["modification"]
    except KeyError:
        modification = timezone.now()
    # Same comment as in get_expiry_age
    try:
        expiry = kwargs["expiry"]
    except KeyError:
        expiry = self.get("_session_expiry")

    if isinstance(expiry, datetime):
        return expiry
    elif isinstance(expiry, str):
        return datetime.fromisoformat(expiry)
    expiry = expiry or self.get_session_cookie_age()
    return modification + timedelta(seconds=expiry)

async def aget_expiry_date(self, **kwargs):
    try:
        modification = kwargs["modification"]
    except KeyError:
        modification = timezone.now()
    try:
        expiry = kwargs["expiry"]
    except KeyError:
        expiry = await self.aget("_session_expiry")

    if isinstance(expiry, datetime):
        return expiry
    elif isinstance(expiry, str):
        return datetime.fromisoformat(expiry)
    expiry = expiry or self.get_session_cookie_age()
    return modification + timedelta(seconds=expiry)

def exists(self, session_key):
    """
    Return True if the given session_key already exists.
    """
    raise NotImplementedError(
        "subclasses of SessionBase must provide an exists() method"
    )

async def aexists(self, session_key):
    return await sync_to_async(self.exists)(session_key)

def delete(self, session_key=None):
    """
    Delete the session data under this key. If the key is None, use the
    current session key value.
    """
    raise NotImplementedError(
        "subclasses of SessionBase must provide a delete() method"
    )

async def adelete(self, session_key=None):
    return await sync_to_async(self.delete)(session_key)

def load(self):
    """
    Load the session data and return a dictionary.
    """
    raise NotImplementedError(
        "subclasses of SessionBase must provide a load() method"
    )

async def aload(self):
    return await sync_to_async(self.load)()

@classmethod

class Command(BaseCommand):
    help = (
        "Can be run as a cronjob or directly to clean out expired sessions "
        "when the backend supports it."
    )

def handle(self, **options):
    engine = import_module(settings.SESSION_ENGINE)
    try:
        engine.SessionStore.clear_expired()
    except NotImplementedError:
        raise CommandError(
            "Session engine '%s' doesn't support clearing expired "
            "sessions." % settings.SESSION_ENGINE
        )

def __init__(self, base_widget, attrs=None):
    widgets = (base_widget, base_widget)
    super().__init__(widgets, attrs)

def decompress(self, value):
    if value:
        return (value.lower, value.upper)
    return (None, None)

class BaseRangeField(forms.MultiValueField):
    default_error_messages = {
        "invalid": _("Enter two valid values."),
        "bound_ordering": _(
            "The start of the range must not exceed the end of the range."
        ),
    }
    hidden_widget = HiddenRangeWidget

def __init__(self, **kwargs):
    if "widget" not in kwargs:
        kwargs["widget"] = RangeWidget(self.base_field.widget)
    if "fields" not in kwargs:
        kwargs["fields"] = [
            self.base_field(required=False),
            self.base_field(required=False),
        ]
    kwargs.setdefault("required", False)
    kwargs.setdefault("require_all_fields", False)
    self.range_kwargs = {}
    if default_bounds := kwargs.pop("default_bounds", None):
        self.range_kwargs = {"bounds": default_bounds}
    super().__init__(**kwargs)

def prepare_value(self, value):
    lower_base, upper_base = self.fields
    if isinstance(value, self.range_type):
        return [
            lower_base.prepare_value(value.lower),
            upper_base.prepare_value(value.upper),
        ]
    if value is None:
        return [
            lower_base.prepare_value(None),
            upper_base.prepare_value(None),
        ]
    return value

def compress(self, values):
    if not values:
        return None
    lower, upper = values
    if lower is not None and upper is not None and lower > upper:
        raise exceptions.ValidationError(
            self.error_messages["bound_ordering"],
            code="bound_ordering",
        )
    try:
        range_value = self.range_type(lower, upper, **self.range_kwargs)
    except TypeError:
        raise exceptions.ValidationError(
            self.error_messages["invalid"],
            code="invalid",
        )
    else:
        return range_value

class IntegerRangeField(BaseRangeField):
    default_error_messages = {"invalid": _("Enter two whole numbers.")}
    base_field = forms.IntegerField
    range_type = NumericRange

class DecimalRangeField(BaseRangeField):
    default_error_messages = {"invalid": _("Enter two numbers.")}
    base_field = forms.DecimalField
    range_type = NumericRange

class DateTimeRangeField(BaseRangeField):
    default_error_messages = {"invalid": _("Enter two valid date/times.")}
    base_field = forms.DateTimeField
    range_type = DateTimeTZRange

class DateRangeField(BaseRangeField):
    default_error_messages = {"invalid": _("Enter two valid dates.")}
    base_field = forms.DateField
    range_type = DateRange

class SimpleArrayField(forms.CharField):
    default_error_messages = {
        "item_invalid": _("Item %(nth)s in the array did not validate:"),
    }

def __init__(
    self, base_field, *, delimiter=",", max_length=None, min_length=None, **kwargs
):
