        return f"({lhs})[%s:]", (*params, self.start)
    else:
        return f"({lhs})[%s:%s]", (*params, self.start, self.end)

def __init__(self, start, end):
    self.start = start
    self.end = end

class HStoreField(CheckPostgresInstalledMixin, CheckFieldDefaultMixin, Field):
    empty_strings_allowed = False
    description = _("Map of strings to strings/nulls")
    default_error_messages = {
        "not_a_string": _("The value of “%(key)s” is not a string or null."),
    }
    _default_hint = ("dict", "{}")

def get_transform(self, name):
    transform = super().get_transform(name)
    if transform:
        return transform
    return KeyTransformFactory(name)

def validate(self, value, model_instance):
    super().validate(value, model_instance)
    for key, val in value.items():
        if not isinstance(val, str) and val is not None:
            raise exceptions.ValidationError(
                self.error_messages["not_a_string"],
                code="not_a_string",
                params={"key": key},
            )

def to_python(self, value):
    if isinstance(value, str):
        value = json.loads(value)
    return value

def formfield(self, **kwargs):
    return super().formfield(
        **{
            "form_class": forms.HStoreField,
            **kwargs,
        }
    )

    def get_prep_value(self, value):
        value = super().get_prep_value(value)

        if isinstance(value, dict):
            prep_value = {}
            for key, val in value.items():
                key = str(key)
                if val is not None:
                    val = str(val)
                prep_value[key] = val
            value = prep_value

        if isinstance(value, list):
            value = [str(item) for item in value]

        return value


HStoreField.register_lookup(lookups.DataContains)
HStoreField.register_lookup(lookups.ContainedBy)
HStoreField.register_lookup(lookups.HasKey)
HStoreField.register_lookup(lookups.HasKeys)
HStoreField.register_lookup(lookups.HasAnyKeys)

def __init__(self, key_name, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self.key_name = key_name

def as_sql(self, compiler, connection):
    lhs, params = compiler.compile(self.lhs)
    return "(%s -> %%s)" % lhs, (*params, self.key_name)

    def __call__(self, *args, **kwargs):
        return KeyTransform(self.key_name, *args, **kwargs)


@HStoreField.register_lookup

class KeysTransform(Transform):
    lookup_name = "keys"
    function = "akeys"
    output_field = ArrayField(TextField())


@HStoreField.register_lookup

class Command(LabelCommand):
    help = "Finds the absolute paths for the given static file(s)."
    label = "staticfile"

def handle_label(self, path, **options):
    verbosity = options["verbosity"]
    result = finders.find(path, find_all=options["all"])
    if verbosity >= 2:
        searched_locations = (
            "\nLooking in the following locations:\n  %s"
            % "\n  ".join([str(loc) for loc in finders.searched_locations])
        )
    else:
        searched_locations = ""
    if result:
        if not isinstance(result, (list, tuple)):
            result = [result]
        result = (os.path.realpath(path) for path in result)
        if verbosity >= 1:
            file_list = "\n  ".join(result)
            return "Found '%s' here:\n  %s%s" % (
                path,
                file_list,
                searched_locations,
            )
        else:
            return "\n".join(result)
    else:
        message = ["No matching file found for '%s'." % path]
        if verbosity >= 2:
            message.append(searched_locations)
        if verbosity >= 1:
            self.stderr.write("\n".join(message))

class Command(RunserverCommand):
    help = (
        "Starts a lightweight web server for development and also serves static files."
    )

def local(self):
    try:
        self.storage.path("")
    except NotImplementedError:
        return False
    return True

def collect(self):
    """
    Perform the bulk of the work of collectstatic.

    Split off from handle() to facilitate testing.
    """
    if self.symlink and not self.local:
        raise CommandError("Can't symlink to a remote destination.")

    if self.clear:
        self.clear_dir("")

    if self.symlink:
        handler = self.link_file
    else:
        handler = self.copy_file

    found_files = {}
    for finder in get_finders():
        for path, storage in finder.list(self.ignore_patterns):
            # Prefix the relative path if the source storage contains it
            if getattr(storage, "prefix", None):
                prefixed_path = os.path.join(storage.prefix, path)
            else:
                prefixed_path = path

            if prefixed_path not in found_files:
                found_files[prefixed_path] = (storage, path)
                handler(path, prefixed_path, storage)
            else:
                self.log(
                    "Found another file with the destination path '%s'. It "
                    "will be ignored since only the first encountered file "
                    "is collected. If this is not what you want, make sure "
                    "every static file has a unique path." % prefixed_path,
                    level=1,
                )

    # Storage backends may define a post_process() method.
    if self.post_process and hasattr(self.storage, "post_process"):
        processor = self.storage.post_process(found_files, dry_run=self.dry_run)
        for original_path, processed_path, processed in processor:
            if isinstance(processed, Exception):
                self.stderr.write("Post-processing '%s' failed!" % original_path)
                # Add a blank line before the traceback, otherwise it's
                # too easy to miss the relevant part of the error message.
                self.stderr.write()
                raise processed
            if processed:
                self.log(
                    "Post-processed '%s' as '%s'" % (original_path, processed_path),
                    level=2,
                )
                self.post_processed_files.append(original_path)
            else:
                self.log("Skipped post-processing '%s'" % original_path)

    return {
        "modified": self.copied_files + self.symlinked_files,
        "unmodified": self.unmodified_files,
        "post_processed": self.post_processed_files,
    }

def handle(self, **options):
    self.set_options(**options)
    message = ["\n"]
    if self.dry_run:
        message.append(
            "You have activated the --dry-run option so no files will be "
            "modified.\n\n"
        )

    message.append(
        "You have requested to collect static files at the destination\n"
        "location as specified in your settings"
    )

    if self.is_local_storage() and self.storage.location:
        destination_path = self.storage.location
        message.append(":\n\n    %s\n\n" % destination_path)
        should_warn_user = self.storage.exists(destination_path) and any(
            self.storage.listdir(destination_path)
        )
    else:
        destination_path = None
        message.append(".\n\n")
        # Destination files existence not checked; play it safe and warn.
        should_warn_user = True

    if self.interactive and should_warn_user:
        if self.clear:
            message.append("This will DELETE ALL FILES in this location!\n")
        else:
            message.append("This will overwrite existing files!\n")

        message.append(
            "Are you sure you want to do this?\n\n"
            "Type 'yes' to continue, or 'no' to cancel: "
        )
        if input("".join(message)) != "yes":
            raise CommandError("Collecting static files cancelled.")

    collected = self.collect()

    if self.verbosity >= 1:
        modified_count = len(collected["modified"])
        unmodified_count = len(collected["unmodified"])
        post_processed_count = len(collected["post_processed"])
        return (
            "\n%(modified_count)s %(identifier)s %(action)s"
            "%(destination)s%(unmodified)s%(post_processed)s."
        ) % {
            "modified_count": modified_count,
            "identifier": "static file" + ("" if modified_count == 1 else "s"),
            "action": "symlinked" if self.symlink else "copied",
            "destination": (
                " to '%s'" % destination_path if destination_path else ""
            ),
            "unmodified": (
                ", %s unmodified" % unmodified_count
                if collected["unmodified"]
                else ""
            ),
            "post_processed": (
                collected["post_processed"]
                and ", %s post-processed" % post_processed_count
                or ""
            ),
        }

def log(self, msg, level=2):
    """
    Small log helper
    """
    if self.verbosity >= level:
        self.stdout.write(msg)

def clear_dir(self, path):
    """
    Delete the given relative path using the destination storage backend.
    """
    if not self.storage.exists(path):
        return

    dirs, files = self.storage.listdir(path)
    for f in files:
        fpath = os.path.join(path, f)
        if self.dry_run:
            self.log("Pretending to delete '%s'" % fpath, level=1)
        else:
            self.log("Deleting '%s'" % fpath, level=1)
            try:
                full_path = self.storage.path(fpath)
            except NotImplementedError:
                self.storage.delete(fpath)
            else:
                if not os.path.exists(full_path) and os.path.lexists(full_path):
                    # Delete broken symlinks
                    os.unlink(full_path)
                else:
                    self.storage.delete(fpath)
    for d in dirs:
        self.clear_dir(os.path.join(path, d))

def delete_file(self, path, prefixed_path, source_storage):
    """
    Check if the target file should be deleted if it already exists.
    """
    if self.storage.exists(prefixed_path):
        try:
            # When was the target file modified last time?
            target_last_modified = self.storage.get_modified_time(prefixed_path)
        except (OSError, NotImplementedError):
            # The storage doesn't support get_modified_time() or failed
            pass
        else:
            try:
                # When was the source file modified last time?
                source_last_modified = source_storage.get_modified_time(path)
            except (OSError, NotImplementedError):
                pass
            else:
                # The full path of the target file
                if self.local:
                    full_path = self.storage.path(prefixed_path)
                    # If it's --link mode and the path isn't a link (i.e.
                    # the previous collectstatic wasn't with --link) or if
                    # it's non-link mode and the path is a link (i.e. the
                    # previous collectstatic was with --link), the old
                    # links/files must be deleted so it's not safe to skip
                    # unmodified files.
                    can_skip_unmodified_files = not (
                        self.symlink ^ os.path.islink(full_path)
                    )
                else:
                    # In remote storages, skipping is only based on the
                    # modified times since symlinks aren't relevant.
                    can_skip_unmodified_files = True
                # Avoid sub-second precision (see #14665, #19540)
                file_is_unmodified = target_last_modified.replace(
                    microsecond=0
                ) >= source_last_modified.replace(microsecond=0)
                if file_is_unmodified and can_skip_unmodified_files:
                    if prefixed_path not in self.unmodified_files:
                        self.unmodified_files.append(prefixed_path)
                    self.log("Skipping '%s' (not modified)" % path)
                    return False
        # Then delete the existing file if really needed
        if self.dry_run:
            self.log("Pretending to delete '%s'" % path)
        else:
            self.log("Deleting '%s'" % path)
            self.storage.delete(prefixed_path)
    return True

def link_file(self, path, prefixed_path, source_storage):
    """
    Attempt to link ``path``
    """
    # Skip this file if it was already copied earlier
    if prefixed_path in self.symlinked_files:
        return self.log("Skipping '%s' (already linked earlier)" % path)
    # Delete the target file if needed or break
    if not self.delete_file(path, prefixed_path, source_storage):
        return
    # The full path of the source file
    source_path = source_storage.path(path)
    # Finally link the file
    if self.dry_run:
        self.log("Pretending to link '%s'" % source_path, level=1)
    else:
        self.log("Linking '%s'" % source_path, level=2)
        full_path = self.storage.path(prefixed_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        try:
            if os.path.lexists(full_path):
                os.unlink(full_path)
            os.symlink(source_path, full_path)
        except NotImplementedError:
            import platform

            raise CommandError(
                "Symlinking is not supported in this "
                "platform (%s)." % platform.platform()
            )
        except OSError as e:
            raise CommandError(e)
    if prefixed_path not in self.symlinked_files:
        self.symlinked_files.append(prefixed_path)

def copy_file(self, path, prefixed_path, source_storage):
    """
    Attempt to copy ``path`` with storage
    """
    # Skip this file if it was already copied earlier
    if prefixed_path in self.copied_files:
        return self.log("Skipping '%s' (already copied earlier)" % path)
    # Delete the target file if needed or break
    if not self.delete_file(path, prefixed_path, source_storage):
        return
    # The full path of the source file
    source_path = source_storage.path(path)
    # Finally start copying
    if self.dry_run:
        self.log("Pretending to copy '%s'" % source_path, level=1)
    else:
        self.log("Copying '%s'" % source_path, level=2)
        with source_storage.open(path) as source_file:
            self.storage.save(prefixed_path, source_file)
    self.copied_files.append(prefixed_path)

def get(self, request, *args, **kwargs):
    """
    Return a JsonResponse with search results as defined in
    serialize_result(), by default:
    {
        results: [{id: "123" text: "foo"}],
        pagination: {more: true}
    }
    """
    (
        self.term,
        self.model_admin,
        self.source_field,
        to_field_name,
    ) = self.process_request(request)

    if not self.has_perm(request):
        raise PermissionDenied

    self.object_list = self.get_queryset()
    context = self.get_context_data()
    return JsonResponse(
        {
            "results": [
                self.serialize_result(obj, to_field_name)
                for obj in context["object_list"]
            ],
            "pagination": {"more": context["page_obj"].has_next()},
        }
    )

def serialize_result(self, obj, to_field_name):
    """
    Convert the provided model object to a dictionary that is added to the
    results list.
    """
    return {"id": str(getattr(obj, to_field_name)), "text": str(obj)}

def get_paginator(self, *args, **kwargs):
    """Use the ModelAdmin's paginator."""
    return self.model_admin.get_paginator(self.request, *args, **kwargs)

def get_queryset(self):
    """Return queryset based on ModelAdmin.get_search_results()."""
    qs = self.model_admin.get_queryset(self.request)
    qs = qs.complex_filter(self.source_field.get_limit_choices_to())
    qs, search_use_distinct = self.model_admin.get_search_results(
        self.request, qs, self.term
    )
    if search_use_distinct:
        qs = qs.distinct()
    return qs

def process_request(self, request):
    """
    Validate request integrity, extract and return request parameters.

    Since the subsequent view permission check requires the target model
    admin, which is determined here, raise PermissionDenied if the
    requested app, model or field are malformed.

    Raise Http404 if the target model admin is not configured properly with
    search_fields.
    """
    term = request.GET.get("term", "")
    try:
        app_label = request.GET["app_label"]
        model_name = request.GET["model_name"]
        field_name = request.GET["field_name"]
    except KeyError as e:
        raise PermissionDenied from e

    # Retrieve objects from parameters.
    try:
        source_model = apps.get_model(app_label, model_name)
    except LookupError as e:
        raise PermissionDenied from e

    try:
        source_field = source_model._meta.get_field(field_name)
    except FieldDoesNotExist as e:
        raise PermissionDenied from e
    try:
        remote_model = source_field.remote_field.model
    except AttributeError as e:
        raise PermissionDenied from e
    try:
        model_admin = self.admin_site.get_model_admin(remote_model)
    except NotRegistered as e:
        raise PermissionDenied from e

    # Validate suitability of objects.
    if not model_admin.get_search_fields(request):
        raise Http404(
            "%s must have search_fields for the autocomplete_view."
            % type(model_admin).__qualname__
        )

    to_field_name = getattr(
        source_field.remote_field, "field_name", remote_model._meta.pk.attname
    )
    to_field_name = remote_model._meta.get_field(to_field_name).attname
    if not model_admin.to_field_allowed(request, to_field_name):
        raise PermissionDenied

    return term, model_admin, source_field, to_field_name

def has_perm(self, request, obj=None):
    """Check if user has permission to access the related model."""
    return self.model_admin.has_view_permission(request, obj=obj)

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    # Populate "fields" dynamically because SEARCH_VAR is a variable:
    self.fields = {
        SEARCH_VAR: forms.CharField(required=False, strip=False),
    }

def __repr__(self):
    return "<%s: model=%s model_admin=%s>" % (
        self.__class__.__qualname__,
        self.model.__qualname__,
        self.model_admin.__class__.__qualname__,
    )

def get_filters(self, request):
    lookup_params = self.get_filters_params()
    may_have_duplicates = False
    has_active_filters = False

    for key, value_list in lookup_params.items():
        for value in value_list:
            if not self.model_admin.lookup_allowed(key, value, request):
                raise DisallowedModelAdminLookup(f"Filtering by {key} not allowed")

    filter_specs = []
    for list_filter in self.list_filter:
        lookup_params_count = len(lookup_params)
        if callable(list_filter):
            # This is simply a custom list filter class.
            spec = list_filter(request, lookup_params, self.model, self.model_admin)
        else:
            field_path = None
            if isinstance(list_filter, (tuple, list)):
                # This is a custom FieldListFilter class for a given field.
                field, field_list_filter_class = list_filter
            else:
                # This is simply a field name, so use the default
                # FieldListFilter class that has been registered for the
                # type of the given field.
                field, field_list_filter_class = list_filter, FieldListFilter.create
            if not isinstance(field, Field):
                field_path = field
                field = get_fields_from_path(self.model, field_path)[-1]

            spec = field_list_filter_class(
                field,
                request,
                lookup_params,
                self.model,
                self.model_admin,
                field_path=field_path,
            )
            # field_list_filter_class removes any lookup_params it
            # processes. If that happened, check if duplicates should be
            # removed.
            if lookup_params_count > len(lookup_params):
                may_have_duplicates |= lookup_spawns_duplicates(
                    self.lookup_opts,
                    field_path,
                )
        if spec and spec.has_output():
            filter_specs.append(spec)
            if lookup_params_count > len(lookup_params):
                has_active_filters = True

    if self.date_hierarchy:
        # Create bounded lookup parameters so that the query is more
        # efficient.
        year = lookup_params.pop("%s__year" % self.date_hierarchy, None)
        if year is not None:
            month = lookup_params.pop("%s__month" % self.date_hierarchy, None)
            day = lookup_params.pop("%s__day" % self.date_hierarchy, None)
            try:
                from_date = datetime(
                    int(year[-1]),
                    int(month[-1] if month is not None else 1),
                    int(day[-1] if day is not None else 1),
                )
            except ValueError as e:
                raise IncorrectLookupParameters(e) from e
            if day:
                to_date = from_date + timedelta(days=1)
            elif month:
                # In this branch, from_date will always be the first of a
                # month, so advancing 32 days gives the next month.
                to_date = (from_date + timedelta(days=32)).replace(day=1)
            else:
                to_date = from_date.replace(year=from_date.year + 1)
            if settings.USE_TZ:
                from_date = make_aware(from_date)
                to_date = make_aware(to_date)
            lookup_params.update(
                {
                    "%s__gte" % self.date_hierarchy: [from_date],
                    "%s__lt" % self.date_hierarchy: [to_date],
                }
            )

    # At this point, all the parameters used by the various ListFilters
    # have been removed from lookup_params, which now only contains other
    # parameters passed via the query string. We now loop through the
    # remaining parameters both to ensure that all the parameters are valid
    # fields and to determine if at least one of them spawns duplicates. If
    # the lookup parameters aren't real fields, then bail out.
    try:
        for key, value in lookup_params.items():
            lookup_params[key] = prepare_lookup_value(key, value)
            may_have_duplicates |= lookup_spawns_duplicates(self.lookup_opts, key)
        return (
            filter_specs,
            bool(filter_specs),
            lookup_params,
            may_have_duplicates,
            has_active_filters,
        )
    except FieldDoesNotExist as e:
        raise IncorrectLookupParameters(e) from e

def get_query_string(self, new_params=None, remove=None):
    if new_params is None:
        new_params = {}
    if remove is None:
        remove = []
    p = self.filter_params.copy()
    for r in remove:
        for k in list(p):
            if k.startswith(r):
                del p[k]
    for k, v in new_params.items():
        if v is None:
            if k in p:
                del p[k]
        else:
            p[k] = v
    return "?%s" % urlencode(sorted(p.items()), doseq=True)

def _get_default_ordering(self):
    ordering = []
    if self.model_admin.ordering:
        ordering = self.model_admin.ordering
    elif self.lookup_opts.ordering:
        ordering = self.lookup_opts.ordering
    return ordering

def get_ordering_field(self, field_name):
    """
    Return the proper model field name corresponding to the given
    field_name to use for ordering. field_name may either be the name of a
    proper model field, possibly across relations, or the name of a method
    (on the admin or model) or a callable with the 'admin_order_field'
    attribute. Return None if no proper model field name can be matched.
    """
    try:
        field = self.lookup_opts.get_field(field_name)
        return field.name
    except FieldDoesNotExist:
        # See whether field_name is a name of a non-field
        # that allows sorting.
        if callable(field_name):
            attr = field_name
        elif hasattr(self.model_admin, field_name):
            attr = getattr(self.model_admin, field_name)
        else:
            try:
                attr = getattr(self.model, field_name)
            except AttributeError:
                if LOOKUP_SEP in field_name:
                    return field_name
                raise
        if isinstance(attr, property) and hasattr(attr, "fget"):
            attr = attr.fget
        return getattr(attr, "admin_order_field", None)

def get_ordering(self, request, queryset):
    """
    Return the list of ordering fields for the change list.
    First check the get_ordering() method in model admin, then check
    the object's default ordering. Then, any manually-specified ordering
    from the query string overrides anything. Finally, a deterministic
    order is guaranteed by calling _get_deterministic_ordering() with the
    constructed ordering.
    """
    params = self.params
    ordering = list(
        self.model_admin.get_ordering(request) or self._get_default_ordering()
    )
    if params.get(ORDER_VAR):
        # Clear ordering and used params
        ordering = []
        order_params = params[ORDER_VAR].split(".")
        for p in order_params:
            try:
                none, pfx, idx = p.rpartition("-")
                field_name = self.list_display[int(idx)]
                order_field = self.get_ordering_field(field_name)
                if not order_field:
                    continue  # No 'admin_order_field', skip it
                if isinstance(order_field, OrderBy):
                    if pfx == "-":
                        order_field = order_field.copy()
                        order_field.reverse_ordering()
                    ordering.append(order_field)
                elif hasattr(order_field, "resolve_expression"):
                    # order_field is an expression.
                    ordering.append(
                        order_field.desc() if pfx == "-" else order_field.asc()
                    )
                # reverse order if order_field has already "-" as prefix
                elif pfx == "-" and order_field.startswith(pfx):
                    ordering.append(order_field.removeprefix(pfx))
                else:
                    ordering.append(pfx + order_field)
            except (IndexError, ValueError):
                continue  # Invalid ordering specified, skip it.

    # Add the given query's ordering fields, if any.
    ordering.extend(queryset.query.order_by)

    return self._get_deterministic_ordering(ordering)

def _get_deterministic_ordering(self, ordering):
    """
    Ensure a deterministic order across all database backends. Search for a
    single field or unique together set of fields providing a total
    ordering. If these are missing, augment the ordering with a descendant
    primary key.
    """
    ordering = list(ordering)
    ordering_fields = set()
    total_ordering_fields = {"pk"} | {
        field.attname
        for field in self.lookup_opts.fields
        if field.unique and not field.null
    }
    for part in ordering:
        # Search for single field providing a total ordering.
        field_name = None
        if isinstance(part, str):
            field_name = part.lstrip("-")
        elif isinstance(part, F):
            field_name = part.name
        elif isinstance(part, OrderBy) and isinstance(part.expression, F):
            field_name = part.expression.name
        if field_name:
            # Normalize attname references by using get_field().
            try:
                field = self.lookup_opts.get_field(field_name)
            except FieldDoesNotExist:
                # Could be "?" for random ordering or a related field
                # lookup. Skip this part of introspection for now.
                continue
            # Ordering by a related field name orders by the referenced
            # model's ordering. Skip this part of introspection for now.
            if field.remote_field and field_name == field.name:
                continue
            if field.attname in total_ordering_fields:
                break
            ordering_fields.add(field.attname)
    else:
        # No single total ordering field, try unique_together and total
        # unique constraints.
        constraint_field_names = (
            *self.lookup_opts.unique_together,
            *(
                constraint.fields
                for constraint in self.lookup_opts.total_unique_constraints
            ),
        )
        for field_names in constraint_field_names:
            # Normalize attname references by using get_field().
            fields = [
                self.lookup_opts.get_field(field_name) for field_name in field_names
            ]
            # Composite unique constraints containing a nullable column
            # cannot ensure total ordering.
            if any(field.null for field in fields):
                continue
            if ordering_fields.issuperset(field.attname for field in fields):
                break
        else:
            # If no set of unique fields is present in the ordering, rely
            # on the primary key to provide total ordering.
            ordering.append("-pk")
    return ordering

def get_ordering_field_columns(self):
    """
    Return a dictionary of ordering field column numbers and asc/desc.
    """
    # We must cope with more than one column having the same underlying sort
    # field, so we base things on column numbers.
    ordering = self._get_default_ordering()
    ordering_fields = {}
    if ORDER_VAR not in self.params:
        # for ordering specified on ModelAdmin or model Meta, we don't know
        # the right column numbers absolutely, because there might be more
        # than one column associated with that ordering, so we guess.
        for field in ordering:
            if isinstance(field, (Combinable, OrderBy)):
                if not isinstance(field, OrderBy):
                    field = field.asc()
                if isinstance(field.expression, F):
                    order_type = "desc" if field.descending else "asc"
                    field = field.expression.name
                else:
                    continue
            elif field.startswith("-"):
                field = field.removeprefix("-")
                order_type = "desc"
            else:
                order_type = "asc"
            for index, attr in enumerate(self.list_display):
                if self.get_ordering_field(attr) == field:
                    ordering_fields[index] = order_type
                    break
    else:
        for p in self.params[ORDER_VAR].split("."):
            none, pfx, idx = p.rpartition("-")
            try:
                idx = int(idx)
            except ValueError:
                continue  # skip it
            ordering_fields[idx] = "desc" if pfx == "-" else "asc"
    return ordering_fields

def apply_select_related(self, qs):
    if self.list_select_related is True:
        return qs.select_related()

    if self.list_select_related is False:
        if self.has_related_field_in_list_display():
            return qs.select_related()

    if self.list_select_related:
        return qs.select_related(*self.list_select_related)
    return qs

def has_related_field_in_list_display(self):
    for field_name in self.list_display:
        try:
            field = self.lookup_opts.get_field(field_name)
        except FieldDoesNotExist:
            pass
        else:
            if isinstance(field.remote_field, ManyToOneRel):
                # <FK>_id field names don't require a join.
                if field_name != field.attname:
                    return True
    return False

def url_for_result(self, result):
    pk = getattr(result, self.pk_attname)
    return reverse(
        "admin:%s_%s_change" % (self.opts.app_label, self.opts.model_name),
        args=(quote(pk),),
        current_app=self.model_admin.admin_site.name,
    )

def staff_member_required(
    view_func=None, redirect_field_name=REDIRECT_FIELD_NAME, login_url="admin:login"
):
    """
    Decorator for views that checks that the user is logged in and is a staff
    member, redirecting to the login page if necessary.
    """
    actual_decorator = user_passes_test(
        lambda u: u.is_active and u.is_staff,
        login_url=login_url,
        redirect_field_name=redirect_field_name,
    )
    if view_func:
        return actual_decorator(view_func)
    return actual_decorator

