/*global SelectBox, interpolate*/
// Handles related-objects functionality: lookup link for raw_id_fields
// and Add Another links.
'use strict';
{
    const $ = django.jQuery;
    let popupIndex = 0;
    const relatedWindows = [];

    function dismissChildPopups() {
        relatedWindows.forEach(function(win) {
            if(!win.closed) {
                win.dismissChildPopups();
                win.close();    
            }
        });
    }

    function setPopupIndex() {
        if(document.getElementsByName("_popup").length > 0) {
            const index = window.name.lastIndexOf("__") + 2;
            popupIndex = parseInt(window.name.substring(index));   
        } else {
            popupIndex = 0;
        }
    }

    function addPopupIndex(name) {
        return name + "__" + (popupIndex + 1);
    }

    function removePopupIndex(name) {
        return name.replace(new RegExp("__" + (popupIndex + 1) + "$"), '');
    }

    function showAdminPopup(triggeringLink, name_regexp, add_popup) {
        const name = addPopupIndex(triggeringLink.id.replace(name_regexp, ''));
        const href = new URL(triggeringLink.href);
        if (add_popup) {
            href.searchParams.set('_popup', 1);
        }
        const win = window.open(href, name, 'height=500,width=800,resizable=yes,scrollbars=yes');
        relatedWindows.push(win);
        win.focus();
        return false;
    }

    function showRelatedObjectLookupPopup(triggeringLink) {
        return showAdminPopup(triggeringLink, /^lookup_/, true);
    }

    function dismissRelatedLookupPopup(win, chosenId) {
        const name = removePopupIndex(win.name);
        const elem = document.getElementById(name);
        if (elem.classList.contains('vManyToManyRawIdAdminField') && elem.value) {
            elem.value += ',' + chosenId;
        } else {
            elem.value = chosenId;
        }
        $(elem).trigger('change');
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function showRelatedObjectPopup(triggeringLink) {
        return showAdminPopup(triggeringLink, /^(change|add|delete)_/, false);
    }

    function updateRelatedObjectLinks(triggeringLink) {
        const $this = $(triggeringLink);
        const siblings = $this.nextAll('.view-related, .change-related, .delete-related');
        if (!siblings.length) {
            return;
        }
        const value = $this.val();
        if (value) {
            siblings.each(function() {
                const elm = $(this);
                elm.attr('href', elm.attr('data-href-template').replace('__fk__', value));
                elm.removeAttr('aria-disabled');
            });
        } else {
            siblings.removeAttr('href');
            siblings.attr('aria-disabled', true);
        }
    }

    function updateRelatedSelectsOptions(currentSelect, win, objId, newRepr, newId, skipIds = []) {
        // After create/edit a model from the options next to the current
        // select (+ or :pencil:) update ForeignKey PK of the rest of selects
        // in the page.

        const path = win.location.pathname;
        // Extract the model from the popup url '.../<model>/add/' or
        // '.../<model>/<id>/change/' depending the action (add or change).
        const modelName = path.split('/')[path.split('/').length - (objId ? 4 : 3)];
        // Select elements with a specific model reference and context of "available-source".
        const selectsRelated = document.querySelectorAll(`[data-model-ref="${modelName}"] [data-context="available-source"]`);

        selectsRelated.forEach(function(select) {
            if (currentSelect === select || skipIds && skipIds.includes(select.id)) {
                return;
            }

            let option = select.querySelector(`option[value="${objId}"]`);

            if (!option) {
                option = new Option(newRepr, newId);
                select.options.add(option);
                // Update SelectBox cache for related fields.
                if (window.SelectBox !== undefined && !SelectBox.cache[currentSelect.id]) {
                    SelectBox.add_to_cache(select.id, option);
                    SelectBox.redisplay(select.id);
                }
                return;
            }

            option.textContent = newRepr;
            option.value = newId;
        });
    }

    function dismissAddRelatedObjectPopup(win, newId, newRepr) {
        const name = removePopupIndex(win.name);
        const elem = document.getElementById(name);
        if (elem) {
            const elemName = elem.nodeName.toUpperCase();
            if (elemName === 'SELECT') {
                elem.options[elem.options.length] = new Option(newRepr, newId, true, true);
                updateRelatedSelectsOptions(elem, win, null, newRepr, newId);
            } else if (elemName === 'INPUT') {
                if (elem.classList.contains('vManyToManyRawIdAdminField') && elem.value) {
                    elem.value += ',' + newId;
                } else {
                    elem.value = newId;
                }
            }
            // Trigger a change event to update related links if required.
            $(elem).trigger('change');
        } else {
            const toId = name + "_to";
            const toElem = document.getElementById(toId);
            const o = new Option(newRepr, newId);
            SelectBox.add_to_cache(toId, o);
            SelectBox.redisplay(toId);
            if (toElem && toElem.nodeName.toUpperCase() === 'SELECT') {
                const skipIds = [name + "_from"];
                updateRelatedSelectsOptions(toElem, win, null, newRepr, newId, skipIds);
            }
        }
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function dismissChangeRelatedObjectPopup(win, objId, newRepr, newId) {
        const id = removePopupIndex(win.name.replace(/^edit_/, ''));
        const selectsSelector = interpolate('#%s, #%s_from, #%s_to', [id, id, id]);
        const selects = $(selectsSelector);
        selects.find('option').each(function() {
            if (this.value === objId) {
                this.textContent = newRepr;
                this.value = newId;
            }
        }).trigger('change');
        updateRelatedSelectsOptions(selects[0], win, objId, newRepr, newId);
        selects.next().find('.select2-selection__rendered').each(function() {
            // The element can have a clear button as a child.
            // Use the lastChild to modify only the displayed value.
            this.lastChild.textContent = newRepr;
            this.title = newRepr;
        });
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function dismissDeleteRelatedObjectPopup(win, objId) {
        const id = removePopupIndex(win.name.replace(/^delete_/, ''));
        const selectsSelector = interpolate('#%s, #%s_from, #%s_to', [id, id, id]);
        const selects = $(selectsSelector);
        selects.find('option').each(function() {
            if (this.value === objId) {
                $(this).remove();
            }
        }).trigger('change');
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    window.showRelatedObjectLookupPopup = showRelatedObjectLookupPopup;
    window.dismissRelatedLookupPopup = dismissRelatedLookupPopup;
    window.showRelatedObjectPopup = showRelatedObjectPopup;
    window.updateRelatedObjectLinks = updateRelatedObjectLinks;
    window.dismissAddRelatedObjectPopup = dismissAddRelatedObjectPopup;
    window.dismissChangeRelatedObjectPopup = dismissChangeRelatedObjectPopup;
    window.dismissDeleteRelatedObjectPopup = dismissDeleteRelatedObjectPopup;
    window.dismissChildPopups = dismissChildPopups;
    window.relatedWindows = relatedWindows;

    // Kept for backward compatibility
    window.showAddAnotherPopup = showRelatedObjectPopup;
    window.dismissAddAnotherPopup = dismissAddRelatedObjectPopup;

    window.addEventListener('unload', function(evt) {
        window.dismissChildPopups();
    });

    $(document).ready(function() {
        setPopupIndex();
        $("a[data-popup-opener]").on('click', function(event) {
            event.preventDefault();
            opener.dismissRelatedLookupPopup(window, $(this).data("popup-opener"));
        });
        $('body').on('click', '.related-widget-wrapper-link[data-popup="yes"]', function(e) {
            e.preventDefault();
            if (this.href) {
                const event = $.Event('django:show-related', {href: this.href});
                $(this).trigger(event);
                if (!event.isDefaultPrevented()) {
                    showRelatedObjectPopup(this);
                }
            }
        });
        $('body').on('change', '.related-widget-wrapper select', function(e) {
            const event = $.Event('django:update-related');
            $(this).trigger(event);
            if (!event.isDefaultPrevented()) {
                updateRelatedObjectLinks(this);
            }
        });
        $('.related-widget-wrapper select').trigger('change');
        $('body').on('click', '.related-lookup', function(e) {
            e.preventDefault();
            const event = $.Event('django:lookup-related');
            $(this).trigger(event);
            if (!event.isDefaultPrevented()) {
                showRelatedObjectLookupPopup(this);
            }
        });
    });
}

/*global Calendar, findPosX, findPosY, get_format, gettext, gettext_noop, interpolate, ngettext, quickElement*/
// Inserts shortcut buttons after all of the following:
//     <input type="text" class="vDateField">
//     <input type="text" class="vTimeField">
'use strict';
{
    const DateTimeShortcuts = {
        calendars: [],
        calendarInputs: [],
        clockInputs: [],
        clockHours: {
            default_: [
                [gettext_noop('Now'), -1],
                [gettext_noop('Midnight'), 0],
                [gettext_noop('6 a.m.'), 6],
                [gettext_noop('Noon'), 12],
                [gettext_noop('6 p.m.'), 18]
            ]
        },
        dismissClockFunc: [],
        dismissCalendarFunc: [],
        calendarDivName1: 'calendarbox', // name of calendar <div> that gets toggled
        calendarDivName2: 'calendarin', // name of <div> that contains calendar
        calendarLinkName: 'calendarlink', // name of the link that is used to toggle
        clockDivName: 'clockbox', // name of clock <div> that gets toggled
        clockLinkName: 'clocklink', // name of the link that is used to toggle
        shortCutsClass: 'datetimeshortcuts', // class of the clock and cal shortcuts
        timezoneWarningClass: 'timezonewarning', // class of the warning for timezone mismatch
        timezoneOffset: 0,
        init: function() {
            const serverOffset = document.body.dataset.adminUtcOffset;
            if (serverOffset) {
                const localOffset = new Date().getTimezoneOffset() * -60;
                DateTimeShortcuts.timezoneOffset = localOffset - serverOffset;
            }

            for (const inp of document.getElementsByTagName('input')) {
                if (inp.type === 'text' && inp.classList.contains('vTimeField')) {
                    DateTimeShortcuts.addClock(inp);
                    DateTimeShortcuts.addTimezoneWarning(inp);
                }
                else if (inp.type === 'text' && inp.classList.contains('vDateField')) {
                    DateTimeShortcuts.addCalendar(inp);
                    DateTimeShortcuts.addTimezoneWarning(inp);
                }
            }
        },
        // Return the current time while accounting for the server timezone.
        now: function() {
            const serverOffset = document.body.dataset.adminUtcOffset;
            if (serverOffset) {
                const localNow = new Date();
                const localOffset = localNow.getTimezoneOffset() * -60;
                localNow.setTime(localNow.getTime() + 1000 * (serverOffset - localOffset));
                return localNow;
            } else {
                return new Date();
            }
        },
        // Add a warning when the time zone in the browser and backend do not match.
        addTimezoneWarning: function(inp) {
            const warningClass = DateTimeShortcuts.timezoneWarningClass;
            let timezoneOffset = DateTimeShortcuts.timezoneOffset / 3600;

            // Only warn if there is a time zone mismatch.
            if (!timezoneOffset) {
                return;
            }

            // Check if warning is already there.
            if (inp.parentNode.querySelectorAll('.' + warningClass).length) {
                return;
            }

            let message;
            if (timezoneOffset > 0) {
                message = ngettext(
                    'Note: You are %s hour ahead of server time.',
                    'Note: You are %s hours ahead of server time.',
                    timezoneOffset
                );
            }
            else {
                timezoneOffset *= -1;
                message = ngettext(
                    'Note: You are %s hour behind server time.',
                    'Note: You are %s hours behind server time.',
                    timezoneOffset
                );
            }
            message = interpolate(message, [timezoneOffset]);

            const warning = document.createElement('div');
            warning.classList.add('help', warningClass);
            warning.textContent = message;
            inp.parentNode.appendChild(warning);
        },
        // Add clock widget to a given field
        addClock: function(inp) {
            const num = DateTimeShortcuts.clockInputs.length;
            DateTimeShortcuts.clockInputs[num] = inp;
            DateTimeShortcuts.dismissClockFunc[num] = function() { DateTimeShortcuts.dismissClock(num); return true; };

            // Shortcut links (clock icon and "Now" link)
            const shortcuts_span = document.createElement('span');
            shortcuts_span.className = DateTimeShortcuts.shortCutsClass;
            inp.parentNode.insertBefore(shortcuts_span, inp.nextSibling);
            const now_link = document.createElement('a');
            now_link.href = "#";
            now_link.textContent = gettext('Now');
            now_link.role = 'button';
            now_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.handleClockQuicklink(num, -1);
            });
            const clock_link = document.createElement('a');
            clock_link.href = '#';
            clock_link.id = DateTimeShortcuts.clockLinkName + num;
            clock_link.addEventListener('click', function(e) {
                e.preventDefault();
                // avoid triggering the document click handler to dismiss the clock
                e.stopPropagation();
                DateTimeShortcuts.openClock(num);
            });

            quickElement(
                'span', clock_link, '',
                'class', 'clock-icon',
                'title', gettext('Choose a Time')
            );
            shortcuts_span.appendChild(document.createTextNode('\u00A0'));
            shortcuts_span.appendChild(now_link);
            shortcuts_span.appendChild(document.createTextNode('\u00A0|\u00A0'));
            shortcuts_span.appendChild(clock_link);

            // Create clock link div
            //
            // Markup looks like:
            // <div id="clockbox1" class="clockbox module">
            //     <h2>Choose a time</h2>
            //     <ul class="timelist">
            //         <li><a href="#">Now</a></li>
            //         <li><a href="#">Midnight</a></li>
            //         <li><a href="#">6 a.m.</a></li>
            //         <li><a href="#">Noon</a></li>
            //         <li><a href="#">6 p.m.</a></li>
            //     </ul>
            //     <p class="calendar-cancel"><a href="#">Cancel</a></p>
            // </div>

            const clock_box = document.createElement('div');
            clock_box.style.display = 'none';
            clock_box.style.position = 'absolute';
            clock_box.className = 'clockbox module';
            clock_box.id = DateTimeShortcuts.clockDivName + num;
            document.body.appendChild(clock_box);
            clock_box.addEventListener('click', function(e) { e.stopPropagation(); });

            quickElement('h2', clock_box, gettext('Choose a time'));
            const time_list = quickElement('ul', clock_box);
            time_list.className = 'timelist';
            // The list of choices can be overridden in JavaScript like this:
            // DateTimeShortcuts.clockHours.name = [['3 a.m.', 3]];
            // where name is the name attribute of the <input>.
            const name = typeof DateTimeShortcuts.clockHours[inp.name] === 'undefined' ? 'default_' : inp.name;
            DateTimeShortcuts.clockHours[name].forEach(function(element) {
                const time_link = quickElement('a', quickElement('li', time_list), gettext(element[0]), 'role', 'button', 'href', '#');
                time_link.addEventListener('click', function(e) {
                    e.preventDefault();
                    DateTimeShortcuts.handleClockQuicklink(num, element[1]);
                });
            });

            const cancel_p = quickElement('p', clock_box);
            cancel_p.className = 'calendar-cancel';
            const cancel_link = quickElement('a', cancel_p, gettext('Cancel'), 'role', 'button', 'href', '#');
            cancel_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.dismissClock(num);
            });

            document.addEventListener('keyup', function(event) {
                if (event.which === 27) {
                    // ESC key closes popup
                    DateTimeShortcuts.dismissClock(num);
                    event.preventDefault();
                }
            });
        },
        openClock: function(num) {
            const clock_box = document.getElementById(DateTimeShortcuts.clockDivName + num);
            const clock_link = document.getElementById(DateTimeShortcuts.clockLinkName + num);

            // Recalculate the clockbox position
            // is it left-to-right or right-to-left layout ?
            if (window.getComputedStyle(document.body).direction !== 'rtl') {
                clock_box.style.left = findPosX(clock_link) + 17 + 'px';
            }
            else {
                // since style's width is in em, it'd be tough to calculate
                // px value of it. let's use an estimated px for now
                clock_box.style.left = findPosX(clock_link) - 110 + 'px';
            }
            clock_box.style.top = Math.max(0, findPosY(clock_link) - 30) + 'px';

            // Show the clock box
            clock_box.style.display = 'block';
            document.addEventListener('click', DateTimeShortcuts.dismissClockFunc[num]);
        },
        dismissClock: function(num) {
            document.getElementById(DateTimeShortcuts.clockDivName + num).style.display = 'none';
            document.removeEventListener('click', DateTimeShortcuts.dismissClockFunc[num]);
        },
        handleClockQuicklink: function(num, val) {
            let d;
            if (val === -1) {
                d = DateTimeShortcuts.now();
            }
            else {
                d = new Date(1970, 1, 1, val, 0, 0, 0);
            }
            DateTimeShortcuts.clockInputs[num].value = d.strftime(get_format('TIME_INPUT_FORMATS')[0]);
            DateTimeShortcuts.clockInputs[num].focus();
            DateTimeShortcuts.dismissClock(num);
        },
        // Add calendar widget to a given field.
        addCalendar: function(inp) {
            const num = DateTimeShortcuts.calendars.length;

            DateTimeShortcuts.calendarInputs[num] = inp;
            DateTimeShortcuts.dismissCalendarFunc[num] = function() { DateTimeShortcuts.dismissCalendar(num); return true; };

            // Shortcut links (calendar icon and "Today" link)
            const shortcuts_span = document.createElement('span');
            shortcuts_span.className = DateTimeShortcuts.shortCutsClass;
            inp.parentNode.insertBefore(shortcuts_span, inp.nextSibling);
            const today_link = document.createElement('a');
            today_link.href = '#';
            today_link.role = 'button';
            today_link.appendChild(document.createTextNode(gettext('Today')));
            today_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, 0);
            });
            const cal_link = document.createElement('a');
            cal_link.href = '#';
            cal_link.id = DateTimeShortcuts.calendarLinkName + num;
            cal_link.addEventListener('click', function(e) {
                e.preventDefault();
                // avoid triggering the document click handler to dismiss the calendar
                e.stopPropagation();
                DateTimeShortcuts.openCalendar(num);
            });
            quickElement(
                'span', cal_link, '',
                'class', 'date-icon',
                'title', gettext('Choose a Date')
            );
            shortcuts_span.appendChild(document.createTextNode('\u00A0'));
            shortcuts_span.appendChild(today_link);
            shortcuts_span.appendChild(document.createTextNode('\u00A0|\u00A0'));
            shortcuts_span.appendChild(cal_link);

            // Create calendarbox div.
            //
            // Markup looks like:
            //
            // <div id="calendarbox3" class="calendarbox module">
            //     <h2>
            //           <a href="#" class="link-previous">&lsaquo;</a>
            //           <a href="#" class="link-next">&rsaquo;</a> February 2003
            //     </h2>
            //     <div class="calendar" id="calendarin3">
            //         <!-- (cal) -->
            //     </div>
            //     <div class="calendar-shortcuts">
            //          <a href="#">Yesterday</a> | <a href="#">Today</a> | <a href="#">Tomorrow</a>
            //     </div>
            //     <p class="calendar-cancel"><a href="#">Cancel</a></p>
            // </div>
            const cal_box = document.createElement('div');
            cal_box.style.display = 'none';
            cal_box.style.position = 'absolute';
            cal_box.className = 'calendarbox module';
            cal_box.id = DateTimeShortcuts.calendarDivName1 + num;
            document.body.appendChild(cal_box);
            cal_box.addEventListener('click', function(e) { e.stopPropagation(); });

            // next-prev links
            const cal_nav = quickElement('div', cal_box);
            const cal_nav_prev = quickElement('a', cal_nav, '<', 'href', '#');
            cal_nav_prev.className = 'calendarnav-previous';
            cal_nav_prev.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.drawPrev(num);
            });

            const cal_nav_next = quickElement('a', cal_nav, '>', 'href', '#');
            cal_nav_next.className = 'calendarnav-next';
            cal_nav_next.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.drawNext(num);
            });

            // main box
            const cal_main = quickElement('div', cal_box, '', 'id', DateTimeShortcuts.calendarDivName2 + num);
            cal_main.className = 'calendar';
            DateTimeShortcuts.calendars[num] = new Calendar(DateTimeShortcuts.calendarDivName2 + num, DateTimeShortcuts.handleCalendarCallback(num));
            DateTimeShortcuts.calendars[num].drawCurrent();

            // calendar shortcuts
            const shortcuts = quickElement('div', cal_box);
            shortcuts.className = 'calendar-shortcuts';
            let day_link = quickElement('a', shortcuts, gettext('Yesterday'), 'role', 'button', 'href', '#');
            day_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, -1);
            });
            shortcuts.appendChild(document.createTextNode('\u00A0|\u00A0'));
            day_link = quickElement('a', shortcuts, gettext('Today'), 'role', 'button', 'href', '#');
            day_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, 0);
            });
            shortcuts.appendChild(document.createTextNode('\u00A0|\u00A0'));
            day_link = quickElement('a', shortcuts, gettext('Tomorrow'), 'role', 'button', 'href', '#');
            day_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, +1);
            });

            // cancel bar
            const cancel_p = quickElement('p', cal_box);
            cancel_p.className = 'calendar-cancel';
            const cancel_link = quickElement('a', cancel_p, gettext('Cancel'), 'role', 'button', 'href', '#');
            cancel_link.addEventListener('click', function(e) {
                e.preventDefault();
                DateTimeShortcuts.dismissCalendar(num);
            });
            document.addEventListener('keyup', function(event) {
                if (event.which === 27) {
                    // ESC key closes popup
                    DateTimeShortcuts.dismissCalendar(num);
                    event.preventDefault();
                }
            });
        },
        openCalendar: function(num) {
            const cal_box = document.getElementById(DateTimeShortcuts.calendarDivName1 + num);
            const cal_link = document.getElementById(DateTimeShortcuts.calendarLinkName + num);
            const inp = DateTimeShortcuts.calendarInputs[num];

            // Determine if the current value in the input has a valid date.
            // If so, draw the calendar with that date's year and month.
            if (inp.value) {
                const format = get_format('DATE_INPUT_FORMATS')[0];
                const selected = inp.value.strptime(format);
                const year = selected.getUTCFullYear();
                const month = selected.getUTCMonth() + 1;
                const re = /\d{4}/;
                if (re.test(year.toString()) && month >= 1 && month <= 12) {
                    DateTimeShortcuts.calendars[num].drawDate(month, year, selected);
                }
            }

            // Recalculate the clockbox position
            // is it left-to-right or right-to-left layout ?
            if (window.getComputedStyle(document.body).direction !== 'rtl') {
                cal_box.style.left = findPosX(cal_link) + 17 + 'px';
            }
            else {
                // since style's width is in em, it'd be tough to calculate
                // px value of it. let's use an estimated px for now
                cal_box.style.left = findPosX(cal_link) - 180 + 'px';
            }
            cal_box.style.top = Math.max(0, findPosY(cal_link) - 75) + 'px';

            cal_box.style.display = 'block';
            document.addEventListener('click', DateTimeShortcuts.dismissCalendarFunc[num]);
        },
        dismissCalendar: function(num) {
            document.getElementById(DateTimeShortcuts.calendarDivName1 + num).style.display = 'none';
            document.removeEventListener('click', DateTimeShortcuts.dismissCalendarFunc[num]);
        },
        drawPrev: function(num) {
            DateTimeShortcuts.calendars[num].drawPreviousMonth();
        },
        drawNext: function(num) {
            DateTimeShortcuts.calendars[num].drawNextMonth();
        },
        handleCalendarCallback: function(num) {
            const format = get_format('DATE_INPUT_FORMATS')[0];
            return function(y, m, d) {
                DateTimeShortcuts.calendarInputs[num].value = new Date(y, m - 1, d).strftime(format);
                DateTimeShortcuts.calendarInputs[num].focus();
                document.getElementById(DateTimeShortcuts.calendarDivName1 + num).style.display = 'none';
            };
        },
        handleCalendarQuickLink: function(num, offset) {
            const d = DateTimeShortcuts.now();
            d.setDate(d.getDate() + offset);
            DateTimeShortcuts.calendarInputs[num].value = d.strftime(get_format('DATE_INPUT_FORMATS')[0]);
            DateTimeShortcuts.calendarInputs[num].focus();
            DateTimeShortcuts.dismissCalendar(num);
        }
    };

    window.addEventListener('load', DateTimeShortcuts.init);
    window.DateTimeShortcuts = DateTimeShortcuts;
}

def create_permissions(
    app_config,
    verbosity=2,
    interactive=True,
    using=DEFAULT_DB_ALIAS,
    apps=global_apps,
    **kwargs,
):
    if not app_config.models_module:
        return

    try:
        Permission = apps.get_model("auth", "Permission")
    except LookupError:
        return
    if not router.allow_migrate_model(using, Permission):
        return

    # Ensure that contenttypes are created for this app. Needed if
    # 'django.contrib.auth' is in INSTALLED_APPS before
    # 'django.contrib.contenttypes'.
    create_contenttypes(
        app_config,
        verbosity=verbosity,
        interactive=interactive,
        using=using,
        apps=apps,
        **kwargs,
    )

    app_label = app_config.label
    try:
        app_config = apps.get_app_config(app_label)
        ContentType = apps.get_model("contenttypes", "ContentType")
    except LookupError:
        return

    models = list(app_config.get_models())

    # Grab all the ContentTypes.
    ctypes = ContentType.objects.db_manager(using).get_for_models(
        *models, for_concrete_models=False
    )

    # Find all the Permissions that have a content_type for a model we're
    # looking for.  We don't need to check for codenames since we already have
    # a list of the ones we're going to create.
    all_perms = set(
        Permission.objects.using(using)
        .filter(
            content_type__in=set(ctypes.values()),
        )
        .values_list("content_type", "codename")
    )

    perms = []
    for model in models:
        ctype = ctypes[model]
        for codename, name in _get_all_permissions(model._meta):
            if (ctype.pk, codename) not in all_perms:
                permission = Permission()
                permission._state.db = using
                permission.codename = codename
                permission.name = name
                permission.content_type = ctype
                perms.append(permission)

    Permission.objects.using(using).bulk_create(perms)
    if verbosity >= 2:
        for perm in perms:
            print("Adding permission '%s'" % perm)

def check_password(environ, username, password):
    """
    Authenticate against Django's auth database.

    mod_wsgi docs specify None, True, False as return value depending
    on whether the user exists and authenticates.
    """
    # db connection state is managed similarly to the wsgi handler
    # as mod_wsgi may call these functions outside of a request/response cycle
    db.reset_queries()
    try:
        try:
            user = UserModel._default_manager.get_by_natural_key(username)
        except UserModel.DoesNotExist:
            return None
        if not user.is_active:
            return None
        return user.check_password(password)
    finally:
        db.close_old_connections()

def groups_for_user(environ, username):
    """
    Authorize a user based on groups
    """
    db.reset_queries()
    try:
        try:
            user = UserModel._default_manager.get_by_natural_key(username)
        except UserModel.DoesNotExist:
            return []
        if not user.is_active:
            return []
        return [group.name.encode() for group in user.groups.all()]
    finally:
        db.close_old_connections()

class NotRunningInTTYException(Exception):
    pass


PASSWORD_FIELD = "password"

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self.UserModel = get_user_model()
    self.username_field = self.UserModel._meta.get_field(
        self.UserModel.USERNAME_FIELD
    )

def add_arguments(self, parser):
    parser.add_argument(
        "--%s" % self.UserModel.USERNAME_FIELD,
        help="Specifies the login for the superuser.",
    )
    parser.add_argument(
        "--noinput",
        "--no-input",
        action="store_false",
        dest="interactive",
        help=(
            "Tells Django to NOT prompt the user for input of any kind. "
            "You must use --%s with --noinput, along with an option for "
            "any other required field. Superusers created with --noinput will "
            "not be able to log in until they're given a valid password."
            % self.UserModel.USERNAME_FIELD
        ),
    )
    parser.add_argument(
        "--database",
        default=DEFAULT_DB_ALIAS,
        choices=tuple(connections),
        help='Specifies the database to use. Default is "default".',
    )
    for field_name in self.UserModel.REQUIRED_FIELDS:
        field = self.UserModel._meta.get_field(field_name)
        if field.many_to_many:
            if (
                field.remote_field.through
                and not field.remote_field.through._meta.auto_created
            ):
                raise CommandError(
                    "Required field '%s' specifies a many-to-many "
                    "relation through model, which is not supported." % field_name
                )
            else:
                parser.add_argument(
                    "--%s" % field_name,
                    action="append",
                    help=(
                        "Specifies the %s for the superuser. Can be used "
                        "multiple times." % field_name,
                    ),
                )
        else:
            parser.add_argument(
                "--%s" % field_name,
                help="Specifies the %s for the superuser." % field_name,
            )

def execute(self, *args, **options):
    self.stdin = options.get("stdin", sys.stdin)  # Used for testing
    return super().execute(*args, **options)

def handle(self, *args, **options):
    username = options[self.UserModel.USERNAME_FIELD]
    database = options["database"]
    user_data = {}
    verbose_field_name = self.username_field.verbose_name
    try:
        self.UserModel._meta.get_field(PASSWORD_FIELD)
    except exceptions.FieldDoesNotExist:
        pass
    else:
        # If not provided, create the user with an unusable password.
        user_data[PASSWORD_FIELD] = None
    try:
        if options["interactive"]:
            # Same as user_data but without many to many fields and with
            # foreign keys as fake model instances instead of raw IDs.
            fake_user_data = {}
            if hasattr(self.stdin, "isatty") and not self.stdin.isatty():
                raise NotRunningInTTYException
            default_username = get_default_username(database=database)
            if username:
                error_msg = self._validate_username(
                    username, verbose_field_name, database
                )
                if error_msg:
                    self.stderr.write(error_msg)
                    username = None
            elif username == "":
                raise CommandError(
                    "%s cannot be blank." % capfirst(verbose_field_name)
                )
            # Prompt for username.
            while username is None:
                message = self._get_input_message(
                    self.username_field, default_username
                )
                username = self.get_input_data(
                    self.username_field, message, default_username
                )
                if username:
                    error_msg = self._validate_username(
                        username, verbose_field_name, database
                    )
                    if error_msg:
                        self.stderr.write(error_msg)
                        username = None
                        continue
            user_data[self.UserModel.USERNAME_FIELD] = username
            fake_user_data[self.UserModel.USERNAME_FIELD] = (
                self.username_field.remote_field.model(username)
                if self.username_field.remote_field
                else username
            )
            # Prompt for required fields.
            for field_name in self.UserModel.REQUIRED_FIELDS:
                field = self.UserModel._meta.get_field(field_name)
                user_data[field_name] = options[field_name]
                if user_data[field_name] is not None:
                    user_data[field_name] = field.clean(user_data[field_name], None)
                while user_data[field_name] is None:
                    message = self._get_input_message(field)
                    input_value = self.get_input_data(field, message)
                    user_data[field_name] = input_value
                    if field.many_to_many and input_value:
                        if not input_value.strip():
                            user_data[field_name] = None
                            self.stderr.write("Error: This field cannot be blank.")
                            continue
                        user_data[field_name] = [
                            pk.strip() for pk in input_value.split(",")
                        ]

                if not field.many_to_many:
                    fake_user_data[field_name] = user_data[field_name]
                # Wrap any foreign keys in fake model instances.
                if field.many_to_one:
                    fake_user_data[field_name] = field.remote_field.model(
                        user_data[field_name]
                    )

            # Prompt for a password if the model has one.
            while PASSWORD_FIELD in user_data and user_data[PASSWORD_FIELD] is None:
                password = getpass.getpass()
                password2 = getpass.getpass("Password (again): ")
                if password != password2:
                    self.stderr.write("Error: Your passwords didn't match.")
                    # Don't validate passwords that don't match.
                    continue
                if password.strip() == "":
                    self.stderr.write("Error: Blank passwords aren't allowed.")
                    # Don't validate blank passwords.
                    continue
                try:
                    validate_password(password2, self.UserModel(**fake_user_data))
                except exceptions.ValidationError as err:
                    self.stderr.write("\n".join(err.messages))
                    response = input(
                        "Bypass password validation and create user anyway? [y/N]: "
                    )
                    if response.lower() != "y":
                        continue
                user_data[PASSWORD_FIELD] = password
        else:
            # Non-interactive mode.
            # Use password from environment variable, if provided.
            if (
                PASSWORD_FIELD in user_data
                and "DJANGO_SUPERUSER_PASSWORD" in os.environ
            ):
                user_data[PASSWORD_FIELD] = os.environ["DJANGO_SUPERUSER_PASSWORD"]
            # Use username from environment variable, if not provided in
            # options.
            if username is None:
                username = os.environ.get(
                    "DJANGO_SUPERUSER_" + self.UserModel.USERNAME_FIELD.upper()
                )
            if username is None:
                raise CommandError(
                    "You must use --%s with --noinput."
                    % self.UserModel.USERNAME_FIELD
                )
            else:
                error_msg = self._validate_username(
                    username, verbose_field_name, database
                )
                if error_msg:
                    raise CommandError(error_msg)

            user_data[self.UserModel.USERNAME_FIELD] = username
            for field_name in self.UserModel.REQUIRED_FIELDS:
                env_var = "DJANGO_SUPERUSER_" + field_name.upper()
                value = options[field_name] or os.environ.get(env_var)
                field = self.UserModel._meta.get_field(field_name)
                if not value:
                    if field.blank and (
                        options[field_name] == "" or os.environ.get(env_var) == ""
                    ):
                        continue
                    raise CommandError(
                        "You must use --%s with --noinput." % field_name
                    )
                user_data[field_name] = field.clean(value, None)
                if field.many_to_many and isinstance(user_data[field_name], str):
                    user_data[field_name] = [
                        pk.strip() for pk in user_data[field_name].split(",")
                    ]

        self.UserModel._default_manager.db_manager(database).create_superuser(
            **user_data
        )
        if options["verbosity"] >= 1:
            self.stdout.write("Superuser created successfully.")
    except KeyboardInterrupt:
        self.stderr.write("\nOperation cancelled.")
        sys.exit(1)
    except exceptions.ValidationError as e:
        raise CommandError("; ".join(e.messages))
    except NotRunningInTTYException:
        self.stdout.write(
            "Superuser creation skipped due to not running in a TTY. "
            "You can run `manage.py createsuperuser` in your project "
            "to create one manually."
        )

def _get_input_message(self, field, default=None):
    return "%s%s%s: " % (
        capfirst(field.verbose_name),
        " (leave blank to use '%s')" % default if default else "",
        (
            " (%s.%s)"
            % (
                field.remote_field.model._meta.object_name,
                (
                    field.m2m_target_field_name()
                    if field.many_to_many
                    else field.remote_field.field_name
                ),
            )
            if field.remote_field
            else ""
        ),
    )

@cached_property

def username_is_unique(self):
    if self.username_field.unique:
        return True
    return any(
        len(unique_constraint.fields) == 1
        and unique_constraint.fields[0] == self.username_field.name
        for unique_constraint in self.UserModel._meta.total_unique_constraints
    )

def _validate_username(self, username, verbose_field_name, database):
    """Validate username. If invalid, return a string error message."""
    if self.username_is_unique:
        try:
            self.UserModel._default_manager.db_manager(database).get_by_natural_key(
                username
            )
        except self.UserModel.DoesNotExist:
            pass
        else:
            return "Error: That %s is already taken." % verbose_field_name
    if not username:
        return "%s cannot be blank." % capfirst(verbose_field_name)
    try:
        self.username_field.clean(username, None)
    except exceptions.ValidationError as e:
        return "; ".join(e.messages)

def _get_pass(self, prompt="Password: "):
    p = getpass.getpass(prompt=prompt)
    if not p:
        raise CommandError("aborted")
    return p

def handle(self, *args, **options):
    if options["username"]:
        username = options["username"]
    else:
        username = getpass.getuser()

    try:
        u = UserModel._default_manager.using(options["database"]).get(
            **{UserModel.USERNAME_FIELD: username}
        )
    except UserModel.DoesNotExist:
        raise CommandError("user '%s' does not exist" % username)

    self.stdout.write("Changing password for user '%s'" % u)

    MAX_TRIES = 3
    count = 0
    p1, p2 = 1, 2  # To make them initially mismatch.
    password_validated = False
    while (p1 != p2 or not password_validated) and count < MAX_TRIES:
        p1 = self._get_pass()
        p2 = self._get_pass("Password (again): ")
        if p1 != p2:
            self.stdout.write("Passwords do not match. Please try again.")
            count += 1
            # Don't validate passwords that don't match.
            continue
        try:
            validate_password(p2, u)
        except ValidationError as err:
            self.stderr.write("\n".join(err.messages))
            count += 1
        else:
            password_validated = True

    if count == MAX_TRIES:
        raise CommandError(
            "Aborting password change for user '%s' after %s attempts" % (u, count)
        )

    u.set_password(p1)
    u.save()

    return "Password changed successfully for user '%s'" % u

def __init__(self, request, *args, **kwargs):
    if not hasattr(request, "session"):
        raise ImproperlyConfigured(
            "The session-based temporary message storage requires session "
            "middleware to be installed, and come before the message "
            "middleware in the MIDDLEWARE list."
        )
    super().__init__(request, *args, **kwargs)

def _get(self, *args, **kwargs):
    """
    Retrieve a list of messages from the request's session. This storage
    always stores everything it is given, so return True for the
    all_retrieved flag.
    """
    return (
        self.deserialize_messages(self.request.session.get(self.session_key)),
        True,
    )

def _store(self, messages, response, *args, **kwargs):
    """
    Store a list of messages to the request's session.
    """
    if messages:
        self.request.session[self.session_key] = self.serialize_messages(messages)
    else:
        self.request.session.pop(self.session_key, None)
    return []

def serialize_messages(self, messages):
    encoder = MessageEncoder()
    return encoder.encode(messages)

def deserialize_messages(self, data):
    if data and isinstance(data, str):
        return json.loads(data, cls=MessageDecoder)
    return data

def default(self, obj):
    if isinstance(obj, Message):
        # Using 0/1 here instead of False/True to produce more compact json
        is_safedata = 1 if isinstance(obj.message, SafeData) else 0
        message = [self.message_key, is_safedata, obj.level, obj.message]
        if obj.extra_tags is not None:
            message.append(obj.extra_tags)
        return message
    return super().default(obj)

def process_messages(self, obj):
    if isinstance(obj, list) and obj:
        if obj[0] == MessageEncoder.message_key:
            if obj[1]:
                obj[3] = mark_safe(obj[3])
            return Message(*obj[2:])
        return [self.process_messages(item) for item in obj]
    if isinstance(obj, dict):
        return {key: self.process_messages(value) for key, value in obj.items()}
    return obj

def decode(self, s, **kwargs):
    decoded = super().decode(s, **kwargs)
    return self.process_messages(decoded)

def dumps(self, obj):
    return [
        json.dumps(
            o,
            separators=(",", ":"),
            cls=MessageEncoder,
        )
        for o in obj
    ]

def dumps(self, obj):
    """
    The parameter is an already serialized list of Message objects. No need
    to serialize it again, only join the list together and encode it.
    """
    return ("[" + ",".join(obj) + "]").encode("latin-1")

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self.signer = signing.get_cookie_signer(salt=self.key_salt)

    def compute_msg(some_serialized_msg):
        return self._encode_parts(
            [*some_serialized_msg, self.not_finished_json],
            encode_empty=True,
        )

    if is_too_large_for_cookie(encoded_data):
        if remove_oldest:
            idx = bisect_keep_right(
                serialized_messages,
                fn=lambda m: is_too_large_for_cookie(compute_msg(m)),
            )
            unstored_messages = messages[:idx]
            encoded_data = compute_msg(serialized_messages[idx:])
        else:
            idx = bisect_keep_left(
                serialized_messages,
                fn=lambda m: is_too_large_for_cookie(compute_msg(m)),
            )
            unstored_messages = messages[idx:]
            encoded_data = compute_msg(serialized_messages[:idx])

self._update_cookie(encoded_data, response)
return unstored_messages

def _encode_parts(self, messages, encode_empty=False):
    """
    Return an encoded version of the serialized messages list which can be
    stored as plain text.

    Since the data will be retrieved from the client-side, the encoded data
    also contains a hash to ensure that the data was not tampered with.
    """
    if messages or encode_empty:
        return self.signer.sign_object(
            messages, serializer=MessagePartGatherSerializer, compress=True
        )

def _decode(self, data):
    """
    Safely decode an encoded text stream back into a list of messages.

    If the encoded text stream contained an invalid hash or was in an
    invalid format, return None.
    """
    if not data:
        return None
    try:
        return self.signer.unsign_object(data, serializer=MessageSerializer)
    except (signing.BadSignature, binascii.Error, json.JSONDecodeError):
        pass
    # Mark the data as used (so it gets removed) since something was wrong
    # with the data.
    self.used = True
    return None

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self.storages = [
        storage_class(*args, **kwargs) for storage_class in self.storage_classes
    ]
    self._used_storages = set()

def __eq__(self, other):
    if not isinstance(other, Message):
        return NotImplemented
    return self.level == other.level and self.message == other.message

def __repr__(self):
    extra_tags = f", extra_tags={self.extra_tags!r}" if self.extra_tags else ""
    return f"Message(level={self.level}, message={self.message!r}{extra_tags})"

@property

def tags(self):
    return " ".join(tag for tag in [self.extra_tags, self.level_tag] if tag)

@property

def __iter__(self):
    self.used = True
    if self._queued_messages:
        self._loaded_messages.extend(self._queued_messages)
        self._queued_messages = []
    return iter(self._loaded_messages)

def __repr__(self):
    return f"<{self.__class__.__qualname__}: request={self.request!r}>"

@property

def _prepare_messages(self, messages):
    """
    Prepare a list of messages for storage.
    """
    for message in messages:
        message._prepare()

def update(self, response):
    """
    Store all unread messages.

    If the backend has yet to be iterated, store previously stored messages
    again. Otherwise, only store messages added after the last iteration.
    """
    self._prepare_messages(self._queued_messages)
    if self.used:
        return self._store(self._queued_messages, response)
    elif self.added_new:
        messages = self._loaded_messages + self._queued_messages
        return self._store(messages, response)

def __init__(self, trans=None):
    self._catalogs = [trans._catalog.copy()] if trans else [{}]
    self._plurals = [trans.plural] if trans else [lambda n: int(n != 1)]

def __getitem__(self, key):
    for cat in self._catalogs:
        try:
            return cat[key]
        except KeyError:
            pass
    raise KeyError(key)

def items(self):
    for cat in self._catalogs:
        yield from cat.items()

def keys(self):
    for cat in self._catalogs:
        yield from cat.keys()

def update(self, trans):
    # Merge if plural function is the same as the top catalog, else prepend.
    if trans.plural.__code__ == self._plurals[0]:
        self._catalogs[0].update(trans._catalog)
    else:
        self._catalogs.insert(0, trans._catalog.copy())
        self._plurals.insert(0, trans.plural)

def get(self, key, default=None):
    missing = object()
    for cat in self._catalogs:
        result = cat.get(key, missing)
        if result is not missing:
            return result
    return default

def plural(self, msgid, num):
    for cat, plural in zip(self._catalogs, self._plurals):
        tmsg = cat.get((msgid, plural(num)))
        if tmsg is not None:
            return tmsg
    raise KeyError

def _add_installed_apps_translations(self):
    """Merge translations from each installed app."""
    try:
        app_configs = reversed(apps.get_app_configs())
    except AppRegistryNotReady:
        raise AppRegistryNotReady(
            "The translation infrastructure cannot be initialized before the "
            "apps registry is ready. Check that you don't make non-lazy "
            "gettext calls at import time."
        )
    for app_config in app_configs:
        localedir = os.path.join(app_config.path, "locale")
        if os.path.exists(localedir):
            translation = self._new_gnu_trans(localedir)
            self.merge(translation)

def _add_local_translations(self):
    """Merge translations defined in LOCALE_PATHS."""
    for localedir in reversed(settings.LOCALE_PATHS):
        translation = self._new_gnu_trans(localedir)
        self.merge(translation)

def _add_fallback(self, localedirs=None):
    """Set the GNUTranslations() fallback with the default language."""
    # Don't set a fallback for the default language or any English variant
    # (as it's empty, so it'll ALWAYS fall back to the default language)
    if self.__language == settings.LANGUAGE_CODE or self.__language.startswith(
        "en"
    ):
        return
    if self.domain == "django":
        # Get from cache
        default_translation = translation(settings.LANGUAGE_CODE)
    else:
        default_translation = DjangoTranslation(
            settings.LANGUAGE_CODE, domain=self.domain, localedirs=localedirs
        )
    self.add_fallback(default_translation)

def merge(self, other):
    """Merge another translation into this catalog."""
    if not getattr(other, "_catalog", None):
        return  # NullTranslations() has no _catalog
    if self._catalog is None:
        # Take plural and _info from first catalog found (generally Django's).
        self.plural = other.plural
        self._info = other._info.copy()
        self._catalog = TranslationCatalog(other)
    else:
        self._catalog.update(other)
    if other._fallback:
        self.add_fallback(other._fallback)

def language(self):
    """Return the translation language."""
    return self.__language

def to_language(self):
    """Return the translation language name."""
    return self.__to_language

def ngettext(self, msgid1, msgid2, n):
    try:
        tmsg = self._catalog.plural(msgid1, n)
    except KeyError:
        if self._fallback:
            return self._fallback.ngettext(msgid1, msgid2, n)
        if n == 1:
            tmsg = msgid1
        else:
            tmsg = msgid2
    return tmsg

def get_language():
    """Return the currently selected language."""
    t = getattr(_active, "value", None)
    if t is not None:
        try:
            return t.to_language()
        except AttributeError:
            pass
    # If we don't have a real translation object, assume it's the default language.
    return settings.LANGUAGE_CODE

def pgettext(context, message):
    msg_with_ctxt = "%s%s%s" % (context, CONTEXT_SEPARATOR, message)
    result = gettext(msg_with_ctxt)
    if CONTEXT_SEPARATOR in result:
        # Translation not found
        result = message
    elif isinstance(message, SafeData):
        result = mark_safe(result)
    return result

def do_ntranslate(singular, plural, number, translation_function):
    global _default

    t = getattr(_active, "value", None)
    if t is not None:
        return getattr(t, translation_function)(singular, plural, number)
    if _default is None:
        _default = translation(settings.LANGUAGE_CODE)
    return getattr(_default, translation_function)(singular, plural, number)

def ngettext(singular, plural, number):
    """
    Return a string of the translation of either the singular or plural,
    based on the number.
    """
    return do_ntranslate(singular, plural, number, "ngettext")

def all_locale_paths():
    """
    Return a list of paths to user-provides languages files.
    """
    globalpath = os.path.join(
        os.path.dirname(sys.modules[settings.__module__].__file__), "locale"
    )
    app_paths = []
    for app_config in apps.get_app_configs():
        locale_path = os.path.join(app_config.path, "locale")
        if os.path.exists(locale_path):
            app_paths.append(locale_path)
    return [globalpath, *settings.LOCALE_PATHS, *app_paths]


@functools.lru_cache(maxsize=1000)

def check_for_language(lang_code):
    """
    Check whether there is a global language file for the given language
    code. This is used to decide whether a user-provided language is
    available.

    lru_cache should have a maxsize to prevent from memory exhaustion attacks,
    as the provided language codes are taken from the HTTP request. See also
    <https://www.djangoproject.com/weblog/2007/oct/26/security-fix/>.
    """
    # First, a quick check to make sure lang_code is well-formed (#21458)
    if lang_code is None or not language_code_re.search(lang_code):
        return False
    return any(
        gettext_module.find("django", path, [to_locale(lang_code)]) is not None
        for path in all_locale_paths()
    )


@functools.lru_cache

def get_languages():
    """
    Cache of settings.LANGUAGES in a dictionary for easy lookups by key.
    Convert keys to lowercase as they should be treated as case-insensitive.
    """
    return {key.lower(): value for key, value in dict(settings.LANGUAGES).items()}


@functools.lru_cache(maxsize=1000)

def get_supported_language_variant(lang_code, strict=False):
    """
    Return the language code that's listed in supported languages, possibly
    selecting a more generic variant. Raise LookupError if nothing is found.

    If `strict` is False (the default), look for a country-specific variant
    when neither the language code nor its generic variant is found.

    The language code is truncated to a maximum length to avoid potential
    denial of service attacks.

    lru_cache should have a maxsize to prevent from memory exhaustion attacks,
    as the provided language codes are taken from the HTTP request. See also
    <https://www.djangoproject.com/weblog/2007/oct/26/security-fix/>.
    """
    if lang_code:
        # Truncate the language code to a maximum length to avoid potential
        # denial of service attacks.
        if len(lang_code) > LANGUAGE_CODE_MAX_LENGTH:
            if (
                not strict
                and (index := lang_code.rfind("-", 0, LANGUAGE_CODE_MAX_LENGTH)) > 0
            ):
                # There is a generic variant under the maximum length accepted length.
                lang_code = lang_code[:index]
            else:
                raise LookupError(lang_code)
        # If 'zh-hant-tw' is not supported, try special fallback or subsequent
        # language codes i.e. 'zh-hant' and 'zh'.
        possible_lang_codes = [lang_code]
        try:
            possible_lang_codes.extend(LANG_INFO[lang_code]["fallback"])
        except KeyError:
            pass
        i = None
        while (i := lang_code.rfind("-", 0, i)) > -1:
            possible_lang_codes.append(lang_code[:i])
        generic_lang_code = possible_lang_codes[-1]
        supported_lang_codes = get_languages()

        for code in possible_lang_codes:
            if code.lower() in supported_lang_codes and check_for_language(code):
                return code
        if not strict:
            # if fr-fr is not supported, try fr-ca.
            for supported_code in supported_lang_codes:
                if supported_code.startswith(generic_lang_code + "-"):
                    return supported_code
    raise LookupError(lang_code)

def get_language_from_path(path, strict=False):
    """
    Return the language code if there's a valid language code found in `path`.

    If `strict` is False (the default), look for a country-specific variant
    when neither the language code nor its generic variant is found.
    """
    regex_match = language_code_prefix_re.match(path)
    if not regex_match:
        return None
    lang_code = regex_match[1]
    try:
        return get_supported_language_variant(lang_code, strict=strict)
    except LookupError:
        return None

def get_language_from_request(request, check_path=False):
    """
    Analyze the request to find what language the user wants the system to
    show. Only languages listed in settings.LANGUAGES are taken into account.
    If the user requests a sublanguage where we have a main language, we send
    out the main language.

    If check_path is True, the URL path prefix will be checked for a language
    code, otherwise this is skipped for backwards compatibility.
    """
    if check_path:
        lang_code = get_language_from_path(request.path_info)
        if lang_code is not None:
            return lang_code

    lang_code = request.COOKIES.get(settings.LANGUAGE_COOKIE_NAME)
    if (
        lang_code is not None
        and lang_code in get_languages()
        and check_for_language(lang_code)
    ):
        return lang_code

    try:
        return get_supported_language_variant(lang_code)
    except LookupError:
        pass

    accept = request.META.get("HTTP_ACCEPT_LANGUAGE", "")
    for accept_lang, unused in parse_accept_lang_header(accept):
        if accept_lang == "*":
            break

        if not language_code_re.search(accept_lang):
            continue

        try:
            return get_supported_language_variant(accept_lang)
        except LookupError:
            continue

    try:
        return get_supported_language_variant(settings.LANGUAGE_CODE)
    except LookupError:
        return settings.LANGUAGE_CODE


@functools.lru_cache(maxsize=1000)

def _parse_accept_lang_header(lang_string):
    """
    Parse the lang_string, which is the body of an HTTP Accept-Language
    header, and return a tuple of (lang, q-value), ordered by 'q' values.

    Return an empty tuple if there are any format errors in lang_string.
    """
    result = []
    pieces = accept_language_re.split(lang_string.lower())
    if pieces[-1]:
        return ()
    for i in range(0, len(pieces) - 1, 3):
        first, lang, priority = pieces[i : i + 3]
        if first:
            return ()
        if priority:
            priority = float(priority)
        else:
            priority = 1.0
        result.append((lang, priority))
    result.sort(key=lambda k: k[1], reverse=True)
    return tuple(result)

def parse_accept_lang_header(lang_string):
    """
    Parse the value of the Accept-Language header up to a maximum length.

    The value of the header is truncated to a maximum length to avoid potential
    denial of service and memory exhaustion attacks. Excessive memory could be
    used if the raw value is very large as it would be cached due to the use of
    functools.lru_cache() to avoid repetitive parsing of common header values.
    """
    # If the header value doesn't exceed the maximum allowed length, parse it.
    if len(lang_string) <= LANGUAGE_CODE_MAX_LENGTH:
        return _parse_accept_lang_header(lang_string)

    # If there is at least one comma in the value, parse up to the last comma
    # before the max length, skipping any truncated parts at the end of the
    # header value.
    if (index := lang_string.rfind(",", 0, LANGUAGE_CODE_MAX_LENGTH)) > 0:
        return _parse_accept_lang_header(lang_string[:index])

    # Don't attempt to parse if there is only one language-range value which is
    # longer than the maximum allowed length and so truncated.
    return ()

