        try:
            token, rest = parser.get_mailbox(addr)
        except (HeaderParseError, ValueError, IndexError):
            raise ValueError('Invalid address "%s"' % addr)
        else:
            if rest:
                # The entire email address must be parsed.
                raise ValueError(
                    'Invalid address; only %s could be parsed from "%s"' % (token, addr)
                )
            nm = token.display_name or ""
            localpart = token.local_part
            domain = token.domain or ""
    else:
        nm, address = addr
        if "@" not in address:
            raise ValueError(f'Invalid address "{address}"')
        localpart, domain = address.rsplit("@", 1)

    address_parts = nm + localpart + domain
    if "\n" in address_parts or "\r" in address_parts:
        raise ValueError("Invalid address; address parts cannot contain newlines.")

    # Avoid UTF-8 encode, if it's possible.
    try:
        nm.encode("ascii")
        nm = Header(nm).encode()
    except UnicodeEncodeError:
        nm = Header(nm, encoding).encode()
    try:
        localpart.encode("ascii")
    except UnicodeEncodeError:
        localpart = Header(localpart, encoding).encode()
    domain = punycode(domain)

    parsed_address = Address(username=localpart, domain=domain)
    return formataddr((nm, parsed_address.addr_spec))

def __init__(self, _text, _subtype="plain", _charset=None):
    self.encoding = _charset
    MIMEText.__init__(self, _text, _subtype=_subtype, _charset=_charset)

def __setitem__(self, name, val):
    name, val = forbid_multi_line_headers(name, val, self.encoding)
    MIMEText.__setitem__(self, name, val)

def set_payload(self, payload, charset=None):
    if charset == "utf-8" and not isinstance(charset, Charset.Charset):
        has_long_lines = any(
            len(line.encode(errors="surrogateescape"))
            > RFC5322_EMAIL_LINE_LENGTH_LIMIT
            for line in payload.splitlines()
        )
        # Quoted-Printable encoding has the side effect of shortening long
        # lines, if any (#22561).
        charset = utf8_charset_qp if has_long_lines else utf8_charset
    MIMEText.set_payload(self, payload, charset=charset)

def __init__(
    self, _subtype="mixed", boundary=None, _subparts=None, encoding=None, **_params
):
    self.encoding = encoding
    MIMEMultipart.__init__(self, _subtype, boundary, _subparts, **_params)

def __init__(
    self,
    subject="",
    body="",
    from_email=None,
    to=None,
    bcc=None,
    connection=None,
    attachments=None,
    headers=None,
    cc=None,
    reply_to=None,
):
    """
    Initialize a single email message (which can be sent to multiple
    recipients).
    """
    if to:
        if isinstance(to, str):
            raise TypeError('"to" argument must be a list or tuple')
        self.to = list(to)
    else:
        self.to = []
    if cc:
        if isinstance(cc, str):
            raise TypeError('"cc" argument must be a list or tuple')
        self.cc = list(cc)
    else:
        self.cc = []
    if bcc:
        if isinstance(bcc, str):
            raise TypeError('"bcc" argument must be a list or tuple')
        self.bcc = list(bcc)
    else:
        self.bcc = []
    if reply_to:
        if isinstance(reply_to, str):
            raise TypeError('"reply_to" argument must be a list or tuple')
        self.reply_to = list(reply_to)
    else:
        self.reply_to = []
    self.from_email = from_email or settings.DEFAULT_FROM_EMAIL
    self.subject = subject
    self.body = body or ""
    self.attachments = []
    if attachments:
        for attachment in attachments:
            if isinstance(attachment, MIMEBase):
                self.attach(attachment)
            else:
                self.attach(*attachment)
    self.extra_headers = headers or {}
    self.connection = connection

def get_connection(self, fail_silently=False):
    from django.core.mail import get_connection

    if not self.connection:
        self.connection = get_connection(fail_silently=fail_silently)
    return self.connection

def send(self, fail_silently=False):
    """Send the email message."""
    if not self.recipients():
        # Don't bother creating the network connection if there's nobody to
        # send to.
        return 0
    return self.get_connection(fail_silently).send_messages([self])

def attach(self, filename=None, content=None, mimetype=None):
    """
    Attach a file with the given filename and content. The filename can
    be omitted and the mimetype is guessed, if not provided.

    If the first parameter is a MIMEBase subclass, insert it directly
    into the resulting message attachments.

    For a text/* mimetype (guessed or specified), when a bytes object is
    specified as content, decode it as UTF-8. If that fails, set the
    mimetype to DEFAULT_ATTACHMENT_MIME_TYPE and don't decode the content.
    """
    if isinstance(filename, MIMEBase):
        if content is not None or mimetype is not None:
            raise ValueError(
                "content and mimetype must not be given when a MIMEBase "
                "instance is provided."
            )
        self.attachments.append(filename)
    elif content is None:
        raise ValueError("content must be provided.")
    else:
        mimetype = (
            mimetype
            or mimetypes.guess_type(filename)[0]
            or DEFAULT_ATTACHMENT_MIME_TYPE
        )
        basetype, subtype = mimetype.split("/", 1)

        if basetype == "text":
            if isinstance(content, bytes):
                try:
                    content = content.decode()
                except UnicodeDecodeError:
                    # If mimetype suggests the file is text but it's
                    # actually binary, read() raises a UnicodeDecodeError.
                    mimetype = DEFAULT_ATTACHMENT_MIME_TYPE

        self.attachments.append(EmailAttachment(filename, content, mimetype))

def _create_attachments(self, msg):
    if self.attachments:
        encoding = self.encoding or settings.DEFAULT_CHARSET
        body_msg = msg
        msg = SafeMIMEMultipart(_subtype=self.mixed_subtype, encoding=encoding)
        if self.body or body_msg.is_multipart():
            msg.attach(body_msg)
        for attachment in self.attachments:
            if isinstance(attachment, MIMEBase):
                msg.attach(attachment)
            else:
                msg.attach(self._create_attachment(*attachment))
    return msg

def _create_attachment(self, filename, content, mimetype=None):
    """
    Convert the filename, content, mimetype triple into a MIME attachment
    object.
    """
    attachment = self._create_mime_attachment(content, mimetype)
    if filename:
        try:
            filename.encode("ascii")
        except UnicodeEncodeError:
            filename = ("utf-8", "", filename)
        attachment.add_header(
            "Content-Disposition", "attachment", filename=filename
        )
    return attachment

def _set_list_header_if_not_empty(self, msg, header, values):
    """
    Set msg's header, either from self.extra_headers, if present, or from
    the values argument if not empty.
    """
    try:
        msg[header] = self.extra_headers[header]
    except KeyError:
        if values:
            msg[header] = ", ".join(str(v) for v in values)

def attach_alternative(self, content, mimetype):
    """Attach an alternative content representation."""
    if content is None or mimetype is None:
        raise ValueError("Both content and mimetype must be provided.")
    self.alternatives.append(EmailAlternative(content, mimetype))

def _create_alternatives(self, msg):
    encoding = self.encoding or settings.DEFAULT_CHARSET
    if self.alternatives:
        body_msg = msg
        msg = SafeMIMEMultipart(
            _subtype=self.alternative_subtype, encoding=encoding
        )
        if self.body:
            msg.attach(body_msg)
        for alternative in self.alternatives:
            msg.attach(
                self._create_mime_attachment(
                    alternative.content, alternative.mimetype
                )
            )
    return msg

def body_contains(self, text):
    """
    Checks that ``text`` occurs in the email body and in all attached MIME
    type text/* alternatives.
    """
    if text not in self.body:
        return False

    for content, mimetype in self.alternatives:
        if mimetype.startswith("text/") and text not in content:
            return False
    return True

    def get_fqdn(self):
        if not hasattr(self, "_fqdn"):
            self._fqdn = punycode(socket.getfqdn())
        return self._fqdn


