def __init__(self, *args, returncode=1, **kwargs):
    self.returncode = returncode
    super().__init__(*args, **kwargs)

def __init__(
    self, *, missing_args_message=None, called_from_command_line=None, **kwargs
):
    self.missing_args_message = missing_args_message
    self.called_from_command_line = called_from_command_line
    super().__init__(**kwargs)

def parse_args(self, args=None, namespace=None):
    # Catch missing argument for a better error message
    if self.missing_args_message and not (
        args or any(not arg.startswith("-") for arg in args)
    ):
        self.error(self.missing_args_message)
    return super().parse_args(args, namespace)

def error(self, message):
    if self.called_from_command_line:
        super().error(message)
    else:
        raise CommandError("Error: %s" % message)

def add_subparsers(self, **kwargs):
    parser_class = kwargs.get("parser_class", type(self))
    if issubclass(parser_class, CommandParser):
        kwargs["parser_class"] = partial(
            parser_class,
            called_from_command_line=self.called_from_command_line,
        )
    return super().add_subparsers(**kwargs)

def handle_default_options(options):
    """
    Include any default options that all commands should accept here
    so that ManagementUtility can handle them before searching for
    user commands.
    """
    if options.settings:
        os.environ["DJANGO_SETTINGS_MODULE"] = options.settings
    if options.pythonpath:
        sys.path.insert(0, options.pythonpath)

def _reordered_actions(self, actions):
    return sorted(
        actions, key=lambda a: set(a.option_strings) & self.show_last != set()
    )

class OutputWrapper:
    """
    Wrapper around stdout/stderr
    """

    @property

def style_func(self):
    return self._style_func

@style_func.setter

def style_func(self, style_func):
    if style_func and self.isatty():
        self._style_func = style_func
    else:
        self._style_func = lambda x: x

def flush(self):
    if hasattr(self._out, "flush"):
        self._out.flush()

def __init__(self, stdout=None, stderr=None, no_color=False, force_color=False):
    self.stdout = OutputWrapper(stdout or sys.stdout)
    self.stderr = OutputWrapper(stderr or sys.stderr)
    if no_color and force_color:
        raise CommandError("'no_color' and 'force_color' can't be used together.")
    if no_color:
        self.style = no_style()
    else:
        self.style = color_style(force_color)
        self.stderr.style_func = self.style.ERROR
    if (
        not isinstance(self.requires_system_checks, (list, tuple))
        and self.requires_system_checks != ALL_CHECKS
    ):
        raise TypeError("requires_system_checks must be a list or tuple.")

def add_base_argument(self, parser, *args, **kwargs):
    """
    Call the parser's add_argument() method, suppressing the help text
    according to BaseCommand.suppressed_base_arguments.
    """
    for arg in args:
        if arg in self.suppressed_base_arguments:
            kwargs["help"] = argparse.SUPPRESS
            break
    parser.add_argument(*args, **kwargs)

def execute(self, *args, **options):
    """
    Try to execute this command, performing system checks if needed (as
    controlled by the ``requires_system_checks`` attribute, except if
    force-skipped).
    """
    if options["force_color"] and options["no_color"]:
        raise CommandError(
            "The --no-color and --force-color options can't be used together."
        )
    if options["force_color"]:
        self.style = color_style(force_color=True)
    elif options["no_color"]:
        self.style = no_style()
        self.stderr.style_func = None
    if options.get("stdout"):
        self.stdout = OutputWrapper(options["stdout"])
    if options.get("stderr"):
        self.stderr = OutputWrapper(options["stderr"])

    if self.requires_system_checks and not options["skip_checks"]:
        check_kwargs = self.get_check_kwargs(options)
        self.check(**check_kwargs)
    if self.requires_migrations_checks:
        self.check_migrations()
    output = self.handle(*args, **options)
    if output:
        if self.output_transaction:
            connection = connections[options.get("database", DEFAULT_DB_ALIAS)]
            output = "%s\n%s\n%s" % (
                self.style.SQL_KEYWORD(connection.ops.start_transaction_sql()),
                output,
                self.style.SQL_KEYWORD(connection.ops.end_transaction_sql()),
            )
        self.stdout.write(output)
    return output

def get_check_kwargs(self, options):
    if self.requires_system_checks == ALL_CHECKS:
        return {}
    return {"tags": self.requires_system_checks}

def check(
    self,
    app_configs=None,
    tags=None,
    display_num_errors=False,
    include_deployment_checks=False,
    fail_level=checks.ERROR,
    databases=None,
):
    """
    Use the system check framework to validate entire Django project.
    Raise CommandError for any serious message (error or critical errors).
    If there are only light messages (like warnings), print them to stderr
    and don't raise an exception.
    """
    all_issues = checks.run_checks(
        app_configs=app_configs,
        tags=tags,
        include_deployment_checks=include_deployment_checks,
        databases=databases,
    )

    header, body, footer = "", "", ""
    visible_issue_count = 0  # excludes silenced warnings

    if all_issues:
        debugs = [
            e for e in all_issues if e.level < checks.INFO and not e.is_silenced()
        ]
        infos = [
            e
            for e in all_issues
            if checks.INFO <= e.level < checks.WARNING and not e.is_silenced()
        ]
        warnings = [
            e
            for e in all_issues
            if checks.WARNING <= e.level < checks.ERROR and not e.is_silenced()
        ]
        errors = [
            e
            for e in all_issues
            if checks.ERROR <= e.level < checks.CRITICAL and not e.is_silenced()
        ]
        criticals = [
            e
            for e in all_issues
            if checks.CRITICAL <= e.level and not e.is_silenced()
        ]
        sorted_issues = [
            (criticals, "CRITICALS"),
            (errors, "ERRORS"),
            (warnings, "WARNINGS"),
            (infos, "INFOS"),
            (debugs, "DEBUGS"),
        ]

        for issues, group_name in sorted_issues:
            if issues:
                visible_issue_count += len(issues)
                formatted = (
                    (
                        self.style.ERROR(str(e))
                        if e.is_serious()
                        else self.style.WARNING(str(e))
                    )
                    for e in issues
                )
                formatted = "\n".join(sorted(formatted))
                body += "\n%s:\n%s\n" % (group_name, formatted)

    if visible_issue_count:
        header = "System check identified some issues:\n"

    if display_num_errors:
        if visible_issue_count:
            footer += "\n"
        footer += "System check identified %s (%s silenced)." % (
            (
                "no issues"
                if visible_issue_count == 0
                else (
                    "1 issue"
                    if visible_issue_count == 1
                    else "%s issues" % visible_issue_count
                )
            ),
            len(all_issues) - visible_issue_count,
        )

    if any(e.is_serious(fail_level) and not e.is_silenced() for e in all_issues):
        msg = self.style.ERROR("SystemCheckError: %s" % header) + body + footer
        raise SystemCheckError(msg)
    else:
        msg = header + body + footer

    if msg:
        if visible_issue_count:
            self.stderr.write(msg, lambda x: x)
        else:
            self.stdout.write(msg)

def check_migrations(self):
    """
    Print a warning if the set of migrations on disk don't match the
    migrations in the database.
    """
    from django.db.migrations.executor import MigrationExecutor

    try:
        executor = MigrationExecutor(connections[DEFAULT_DB_ALIAS])
    except ImproperlyConfigured:
        # No databases are configured (or the dummy one)
        return

    plan = executor.migration_plan(executor.loader.graph.leaf_nodes())
    if plan:
        apps_waiting_migration = sorted(
            {migration.app_label for migration, backwards in plan}
        )
        self.stdout.write(
            self.style.NOTICE(
                "\nYou have %(unapplied_migration_count)s unapplied migration(s). "
                "Your project may not work properly until you apply the "
                "migrations for app(s): %(apps_waiting_migration)s."
                % {
                    "unapplied_migration_count": len(plan),
                    "apps_waiting_migration": ", ".join(apps_waiting_migration),
                }
            )
        )
        self.stdout.write(
            self.style.NOTICE("Run 'python manage.py migrate' to apply them.")
        )

def handle(self, *app_labels, **options):
    from django.apps import apps

    try:
        app_configs = [apps.get_app_config(app_label) for app_label in app_labels]
    except (LookupError, ImportError) as e:
        raise CommandError(
            "%s. Are you sure your INSTALLED_APPS setting is correct?" % e
        )
    output = []
    for app_config in app_configs:
        app_output = self.handle_app_config(app_config, **options)
        if app_output:
            output.append(app_output)
    return "\n".join(output)

