def validate_file_name(name, allow_relative_path=False):
    # Remove potentially dangerous names
    if os.path.basename(name) in {"", ".", ".."}:
        raise SuspiciousFileOperation("Could not derive file name from '%s'" % name)

    if allow_relative_path:
        # Ensure that name can be treated as a pure posix path, i.e. Unix
        # style (with forward slashes).
        path = pathlib.PurePosixPath(str(name).replace("\\", "/"))
        if path.is_absolute() or ".." in path.parts:
            raise SuspiciousFileOperation(
                "Detected path traversal attempt in '%s'" % name
            )
    elif name != os.path.basename(name):
        raise SuspiciousFileOperation("File name '%s' includes path elements" % name)

    return name

def readable(self):
    if self.closed:
        return False
    if hasattr(self.file, "readable"):
        return self.file.readable()
    return True

def writable(self):
    if self.closed:
        return False
    if hasattr(self.file, "writable"):
        return self.file.writable()
    return "w" in getattr(self.file, "mode", "")

def seekable(self):
    if self.closed:
        return False
    if hasattr(self.file, "seekable"):
        return self.file.seekable()
    return True

def __init__(self, name, content_type, size, charset, content_type_extra=None):
    _, ext = os.path.splitext(name)
    file = tempfile.NamedTemporaryFile(
        suffix=".upload" + ext, dir=settings.FILE_UPLOAD_TEMP_DIR
    )
    super().__init__(file, name, content_type, size, charset, content_type_extra)

def temporary_file_path(self):
    """Return the full path of this file."""
    return self.file.name

def close(self):
    try:
        return self.file.close()
    except FileNotFoundError:
        # The file was moved or deleted before the tempfile could unlink
        # it. Still sets self.file.close_called and calls
        # self.file.file.close() before the exception.
        pass

def open(self, mode=None):
    self.file.seek(0)
    return self

def chunks(self, chunk_size=None):
    self.file.seek(0)
    yield self.read()

def multiple_chunks(self, chunk_size=None):
    # Since it's in memory, we'll never have multiple chunks.
    return False

def __init__(self, name, content, content_type="text/plain"):
    content = content or b""
    super().__init__(
        BytesIO(content), None, name, content_type, len(content), None, None
    )

@classmethod

class ImageFile(File):
    """
    A mixin for use alongside django.core.files.base.File, which provides
    additional features for dealing with images.
    """

    @property

def width(self):
    return self._get_image_dimensions()[0]

@property

def _get_image_dimensions(self):
    if not hasattr(self, "_dimensions_cache"):
        close = self.closed
        self.open()
        self._dimensions_cache = get_image_dimensions(self, close=close)
    return self._dimensions_cache

def get_image_dimensions(file_or_path, close=False):
    """
    Return the (width, height) of an image, given an open file or a path.  Set
    'close' to True to close the file at the end if it is initially in an open
    state.
    """
    from PIL import ImageFile as PillowImageFile

    p = PillowImageFile.Parser()
    if hasattr(file_or_path, "read"):
        file = file_or_path
        file_pos = file.tell()
        file.seek(0)
    else:
        try:
            file = open(file_or_path, "rb")
        except OSError:
            return (None, None)
        close = True
    try:
        # Most of the time Pillow only needs a small chunk to parse the image
        # and get the dimensions, but with some TIFF files Pillow needs to
        # parse the whole file.
        chunk_size = 1024
        while 1:
            data = file.read(chunk_size)
            if not data:
                break
            try:
                p.feed(data)
            except zlib.error as e:
                # ignore zlib complaining on truncated stream, just feed more
                # data to parser (ticket #19457).
                if e.args[0].startswith("Error -5"):
                    pass
                else:
                    raise
            except struct.error:
                # Ignore PIL failing on a too short buffer when reads return
                # less bytes than expected. Skip and feed more data to the
                # parser (ticket #24544).
                pass
            except RuntimeError:
                # e.g. "RuntimeError: could not create decoder object" for
                # WebP files. A different chunk_size may work.
                pass
            if p.image:
                return p.image.size
            chunk_size *= 2
        return (None, None)
    finally:
        if close:
            file.close()
        else:
            file.seek(file_pos)

def __init__(self, file, name=None):
    self.file = file
    if name is None:
        name = getattr(file, "name", None)
    self.name = name
    if hasattr(file, "mode"):
        self.mode = file.mode

def __len__(self):
    return self.size

@cached_property

def size(self):
    if hasattr(self.file, "size"):
        return self.file.size
    if hasattr(self.file, "name"):
        try:
            return os.path.getsize(self.file.name)
        except (OSError, TypeError):
            pass
    if hasattr(self.file, "tell") and hasattr(self.file, "seek"):
        pos = self.file.tell()
        self.file.seek(0, os.SEEK_END)
        size = self.file.tell()
        self.file.seek(pos)
        return size
    raise AttributeError("Unable to determine the file's size.")

def chunks(self, chunk_size=None):
    """
    Read the file and yield chunks of ``chunk_size`` bytes (defaults to
    ``File.DEFAULT_CHUNK_SIZE``).
    """
    chunk_size = chunk_size or self.DEFAULT_CHUNK_SIZE
    try:
        self.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass

    while True:
        data = self.read(chunk_size)
        if not data:
            break
        yield data

def __iter__(self):
    # Iterate over this file-like object by newlines
    buffer_ = None
    for chunk in self.chunks():
        for line in chunk.splitlines(True):
            if buffer_:
                if endswith_cr(buffer_) and not equals_lf(line):
                    # Line split after a \r newline; yield buffer_.
                    yield buffer_
                    # Continue with line.
                else:
                    # Line either split without a newline (line
                    # continues after buffer_) or with \r\n
                    # newline (line == b'\n').
                    line = buffer_ + line
                # buffer_ handled, clear it.
                buffer_ = None

            # If this is the end of a \n or \r\n line, yield.
            if endswith_lf(line):
                yield line
            else:
                buffer_ = line

    if buffer_ is not None:
        yield buffer_

def open(self, mode=None, *args, **kwargs):
    if not self.closed:
        self.seek(0)
    elif self.name and os.path.exists(self.name):
        self.file = open(self.name, mode or self.mode, *args, **kwargs)
    else:
        raise ValueError("The file cannot be reopened.")
    return self

def open(self, mode=None):
    self.seek(0)
    return self

def write(self, data):
    self.__dict__.pop("size", None)  # Clear the computed size.
    return self.file.write(data)

def endswith_cr(line):
    """Return True if line (a text or bytestring) ends with '\r'."""
    return line.endswith("\r" if isinstance(line, str) else b"\r")

def endswith_lf(line):
    """Return True if line (a text or bytestring) ends with '\n'."""
    return line.endswith("\n" if isinstance(line, str) else b"\n")

def convert_exception_to_response(get_response):
    """
    Wrap the given get_response callable in exception-to-response conversion.

    All exceptions will be converted. All known 4xx exceptions (Http404,
    PermissionDenied, MultiPartParserError, SuspiciousOperation) will be
    converted to the appropriate response, and all other exceptions will be
    converted to 500 responses.

    This decorator is automatically applied to all middleware to ensure that
    no middleware leaks an exception and that the next middleware in the stack
    can rely on getting a response instead of an exception.
    """
    if iscoroutinefunction(get_response):

        @wraps(get_response)
        async def inner(request):
            try:
                response = await get_response(request)
            except Exception as exc:
                response = await sync_to_async(
                    response_for_exception, thread_sensitive=False
                )(request, exc)
            return response

        return inner
    else:

        @wraps(get_response)

def inner(request):
    try:
        response = get_response(request)
    except Exception as exc:
        response = response_for_exception(request, exc)
    return response

return inner

def response_for_exception(request, exc):
    if isinstance(exc, Http404):
        if settings.DEBUG:
            response = debug.technical_404_response(request, exc)
        else:
            response = get_exception_response(
                request, get_resolver(get_urlconf()), 404, exc
            )

    elif isinstance(exc, PermissionDenied):
        response = get_exception_response(
            request, get_resolver(get_urlconf()), 403, exc
        )
        log_response(
            "Forbidden (Permission denied): %s",
            request.path,
            response=response,
            request=request,
            exception=exc,
        )

    elif isinstance(exc, MultiPartParserError):
        response = get_exception_response(
            request, get_resolver(get_urlconf()), 400, exc
        )
        log_response(
            "Bad request (Unable to parse request body): %s",
            request.path,
            response=response,
            request=request,
            exception=exc,
        )

    elif isinstance(exc, BadRequest):
        if settings.DEBUG:
            response = debug.technical_500_response(
                request, *sys.exc_info(), status_code=400
            )
        else:
            response = get_exception_response(
                request, get_resolver(get_urlconf()), 400, exc
            )
        log_response(
            "%s: %s",
            str(exc),
            request.path,
            response=response,
            request=request,
            exception=exc,
        )
    elif isinstance(exc, SuspiciousOperation):
        if isinstance(exc, (RequestDataTooBig, TooManyFieldsSent, TooManyFilesSent)):
            # POST data can't be accessed again, otherwise the original
            # exception would be raised.
            request._mark_post_parse_error()

        if settings.DEBUG:
            response = debug.technical_500_response(
                request, *sys.exc_info(), status_code=400
            )
        else:
            response = get_exception_response(
                request, get_resolver(get_urlconf()), 400, exc
            )
        # The logger is set to django.security, which specifically captures
        # SuspiciousOperation events, unlike the default django.request logger.
        security_logger = logging.getLogger(f"django.security.{exc.__class__.__name__}")
        log_response(
            str(exc),
            exception=exc,
            request=request,
            response=response,
            level="error",
            logger=security_logger,
        )

    else:
        signals.got_request_exception.send(sender=None, request=request)
        response = handle_uncaught_exception(
            request, get_resolver(get_urlconf()), sys.exc_info()
        )
        log_response(
            "%s: %s",
            response.reason_phrase,
            request.path,
            response=response,
            request=request,
            exception=exc,
        )

    # Force a TemplateResponse to be rendered.
    if not getattr(response, "is_rendered", True) and callable(
        getattr(response, "render", None)
    ):
        response = response.render()

    return response

def get_exception_response(request, resolver, status_code, exception):
    try:
        callback = resolver.resolve_error_handler(status_code)
        response = callback(request, exception=exception)
    except Exception:
        signals.got_request_exception.send(sender=None, request=request)
        response = handle_uncaught_exception(request, resolver, sys.exc_info())

    return response

def handle_uncaught_exception(request, resolver, exc_info):
    """
    Processing for any otherwise uncaught exceptions (those that will
    generate HTTP 500 responses).
    """
    if settings.DEBUG_PROPAGATE_EXCEPTIONS:
        raise

    if settings.DEBUG:
        return debug.technical_500_response(request, *exc_info)

    # Return an HttpResponse that displays a friendly error message.
    callback = resolver.resolve_error_handler(500)
    return callback(request)

def _get_post(self):
    if not hasattr(self, "_post"):
        self._load_post_and_files()
    return self._post

def _get_files(self):
    if not hasattr(self, "_files"):
        self._load_post_and_files()
    return self._files

POST = property(_get_post, _set_post)
FILES = property(_get_files)

@cached_property

def close(self):
    super().close()
    self._stream.close()

def create_request(self, scope, body_file):
    """
    Create the Request object and returns either (request, None) or
    (None, response) if there is an error response.
    """
    try:
        return self.request_class(scope, body_file), None
    except UnicodeDecodeError:
        logger.warning(
            "Bad Request (UnicodeDecodeError)",
            exc_info=sys.exc_info(),
            extra={"status_code": 400},
        )
        return None, HttpResponseBadRequest()
    except RequestDataTooBig:
        return None, HttpResponse("413 Payload too large", status=413)

def handle_uncaught_exception(self, request, resolver, exc_info):
    """Last-chance handler for exceptions."""
    # There's no WSGI server to catch the exception further up
    # if this fails, so translate it into a plain text response.
    try:
        return super().handle_uncaught_exception(request, resolver, exc_info)
    except Exception:
        return HttpResponseServerError(
            traceback.format_exc() if settings.DEBUG else "Internal Server Error",
            content_type="text/plain",
        )

async def send_response(self, response, send):
    """Encode and send a response out over ASGI."""
    # Collect cookies into headers. Have to preserve header case as there
    # are some non-RFC compliant clients that require e.g. Content-Type.
    response_headers = []
    for header, value in response.items():
        if isinstance(header, str):
            header = header.encode("ascii")
        if isinstance(value, str):
            value = value.encode("latin1")
        response_headers.append((bytes(header), bytes(value)))
    for c in response.cookies.values():
        response_headers.append((b"Set-Cookie", c.OutputString().encode("ascii")))
    # Initial response message.
    await send(
        {
            "type": "http.response.start",
            "status": response.status_code,
            "headers": response_headers,
        }
    )
    # Streaming responses need to be pinned to their iterator.
    if response.streaming:
        # - Consume via `__aiter__` and not `streaming_content` directly, to
        #   allow mapping of a sync iterator.
        # - Use aclosing() when consuming aiter. See
        #   https://github.com/python/cpython/commit/6e8dcdaaa49d4313bf9fab9f9923ca5828fbb10e
        async with aclosing(aiter(response)) as content:
            async for part in content:
                for chunk, _ in self.chunk_bytes(part):
                    await send(
                        {
                            "type": "http.response.body",
                            "body": chunk,
                            # Ignore "more" as there may be more parts; instead,
                            # use an empty final closing message with False.
                            "more_body": True,
                        }
                    )
        # Final closing message.
        await send({"type": "http.response.body"})
    # Other responses just need chunking.
    else:
        # Yield chunks of response.
        for chunk, last in self.chunk_bytes(response.content):
            await send(
                {
                    "type": "http.response.body",
                    "body": chunk,
                    "more_body": not last,
                }
            )

@classmethod

def load_middleware(self, is_async=False):
    """
    Populate middleware lists from settings.MIDDLEWARE.

    Must be called after the environment is fixed (see __call__ in subclasses).
    """
    self._view_middleware = []
    self._template_response_middleware = []
    self._exception_middleware = []

    get_response = self._get_response_async if is_async else self._get_response
    handler = convert_exception_to_response(get_response)
    handler_is_async = is_async
    for middleware_path in reversed(settings.MIDDLEWARE):
        middleware = import_string(middleware_path)
        middleware_can_sync = getattr(middleware, "sync_capable", True)
        middleware_can_async = getattr(middleware, "async_capable", False)
        if not middleware_can_sync and not middleware_can_async:
            raise RuntimeError(
                "Middleware %s must have at least one of "
                "sync_capable/async_capable set to True." % middleware_path
            )
        elif not handler_is_async and middleware_can_sync:
            middleware_is_async = False
        else:
            middleware_is_async = middleware_can_async
        try:
            # Adapt handler, if needed.
            adapted_handler = self.adapt_method_mode(
                middleware_is_async,
                handler,
                handler_is_async,
                debug=settings.DEBUG,
                name="middleware %s" % middleware_path,
            )
            mw_instance = middleware(adapted_handler)
        except MiddlewareNotUsed as exc:
            if settings.DEBUG:
                if str(exc):
                    logger.debug("MiddlewareNotUsed(%r): %s", middleware_path, exc)
                else:
                    logger.debug("MiddlewareNotUsed: %r", middleware_path)
            continue
        else:
            handler = adapted_handler

        if mw_instance is None:
            raise ImproperlyConfigured(
                "Middleware factory %s returned None." % middleware_path
            )

        if hasattr(mw_instance, "process_view"):
            self._view_middleware.insert(
                0,
                self.adapt_method_mode(is_async, mw_instance.process_view),
            )
        if hasattr(mw_instance, "process_template_response"):
            self._template_response_middleware.append(
                self.adapt_method_mode(
                    is_async, mw_instance.process_template_response
                ),
            )
        if hasattr(mw_instance, "process_exception"):
            # The exception-handling stack is still always synchronous for
            # now, so adapt that way.
            self._exception_middleware.append(
                self.adapt_method_mode(False, mw_instance.process_exception),
            )

        handler = convert_exception_to_response(mw_instance)
        handler_is_async = middleware_is_async

    # Adapt the top of the stack, if needed.
    handler = self.adapt_method_mode(is_async, handler, handler_is_async)
    # We only assign to this when initialization is complete as it is used
    # as a flag for initialization being complete.
    self._middleware_chain = handler

def adapt_method_mode(
    self,
    is_async,
    method,
    method_is_async=None,
    debug=False,
    name=None,
):
    """
    Adapt a method to be in the correct "mode":
    - If is_async is False:
      - Synchronous methods are left alone
      - Asynchronous methods are wrapped with async_to_sync
    - If is_async is True:
      - Synchronous methods are wrapped with sync_to_async()
      - Asynchronous methods are left alone
    """
    if method_is_async is None:
        method_is_async = iscoroutinefunction(method)
    if debug and not name:
        name = name or "method %s()" % method.__qualname__
    if is_async:
        if not method_is_async:
            if debug:
                logger.debug("Synchronous handler adapted for %s.", name)
            return sync_to_async(method, thread_sensitive=True)
    elif method_is_async:
        if debug:
            logger.debug("Asynchronous handler adapted for %s.", name)
        return async_to_sync(method)
    return method

def _get_response(self, request):
    """
    Resolve and call the view, then apply view, exception, and
    template_response middleware. This method is everything that happens
    inside the request/response middleware.
    """
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)

    # Apply view middleware
    for middleware_method in self._view_middleware:
        response = middleware_method(
            request, callback, callback_args, callback_kwargs
        )
        if response:
            break

    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        # If it is an asynchronous view, run it in a subthread.
        if iscoroutinefunction(wrapped_callback):
            wrapped_callback = async_to_sync(wrapped_callback)
        try:
            response = wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise

    # Complain if the view returned None (a common error).
    self.check_response(response, callback)

    # If the response supports deferred rendering, apply template
    # response middleware and then render the response
    if hasattr(response, "render") and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = middleware_method(request, response)
            # Complain if the template response middleware returned None
            # (a common error).
            self.check_response(
                response,
                middleware_method,
                name="%s.process_template_response"
                % (middleware_method.__self__.__class__.__name__,),
            )
        try:
            response = response.render()
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise

    return response

async def _get_response_async(self, request):
    """
    Resolve and call the view, then apply view, exception, and
    template_response middleware. This method is everything that happens
    inside the request/response middleware.
    """
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)

    # Apply view middleware.
    for middleware_method in self._view_middleware:
        response = await middleware_method(
            request, callback, callback_args, callback_kwargs
        )
        if response:
            break

    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        # If it is a synchronous view, run it in a subthread
        if not iscoroutinefunction(wrapped_callback):
            wrapped_callback = sync_to_async(
                wrapped_callback, thread_sensitive=True
            )
        try:
            response = await wrapped_callback(
                request, *callback_args, **callback_kwargs
            )
        except Exception as e:
            response = await sync_to_async(
                self.process_exception_by_middleware,
                thread_sensitive=True,
            )(e, request)
            if response is None:
                raise

    # Complain if the view returned None or an uncalled coroutine.
    self.check_response(response, callback)

    # If the response supports deferred rendering, apply template
    # response middleware and then render the response
    if hasattr(response, "render") and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = await middleware_method(request, response)
            # Complain if the template response middleware returned None or
            # an uncalled coroutine.
            self.check_response(
                response,
                middleware_method,
                name="%s.process_template_response"
                % (middleware_method.__self__.__class__.__name__,),
            )
        try:
            if iscoroutinefunction(response.render):
                response = await response.render()
            else:
                response = await sync_to_async(
                    response.render, thread_sensitive=True
                )()
        except Exception as e:
            response = await sync_to_async(
                self.process_exception_by_middleware,
                thread_sensitive=True,
            )(e, request)
            if response is None:
                raise

    # Make sure the response is not a coroutine
    if asyncio.iscoroutine(response):
        raise RuntimeError("Response is still a coroutine.")
    return response

def check_response(self, response, callback, name=None):
    """
    Raise an error if the view returned None or an uncalled coroutine.
    """
    if not (response is None or asyncio.iscoroutine(response)):
        return
    if not name:
        if isinstance(callback, types.FunctionType):  # FBV
            name = "The view %s.%s" % (callback.__module__, callback.__name__)
        else:  # CBV
            name = "The view %s.%s.__call__" % (
                callback.__module__,
                callback.__class__.__name__,
            )
    if response is None:
        raise ValueError(
            "%s didn't return an HttpResponse object. It returned None "
            "instead." % name
        )
    elif asyncio.iscoroutine(response):
        raise ValueError(
            "%s didn't return an HttpResponse object. It returned an "
            "unawaited coroutine instead. You may need to add an 'await' "
            "into your view." % name
        )

# Other utility methods.

def make_view_atomic(self, view):
    non_atomic_requests = getattr(view, "_non_atomic_requests", set())
    for alias, settings_dict in connections.settings.items():
        if settings_dict["ATOMIC_REQUESTS"] and alias not in non_atomic_requests:
            if iscoroutinefunction(view):
                raise RuntimeError(
                    "You cannot use ATOMIC_REQUESTS with async views."
                )
            view = transaction.atomic(using=alias)(view)
    return view

def process_exception_by_middleware(self, exception, request):
    """
    Pass the exception to the exception middleware. If no middleware
    return a response for this exception, return None.
    """
    for middleware_method in self._exception_middleware:
        response = middleware_method(request, exception)
        if response:
            return response
    return None

def read(self, size=-1, /):
    _pos = self._pos
    limit = self.limit
    if _pos >= limit:
        return b""
    if size == -1 or size is None:
        size = limit - _pos
    else:
        size = min(size, limit - _pos)
    data = self._read(size)
    self._pos += len(data)
    return data

def readline(self, size=-1, /):
    _pos = self._pos
    limit = self.limit
    if _pos >= limit:
        return b""
    if size == -1 or size is None:
        size = limit - _pos
    else:
        size = min(size, limit - _pos)
